insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('nb',10,12,'crampon1923','et les enfants d''Israël, reprenant leurs marches, partirent du désert de Sinaï, et la nuée s''arrêta dans le désert de Pharan.'),
('nb',10,13,'crampon1923','Ils se mirent en marche pour la première fois, suivant le commandement de Yahweh par l''organe de Moïse.'),
('nb',10,14,'crampon1923','La bannière du camp des fils de Juda partit la première, selon leurs troupes, et la troupe de Juda était commandée par Nahasson, fils d''Aminadab;'),
('nb',10,15,'crampon1923','la troupe de la tribu des fils d''Issachar était commandée par Nathanaël, fils de Suar;'),
('nb',10,16,'crampon1923','et la troupe de la tribu des fils de Zabulon était commandée par Eliab, fils de Hélon.'),
('nb',10,17,'crampon1923','La Demeure fut démontée, et les fils de Gerson et les fils de Mérari partirent, portant la Demeure.'),
('nb',10,18,'crampon1923','La bannière du camp de Ruben partit, selon leurs troupes, et la troupe de Ruben était commandée par Elisur, fils de Sédéur;'),
('nb',10,19,'crampon1923','la troupe de la tribu des fils de Siméon était commandée par Salamiel, fils de Surisaddaï;'),
('nb',10,20,'crampon1923','et la troupe de la tribu des fils de Gad était commandée par Eliasaph, fils de Duel.'),
('nb',10,21,'crampon1923','Les Caathites partirent portant les objets sacrés, et les autres dressaient la Demeure, en attendant leur arrivée.'),
('nb',10,22,'crampon1923','La bannière du camp des fils d''Ephraïm partit, selon leurs troupes et la troupe d''Ephraïm était commandée par Elisama, fils d''Ammiud;'),
('nb',10,23,'crampon1923','la troupe de la tribu des fils de Manassé était commandée par Gamaliel, fils de Phadassur,'),
('nb',10,24,'crampon1923','et la troupe de la tribu de Benjamin était commandée par Abidan, fils de Gédéon.'),
('nb',10,25,'crampon1923','La bannière du camp des fils de Dan partit, selon leurs troupes: elle formait l''arrière-garde de tous les camps. La troupe de Dan était commandée par Ahiéser, fils d''Ammisaddaï;'),
('nb',10,26,'crampon1923','la troupe de la tribu des fils d''Aser était commandée par Phégiel, fils d''Ochran,'),
('nb',10,27,'crampon1923','et la troupe des fils de Nephthali était commandée par Ahira, fils d''Enan.'),
('nb',10,28,'crampon1923','Tel était l''ordre de marche des enfants d''Israël selon leurs troupes; et ils partirent.'),
('nb',10,29,'crampon1923','Moïse dit à Hobab, fils de Raguel, le Madianite, beau-père de Moïse: « Nous partons pour le lieu dont Yahweh a dit: Je vous le donnerai. Viens avec nous, et nous te ferons du bien, car Yahweh a promis de faire du bien à Israël. »'),
('nb',10,30,'crampon1923','Hobab lui répondit: « Je n''irai point, mais je m''en irai dans mon pays et ma famille. »'),
('nb',10,31,'crampon1923','Et Moïse dit: « Ne nous quitte pas, je te prie; puisque tu connais les lieux où nous aurons à camper dans le désert, tu nous serviras d''œil.'),
('nb',10,32,'crampon1923','Si tu viens avec nous, nous te ferons partager le bien que Yahweh nous fera. »'),
('nb',10,33,'crampon1923','Etant partis de la montagne de Yahweh, ils firent trois journées de marche, et pendant ces trois journées de marche, l''arche de l''alliance de Yahweh s''avança devant eux pour leur chercher un lieu de repos.'),
('nb',10,34,'crampon1923','La nuée de Yahweh était au-dessus d''eux pendant le jour, lorsqu''ils partaient du camp.'),
('nb',10,35,'crampon1923','Quand l''arche partait, Moïse disait: « Lève-toi, Yahweh, et que tes ennemis soient dispersés! Que ceux qui te haïssent fuient devant ta face! »'),
('nb',10,36,'crampon1923','Et quand elle s''arrêtait, il disait: « Reviens, Yahweh, vers les myriades des milliers d''Israël! »'),
('nb',11,1,'crampon1923','Le peuple se mit à murmurer du mal aux oreilles de Yahweh. Yahweh l''entendit, et sa colère s''enflamma, et le feu de Yahweh s''alluma contre eux et il dévorait à l''extrémité du camp.'),
('nb',11,2,'crampon1923','Le peuple cria vers Moïse, et Moïse pria Yahweh, et le feu s''éteignit.'),
('nb',11,3,'crampon1923','On donna à ce lieu le nom de Thabéera, parce que le feu de Yahweh s''était allumé contre eux.'),
('nb',11,4,'crampon1923','Le ramas de gens qui se trouvaient au milieu d''Israël s''enflamma de convoitise, et même les enfants d''Israël recommencèrent à pleurer et dirent: « Qui nous donnera de la viande à manger?'),
('nb',11,5,'crampon1923','Il nous souvient des poissons que nous mangions pour rien en Egypte, des concombres, des melons, des poireaux, des oignons et de l''ail.'),
('nb',11,6,'crampon1923','Maintenant notre âme est desséchée; plus rien! Nos yeux ne voient que de la manne. »'),
('nb',11,7,'crampon1923','La manne était semblable à la graine de coriandre, et avait l''aspect du bdellium.'),
('nb',11,8,'crampon1923','Le peuple se répandait pour la ramasser; il la broyait avec des meules ou la pilait dans un mortier; il la cuisait au pot, et en faisait des gâteaux. Elle avait le goût d''un gâteau à l''huile.'),
('nb',11,9,'crampon1923','Quand la rosée descendait pendant la nuit sur le camp, la manne y descendait aussi.'),
('nb',11,10,'crampon1923','Moïse entendit le peuple qui pleurait dans chaque famille, chacun à l''entrée de sa tente. La colère de Yahweh s''enflamma grandement. Moïse fut attristé,'),
('nb',11,11,'crampon1923','et il dit à Yahweh: « Pourquoi avez-vous fait ce mal à votre serviteur, et pourquoi n''ai-je pas trouvé grâce à vos yeux, que vous ayez mis sur moi la charge de tout ce peuple?'),
('nb',11,12,'crampon1923','Est-ce moi qui ai conçu tout ce peuple? est-ce moi qui l''ai enfanté, pour que vous me disiez: Porte-le sur ton sein, comme le nourricier porte un enfant qu''on allaite, jusqu''au pays que vous avez juré à ses pères de lui donner?'),
('nb',11,13,'crampon1923','Où prendrai-je de la viande pour en donner à tout ce peuple? Car ils pleurent autour de moi, en disant: Donne-nous de la viande à manger.'),
('nb',11,14,'crampon1923','Je ne puis pas, à moi seul, porter tout ce peuple; il est trop pesant pour moi.'),
('nb',11,15,'crampon1923','Pour me traiter ainsi, tuez-moi plutôt, je vous prie, si j''ai trouvé grâce à vos yeux, et que je ne voie pas mon malheur! »'),
('nb',11,16,'crampon1923','Yahweh dit à Moïse: « Assemble-moi soixante-dix hommes des anciens d''Israël, que tu connais pour être anciens du peuple et préposés sur lui; amène-les à la tente de réunion et qu''ils se tiennent là avec toi.'),
('nb',11,17,'crampon1923','Je descendrai et je te parlerai là; je prendrai de l''esprit qui est sur toi et je le mettrai sur eux, afin qu''ils portent avec toi la charge du peuple, et tu ne la porteras plus toi seul.'),
('nb',11,18,'crampon1923','Tu diras au peuple: Sanctifiez-vous pour demain, et vous aurez de la viande à manger, puisque vous avez pleuré aux oreilles de Yahweh, en disant: Qui nous fera manger de la viande? car nous étions bien en Egypte! Et Yahweh vous donnera de la viande, et vous en mangerez;'),
('nb',11,19,'crampon1923','ce n''est pas un jour que vous en mangerez, ni deux jours, ni cinq jours, ni dix jours, ni vingt jours,'),
('nb',11,20,'crampon1923','mais un mois entier, jusqu''à ce qu''elle vous sorte par les narines et qu''elle vous soit en dégoût, parce que vous avez rejeté Yahweh qui est au milieu de vous, et que vous avez pleuré devant lui, en disant: Pourquoi donc sommes-nous sortis d''Egypte? »'),
('nb',11,21,'crampon1923','Moïse dit: « Le peuple au milieu duquel je suis est de six cent mille hommes de pied, et vous dites: Je leur donnerai de la viande, et ils en mangeront un mois entier!'),
('nb',11,22,'crampon1923','Egorgera-t-on pour eux les brebis et les bœufs, pour qu''ils en aient assez? Ou leur ramassera-t-on tous les poissons de la mer, pour qu''ils en aient assez? »'),
('nb',11,23,'crampon1923','Yahweh répondit à Moïse: « La main de Yahweh est-elle trop courte? Tu verras maintenant si ce que j''ai dit t''arrivera ou non. »'),
('nb',11,24,'crampon1923','Moïse sortit et rapporta au peuple les paroles de Yahweh, et il assembla soixante-dix hommes des anciens du peuple et les plaça autour de la tente.'),
('nb',11,25,'crampon1923','Yahweh descendit dans la nuée et parla à Moïse; il prit de l''esprit qui était sur lui et le mit sur les soixante-dix anciens; et, dès que l''esprit reposa sur eux, ils prophétisèrent; mais ils ne continuèrent pas.'),
('nb',11,26,'crampon1923','Deux hommes, l''un nommé Eldad, et l''autre Médad, étaient restés dans le camp, et l''esprit reposa aussi sur eux; ils étaient parmi les inscrits, mais ils ne s''étaient pas rendus à la tente; et ils prophétisèrent dans le camp.'),
('nb',11,27,'crampon1923','Un jeune garçon courut l''annoncer à Moïse, en disant: « Eldad et Médad prophétisent dans le camp. »'),
('nb',11,28,'crampon1923','Aussitôt Josué, fils de Nun, serviteur de Moïse depuis sa jeunesse, prenant la parole dit: « Moïse, mon seigneur, empêche-les. »'),
('nb',11,29,'crampon1923','Moïse lui répondit: « Es-tu donc jaloux pour moi? Plût à Dieu que tout le peuple de Yahweh fût prophète, et que Yahweh mit son esprit sur eux! »'),
('nb',11,30,'crampon1923','Et Moïse se retira dans le camp, lui et les anciens d''Israël.'),
('nb',11,31,'crampon1923','Un vent souffla de par l''ordre de Yahweh, qui, de la mer, amena des cailles et les abattit sur le camp, sur l''étendue d''environ une journée de chemin d''un côté, d''environ une journée de chemin de l''autre côté, autour du camp; et il y en avait près de deux coudées de haut sur la surface de la terre.'),
('nb',11,32,'crampon1923','Pendant tout ce jour, toute la nuit et toute la journée du lendemain, le peuple se leva et ramassa les cailles; celui qui en avait ramassé le moins en avait dix gomors; et ils les étendirent pour eux, tout autour du camp.'),
('nb',11,33,'crampon1923','Mais la chair était encore entre leurs dents, avant d''être consommée, que la colère de Yahweh s''enflamma contre le peuple, et Yahweh frappa le peuple d''une très grande plaie.'),
('nb',11,34,'crampon1923','On donna à ce lieu le nom de Qibroth-Hattaava, parce qu''on y enterra le peuple qui s''était enflammé de convoitise.'),
('nb',11,35,'crampon1923','De Qibroth-Hattaava le peuple partit pour Haséroth, et il s''arrêta à Haséroth.'),
('nb',12,1,'crampon1923','Marie, avec Aaron, parla contre Moïse au sujet de la femme couschite qu''il avait prise; car il avait pris une femme couschite.'),
('nb',12,2,'crampon1923','Ils dirent: « Est-ce seulement par Moïse que Yahweh a parlé? N''a-t-il pas parlé aussi par nous? » Et Yahweh l''entendit.'),
('nb',12,3,'crampon1923','Mais Moïse était un homme fort doux, plus qu''aucun homme qui fût sur la face de la terre.'),
('nb',12,4,'crampon1923','Soudain Yahweh dit à Moïse, à Aaron et à Marie: « Sortez, vous trois, vers la tente de réunion. » Et ils sortirent tous les trois;'),
('nb',12,5,'crampon1923','et Yahweh descendit dans la colonne de nuée et se tint à l''entrée de la tente. Il appela Aaron et Marie, qui s''avancèrent tous deux;'),
('nb',12,6,'crampon1923','et il dit: « Ecoutez bien mes paroles: si vous avez quelque prophète de Yahweh, c''est en vision que je me révèle à lui, c''est en songe que je lui parle.'),
('nb',12,7,'crampon1923','Tel n''est pas mon serviteur Moïse; il est reconnu fidèle dans toute ma maison.'),
('nb',12,8,'crampon1923','Je lui parle bouche à bouche, en me faisant voir, et non par énigmes, et il contemple la figure de Yahweh. Pourquoi donc n''avez-vous pas craint de parler contre mon serviteur, contre Moïse? »'),
('nb',12,9,'crampon1923','Et la colère de Yahweh s''enflamma contre eux; et il s''en alla;'),
('nb',12,10,'crampon1923','la nuée se retira de dessus la tente. Et voici, Marie devint lépreuse, blanche comme la neige. Aaron se tourna vers Marie, et voici, elle était lépreuse.'),
('nb',12,11,'crampon1923','Et Aaron dit à Moïse: « De grâce, mon seigneur, ne mets pas sur nous ce péché que nous avons follement commis, et dont nous sommes coupables.'),
('nb',12,12,'crampon1923','Ah! Qu''elle ne soit pas comme l''enfant mort-né qui, en sortant du sein de sa mère, a la chair à demi-consumée! »'),
('nb',12,13,'crampon1923','Moïse cria à Yahweh, en disant: « O Dieu, je vous prie, guérissez-là! »'),
('nb',12,14,'crampon1923','Yahweh dit à Moïse: « Si son père lui avait craché au visage, ne serait-elle pas pendant sept jours couverte de honte? Qu''elle soit séquestrée sept jours hors du camp; après quoi, elle y sera reçue. »'),
('nb',12,15,'crampon1923','Marie fut donc séquestrée sept jours hors du camp, et le peuple ne partit point, jusqu''à ce que Marie eût été reçue.'),
('nb',12,16,'crampon1923','Après cela, le peuple partit de Haséroth, et ils campèrent dans le désert de Pharan.'),
('nb',13,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',13,2,'crampon1923','« Envoie des hommes pour explorer le pays de Chanaan, que je donne aux enfants d''Israël. Vous enverrez un homme par chacune des tribus patriarcales; que tous soient des princes parmi eux. »'),
('nb',13,3,'crampon1923','Moïse les envoya du désert de Pharan, selon l''ordre de Yahweh; tous ces hommes étaient des chefs des enfants d''Israël.'),
('nb',13,4,'crampon1923','Voici leurs noms: pour la tribu de Ruben, Sammua, fils de Zéchur;'),
('nb',13,5,'crampon1923','pour la tribu de Siméon, Saphat, fils de Huri;'),
('nb',13,6,'crampon1923','pour la tribu de Juda, Caleb, fils de Jéphoné;'),
('nb',13,7,'crampon1923','pour la tribu d''Issachar, Igal, fils de Joseph;'),
('nb',13,8,'crampon1923','pour la tribu d''Ephraïm, Osée, fils de Nun;'),
('nb',13,9,'crampon1923','pour la tribu de Benjamin, Phalti, fils de Raphu;'),
('nb',13,10,'crampon1923','pour la tribu de Zabulon, Geddiel, fils de Sodi;'),
('nb',13,11,'crampon1923','pour la tribu de Joseph, la tribu de Manassé, Gaddi, fils de Susi;'),
('nb',13,12,'crampon1923','pour la tribu de Dan, Ammiel, fils de Gemalli;'),
('nb',13,13,'crampon1923','pour la tribu d''Aser, Sthur, fils de Michaël;'),
('nb',13,14,'crampon1923','pour la tribu de Nephthali, Nahabi, fils de Vapsi;'),
('nb',13,15,'crampon1923','pour la tribu de Gad, Guel, fils de Machi. —'),
('nb',13,16,'crampon1923','Tels sont les noms des hommes que Moïse envoya pour explorer le pays. Moïse donna à Osée, fils de Nun, le nom de Josué.'),
('nb',13,17,'crampon1923','Moïse les envoya pour explorer le pays de Chanaan; il leur dit: « Montez là par le Négeb; et vous monterez sur la montagne.'),
('nb',13,18,'crampon1923','Vous examinerez le pays, ce qu''il est, et le peuple qui l''habite, s''il est fort ou faible, peu nombreux ou considérable;'),
('nb',13,19,'crampon1923','ce qu''est le pays où il habite, s''il est bon ou mauvais; ce que sont les villes où il habite, si elles sont ouvertes ou fortifiées;'),
('nb',13,20,'crampon1923','ce qu''est le sol, s''il est gras ou maigre, s''il y a des arbres ou non. Ayez bon courage, et prenez des fruits du pays. » C''était le temps des premiers raisins.'),
('nb',13,21,'crampon1923','Ils montèrent et explorèrent le pays, depuis le désert de Sin jusqu''à Rohob, sur le chemin d''Emath.'),
('nb',13,22,'crampon1923','Ils montèrent dans le Négeb et allèrent jusqu''à Hébron, où étaient Achiman, Sisaï et Tholmaï, enfants d''Enac. Hébron avait été bâtie sept ans avant Tanis d''Egypte.'),
('nb',13,23,'crampon1923','Arrivés à la vallée d''Escol, ils coupèrent une branche de vigne avec sa grappe de raisin, et ils la portèrent à deux au moyen d''une perche; ils prirent aussi des grenades et des figues.'),
('nb',13,24,'crampon1923','On donna à ce lieu le nom de vallée d''Escol, à cause de la grappe que les enfants d''Israël y coupèrent.'),
('nb',13,25,'crampon1923','Au bout de quarante jours, ils revinrent d''explorer le pays.'),
('nb',13,26,'crampon1923','Ils allèrent et se rendirent auprès de Moïse et d''Aaron, et de toute l''assemblée des enfants d''Israël, à Cadès, dans le désert de Pharan. Ils leur firent un rapport, ainsi qu''à toute l''assemblée, et leur montrèrent les fruits du pays.'),
('nb',13,27,'crampon1923','Voici le récit qu''ils firent à Moïse: « Nous sommes allés dans le pays où tu nous as envoyés. C''est vraiment un pays où coulent le lait et le miel, et en voici les fruits.'),
('nb',13,28,'crampon1923','Mais le peuple qui habite le pays est puissant, et les villes sont fortifiées et très grandes; nous y avons même vu des enfants d''Enac.'),
('nb',13,29,'crampon1923','Amalec habite la contrée du Négeb; le Héthéen, le Jébuséen et l''Amorrhéen habitent dans la montagne, et le Chananéen habite au bord de la mer et le long du Jourdain. »'),
('nb',13,30,'crampon1923','Caleb fit taire le peuple au sujet de Moïse: « Montons, dit-il, emparons-nous du pays, car nous pouvons nous en rendre maîtres. »'),
('nb',13,31,'crampon1923','Mais les hommes qui y étaient montés avec lui, dirent: « Nous ne sommes pas capables de monter contre ce peuple: il est plus fort que nous. »'),
('nb',13,32,'crampon1923','Et ils décrièrent devant les enfants d''Israël le pays qu''ils avaient exploré, en disant: « Le pays que nous avons parcouru pour l''explorer, est un pays qui dévore ses habitants; tout le peuple que nous y avons vu est formé de gens de haute taille;'),
('nb',13,33,'crampon1923','et nous y avons vu les géants, fils d''Enac, de la race des géants: nous étions à nos yeux et aux leurs comme des sauterelles. »'),
('nb',14,1,'crampon1923','Toute l''assemblée éleva la voix et poussa des cris, et le peuple pleura pendant cette nuit-là.'),
('nb',14,2,'crampon1923','Tous les enfants d''Israël murmurèrent contre Moïse et Aaron, et toute l''assemblée leur dit: « Que ne sommes-nous morts dans le pays d''Egypte, ou que ne sommes-nous morts dans ce désert?'),
('nb',14,3,'crampon1923','Pourquoi Yahweh nous fait-il aller dans ce pays, pour que nous tombions par l''épée? Nos femmes et nos enfants deviendront une proie. Ne vaut-il pas mieux pour nous retourner en Egypte? »'),
('nb',14,4,'crampon1923','Et ils se dirent les uns aux autres: « Nommons un chef, et retournons en Egypte. »'),
('nb',14,5,'crampon1923','Moïse et Aaron tombèrent sur leur visage en présence de toute l''assemblée réunie des enfants d''Israël.'),
('nb',14,6,'crampon1923','Josué, fils de Nun, et Caleb, fils de Jéphoné, deux de ceux qui avaient exploré le pays, déchirèrent leurs vêtements'),
('nb',14,7,'crampon1923','et ils parlèrent ainsi à toute l''assemblée des enfants d''Israël: « Le pays que nous avons parcouru pour l''explorer est un excellent pays.'),
('nb',14,8,'crampon1923','Si Yahweh nous est favorable, il nous fera entrer dans ce pays et nous le donnera; c''est un pays où coulent le lait et le miel.'),
('nb',14,9,'crampon1923','Seulement ne vous mettez pas en rébellion contre Yahweh, et ne craignez point les hommes de ce pays, car ils seront pour nous une pâture; leur abri s''est retiré d''eux, et Yahweh est avec nous, ne les craignez point. »'),
('nb',14,10,'crampon1923','Toute l''assemblée parlait de les lapider, lorsque la gloire de Yahweh apparut sur la tente de réunion, devant tous les enfants d''Israël.'),
('nb',14,11,'crampon1923','Et Yahweh dit à Moïse: « Jusques à quand ce peuple me méprisera-t-il? Jusques à quand ne croira-t-il pas en moi, malgré tous les prodiges que j''ai faits au milieu de lui?'),
('nb',14,12,'crampon1923','Je le frapperai par la peste et je le détruirai, et je ferai de toi une nation plus grande et plus puissante que lui. »'),
('nb',14,13,'crampon1923','Moïse dit à Yahweh: « Les Egyptiens ont appris que, par votre puissance, vous avez fait monter ce peuple du milieu d''eux, et ils l''ont dit aux habitants de ce pays.'),
('nb',14,14,'crampon1923','Tous ont appris que vous, Yahweh, vous êtes au milieu de ce peuple; que vous vous montrez face à face, vous, Yahweh; que votre nuée se tient sur eux, et que vous marchez devant eux le jour dans une colonne de nuée, et la nuit dans une colonne de feu.'),
('nb',14,15,'crampon1923','Si vous faites mourir ce peuple comme un seul homme, les nations qui ont entendu parler de vous diront:'),
('nb',14,16,'crampon1923','Yahweh n''avait pas le pouvoir de faire entrer ce peuple dans le pays qu''il avait juré de leur donner; c''est pourquoi il les a fait périr dans le désert.'),
('nb',14,17,'crampon1923','Maintenant que la puissance du Seigneur se montre grande, comme vous l''avez déclaré, en disant:'),
('nb',14,18,'crampon1923','Yahweh est lent à la colère et riche en bonté, il pardonne l''iniquité et le péché; mais il ne tient pas le coupable pour innocent, et il punit l''iniquité des pères sur les enfants, sur ceux de la troisième et de la quatrième génération.'),
('nb',14,19,'crampon1923','Pardonnez l''iniquité de ce peuple selon la grandeur de votre miséricorde, comme vous avez pardonné à ce peuple depuis l''Egypte jusqu''ici. »'),
('nb',14,20,'crampon1923','Et Yahweh dit: « Je pardonne, selon ta demande;'),
('nb',14,21,'crampon1923','mais, — je suis vivant! et la gloire de Yahweh remplira toute la terre! —'),
('nb',14,22,'crampon1923','tous les hommes qui ont vu ma gloire et les prodiges que j''ai faits en Egypte et dans le désert, qui m''ont tenté déjà dix fois et qui n''ont pas écouté ma voix,'),
('nb',14,23,'crampon1923','tous ceux-là ne verront point le pays que j''ai promis avec serment à leurs pères. Aucun de ceux qui m''ont méprisé ne le verra.'),
('nb',14,24,'crampon1923','Mais mon serviteur Caleb, qui a été animé d''un autre esprit et s''est fidèlement attaché à moi, je le ferai entrer dans le pays où il est allé, et ses descendants le posséderont.'),
('nb',14,25,'crampon1923','L''Amalécite et le Chananéen habitent dans la vallée: demain retournez-vous, et partez pour le désert, sur le chemin de la mer Rouge. »'),
('nb',14,26,'crampon1923','Yahweh parla à Moïse et à Aaron, en disant:'),
('nb',14,27,'crampon1923','« Jusques à quand supporterai-je cette méchante assemblée qui murmure contre moi? J''ai entendu les murmures que les enfants d''Israël profèrent contre moi.'),
('nb',14,28,'crampon1923','Dis-leur: Je suis vivant! dit Yahweh: je vous ferai selon que vous avez parlé à mes oreilles.'),
('nb',14,29,'crampon1923','Vos cadavres tomberont dans ce désert. Vous tous, dont on a fait le recensement, en vous comptant depuis l''âge de vingt ans et au-dessus, et qui avez murmuré contre moi,'),
('nb',14,30,'crampon1923','vous n''entrerez point dans le pays où j''ai juré de vous établir, à l''exception de Caleb, fils de Jéphoné, et de Josué, fils de Nun.'),
('nb',14,31,'crampon1923','Et vos petits enfants, dont vous avez dit: Ils deviendront une proie! je les y ferai entrer, et ils connaîtront le pays que vous avez dédaigné.'),
('nb',14,32,'crampon1923','Vos cadavres, à vous, tomberont dans le désert;'),
('nb',14,33,'crampon1923','et vos fils mèneront leurs troupeaux dans le désert pendant quarante ans, et ils porteront la peine de vos infidélités, jusqu''à ce que vos cadavres soient consumés dans le désert.'),
('nb',14,34,'crampon1923','Selon les quarante jours que vous avez mis à explorer le pays, — autant de jours, autant d''années — vous porterez vos iniquités quarante années, et vous saurez ce que c''est que mon éloignement.'),
('nb',14,35,'crampon1923','Moi, Yahweh, j''ai parlé! Voilà ce que je ferai à cette méchante assemblée qui s''est ameutée contre moi: ils seront consumés dans ce désert, ils y mourront. »'),
('nb',14,36,'crampon1923','Les hommes que Moïse avait envoyés pour explorer le pays et qui, à leur retour, avaient fait murmurer contre lui toute l''assemblée, en décrivant le pays,'),
('nb',14,37,'crampon1923','ces hommes, qui avaient décrié le pays, moururent frappés d''une plaie devant Yahweh.'),
('nb',14,38,'crampon1923','Josué, fils de Nun, et Caleb, fils de Jéphoné, restèrent seuls vivants parmi ces hommes qui étaient allés explorer le pays.'),
('nb',14,39,'crampon1923','Moïse rapporta ces paroles à tous les enfants d''Israël, et le peuple fut en grande désolation.'),
('nb',14,40,'crampon1923','S''étant levés de bon matin, ils montèrent vers le sommet de la montagne, en disant: « Nous voici! Nous monterons au lieu dont Yahweh a parlé, car nous avons péché. »'),
('nb',14,41,'crampon1923','Moïse dit: « Pourquoi transgressez-vous l''ordre de Yahweh? Cela ne vous réussira point.'),
('nb',14,42,'crampon1923','Ne montez pas, car Yahweh n''est pas au milieu de vous! Ne vous faites pas battre par vos ennemis.'),
('nb',14,43,'crampon1923','Car l''Amalécite et le Chananéen sont là devant vous, et vous tomberiez par l''épée; parce qui vous vous êtes détournés de Yahweh, Yahweh ne sera pas avec vous. »'),
('nb',14,44,'crampon1923','Ils s''obstinèrent à monter vers le sommet de la montagne; mais l''arche d''alliance de Yahweh et Moïse ne bougèrent pas du milieu du camp.'),
('nb',14,45,'crampon1923','Alors l''Amalécite et le Chananéen qui habitaient cette montagne descendirent, les battirent et les taillèrent en pièces jusqu''à Horma.'),
('nb',15,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',15,2,'crampon1923','« Parle aux enfants d''Israël et dis-leur: Quand vous serez entrés dans le pays où vous demeurerez et que je vous donne,'),
('nb',15,3,'crampon1923','et quand vous offrirez à Yahweh un sacrifice fait par le feu, soit un holocauste, soit un sacrifice, pour l''accomplissement d''un vœu ou comme offrande volontaire, ou bien dans vos fêtes, afin de produire avec vos bœufs ou vos brebis une agréable odeur à Yahweh,'),
('nb',15,4,'crampon1923','celui qui fera son offrande à Yahweh offrira en oblation un dixième de fleur de farine pétrie avec un quart de hin d''huile;'),
('nb',15,5,'crampon1923','tu feras une libation d''un quart de hin de vin, avec l''holocauste ou le sacrifice pacifique, pour chaque agneau.'),
('nb',15,6,'crampon1923','Pour un bélier, tu feras une oblation de deux dixièmes de fleur de farine pétrie avec un tiers de hin d''huile,'),
('nb',15,7,'crampon1923','et pour la libation tu offriras un tiers de hin de vin, en offrande d''agréable odeur à Yahweh.'),
('nb',15,8,'crampon1923','Si tu offres un taureau, soit comme holocauste, soit comme sacrifice, pour l''acquittement d''un vœu ou comme sacrifice pacifique à Yahweh,'),
('nb',15,9,'crampon1923','on offrira, avec le taureau, comme oblation, trois dixièmes de fleur de farine pétrie avec un demi-hin d''huile,'),
('nb',15,10,'crampon1923','et tu offriras un demi-hin de vin pour la libation: c''est un sacrifice fait par le feu, d''une agréable odeur à Yahweh.'),
('nb',15,11,'crampon1923','On fera ainsi pour chaque bœuf, pour chaque bélier, pour chaque agneau ou chevreau.'),
('nb',15,12,'crampon1923','Suivant le nombre de victimes que vous offrirez, vous ferez ainsi pour chacune, selon leur nombre.'),
('nb',15,13,'crampon1923','Tout indigène fera ces choses de cette manière, lorsqu''il offrira un sacrifice par le feu, d''une agréable odeur à Yahweh.'),
('nb',15,14,'crampon1923','Si un étranger séjournant chez vous, un homme quelconque vivant parmi vous, de génération en génération, offre un sacrifice par le feu, d''une agréable odeur à Yahweh, il fera comme vous ferez.'),
('nb',15,15,'crampon1923','Il y aura une seule loi pour l''assemblée, pour vous comme pour l''étranger de séjour au milieu de vous; ce sera une loi perpétuelle pour vos descendants: il en sera de l''étranger comme de vous devant Yahweh.'),
('nb',15,16,'crampon1923','Il y aura une seule loi et une seule règle pour vous et pour l''étranger qui séjourne parmi vous. »'),
('nb',15,17,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',15,18,'crampon1923','« Parle aux enfants d''Israël et dis-leur: Quand vous serez arrivés dans le pays où je vous fais entrer,'),
('nb',15,19,'crampon1923','et que vous mangerez du pain de ce pays, vous prélèverez une offrande pour Yahweh.'),
('nb',15,20,'crampon1923','Comme prémices de votre pâte, vous prélèverez en offrande un gâteau; vous le prélèverez comme l''offrande qu''on prélève de l''aire.'),
('nb',15,21,'crampon1923','Comme prémices de votre pâte, vous prélèverez une offrande pour Yahweh, vous et vos descendants. »'),
('nb',15,22,'crampon1923','« Si vous péchez par erreur en n''observant pas tous ces commandements que Yahweh a fait connaître à Moïse,'),
('nb',15,23,'crampon1923','tout ce que Yahweh vous a ordonné par Moïse, depuis le jour où Yahweh a donné des commandements, et à la suite pour vos générations,'),
('nb',15,24,'crampon1923','si, dis-je, on a péché par erreur, sans que l''assemblée s''en soit aperçue, — toute l''assemblée offrira un jeune taureau en holocauste d''une agréable odeur à Yahweh, avec son oblation et sa libation, selon le rite prescrit, ainsi qu''un bouc en sacrifice pour le péché.'),
('nb',15,25,'crampon1923','Le prêtre fera l''expiation pour toute l''assemblée des enfants d''Israël, et il leur sera pardonné, car c''est un péché commis par erreur, et ils ont présenté leur offrande, un sacrifice fait par le feu à Yahweh, et leur sacrifice pour le péché devant Yahweh, à cause du péché qu''ils ont commis par erreur.'),
('nb',15,26,'crampon1923','Il sera pardonné à toute l''assemblée des enfants d''Israël et à l''étranger qui séjourne au milieu d''eux, car c''est par erreur que tout le peuple a péché.'),
('nb',15,27,'crampon1923','Si c''est une seule personne qui a péché par erreur, elle offrira une chèvre d''un an en sacrifice pour le péché.'),
('nb',15,28,'crampon1923','Le prêtre fera l''expiation devant Yahweh pour la personne qui a erré en commettant un péché par erreur; l''expiation pour elle étant faite, il lui sera pardonné.'),
('nb',15,29,'crampon1923','Pour l''indigène d''entre les enfants d''Israël et pour l''étranger qui séjourne au milieu d''eux, vous aurez une même loi, si quelqu''un agit mal par erreur.'),
('nb',15,30,'crampon1923','Mais si quelqu''un, indigène ou étranger, agit la main levée, il outrage Yahweh; cet homme sera retranché du milieu de son peuple.'),
('nb',15,31,'crampon1923','Car il a méprisé la parole de Yahweh et violé son commandement: cet homme sera retranché, son iniquité sera sur lui. »'),
('nb',15,32,'crampon1923','Pendant que les enfants d''Israël étaient dans le désert, ils trouvèrent un homme qui ramassait du bois le jour du sabbat.'),
('nb',15,33,'crampon1923','Ceux qui l''avaient trouvé ramassant du bois l''amenèrent à Moïse, à Aaron et à toute l''assemblée.'),
('nb',15,34,'crampon1923','On le mit sous garde, car ce qu''on devait lui faire n''avait pas été déterminé.'),
('nb',15,35,'crampon1923','Yahweh dit à Moïse: « Cet homme sera mis à mort! Toute l''assemblée le lapidera hors du camp. »'),
('nb',15,36,'crampon1923','Toute l''assemblée l''ayant fait sortir du camp, le lapida et il mourut, comme Yahweh l''avait ordonné à Moïse.'),
('nb',15,37,'crampon1923','Yahweh dit à Moïse:'),
('nb',15,38,'crampon1923','« Parle aux enfants d''Israël et dis-leur de se faire, de génération en génération, des glands aux coins de leurs manteaux; et qu''ils mettent au gland de chaque coin un cordon de pourpre violette.'),
('nb',15,39,'crampon1923','Ce sera pour vous un gland et, en le voyant, vous vous souviendrez de tous les commandements de Yahweh pour les mettre en pratique, et vous n''irez pas après les désirs de votre cœur et de vos yeux, qui vous entraînent dans l''infidélité.'),
('nb',15,40,'crampon1923','Vous vous souviendrez ainsi de tous mes commandements et les mettrez en pratique, et vous serez saints à votre Dieu.'),
('nb',15,41,'crampon1923','Je suis Yahweh, votre Dieu, qui vous ai fait sortir du pays d''Egypte, pour être votre Dieu. Je suis Yahweh, votre Dieu. »'),
('nb',16,1,'crampon1923','Coré, fils d''Isaar, fils de Caath, fils de Lévi, se fit des partisans, avec Dathan et Abiron, fils d''Eliab, et Hon, fils de Phéleth, ceux-ci, fils de Ruben,'),
('nb',16,2,'crampon1923','et ils se soulevèrent en présence de Moïse, ayant avec eux deux cent cinquante hommes des enfants d''Israël, princes de l''assemblée, appelés aux conseils et gens de renom.'),
('nb',16,3,'crampon1923','Ils s''attroupèrent contre Moïse et Aaron, et leur dirent: « C''en est assez! car toute l''assemblée, tous sont saints, et Yahweh est au milieu d''eux. Pourquoi vous élevez-vous au-dessus de l''assemblée de Yahweh? »'),
('nb',16,4,'crampon1923','Quand Moïse entendit cela, il tomba sur son visage.'),
('nb',16,5,'crampon1923','Il parla à Coré et à toute sa troupe en disant: « Demain, Yahweh fera connaître celui qui est à lui et qui est saint, et il le fera approcher de lui; celui qu''il aura choisi, il le fera approcher de lui.'),
('nb',16,6,'crampon1923','Faites ceci: Prenez des encensoirs, Coré et toute sa troupe.'),
('nb',16,7,'crampon1923','Demain, mettez-y du feu, et jetez dessus du parfum devant Yahweh; celui que Yahweh choisira, c''est lui qui est saint. C''en est assez, enfants de Lévi. »'),
('nb',16,8,'crampon1923','Moïse dit à Coré: « Ecoutez donc, enfants de Lévi.'),
('nb',16,9,'crampon1923','Est-ce trop peu pour vous que le Dieu d''Israël vous ait séparés de l''assemblée d''Israël en vous faisant approcher de lui, pour faire le service de la Demeure de Yahweh, et pour vous tenir devant l''assemblée pour faire son service?'),
('nb',16,10,'crampon1923','Il t''a fait approcher de lui, toi et tous tes frères, les enfants de Lévi, avec toi, et vous ambitionnez encore le sacerdoce!'),
('nb',16,11,'crampon1923','C''est pour cela que toi et toute ta troupe, vous vous assemblez contre Yahweh! Et Aaron, qui est-il, pour que vous murmuriez contre lui? »'),
('nb',16,12,'crampon1923','Moïse fit appeler Dathan et Abiron, fils d''Eliab; et ils dirent: « Nous ne monterons pas.'),
('nb',16,13,'crampon1923','N''est-ce pas assez de nous avoir fait sortir d''un pays où coulent le lait et le miel pour nous faire mourir au désert, que tu t''ériges en maître sur nous?'),
('nb',16,14,'crampon1923','Ah! Ce n''est pas dans un pays où coulent le lait et le miel que tu nous as conduits; ce ne sont pas des champs et des vignes que tu nous as donnés en possession! Penses-tu crever les yeux de ces gens? Nous ne monterons pas! »'),
('nb',16,15,'crampon1923','Moïse, très irrité, dit à Yahweh: « N''ayez point égard à leur oblation. Je ne leur ai pas même pris un âne, et je n''ai fait de mal à aucun d''eux. »'),
('nb',16,16,'crampon1923','Moïse dit à Coré: « Toi et toute ta troupe, trouvez-vous demain devant Yahweh, toi et eux, avec Aaron.'),
('nb',16,17,'crampon1923','Prenez chacun votre encensoir, mettez-y du parfum et présentez chacun votre encensoir devant Yahweh: deux cent cinquante encensoirs; toi aussi et Aaron, vous prendrez chacun votre encensoir. »'),
('nb',16,18,'crampon1923','Ils prirent chacun leur encensoir, y mirent du feu et y jetèrent du parfum, et ils se tinrent à l''entrée de la tente de réunion, avec Moïse et Aaron.'),
('nb',16,19,'crampon1923','Coré avait convoqué toute l''assemblée contre Moïse et Aaron, à l''entrée de la tente de réunion. Alors la gloire de Yahweh apparut à toute l''assemblée.'),
('nb',16,20,'crampon1923','Et Yahweh parla à Moïse et à Aaron, en disant:'),
('nb',16,21,'crampon1923','« Séparez-vous du milieu de cette assemblée, et je les consumerai en un instant. »'),
('nb',16,22,'crampon1923','Et ils tombèrent sur leur visage, et dirent: « O Dieu, Dieu des esprits de toute chair, un seul homme a péché, et tu t''irriterais contre toute l''assemblée! »'),
('nb',16,23,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',16,24,'crampon1923','« Parle à l''assemblée et dis: Ecartez-vous tout à l''entour de la demeure de Coré, de Dathan et d''Abiron. »'),
('nb',16,25,'crampon1923','Moïse se leva et alla vers Dathan et Abiron, et des anciens d''Israël allèrent après lui.'),
('nb',16,26,'crampon1923','Il parla à l''assemblée, en disant: « Eloignez-vous des tentes de ces méchants hommes, et ne touchez à rien de ce qui leur appartient, de peur que vous ne périssiez, enveloppés dans tous leurs péchés. »'),
('nb',16,27,'crampon1923','Ils s''écartèrent tout à l''entour de la demeure de Coré, de Dathan et d''Abiron. Alors Dathan et Abiron étant sortis se tinrent à l''entrée de leurs tentes, avec leurs femmes, leurs fils et leurs petits enfants.'),
('nb',16,28,'crampon1923','Moïse dit: « Vous connaîtrez à ceci que Yahweh m''a envoyé pour faire toutes ces œuvres, et que je n''agis pas de moi-même:'),
('nb',16,29,'crampon1923','Si ces gens meurent comme meurent tous les hommes, et si leur sort est celui de tous les hommes, ce n''est pas Yahweh qui m''a envoyé;'),
('nb',16,30,'crampon1923','mais si Yahweh fait une chose inouïe, si la terre ouvre sa bouche et les engloutit, eux et tout ce qui leur appartient, et qu''ils descendent vivants dans le séjour des morts, vous saurez que ces gens ont méprisé Yahweh. »'),
('nb',16,31,'crampon1923','Comme il achevait de prononcer toutes ces paroles, le sol qui était sous eux se fendit.'),
('nb',16,32,'crampon1923','La terre ouvrit sa bouche et les engloutit, eux et leurs familles, avec tous les gens de Coré et tous leurs biens.'),
('nb',16,33,'crampon1923','Ils descendirent vivants dans le séjour des morts, eux et tout ce qui leur appartenait; et la terre les recouvrit, et ils disparurent du milieu de l''assemblée.'),
('nb',16,34,'crampon1923','Tout Israël, qui était autour d''eux, s''enfuit à leur cri; car ils disaient: « Fuyons, de peur que la terre ne nous engloutisse! »'),
('nb',16,35,'crampon1923','Un feu sortit d''auprès de Yahweh et consuma les deux cent cinquante hommes qui offraient le parfum.'),
('nb',17,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',17,2,'crampon1923','« Dis à Eléazar, fils d''Aaron, le prêtre, de retirer les encensoirs du milieu de l''embrasement et d''en répandre au loin le feu, car ils sont sanctifiés.'),
('nb',17,3,'crampon1923','Des encensoirs de ces gens qui ont péché contre leur propre vie, qu''on fasse des lames étendues, pour en recouvrir l''autel des holocaustes; car on les a présentés devant Yahweh, et ils sont devenus saints; ils serviront de signe aux enfants d''Israël. »'),
('nb',17,4,'crampon1923','Le prêtre Eléazar prit les encensoirs d''airain qu''avaient présentés les hommes consumés par le feu, et il en fit des lames pour couvrir l''autel.'),
('nb',17,5,'crampon1923','C''est un mémorial pour les enfants d''Israël, afin qu''aucun étranger, qui n''est pas de la race d''Aaron, ne s''approche pour offrir du parfum devant Yahweh, et ne soit comme Coré et comme sa troupe, selon ce que Yahweh lui avait déclaré par Moïse.'),
('nb',17,6,'crampon1923','Le lendemain, toute l''assemblée des enfants d''Israël murmura contre Moïse et Aaron, en disant: « Vous avez fait mourir le peuple de Yahweh. »'),
('nb',17,7,'crampon1923','Comme l''assemblée s''attroupait contre Moïse et Aaron, ceux-ci se tournèrent vers la tente de réunion, et voici que la nuée la couvrit, et que la gloire de Yahweh apparut.'),
('nb',17,8,'crampon1923','Moïse et Aaron s''avancèrent devant la tente de réunion,'),
('nb',17,9,'crampon1923','et Yahweh parla à Moïse en disant:'),
('nb',17,10,'crampon1923','« Eloignez-vous du milieu de cette assemblée, et je les consumerai en un instant. » Ils tombèrent sur leur visage,'),
('nb',17,11,'crampon1923','et Moïse dit à Aaron: « Prends l''encensoir, et mets-y du feu de dessus l''autel, jettes-y du parfum, va promptement vers l''assemblée, et fais pour eux l''expiation; car la colère est sortie de devant Yahweh; la plaie commence. »'),
('nb',17,12,'crampon1923','Aaron prit l''encensoir, comme Moïse avait dit, et courut au milieu de l''assemblée; et voici que la plaie commençait parmi le peuple. Ayant mis le parfum, il fit l''expiation pour le peuple.'),
('nb',17,13,'crampon1923','Il se plaça entre les morts et les vivants, et la plaie fut arrêtée.'),
('nb',17,14,'crampon1923','Quatorze mille sept cents personnes moururent par cette plaie, outre ceux qui étaient morts à cause de Coré.'),
('nb',17,15,'crampon1923','Aaron retourna auprès de Moïse, à l''entrée de la tente de réunion, et la plaie était arrêtée.'),
('nb',17,16,'crampon1923','Yahweh parla à Moïse en disant:'),
('nb',17,17,'crampon1923','« Parle aux enfants d''Israël et prends d''eux une verge, une verge par chaque maison patriarcale, soit douze verges de la part de tous leurs princes pour leurs douze maisons patriarcales. Tu écriras le nom de chacun sur sa verge;'),
('nb',17,18,'crampon1923','tu écriras le nom d''Aaron sur la verge de Lévi, car il y aura une verge par chef de leurs maisons patriarcales.'),
('nb',17,19,'crampon1923','Tu les déposeras dans la tente de réunion, devant le témoignage, où je me rencontre avec vous.'),
('nb',17,20,'crampon1923','L''homme que je choisirai sera celui dont la verge fleurira, et je ferai cesser de devant moi les murmures que profèrent contre vous les enfants d''Israël. »'),
('nb',17,21,'crampon1923','Moïse parla aux enfants d''Israël, et tous leurs princes lui donnèrent une verge, chaque prince une verge, selon leurs maisons patriarcales, soit douze verges, et la verge d''Aaron était au milieu de leurs verges.'),
('nb',17,22,'crampon1923','Moïse déposa les verges devant Yahweh, dans la tente du témoignage.'),
('nb',17,23,'crampon1923','Le lendemain, Moïse retourna dans la tente du témoignage, et voici que la verge d''Aaron avait fleuri, pour la tribu de Lévi: il y avait poussé des boutons, éclos des fleurs et mûri des amandes.'),
('nb',17,24,'crampon1923','Moïse emporta toutes les verges de devant Yahweh, vers tous les enfants d''Israël, et ils les virent, et chacun reprit sa verge.'),
('nb',17,25,'crampon1923','Yahweh dit à Moïse: « Replace la verge d''Aaron devant le témoignage, pour être conservée comme un signe pour les enfants de rébellion, afin que tu fasses cesser de devant moi leurs murmures, et qu''ils ne meurent point. »'),
('nb',17,26,'crampon1923','Moïse fit ainsi; il fit selon l''ordre que Yahweh lui avait donné.'),
('nb',17,27,'crampon1923','les enfants d''Israël dirent à Moïse: « Voici que nous périssons, nous sommes perdus, tous perdus!'),
('nb',17,28,'crampon1923','Quiconque s''approche de la Demeure de Yahweh meurt. Nous faudra-t-il donc tous périr? »'),
('nb',18,1,'crampon1923','Yahweh dit à Aaron: « Toi et tes fils, et la maison de ton père avec toi, vous porterez l''iniquité du sanctuaire; toi et tes fils avec toi, vous porterez l''iniquité de votre sacerdoce.'),
('nb',18,2,'crampon1923','Fais aussi approcher avec toi du sanctuaire tes autres frères, la tribu de Lévi, la tribu de ton père, afin qu''ils te soient adjoints et qu''ils te servent, lorsque toi, et tes fils avec toi, vous serez devant la tente du témoignage.'),
('nb',18,3,'crampon1923','Ils rempliront ton service et le service de toute la tente; mais ils ne s''approcheront ni des ustensiles du sanctuaire, ni de l''autel, de peur que vous ne mouriez, eux et vous.'),
('nb',18,4,'crampon1923','Ils te seront adjoints, et ils rempliront le service de la tente de réunion, pour tout le travail de la tente. Aucun étranger n''approchera de vous.'),
('nb',18,5,'crampon1923','Vous remplirez le service du sanctuaire et le service de l''autel, afin qu''il n''y ait plus de colère contre les enfants d''Israël.'),
('nb',18,6,'crampon1923','Voici, j''ai pris vos frères les lévites du milieu des enfants d''Israël; donnés à Yahweh, ils vous sont remis en don pour faire le travail de la tente de réunion.'),
('nb',18,7,'crampon1923','Toi et tes fils avec toi, vous remplirez votre sacerdoce pour tout ce qui concerne l''autel et pour ce qui est en dedans du voile: vous ferez ce travail. Comme une fonction en pur don, je vous confère votre sacerdoce. L''étranger qui approchera sera mis à mort. »'),
('nb',18,8,'crampon1923','Yahweh dit à Aaron: « Voici, je te donne le service de ce qui est prélevé pour moi, de toutes les choses consacrées des enfants d''Israël; je te les donne, à raison de l''onction que tu as reçue, à toi et à tes fils, par une loi perpétuelle.'),
('nb',18,9,'crampon1923','Voici ce qui te reviendra des choses très saintes, sauf ce que le feu doit consumer: toutes leurs offrandes, savoir toutes leurs oblations, tous leurs sacrifices pour le péché et tous leurs sacrifices de réparation qu''ils me rendront: tout cela, comme choses très saintes, sera pour toi et pour tes fils.'),
('nb',18,10,'crampon1923','Tu les mangeras dans un lieu très saint; tout mâle en mangera; elles seront saintes pour toi.'),
('nb',18,11,'crampon1923','Ceci encore t''appartient: ce qui est prélevé sur leurs dons, sur toute offrande balancée des enfants d''Israël; je te le donne à toi, à tes fils et à tes filles avec toi, par une loi perpétuelle; quiconque est pur dans ta maison en mangera.'),
('nb',18,12,'crampon1923','Tout le meilleur de l''huile, tout le meilleur du vin nouveau et du blé, leurs prémices qu''ils offrent à Yahweh, je te les donne.'),
('nb',18,13,'crampon1923','Les premiers produits de leur terre qu''ils apporteront à Yahweh seront pour toi. Quiconque est pur dans ta maison en mangera.'),
('nb',18,14,'crampon1923','Tout ce qui sera dévoué par anathème en Israël sera pour toi.'),
('nb',18,15,'crampon1923','Tout premier-né de toute chair, des hommes comme des animaux, qu''ils offrent à Yahweh, sera pour toi. Seulement tu feras racheter le premier-né de l''homme, et tu feras racheter le premier-né d''un animal impur.'),
('nb',18,16,'crampon1923','Quant à son rachat, tu le feras racheter dès l''âge d''un mois, selon ton estimation, contre cinq sicles d''argent, selon le sicle du sanctuaire, qui est de vingt guéras.'),
('nb',18,17,'crampon1923','Mais tu ne feras point racheter le premier-né du bœuf, ni le premier-né de la brebis, ni le premier-né de la chèvre: ils sont saints. Tu répandras leur sang sur l''autel et tu feras fumer leur graisse: c''est un sacrifice fait par le feu, d''une agréable odeur à Yahweh.'),
('nb',18,18,'crampon1923','Leur chair sera pour toi, comme la poitrine qu''on balance et comme la cuisse droite.'),
('nb',18,19,'crampon1923','Tout ce qui est prélevé sur les choses saintes, ce que les enfants d''Israël prélèvent pour Yahweh, je te le donne à toi, à tes fils et à tes filles avec toi, par une loi perpétuelle; c''est une alliance de sel, perpétuelle, devant Yahweh, pour toi et pour ta postérité avec toi. »'),
('nb',18,20,'crampon1923','Yahweh dit à Aaron: « Tu n''auras pas d''héritage dans leur pays, et il n''y aura point de part pour toi au milieu d''eux; c''est moi qui suis ta part et ton héritage au milieu des enfants d''Israël.'),
('nb',18,21,'crampon1923','Voici que je donne comme héritage aux fils de Lévi toute dîme en Israël, pour le travail qu''ils font, le travail de la tente de réunion.'),
('nb',18,22,'crampon1923','Les enfants d''Israël n''approcheront plus de la tente de réunion, de peur qu''ils ne portent leur péché et qu''ils meurent.'),
('nb',18,23,'crampon1923','Les Lévites feront le travail de la tente de réunion, et ils porteront leur iniquité. En vertu d''une loi perpétuelle parmi vos descendants, ils n''auront point d''héritage au milieu des enfants d''Israël.'),
('nb',18,24,'crampon1923','Car je donne aux Lévites comme héritage les dîmes que les enfants d''Israël prélèveront pour Yahweh; c''est pourquoi je leur dis: Ils n''auront point d''héritage au milieu des enfants d''Israël. »'),
('nb',18,25,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',18,26,'crampon1923','« Tu parleras aux Lévites et tu leur diras: “Lorsque vous recevrez des enfants d''Israël la dîme que je vous donne de leurs biens pour votre héritage, vous en prélèverez une offrande pour Yahweh, une dîme de la dîme;'),
('nb',18,27,'crampon1923','et ce prélèvement que vous ferez vous sera compté comme le blé qu''on prélève de l''aire, et comme le vin nouveau qu''on prélève de la cuve.'),
('nb',18,28,'crampon1923','C''est ainsi que vous prélèverez, vous aussi, une offrande pour Yahweh, sur toutes les dîmes que vous recevrez des enfants d''Israël, et cette offrande que vous en aurez prélevée pour Yahweh, vous la donnerez au prêtre Aaron.'),
('nb',18,29,'crampon1923','Sur tous les dons que vous recevrez, vous prélèverez toute l''offrande de Yahweh; sur tout le meilleur, la sainte portion qui en est tirée.'),
('nb',18,30,'crampon1923','Tu leur diras: Quand vous en aurez prélevé le meilleur, la dîme sera comptée aux lévites comme le produit de l''aire et comme le produit du pressoir.'),
('nb',18,31,'crampon1923','Vous la mangerez en tout lieu, vous et votre famille; car c''est votre salaire pour le travail que vous faites dans la tente de réunion.'),
('nb',18,32,'crampon1923','Vous ne porterez pour cela aucun péché, quand vous en aurez prélevé le meilleur, vous ne profanerez point les saintes offrandes des enfants d''Israël, et vous ne mourrez point.” »'),
('nb',19,1,'crampon1923','Yahweh parla à Moïse et à Aaron, en disant:'),
('nb',19,2,'crampon1923','« Voici l''ordonnance de la loi que Yahweh a prescrite, en disant: Dis aux enfants d''Israël de t''amener une vache rousse, sans tache, sans défaut corporel, et qui n''ait point porté le joug.'),
('nb',19,3,'crampon1923','Vous la remettrez au prêtre Eléazar, qui la fera sortir du camp, et on l''égorgera devant lui.'),
('nb',19,4,'crampon1923','Le prêtre Eléazar prendra du sang de la vache avec le doigt, et il fera sept fois l''aspersion de ce sang du côté de l''entrée de la tente de réunion.'),
('nb',19,5,'crampon1923','On brûlera la vache sous ses yeux; on brûlera sa peau, sa chair et son sang, ainsi que ses excréments.'),
('nb',19,6,'crampon1923','Le prêtre prendra du bois de cèdre, de l''hysope et du cramoisi, et il les jettera au milieu du feu qui consume la vache.'),
('nb',19,7,'crampon1923','Le prêtre lavera ses vêtements et baignera son corps dans l''eau; puis il rentrera dans le camp et sera impur jusqu''au soir.'),
('nb',19,8,'crampon1923','Celui qui aura brûlé la vache lavera ses vêtements dans l''eau, et baignera son corps dans l''eau, et il sera impur jusqu''au soir.'),
('nb',19,9,'crampon1923','Un homme pur recueillera la cendre de la vache et la déposera hors du camp, dans un lieu pur; on la conservera pour l''assemblée des enfants d''Israël, en vue de l''eau qui ôte la souillure: c''est un sacrifice pour le péché.'),
('nb',19,10,'crampon1923','Celui qui aura recueilli la cendre de la vache lavera ses vêtements, et sera impur jusqu''au soir. — Ce sera une loi perpétuelle pour les enfants d''Israël et pour l''étranger qui séjourne au milieu d''eux.'),
('nb',19,11,'crampon1923','Celui qui touchera un mort, un corps humain quelconque, sera impur pendant sept jours.'),
('nb',19,12,'crampon1923','Il se purifiera avec cette eau le troisième jour et le septième jour, et il sera pur; mais s''il ne se purifie pas le troisième jour et le septième jour, il ne sera pas pur.'),
('nb',19,13,'crampon1923','Celui qui touchera un mort, le corps d''un homme qui est mort, et qui ne se purifiera pas, souillera la Demeure de Yahweh; cet homme sera retranché d''Israël. Parce que l''eau qui ôte la souillure n''a pas été répandue sur lui, il est impur, et sa souillure est encore sur lui.'),
('nb',19,14,'crampon1923','Voici la loi. Lorsqu''un homme meurt dans une tente, quiconque entre dans la tente et tout ce qui se trouve dans la tente sera impur pendant sept jours.'),
('nb',19,15,'crampon1923','Tout vase découvert, sur lequel il n''y a point de couvercle attaché, est impur.'),
('nb',19,16,'crampon1923','Quiconque touche dans les champs un homme tué par l''épée, ou un mort, ou des ossements humains, ou un sépulcre, sera impur pendant sept jours.'),
('nb',19,17,'crampon1923','On prendra, pour celui qui est impur, de la cendre de la victime, consumée en sacrifice expiatoire, et l''on mettra dessus de l''eau vive dans un vase.'),
('nb',19,18,'crampon1923','Un homme pur prendra de l''hysope et, l''ayant trempée dans l''eau, il en fera l''aspersion sur la tente, sur tous les ustensiles et sur les personnes qui étaient là, sur celui qui a touché des ossements, ou un homme tué, ou un mort, ou un sépulcre.'),
('nb',19,19,'crampon1923','L''homme pur fera l''aspersion sur celui qui est impur, le troisième jour et le septième jour, et il lui ôtera son péché le septième jour. L''homme impur lavera ses vêtements et se baignera dans l''eau, et le soir il sera pur.'),
('nb',19,20,'crampon1923','L''homme qui sera devenu impur et qui ne se purifiera pas, sera retranché du milieu de l''assemblée, car il souille le sanctuaire de Yahweh; parce que l''eau qui ôte la souillure n''a pas été répandue sur lui, il est impur.'),
('nb',19,21,'crampon1923','Ce sera pour eux une loi perpétuelle. Celui qui aura fait l''aspersion de l''eau qui ôte la souillure lavera ses vêtements, et celui qui touchera l''eau qui ôte la souillure, sera impur jusqu''au soir.'),
('nb',19,22,'crampon1923','Tout ce que touchera celui qui est impur sera souillé, et la personne qui le touchera sera impure jusqu''au soir. »'),
('nb',20,1,'crampon1923','Les enfants d''Israël, toute l''assemblée, arrivèrent au désert de Sin, dans le premier mois, et le peuple séjourna à Cadès. C''est là que mourut Marie et qu''elle fut enterrée.'),
('nb',20,2,'crampon1923','Comme il n''y avait pas d''eau pour l''assemblée, ils s''attroupèrent contre Moïse et Aaron.'),
('nb',20,3,'crampon1923','Le peuple disputa avec Moïse, et ils dirent: « Que n''avons-nous péri quand nos frères périrent devant Yahweh?'),
('nb',20,4,'crampon1923','Pourquoi avez-vous fait venir l''assemblée de Yahweh dans ce désert, pour que nous y mourions, nous et notre bétail?'),
('nb',20,5,'crampon1923','Pourquoi nous avez-vous fait monter d''Egypte, pour nous amener dans ce méchant lieu? Ce n''est pas un lieu où l''on puisse semer, et il n''y a ni figuier, ni vigne, ni grenadier, ni même d''eau à boire? »'),
('nb',20,6,'crampon1923','Moïse et Aaron, s''éloignant de l''assemblée, vinrent à l''entrée de la tente de réunion. Ils tombèrent sur leur visage, et la gloire de Yahweh leur apparut.'),
('nb',20,7,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',20,8,'crampon1923','« Prends le bâton et convoque l''assemblée, toi et ton frère Aaron; vous parlerez au rocher en leur présence, afin qu''il donne ses eaux; et tu feras sortir pour eux de l''eau du rocher, et tu donneras à boire à l''assemblée et à son bétail. »'),
('nb',20,9,'crampon1923','Moïse prit le bâton qui était devant Yahweh, comme Yahweh le lui avait ordonné.'),
('nb',20,10,'crampon1923','Puis Moïse et Aaron convoquèrent l''assemblée en face du rocher, et Moïse leur dit: « Ecoutez-donc, rebelles! Vous ferons-nous sortir de l''eau de ce rocher? »'),
('nb',20,11,'crampon1923','Moïse leva la main et frappa deux fois le rocher de son bâton; et il sortit de l''eau en abondance. L''assemblée but, ainsi que le bétail.'),
('nb',20,12,'crampon1923','Alors Yahweh dit à Moïse et à Aaron: « Parce que vous n''avez pas cru en moi, pour me sanctifier aux yeux des enfants d''Israël, vous ne ferez point entrer cette assemblée dans le pays que je lui donne. »'),
('nb',20,13,'crampon1923','Ce sont là les eaux de Mériba, où les enfants d''Israël contestèrent avec Yahweh, et il se sanctifia en eux.'),
('nb',20,14,'crampon1923','De Cadès, Moïse envoya des messages au roi d''Edom, pour lui dire: « Ainsi parle ton frère Israël: Tu sais toutes les souffrances que nous avons endurées.'),
('nb',20,15,'crampon1923','Nos pères descendirent en Egypte, et nous y demeurâmes longtemps; mais les Egyptiens nous maltraitèrent, nous et nos pères.'),
('nb',20,16,'crampon1923','Nous avons crié à Yahweh, et il a entendu notre voix; il a envoyé un ange et nous a fait sortir d''Egypte. Et voici que nous sommes à Cadès, ville située à la limite de ton territoire.'),
('nb',20,17,'crampon1923','Laisse-nous, de grâce, traverser ton pays; nous ne traverserons ni les champs, ni les vignes, et nous ne boirons pas l''eau des puits; mais nous suivrons la route royale, sans nous détourner à droite ou à gauche, jusqu''à ce que nous ayons traversé ton territoire. »'),
('nb',20,18,'crampon1923','Edom lui dit: « Tu ne passeras point chez moi, sinon je sortirai à ta rencontre avec l''épée. »'),
('nb',20,19,'crampon1923','Les enfants d''Israël lui dirent: « Nous monterons par la grande route, et, si nous buvons de ton eau, moi et mes troupeaux, j''en paierai le prix. Ce n''est pas une affaire; je ne ferai que passer avec mes pieds. »'),
('nb',20,20,'crampon1923','Il répondit: « Tu ne passeras pas! » Et Edom sortit à sa rencontre avec un peuple nombreux et à main forte.'),
('nb',20,21,'crampon1923','C''est ainsi qu''Edom refusa de donner passage à Israël sur son territoire; et Israël se détourna de lui.'),
('nb',20,22,'crampon1923','Les enfants d''Israël, toute l''assemblée, partirent de Cadès et arrivèrent à la montagne de Hor.'),
('nb',20,23,'crampon1923','Yahweh dit à Moïse et à Aaron, à la montagne de Hor, sur la frontière du pays d''Edom:'),
('nb',20,24,'crampon1923','« Aaron va être recueilli auprès de son peuple; car il n''entrera point dans le pays que je donne aux enfants d''Israël, parce que vous avez été rebelles à mon ordre, aux eaux de Mériba.'),
('nb',20,25,'crampon1923','Prends Aaron et son fils Eléazar, et fais-les monter sur la montagne de Hor.'),
('nb',20,26,'crampon1923','Tu dépouilleras Aaron de ses vêtements et tu en feras revêtir Eléazar, son fils. C''est là qu''Aaron sera recueilli et mourra. »'),
('nb',20,27,'crampon1923','Moïse fit ce qui Yahweh avait ordonné; ils montèrent sur la montagne de Hor, aux yeux de toute l''assemblée;'),
('nb',20,28,'crampon1923','puis Moïse, ayant dépouillé Aaron de ses vêtements, les fit revêtir à Eléazar, son fils; et Aaron mourut là, au sommet de la montagne, et Moïse et Eléazar descendirent de la montagne.'),
('nb',20,29,'crampon1923','Toute l''assemblée vit qu''Aaron avait expiré, et toute la maison d''Israël pleura Aaron pendant trente jours.'),
('nb',21,1,'crampon1923','Le Chananéen, roi d''Arad, qui habitait le Négeb, apprit qu''Israël venait par le chemin d''Atharim. Il livra bataille à Israël et lui fit des prisonniers.'),
('nb',21,2,'crampon1923','Alors Israël fit un vœu à Yahweh, en disant: « Si vous livrez ce peuple entre mes mains, je dévouerai ses villes à l''anathème. »'),
('nb',21,3,'crampon1923','Yahweh entendit la voix d''Israël et livra les Chananéens; on les dévoua à l''anathème, eux et leurs villes, et on nomma ce lieu Horma.'),
('nb',21,4,'crampon1923','Ils partirent de la montagne de Hor par le chemin de la mer Rouge, pour tourner le pays d''Edom. Le peuple perdit patience dans ce chemin,'),
('nb',21,5,'crampon1923','et il parla contre Dieu et contre Moïse: « Pourquoi nous avez-vous fait monter d''Egypte, pour que nous mourions dans le désert? Il n''y a point de pain, il n''y a point d''eau, et notre âme a pris en dégoût cette misérable nourriture. »'),
('nb',21,6,'crampon1923','Alors Yahweh envoya contre le peuple les serpents brûlants; ils mordirent le peuple, et il mourut beaucoup de gens en Israël.'),
('nb',21,7,'crampon1923','Le peuple vint à Moïse et dit: « Nous avons péché, car nous avons parlé contre Yahweh et contre toi. Prie Yahweh, afin qu''il éloigne de nous ces serpents. » Moïse pria pour le peuple.'),
('nb',21,8,'crampon1923','Et Yahweh dit à Moïse: « Fais-toi un serpent brûlant et place-le sur un poteau; quiconque aura été mordu et le regardera, conservera la vie. »'),
('nb',21,9,'crampon1923','Moïse fit un serpent d''airain et le plaça sur un poteau, et, si quelqu''un était mordu par un serpent, il regardait le serpent d''airain, et il vivait.'),
('nb',21,10,'crampon1923','Les enfants d''Israël partirent, et ils campèrent à Oboth.'),
('nb',21,11,'crampon1923','Ils partirent d''Oboth, et ils campèrent à Jeabarim, dans le désert qui est vis-à-vis de Moab, vers le soleil levant.'),
('nb',21,12,'crampon1923','Ils partirent de là, et campèrent dans la vallée de Zared.'),
('nb',21,13,'crampon1923','Ils partirent de là, et campèrent au-delà de l''Arnon, qui coule dans le désert, en sortant du territoire des Amorrhéens; car l''Arnon est la frontière de Moab, entre Moab et les Amorrhéens.'),
('nb',21,14,'crampon1923','C''est pourquoi il est dit dans le livre des Guerres de Yahweh: « Yahweh a pris Vaheb, dans sa course impétueuse, et les torrents de l''Arnon,'),
('nb',21,15,'crampon1923','et la pente des torrents qui s''étend vers le site d''Ar et s''appuie à la frontière de Moab. »'),
('nb',21,16,'crampon1923','De là ils allèrent à Beer. C''est le puits à propos duquel Yahweh dit à Moïse: « Rassemble le peuple, et je leur donnerai de l''eau. »'),
('nb',21,17,'crampon1923','Alors Israël chanta ce cantique: Monte, puits! Acclamez-le!'),
('nb',21,18,'crampon1923','Le puits, que des princes ont creusé, que les grands du peuple ont ouvert, avec le sceptre, avec leurs bâtons! Du désert ils allèrent à Matthana;'),
('nb',21,19,'crampon1923','de Matthana à Nahaliel; de Nahaliel, à Bamoth;'),
('nb',21,20,'crampon1923','de Bamoth, à la vallée qui est dans les champs de Moab, au sommet du Phasga, qui domine le désert.'),
('nb',21,21,'crampon1923','Israël envoya des messagers à Séhon, roi des Amorrhéens, pour lui dire:'),
('nb',21,22,'crampon1923','« Laisse-moi passer par ton pays; nous ne nous écarterons ni dans les champs, ni dans les vignes, et nous ne boirons pas l''eau des puits; nous suivrons la route royale, jusqu''à ce que nous ayons franchi ton territoire. »'),
('nb',21,23,'crampon1923','Séhon ne permit pas à Israël de passer sur son territoire; il rassembla tout son peuple et, étant sorti à la rencontre d''Israël dans le désert, il vint à Jasa et livra bataille à Israël.'),
('nb',21,24,'crampon1923','Israël le frappa du tranchant de l''épée, et se rendit maître de son pays depuis l''Arnon jusqu''au Jaboc, jusqu''aux enfants d''Ammon; car la frontière des enfants d''Ammon était forte.'),
('nb',21,25,'crampon1923','Israël prit toutes ces villes et Israël s''établit dans toutes les villes des Amorrhéens, à Hésebon et dans toutes les villes de son ressort.'),
('nb',21,26,'crampon1923','Car Hésebon était la ville de Séhon, roi des Amorrhéens, qui avait fait la guerre au précédent roi de Moab et lui avait enlevé tout son pays jusqu''à l''Arnon.'),
('nb',21,27,'crampon1923','C''est pourquoi les poètes disent: Venez à Hésebon! Que la ville de Séhon soit rebâtie et fortifiée!'),
('nb',21,28,'crampon1923','Car il est sorti un feu de Hésebon, une flamme de la ville de Séhon; elle a dévoré Ar-Moab. Les maîtres des hauteurs de l''Arnon.'),
('nb',21,29,'crampon1923','Malheur à toi, Moab! Tu es perdu, peuple de Chamos! Il a livré ses fils fugitifs et ses filles captives à Séhon, roi des Amorrhéens.'),
('nb',21,30,'crampon1923','Et nous avons lancé sur eux nos traits; Hésebon est détruite jusqu''à Dibon; nous avons dévasté jusqu''à Nophé, avec le feu jusqu''à Médaba.'),
('nb',21,31,'crampon1923','Israël s''établit dans le pays des Amorrhéens.'),
('nb',21,32,'crampon1923','Moïse envoya reconnaître Jaser; et ils prirent les villes de son ressort, et expulsèrent les Amorrhéens qui y étaient.'),
('nb',21,33,'crampon1923','Puis, changeant de direction, ils montèrent par le chemin de Basan. Og, roi de Basan, sortit à leur rencontre, avec tout son peuple, pour les combattre à Edraï.'),
('nb',21,34,'crampon1923','Yahweh dit à Moïse: « Ne le crains point, car je le livre entre tes mains, lui, tout son peuple et son pays; tu le traiteras comme tu as traité Séhon, roi des Amorrhéens, qui habitait à Hésebon. »'),
('nb',21,35,'crampon1923','Et ils le battirent, lui et ses fils, et tout son peuple, jusqu''à ne pas lui laisser de survivant, et ils s''emparèrent de son pays.'),
('nb',22,1,'crampon1923','Les enfants d''Israël, étant partis, campèrent dans les plaines de Moab, au-delà du Jourdain, vis-à-vis de Jéricho.'),
('nb',22,2,'crampon1923','Balac, fils de Séphor, vit tout ce qu''Israël avait fait aux Amorrhéens;'),
('nb',22,3,'crampon1923','et Moab fut très effrayé en face du peuple, car celui-ci était nombreux; il fut saisi d''épouvante en face des enfants d''Israël.'),
('nb',22,4,'crampon1923','Moab dit aux anciens de Madian: « Cette multitude va dévorer tout ce qui nous entoure, comme le bœuf dévore la verdure des champs. » — Balac, fils de Séphor était alors roi de Moab. —'),
('nb',22,5,'crampon1923','Il envoya des messagers à Balaam, fils de Béor, à Péthor, qui est sur le Fleuve, dans le pays des fils de son peuple, pour l''appeler et lui dire: « Voici, un peuple est sorti d''Egypte; il couvre la face de la terre, et il habite vis-à-vis de moi.'),
('nb',22,6,'crampon1923','Viens donc, je te prie, maudis-moi ce peuple, car il est plus puissant que moi; peut-être ainsi pourrai-je le battre et le jeter hors du pays; car je sais que celui que tu bénis est béni, et que celui que tu maudis est maudit. »'),
('nb',22,7,'crampon1923','Les anciens de Moab et les anciens de Madian se mirent en route, emportant avec eux le salaire du devin. Arrivés auprès de Balaam, ils lui rapportèrent les paroles de Balac.'),
('nb',22,8,'crampon1923','Balaam leur dit: « Passez ici la nuit, et je vous donnerai réponse, selon ce que Yahweh me dira. » Et les princes de Moab restèrent chez Balaam.'),
('nb',22,9,'crampon1923','Dieu vint à Balaam et lui dit: « Qui sont ces hommes que tu as chez toi? »'),
('nb',22,10,'crampon1923','Balaam répondit à Dieu: « Balac, fils de Séphor, roi de Moab, les a envoyés pour me dire:'),
('nb',22,11,'crampon1923','Voici, le peuple qui est sorti d''Egypte couvre la face de la terre; viens donc, maudis-le-moi; peut-être ainsi pourrai-je le combattre et le chasser. »'),
('nb',22,12,'crampon1923','Dieu dit à Balaam: « Tu n''iras pas avec eux; tu ne maudiras pas ce peuple, car il est béni. »'),
('nb',22,13,'crampon1923','Le matin, Balaam, s''étant levé, dit aux princes de Balac: « Allez dans votre pays, car Yahweh refuse de me laisser aller avec vous. »'),
('nb',22,14,'crampon1923','Alors les princes de Moab se levèrent et retournèrent vers Balac, et ils dirent: « Balaam a refusé de venir avec nous. »'),
('nb',22,15,'crampon1923','Balac envoya de nouveau des princes en plus grand nombre et de plus haut rang que les premiers.'),
('nb',22,16,'crampon1923','Arrivés auprès de Balaam, ils lui dirent: « Ainsi parle Balac, fils de Séphor: « Que rien, je te prie, ne t''empêche de venir vers moi;'),
('nb',22,17,'crampon1923','car je te rendrai les plus grands honneurs, et je ferai tout ce que tu me diras. Mais viens, je te prie; maudis-moi ce peuple. »'),
('nb',22,18,'crampon1923','Balaam répondit et dit aux serviteurs de Balac: « Quand Balac me donnerait plein sa maison d''argent et d''or, je ne pourrai transgresser l''ordre de Yahweh mon Dieu, en faisant une chose, petite ou grande.'),
('nb',22,19,'crampon1923','Maintenant, je vous prie, restez ici, vous aussi, cette nuit, que je sache ce que Yahweh me dira encore. »'),
('nb',22,20,'crampon1923','Dieu vint à Balaam dans la nuit, et lui dit: « Si ces hommes sont venus pour t''appeler, lève-toi et va avec eux; mais tu feras ce que je te dirai. »'),
('nb',22,21,'crampon1923','Balaam se leva le matin et, ayant sellé son ânesse, il partit avec les princes de Moab.'),
('nb',22,22,'crampon1923','La colère de Dieu s''alluma parce qu''il allait, et l''ange de Yahweh se plaça sur le chemin, pour lui faire obstacle. — Balaam était monté sur son ânesse, et il avait avec lui ses deux serviteurs. —'),
('nb',22,23,'crampon1923','L''ânesse vit l''ange de Yahweh qui se tenait sur le chemin, son épée nue à la main; elle se détourna du chemin et alla dans les champs; et Balaam frappa l''ânesse pour la ramener dans le chemin.'),
('nb',22,24,'crampon1923','Alors l''ange de Yahweh se tint dans un chemin creux entre les vignes, où il y avait une clôture de chaque côté.'),
('nb',22,25,'crampon1923','Voyant l''ange de Yahweh, l''ânesse se serra contre le mur, et pressa contre le mur le pied de Balaam, et celui-ci la frappa de nouveau.'),
('nb',22,26,'crampon1923','L''ange de Yahweh passa plus loin et se tint dans un lieu étroit où il n''y avait pas d''espace pour se détourner à droite ou à gauche.'),
('nb',22,27,'crampon1923','L''ânesse, en voyant l''ange de Yahweh, se coucha sous Balaam, et la colère de Balaam s''enflamma, et il frappa l''ânesse de son bâton.'),
('nb',22,28,'crampon1923','Yahweh ouvrit la bouche de l''ânesse, et elle dit à Balaam: « Que t''ai-je fait, que tu m''aies frappée ces trois fois? »'),
('nb',22,29,'crampon1923','Balaam répondit à l''ânesse: « C''est parce que tu t''es jouée de moi; si j''avais une épée dans la main, je te tuerais à l''instant. »'),
('nb',22,30,'crampon1923','L''ânesse dit à Balaam: « Ne suis-je pas ton ânesse, que tu as toujours montée jusqu''à présent? Ai-je l''habitude d''agir ainsi envers toi? » Et il répondit: « Non. »'),
('nb',22,31,'crampon1923','Yahweh ouvrit les yeux de Balaam, et Balaam vit l''ange de Yahweh qui se tenait sur le chemin, son épée nue dans la main; et il s''inclina et se prosterna sur son visage.'),
('nb',22,32,'crampon1923','L''ange de Yahweh lui dit: « Pourquoi as-tu frappé ton ânesse ces trois fois? Voici, je suis sorti pour te faire obstacle, car, à mes yeux, le chemin que tu suis te mène à la ruine.'),
('nb',22,33,'crampon1923','L''ânesse m''a vu; et elle s''est détournée devant moi ces trois fois; si elle ne s''était pas détournée devant moi, je t''aurais tué, toi, et je lui aurais laissé la vie. »'),
('nb',22,34,'crampon1923','Balaam dit à l''ange de Yahweh: « J''ai péché, car je ne savais pas que tu te tenais devant moi sur le chemin; et maintenant, si cela te déplaît, je m''en retournerai. »'),
('nb',22,35,'crampon1923','L''ange de Yahweh dit à Balaam: « Va avec ces hommes; mais tu ne diras pas autre chose que ce que je te dirai. » Et Balaam alla avec les princes de Balac.'),
('nb',22,36,'crampon1923','Balac, ayant appris que Balaam arrivait, sortit à sa rencontre jusqu''à la ville de Moab, qui est sur la frontière de l''Arnon, à l''extrême frontière.'),
('nb',22,37,'crampon1923','Balac dit à Balaam: « N''avais-je pas envoyé déjà vers toi pour t''appeler? Pourquoi n''es-tu pas venu vers moi? Ne puis-je pas en vérité te traiter avec honneur? »'),
('nb',22,38,'crampon1923','Balaam dit à Balac: « Voici, je suis venu vers toi; mais maintenant pourrai-je dire quoi que ce soit? Les paroles que Dieu mettra dans ma bouche, je les dirai. »'),
('nb',22,39,'crampon1923','Balaam se mit en route avec Balac, et ils arrivèrent à Qiriath-Chutsoth.'),
('nb',22,40,'crampon1923','Balac immola en sacrifice des bœufs et des brebis, et il en envoya des portions à Balaam et aux princes qui étaient avec lui.'),
('nb',22,41,'crampon1923','Le matin, Balac prit avec lui Balaam et le fit monter à Bamoth-Baal, d''où Balaam put apercevoir les derniers rangs du peuple.'),
('nb',23,1,'crampon1923','Balaam dit à Balac: « Bâtis-moi ici sept autels, et prépare-moi ici sept taureaux et sept béliers. »'),
('nb',23,2,'crampon1923','Balac fit ce que Balaam avait dit, et Balac avec Balaam offrit un taureau et un bélier sur chaque autel.'),
('nb',23,3,'crampon1923','Balaam dit à Balac: « Tiens-toi près de ton holocauste, et je m''éloignerai; peut-être que Yahweh viendra à ma rencontre et quoi qu''il me fasse voir, je te le dirai. » Et il s''en alla sur une hauteur dénudée.'),
('nb',23,4,'crampon1923','Dieu vint à la rencontre de Balaam, qui lui dit: « J''ai dressé les sept autels, et j''ai offert sur chaque autel un taureau et un bélier. »'),
('nb',23,5,'crampon1923','Yahweh mit une parole dans la bouche de Balaam et dit: « Retourne auprès de Balac, et parle-lui ainsi. »'),
('nb',23,6,'crampon1923','Il retourna vers lui, et voici, Balac se tenait près de son holocauste, lui et tous les princes de Moab.'),
('nb',23,7,'crampon1923','Et Balaam prononça son discours en disant: D''Aram, Balac m''a fait venir, le roi de Moab m''a fait venir des montagnes de l''Orient: « Viens, maudis-moi Jacob! Viens, courrouce-toi contre Israël! »'),
('nb',23,8,'crampon1923','Comment maudirai-je quand Dieu ne maudit pas? Comment me courroucerai-je, quand Yahweh n''est pas courroucé?'),
('nb',23,9,'crampon1923','Car du sommet des rochers je le vois, du haut des collines je le considère: c''est un peuple qui a sa demeure à part, et qui ne sera pas mis au nombre des nations.'),
('nb',23,10,'crampon1923','Qui peut compter la poussière de Jacob, et dénombrer le quart d''Israël? Que je meure de la mort des justes, et que ma fin soit semblable à la leur!'),
('nb',23,11,'crampon1923','Balac dit à Balaam: « Que m''as-tu fait? Je t''ai pris pour maudire mes ennemis, et voilà, tu ne fais que bénir! »'),
('nb',23,12,'crampon1923','Il répondit et dit: « Ne dois-je pas avoir soin de dire ce que Yahweh met dans ma bouche? »'),
('nb',23,13,'crampon1923','Balac lui dit: « Viens avec moi à une autre place, d''où tu le verras; tu en verras seulement l''extrémité, sans le voir tout entier; et de là, maudis-le-moi. »'),
('nb',23,14,'crampon1923','Il le mena au champ des Sentinelles, sur le sommet de Phasga; et, ayant bâti sept autels, il offrit un taureau et un bélier sur chaque autel.'),
('nb',23,15,'crampon1923','Et Balaam dit à Balac: « Tiens-toi ici près de ton holocauste, et moi j''irai là à la rencontre de Dieu. »'),
('nb',23,16,'crampon1923','Yahweh vint à la rencontre de Balaam, et il mit une parole dans sa bouche et dit: « Retourne vers Balac, et tu parleras ainsi. »'),
('nb',23,17,'crampon1923','Il retourna vers lui, et voici, Balac se tenait près de son holocauste, et les princes de Moab avec lui. Balac lui dit: « Qu''a dit Yahweh? »'),
('nb',23,18,'crampon1923','Et Balaam prononça son discours, en disant: Lève-toi, Balac, et écoute: prête-moi l''oreille, fils de Séphor:'),
('nb',23,19,'crampon1923','Dieu n''est point un homme pour mentir, ni un fils d''homme pour se repentir. Est-ce lui qui dit et ne fais pas, qui parle et n''exécute pas?'),
('nb',23,20,'crampon1923','Voici, j''ai reçu ordre de bénir; il a béni: je ne révoquerai point.'),
('nb',23,21,'crampon1923','Il n''aperçoit pas d''iniquité en Jacob, il ne voit pas d''injustice en Israël. Yahweh, son Dieu, est avec lui, chez lui retentit l''acclamation d''un roi.'),
('nb',23,22,'crampon1923','Dieu les fait sortir d''Egypte, sa vigueur est comme celle du buffle.'),
('nb',23,23,'crampon1923','Parce qu''il n''y a pas de magie en Jacob, ni de divination en Israël, en son temps il sera dit à Jacob et à Israël ce que Dieu veut accomplir.'),
('nb',23,24,'crampon1923','Voici un peuple qui se lève comme une lionne, et qui se dresse comme un lion; il ne se couche point qu''il n''ait dévoré sa proie, et qu''il n''ait bu le sang des blessés.'),
('nb',23,25,'crampon1923','Balac dit à Balaam: « Ne le maudis pas et ne le bénis pas. »'),
('nb',23,26,'crampon1923','Balaam répondit et dit à Balac: « Ne t''ai-je pas parlé ainsi: Je ferai tout ce que dira Yahweh? »'),
('nb',23,27,'crampon1923','Balac dit à Balaam: « Viens donc, je te mènerai à une autre place; peut-être plaira-t-il au regard de Dieu que de là tu me le maudisses. »'),
('nb',23,28,'crampon1923','Balac mena Balaam sur le sommet du Phogor, qui domine le désert.'),
('nb',23,29,'crampon1923','Et Balaam dit à Balac: « Bâtis-moi ici sept autels, et prépare-moi ici sept taureaux et sept béliers. »'),
('nb',23,30,'crampon1923','Balac fit ce que Balaam avait dit, et il offrit un taureau et un bélier sur chaque autel.'),
('nb',24,1,'crampon1923','Balaam vit que Yahweh avait pour agréable de bénir Israël, et il n''alla pas, comme les autres fois, à la rencontre des signes magiques; mais il tourna son visage du côté du désert.'),
('nb',24,2,'crampon1923','Ayant levé les yeux, il vit Israël campé par tribus; et l''Esprit de Dieu fut sur lui,'),
('nb',24,3,'crampon1923','et il prononça son discours, en disant: Oracle de Balaam fils de Béor, oracle de l''homme dont l''œil est fermé;'),
('nb',24,4,'crampon1923','oracle de celui qui entend les paroles de Dieu, qui contemple la vision du Tout-Puissant, qui tombe, et dont les yeux s''ouvrent.'),
('nb',24,5,'crampon1923','Qu''elles sont belles tes tentes, ô Jacob, tes demeures, ô Israël!'),
('nb',24,6,'crampon1923','Elles s''étendent comme des vallées, comme des jardins au bord d''un fleuve, comme des aloès que Yahweh a plantés, comme des cèdres sur le bord des eaux.'),
('nb',24,7,'crampon1923','L''eau déborde de ses deux seaux, sa race croît sur des eaux abondantes, son roi s''élève au-dessus d''Agag, et son royaume est exalté!'),
('nb',24,8,'crampon1923','Dieu le fait sortir d''Egypte: il lui donne la vigueur du buffle. Il dévore les nations qui lui font la guerre. Il brise leurs os et les foudroie de ses flèches.'),
('nb',24,9,'crampon1923','Il ploie les genoux, il se couche comme un lion, comme une lionne; qui le fera lever? Béni soit qui te bénira et maudit soit qui te maudira!'),
('nb',24,10,'crampon1923','La colère de Balac s''enflamma contre Balaam, et il frappa des mains; et Balac dit à Balaam: « Je t''ai appelé pour maudire mes ennemis, et voici, tu n''as fait que les bénir ces trois fois!'),
('nb',24,11,'crampon1923','Et maintenant fuis, va-t''en chez toi! J''avais dit que je te comblerais d''honneur; et voici, Yahweh t''écarte de l''honneur. »'),
('nb',24,12,'crampon1923','Balaam répondit à Balac: « N''ai-je pas dit à tes messagers que tu m''as envoyés:'),
('nb',24,13,'crampon1923','Quand Balac me donnerait plein sa maison d''argent et d''or, je ne pourrai transgresser l''ordre de Yahweh, en faisant de moi-même une chose bonne ou mauvaise; mais ce que Yahweh me dira, je le dirai?'),
('nb',24,14,'crampon1923','Et maintenant, voici, je m''en vais vers mon peuple; viens donc, que je t''annonce ce que ce peuple fera à ton peuple dans la suite des jours. »'),
('nb',24,15,'crampon1923','Et Balaam prononça son discours et dit: Oracle de Balaam, fils de Béor, oracle de l''homme dont l''œil est fermé;'),
('nb',24,16,'crampon1923','oracle de celui qui entend les paroles de Dieu, qui connaît la science du Très-Haut, qui contemple la vision du Tout-puissant, qui tombe, et dont les yeux s''ouvrent.'),
('nb',24,17,'crampon1923','Je le vois, mais non comme présent; je le contemple, mais non de près. Un astre sort de Jacob, un sceptre s''élève d''Israël. Il brise les deux flancs de Moab, il extermine tous les fils du tumulte.'),
('nb',24,18,'crampon1923','Edom est sa possession; Séïr, son ennemi, est sa possession, et Israël déploie sa vaillance.'),
('nb',24,19,'crampon1923','De Jacob sort un dominateur, il fait périr dans les villes ce qui reste d''Edom.'),
('nb',24,20,'crampon1923','Balaam vit Amalec, et il prononça son discours et dit: Amalec est la première des nations et sa fin sera la ruine.'),
('nb',24,21,'crampon1923','Balaam vit le Cinéen, et il prononça son discours et dit: Ta demeure est solide, et ton nid posé sur le roc.'),
('nb',24,22,'crampon1923','Toutefois le Cinéen ira se consumant; jusqu''à quand? Assur l''emmènera en captivité.'),
('nb',24,23,'crampon1923','Balaam prononça son discours et dit: Hélas! qui subsistera quand Dieu fera cela?'),
('nb',24,24,'crampon1923','Des navires viennent de Citthim; ils oppriment Assur, ils oppriment Héber, et lui aussi est voué à la ruine.'),
('nb',24,25,'crampon1923','Balaam s''étant levé, se mit en route et s''en retourna chez lui; Balac s''en alla aussi de son côté.'),
('nb',25,1,'crampon1923','Pendant qu''Israël demeurait à Settim, le peuple commença à se livrer à la débauche avec les filles de Moab.'),
('nb',25,2,'crampon1923','Elles invitèrent le peuple au sacrifice de leurs dieux. Et le peuple mangea et se prosterna devant leurs dieux.'),
('nb',25,3,'crampon1923','Israël s''attacha à Béelphégor, et la colère de Yahweh s''enflamma contre Israël.'),
('nb',25,4,'crampon1923','Yahweh dit à Moïse: « Assemble tous les chefs du peuple, et pends les coupables devant Yahweh, à la face du soleil, afin que le feu de la colère de Yahweh se détourne d''Israël. »'),
('nb',25,5,'crampon1923','Et Moïse dit aux juges d''Israël: « Que chacun de vous mette à mort ceux de ses gens qui se sont attachés à Béelphégor. »'),
('nb',25,6,'crampon1923','Et voici qu''un homme des enfants d''Israël vint et amena vers ses frères une Madianite, sous les yeux de Moïse et sous les yeux de toute l''assemblée des enfants d''Israël, qui pleuraient à l''entrée de la tente de réunion.'),
('nb',25,7,'crampon1923','A cette vue, Phinées, fils d''Eléazar, fils d''Aaron, le prêtre, se leva du milieu de l''assemblée; il prit une lance dans sa main,'),
('nb',25,8,'crampon1923','suivit l''homme d''Israël dans l''arrière-tente, et les perça tous deux, l''homme d''Israël et la femme, par le ventre. Alors la plaie s''arrêta parmi les enfants d''Israël.'),
('nb',25,9,'crampon1923','Il y en eut vingt-quatre mille qui moururent de la plaie.'),
('nb',25,10,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',25,11,'crampon1923','« Phinées, fils d''Eléazar, fils d''Aaron, le prêtre, a détourné ma fureur de dessus les enfants d''Israël, parce qu''il a été animé de ma jalousie au milieu d''eux; et je n''ai point, dans ma jalousie, consumé les enfants d''Israël.'),
('nb',25,12,'crampon1923','C''est pourquoi dis: Je lui accorde mon alliance de paix:'),
('nb',25,13,'crampon1923','ce sera, pour lui et pour sa postérité après lui, l''alliance d''un sacerdoce perpétuel, parce qu''il a été jaloux pour son Dieu, et qu''il a fait l''expiation pour les enfants d''Israël. »'),
('nb',25,14,'crampon1923','L''homme d''Israël qui fut tué avec la Madianite s''appelait Zamri, fils de Salu; il était prince d''une maison patriarcale des Siméonites.'),
('nb',25,15,'crampon1923','La femme Madianite qui fut tuée s''appelait Cozbi, fille de Sur, chef de tribu, de maison patriarcale en Madian.'),
('nb',25,16,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',25,17,'crampon1923','« Traitez les Madianites en ennemis, et tuez-les;'),
('nb',25,18,'crampon1923','car ils ont agi en ennemis à votre égard, en vous séduisant par leurs ruses, au moyen de Phogor, au moyen de Cozbi, fille d''un chef de Madian, leur sœur, qui fut tuée le jour de la plaie survenue à l''occasion de Phogor. »'),
('nb',25,19,'crampon1923','A la suite de cette plaie,'),
('nb',26,1,'crampon1923','Yahweh parla à Moïse et à Eléazar, fils d''Aaron, le prêtre, en disant:'),
('nb',26,2,'crampon1923','« Faites le compte de toute l''assemblée des enfants d''Israël depuis l''âge de vingt ans et au-dessus, selon leurs maisons patriarcales, de tous les hommes d''Israël en état de porter les armes. »'),
('nb',26,3,'crampon1923','Moïse et le prêtre Eléazar leur parlèrent donc dans les plaines de Moab, près du Jourdain, vis-à-vis de Jéricho, en disant:'),
('nb',26,4,'crampon1923','« Vous ferez le recensement du peuple depuis l''âge de vingt ans et au-dessus, comme Yahweh l''a ordonné à Moïse et aux enfants d''Israël, à leur sortie du pays d''Egypte. »'),
('nb',26,5,'crampon1923','Ruben, premier-né d''Israël. Fils de Ruben: de Hénoch, la famille des Hénochites; de Phallu, la famille des Phalluites;'),
('nb',26,6,'crampon1923','de Hesron, la famille des Hesronites; de Charmi, la famille des Charmites.'),
('nb',26,7,'crampon1923','Telles sont les familles des Rubénites; leurs recensés furent quarante-trois mille sept cent trente. —'),
('nb',26,8,'crampon1923','Fils de Phallu, Eliab. —'),
('nb',26,9,'crampon1923','Fils d''Eliab: Namuel, Dathan et Abiron. C''est ce Dathan et cet Abiron, membres du conseil, qui se soulevèrent contre Moïse et Aaron, dans la troupe de Coré, lorsqu''elle se souleva contre Yahweh.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('nb',26,10,'crampon1923','La terre, ouvrant sa bouche, les engloutit avec Coré, quand la troupe périt, et que le feu consuma les deux cent cinquante hommes: ils servirent d''exemple.'),
('nb',26,11,'crampon1923','Mais les fils de Coré ne moururent pas.'),
('nb',26,12,'crampon1923','Fils de Siméon, selon leurs familles: de Namuel, la famille des Namuélites; de Jamin, la famille des Jaminites; de Jachin, la famille des Jachinites;'),
('nb',26,13,'crampon1923','de Zaré la famille des Zaréites; de Saül, la famille des Saülites.'),
('nb',26,14,'crampon1923','Telles sont les familles des Siméonites: vingt-deux mille deux cents.'),
('nb',26,15,'crampon1923','Fils de Gad, selon leurs familles: de Séphon, la famille des Séphonites; d''Aggi, la famille des Aggites; de Sunit, la famille des Sunites;'),
('nb',26,16,'crampon1923','d''Ozni, la famille des Oznites; de Her, la famille des Hérites;'),
('nb',26,17,'crampon1923','d''Arod, la famille des Arodites; d''Ariel, la famille des Ariélites.'),
('nb',26,18,'crampon1923','Telles sont les familles des fils de Gad, selon leurs recensés: quarante mille cinq cents.'),
('nb',26,19,'crampon1923','Fils de Juda: Her et Onan; mais Her et Onan moururent au pays de Chanaan.'),
('nb',26,20,'crampon1923','Voici les fils de Juda selon leurs familles: de Séla, la famille des Sélaïtes; de Pharès, la famille des Pharésites; de Zaré, la famille des Zaréites. —'),
('nb',26,21,'crampon1923','Les fils de Pharès furent: de Hesron, la famille des Hesronites; de Hamul, la famille des Hamulites. —'),
('nb',26,22,'crampon1923','Telles sont les familles de Juda, selon leurs recensés: soixante-seize mille cinq cents.'),
('nb',26,23,'crampon1923','Fils d''Issachar selon leurs familles: de Thola, la famille des Tholaïtes; de Phua, la famille des Phuaïtes;'),
('nb',26,24,'crampon1923','de Jasub, la famille des Jasubites; de Semran, la famille des Semranites.'),
('nb',26,25,'crampon1923','Telles sont les familles d''Issachar, selon leurs recensés: soixante-quatre mille trois cents.'),
('nb',26,26,'crampon1923','Fils de Zabulon selon leurs familles: de Sared, la famille des Sarédites; d''Elon, la famille des Elonites; de Jalel, la famille des Jalélites.'),
('nb',26,27,'crampon1923','Telles sont les familles issues de Zabulon, selon leurs recensés: soixante mille cinq cents.'),
('nb',26,28,'crampon1923','Fils de Joseph selon leurs familles: Manassé et Ephraïm.'),
('nb',26,29,'crampon1923','Fils de Manassé: de Machir, la famille des Machirites. — Machir engendra Galaad; de Galaad, la famille des Galaadites. —'),
('nb',26,30,'crampon1923','Voici les fils de Galaad: Jézer, d''où la famille des Jézérites; de Hélec, la famille des Hélicites;'),
('nb',26,31,'crampon1923','Asriel, d''où la famille des Asriélites; Séchem, d''où la famille des Séchémites;'),
('nb',26,32,'crampon1923','Sémida, d''où la famille de Sémidaïtes; Hépher, d''où la famille des Héphrites.'),
('nb',26,33,'crampon1923','Salphaad, fils d''Hépher, n''eut point de fils, mais il eut des filles. Voici les noms des filles de Salphaad: Maala, Noa, Hégla, Melcha et Thersa. —'),
('nb',26,34,'crampon1923','Telles sont les familles de Manassé; leurs recensés furent cinquante-deux mille sept cents.'),
('nb',26,35,'crampon1923','Voici les fils d''Ephraïm selon leurs familles: de Suthala, la famille des Suthalaïtes; de Bécher, la famille des Béchrites; de Théhen, la famille des Théhénites. —'),
('nb',26,36,'crampon1923','Voici les fils de Suthala: d''Héran, la famille des Héranites. —'),
('nb',26,37,'crampon1923','Telles sont les familles des fils d''Ephraïm, selon leurs recensés: trente-deux mille cinq cents. Ce sont là les fils de Joseph, selon leurs familles.'),
('nb',26,38,'crampon1923','Fils de Benjamin, selon leurs familles: de Béla, la famille des Bélaïtes; d''Asbel, la famille des Asbélites; d''Ahiram, la famille des Ahiramites;'),
('nb',26,39,'crampon1923','de Supham, la famille des Suphamites; de Hupham, la famille des Huphamites. —'),
('nb',26,40,'crampon1923','Les fils de Béla furent Héred et Noéman; de Héred, la famille des Hérédites; de Noéman, la famille des Noémanites. —'),
('nb',26,41,'crampon1923','Tels sont les fils de Benjamin, selon leurs familles, et leurs recensés furent quarante-cinq mille six cents.'),
('nb',26,42,'crampon1923','Voici les fils de Dan, selon leurs familles: de Suham descend la famille des Suhamites. Telles sont les familles de Dan, selon leurs familles.'),
('nb',26,43,'crampon1923','Total des familles des Suhamites, selon leurs recensés: soixante-quatre mille quatre cents.'),
('nb',26,44,'crampon1923','Fils d''Aser, selon leurs familles: de Jemna, la famille des Jemnites; de Jessui, la famille des Jessuites; de Brié, la famille des Briéïtes. —'),
('nb',26,45,'crampon1923','Des fils de Brié: de Héber, la famille des Hébrites; de Melchiel, la famille des Melchiélites. —'),
('nb',26,46,'crampon1923','Le nom de la fille d''Aser était Sara. —'),
('nb',26,47,'crampon1923','Telles sont les familles des fils d''Aser, d''après leurs recensés: cinquante-trois mille quatre cents.'),
('nb',26,48,'crampon1923','Fils de Nephthali, selon leurs familles: de Jésiel, la famille des Jésiélites; de Guni, la famille des Gunites;'),
('nb',26,49,'crampon1923','de Jéser, la famille des Jésérites; de Sellem, la famille des Sélémites.'),
('nb',26,50,'crampon1923','Telles sont les familles de Nephthali, selon leurs familles, et leurs recensés furent quarante-cinq mille quatre cents.'),
('nb',26,51,'crampon1923','Tels sont les enfants d''Israël qui furent recensés: six cent un mille sept cent trente.'),
('nb',26,52,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',26,53,'crampon1923','« A ceux-ci le pays sera partagé, pour être leur héritage, selon le nombre des noms.'),
('nb',26,54,'crampon1923','Aux plus nombreux tu donneras un héritage plus grand, et aux moins nombreux tu donneras un héritage plus petit; on donnera à chacun son héritage selon ses recensés.'),
('nb',26,55,'crampon1923','Seulement le partage du pays aura lieu par le sort. Ils le recevront en partage selon les noms des tribus patriarcales.'),
('nb',26,56,'crampon1923','C''est par le sort que l''héritage sera réparti aux plus nombreux comme à ceux qui le sont moins. »'),
('nb',26,57,'crampon1923','Voici, selon leurs familles, les Lévites qui furent recensés: de Gerson, la famille des Gersonites; de Caath, la famille des Caathites; de Mérari, la famille des Mérarites. —'),
('nb',26,58,'crampon1923','Voici les familles de Lévi; la famille des Lobnites, la famille des Hébronites, la famille des Moholites, la famille des Musites et la famille des Coréïtes. — Caath engendra Amram,'),
('nb',26,59,'crampon1923','et le nom de la femme d''Amram était Jochabed, fille de Lévi, que sa mère enfanta à Lévi en Egypte; elle enfanta à Amram Aaron, Moïse et Marie, leur sœur.'),
('nb',26,60,'crampon1923','Il naquit à Aaron: Nadab et Abiu, Eléazar et Ithamar.'),
('nb',26,61,'crampon1923','Nadab et Abiu moururent lorsqu''ils apportèrent du feu étranger devant Yahweh. —'),
('nb',26,62,'crampon1923','Leurs recensés, tous les mâles depuis l''âge d''un mois et au-dessus, furent vingt-trois mille. Car ils ne furent pas compris dans le recensement des enfants d''Israël, parce qu''ils ne leur fut point assigné d''héritage au milieu des enfants d''Israël.'),
('nb',26,63,'crampon1923','Tels sont les hommes recensés par Moïse et Eléazar, le prêtre, qui firent le recensement des enfants d''Israël dans les plaines de Moab, près du Jourdain, vis-à-vis de Jéricho.'),
('nb',26,64,'crampon1923','Parmi eux, il n''y avait aucun des enfants d''Israël dont Moïse et Aaron le prêtre avaient fait le recensement dans le désert de Sinaï;'),
('nb',26,65,'crampon1923','car Yahweh avait dit d''eux: « Ils mourront dans le désert »; et il n''en resta pas un, excepté Caleb, fils de Jéphoné, et Josué, fils de Nun.'),
('nb',26,66,'crampon1923',''),
('nb',27,1,'crampon1923','Alors s''approchèrent les filles de Salphaad, fils de Hépher, fils de Galaad, fils de Machir, fils de Manassé, des familles de Manassé, le fils de Joseph; leurs noms étaient Maala, Noa, Hégla, Melcha et Thersa.'),
('nb',27,2,'crampon1923','Elles se présentèrent devant Moïse, devant le prêtre Eléazar, et devant les princes de toute l''assemblée, à l''entrée de la tente de réunion, et elles dirent:'),
('nb',27,3,'crampon1923','« Notre père est mort dans le désert; il n''était pas au milieu de la troupe de ceux qui se liguèrent contre Yahweh, de la troupe de Coré, mais il est mort pour son péché, et il n''avait point de fils.'),
('nb',27,4,'crampon1923','Pourquoi le nom de notre père serait-il retranché du milieu de sa famille, parce qu''il n''a pas eu de fils? Donne-nous une propriété parmi les frères de notre père. »'),
('nb',27,5,'crampon1923','Moïse porta leur cause devant Yahweh;'),
('nb',27,6,'crampon1923','et Yahweh dit à Moïse:'),
('nb',27,7,'crampon1923','« Les filles de Salphaad ont dit une chose juste. Tu leur donneras en héritage une propriété parmi les frères de leur père, et tu leur feras passer l''héritage de leur père.'),
('nb',27,8,'crampon1923','Tu parleras aux enfants d''Israël, en disant: Si un homme meurt sans avoir de fils, vous ferez passer son héritage à sa fille;'),
('nb',27,9,'crampon1923','et s''il n''a point de fille, vous donnerez son héritage à ses frères.'),
('nb',27,10,'crampon1923','S''il n''a point de frères, vous donnerez son héritage aux frères de son père;'),
('nb',27,11,'crampon1923','et s''il n''y a point de frères de son père, vous donnerez son héritage au parent le plus proche dans sa famille, et c''est lui qui le possédera. Ce sera pour les enfants d''Israël une règle de droit, comme Yahweh l''a ordonné à Moïse. »'),
('nb',27,12,'crampon1923','Yahweh dit à Moïse: « Monte sur cette montagne d''Abarim, et vois le pays que je donne aux enfants d''Israël.'),
('nb',27,13,'crampon1923','Tu le verras, et toi aussi tu seras recueilli auprès de ton peuple, comme Aaron, ton frère, a été recueilli,'),
('nb',27,14,'crampon1923','parce que dans le désert de Sin, lors de la contestation de l''assemblée, vous avez été tous deux rebelles à l''ordre que j''avais donné de me sanctifier devant eux à l''occasion des eaux. Ce sont les eaux de Mériba, à Cadès, dans le désert de Sin. »'),
('nb',27,15,'crampon1923','Moïse parla à Yahweh, en disant:'),
('nb',27,16,'crampon1923','« Que Yahweh, le Dieu des esprits de toute chair, établisse sur l''assemblée un homme'),
('nb',27,17,'crampon1923','qui sorte devant eux et qui entre devant eux, qui les fasse sortir et qui les fasse entrer, afin que l''assemblée de Yahweh ne soit pas comme des brebis qui n''ont point de berger. »'),
('nb',27,18,'crampon1923','Yahweh dit à Moïse: « Prends Josué, fils de Nun, homme en qui réside l''Esprit, et tu poseras ta main sur lui.'),
('nb',27,19,'crampon1923','Tu le placeras devant Eléazar, le prêtre, et devant toute l''assemblée, et tu l''installeras sous leurs yeux.'),
('nb',27,20,'crampon1923','Tu mettras sur lui une part de ton autorité, afin que toute l''assemblée des enfants d''Israël lui obéisse.'),
('nb',27,21,'crampon1923','Il se présentera devant le prêtre Eléazar, qui consultera pour lui le jugement de l''Urim devant Yahweh; c''est sur son ordre que sortiront, sur son ordre qu''entreront, lui, Josué, tous les enfants d''Israël avec lui et toute l''assemblée. »'),
('nb',27,22,'crampon1923','Moïse fit ce que Yahweh lui avait ordonné. Il prit Josué, et il le plaça devant Eléazar, le prêtre, et devant toute l''assemblée.'),
('nb',27,23,'crampon1923','Et ayant posé ses mains sur lui, il l''installa, comme Yahweh l''avait dit par Moïse.'),
('nb',28,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',28,2,'crampon1923','« Donne cet ordre aux enfants d''Israël et dis-leur: Vous aurez soin de me présenter, au temps fixé, mon offrande, mon aliment pour les sacrifices faits par le feu, qui sont pour moi d''agréable odeur.'),
('nb',28,3,'crampon1923','Tu leur diras: Voici le sacrifice par le feu que vous offrirez à Yahweh: chaque jour, deux agneaux d''un an, sans défaut, comme holocauste perpétuel.'),
('nb',28,4,'crampon1923','Tu offriras l''un des agneaux le matin, et le deuxième agneau entre les deux soirs,'),
('nb',28,5,'crampon1923','et, pour l''oblation, un dixième d''épha de fleur de farine, pétrie avec un quart de hin d''huile d''olives concassées.'),
('nb',28,6,'crampon1923','C''est l''holocauste perpétuel qui a été offert à la montagne de Sinaï, d''agréable odeur, un sacrifice par le feu à Yahweh.'),
('nb',28,7,'crampon1923','Sa libation sera d''un quart de hin pour chaque agneau; c''est dans le lieu saint que tu feras la libation de vin pur à Yahweh.'),
('nb',28,8,'crampon1923','Tu offriras le second agneau entre les deux soirs; tu feras comme pour l''oblation du matin et sa libation: c''est un sacrifice par le feu, d''une agréable odeur à Yahweh.'),
('nb',28,9,'crampon1923','Le jour du sabbat, vous offrirez deux agneaux d''un an, sans défaut, et, comme oblation, deux dixièmes de fleur de farine pétrie à l''huile, et sa libation.'),
('nb',28,10,'crampon1923','C''est l''holocauste du sabbat, pour chaque sabbat, outre l''holocauste perpétuel et sa libation.'),
('nb',28,11,'crampon1923','Au commencement de vos mois, vous offrirez comme holocauste à Yahweh deux jeunes taureaux, un bélier et sept agneaux d''un an sans défaut,'),
('nb',28,12,'crampon1923','et, comme oblation pour chaque taureau, trois dixièmes de fleur de farine pétrie à l''huile; comme oblation pour le bélier, deux dixièmes de fleur de farine pétrie à l''huile;'),
('nb',28,13,'crampon1923','comme oblation pour chaque agneau, un dixième de fleur de farine pétrie à l''huile. C''est un holocauste d''agréable odeur, un sacrifice par le feu de Yahweh.'),
('nb',28,14,'crampon1923','Leurs libations seront d''un demi-hin de vin pour un taureau, d''un tiers de hin pour un bélier et d''un quart de hin pour un agneau. Tel est l''holocauste du commencement du mois, pour chaque mois, pour les mois de l''année.'),
('nb',28,15,'crampon1923','On offrira aussi à Yahweh un bouc en sacrifice pour le péché, outre l''holocauste perpétuel et sa libation.'),
('nb',28,16,'crampon1923','Au premier mois, le quatorzième jour du mois, ce sera la Pâque de Yahweh.'),
('nb',28,17,'crampon1923','Le quinzième jour de ce mois sera jour de fête. On mangera pendant sept jours des pains sans levain.'),
('nb',28,18,'crampon1923','Le premier jour, il y aura une sainte assemblée: vous ne ferez aucune œuvre servile.'),
('nb',28,19,'crampon1923','Vous offrirez en sacrifice par le feu un holocauste à Yahweh: deux jeunes taureaux, un bélier et sept agneaux d''un an, sans défaut,'),
('nb',28,20,'crampon1923','et, comme leur oblation, de la fleur de farine pétrie à l''huile: trois dixièmes pour un taureau, deux dixièmes pour un bélier,'),
('nb',28,21,'crampon1923','et un dixième pour chacun des sept agneaux.'),
('nb',28,22,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, pour faire l''expiation pour vous.'),
('nb',28,23,'crampon1923','Vous ferez cela sans préjudice de l''holocauste du matin, qui est l''holocauste perpétuel.'),
('nb',28,24,'crampon1923','Vous ferez cela chaque jour, pendant sept jours; c''est l''aliment d''un sacrifice par le feu, d''agréable odeur à Yahweh; ainsi sera-t-il fait sans préjudice de l''holocauste perpétuel et de sa libation.'),
('nb',28,25,'crampon1923','Le septième jour, vous aurez une sainte assemblée: vous ne ferez aucune œuvre servile.'),
('nb',28,26,'crampon1923','Au jour des prémices, quand vous présenterez à Yahweh une oblation de la moisson nouvelle, à votre fête des Semaines, vous aurez une sainte assemblée: vous ne ferez aucune œuvre servile.'),
('nb',28,27,'crampon1923','Vous offrirez comme holocauste d''agréable odeur à Yahweh deux jeunes taureaux, un bélier et sept agneaux d''un an,'),
('nb',28,28,'crampon1923','et, comme leur oblation, de la fleur de farine pétrie à l''huile: trois dixièmes pour chaque taureau, deux dixièmes pour le bélier,'),
('nb',28,29,'crampon1923','et un dixième pour chacun des sept agneaux.'),
('nb',28,30,'crampon1923','Vous offrirez aussi un bouc, pour faire l''expiation pour vous. Vous ferez cela sans préjudice de l''holocauste perpétuel et de son oblation.'),
('nb',28,31,'crampon1923','Vous aurez des victimes sans défaut; et vous y joindrez leurs libations.'),
('nb',29,1,'crampon1923','Au septième mois, le premier jour du mois, vous aurez une sainte assemblée: vous ne ferez aucune œuvre servile. Ce sera pour vous le jour du son éclatant des trompettes.'),
('nb',29,2,'crampon1923','Vous offrirez comme holocauste d''agréable odeur à Yahweh un jeune taureau, un bélier et sept agneaux d''un an, sans défaut,'),
('nb',29,3,'crampon1923','et, comme leur oblation, de la fleur de farine pétrie à l''huile: trois dixièmes pour le taureau, deux dixièmes pour le bélier'),
('nb',29,4,'crampon1923','et un dixième pour chacun des sept agneaux.'),
('nb',29,5,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, pour faire l''expiation pour vous.'),
('nb',29,6,'crampon1923','Vous ferez cela sans préjudice de l''holocauste du mois et de son oblation, de l''holocauste perpétuel et de son oblation, et de leurs libations d''après les règles prescrites. Ce sont des sacrifices par le feu, d''agréable odeur à Yahweh.'),
('nb',29,7,'crampon1923','Le dixième jour de ce septième mois, vous aurez une sainte assemblée et vous affligerez vos âmes: vous ne ferez aucune œuvre.'),
('nb',29,8,'crampon1923','Vous offrirez en holocauste d''agréable odeur à Yahweh un jeune taureau, un bélier et sept agneaux d''un an, sans défaut,'),
('nb',29,9,'crampon1923','et, comme leur oblation, de la fleur de farine pétrie à l''huile: trois dixièmes pour le taureau, deux dixièmes pour le bélier'),
('nb',29,10,'crampon1923','et un dixième pour chacun des sept agneaux.'),
('nb',29,11,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, sans préjudice du sacrifice expiatoire, de l''holocauste perpétuel, de son oblation, et de leurs libations.'),
('nb',29,12,'crampon1923','Le quinzième jour, du septième mois, vous aurez une sainte assemblée: vous ne ferez aucune œuvre servile. Et vous célébrerez une fête en l''honneur de Yahweh pendant sept jours.'),
('nb',29,13,'crampon1923','Vous offrirez un holocauste, sacrifice par le feu, d''agréable odeur à Yahweh: treize jeunes taureaux, deux béliers et quatorze agneaux d''un an, sans défaut,'),
('nb',29,14,'crampon1923','et, comme leur oblation, de la fleur de farine pétrie à l''huile: trois dixièmes pour chacun des treize taureaux, deux dixièmes pour chacun des deux béliers,'),
('nb',29,15,'crampon1923','et un dixième pour chacun des quatorze agneaux.'),
('nb',29,16,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, sans préjudice de l''holocauste perpétuel avec son oblation et sa libation.'),
('nb',29,17,'crampon1923','Le second jour, vous offrirez douze jeunes taureaux, deux béliers et quatorze agneaux d''un an, sans défaut,'),
('nb',29,18,'crampon1923','avec leur oblation et leurs libations, pour les taureaux, les béliers et les agneaux, selon leur nombre, d''après la règle.'),
('nb',29,19,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, sans préjudice de l''holocauste perpétuel, de son oblation et de leurs libations.'),
('nb',29,20,'crampon1923','Le troisième jour, vous offrirez onze taureaux, deux béliers et quatorze agneaux d''un an, sans défaut,'),
('nb',29,21,'crampon1923','avec leur oblation et leurs libations, pour les taureaux, les béliers et les agneaux, selon leur nombre, d''après la règle.'),
('nb',29,22,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, sans préjudice de l''holocauste perpétuel, de son oblation et de sa libation.'),
('nb',29,23,'crampon1923','Le quatrième jour, vous offrirez dix taureaux, deux béliers et quatorze agneaux d''un an, sans défaut,'),
('nb',29,24,'crampon1923','avec leur oblation et leurs libations, pour les taureaux, les béliers et les agneaux, selon leur nombre d''après la règle.'),
('nb',29,25,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, sans préjudice de l''holocauste perpétuel, de son oblation et de sa libation.'),
('nb',29,26,'crampon1923','Le cinquième jour, vous offrirez neuf taureaux, deux béliers et quatorze agneaux d''un an, sans défaut,'),
('nb',29,27,'crampon1923','avec leur oblation et leurs libations, pour les taureaux, les béliers et les agneaux, selon leur nombre, d''après la règle.'),
('nb',29,28,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, sans préjudice de l''holocauste perpétuel, de son oblation et de sa libation.'),
('nb',29,29,'crampon1923','Le sixième jour, vous offrirez huit taureaux, deux béliers et quatorze agneaux d''un an, sans défaut,'),
('nb',29,30,'crampon1923','avec leur oblation et leurs libations, pour les taureaux, les béliers et les agneaux, selon leur nombre, d''après la règle.'),
('nb',29,31,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, sans préjudice de l''holocauste perpétuel, de son oblation et de sa libation.'),
('nb',29,32,'crampon1923','Le septième jour, vous offrirez sept taureaux, deux béliers et quatorze agneaux d''un an, sans défaut,'),
('nb',29,33,'crampon1923','avec leur oblation et leurs libations, pour les taureaux, les béliers et les agneaux, selon leur nombre, d''après la règle.'),
('nb',29,34,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, sans préjudice de l''holocauste perpétuel, de son oblation et de sa libation.'),
('nb',29,35,'crampon1923','Le huitième jour, vous aurez une assemblée solennelle: vous ne ferez aucune œuvre servile.'),
('nb',29,36,'crampon1923','Vous offrirez un holocauste, un sacrifice par le feu d''agréable odeur à Yahweh: un taureau, un bélier et sept agneaux d''un an, sans défaut,'),
('nb',29,37,'crampon1923','avec leur oblation et leurs libations, pour le taureau, le bélier et les agneaux, selon leur nombre, d''après la règle.'),
('nb',29,38,'crampon1923','Vous offrirez aussi un bouc en sacrifice pour le péché, sans préjudice de l''holocauste perpétuel, de son oblation et de sa libation.'),
('nb',29,39,'crampon1923','Tels sont les sacrifices que vous offrirez à Yahweh dans vos fêtes, sans préjudice de vos vœux et de vos offrandes volontaires: vos holocaustes, vos oblations, vos libations et vos sacrifices pacifiques. »'),
('nb',30,1,'crampon1923','Moïse parla aux enfants d''Israël selon tout ce que Yahweh lui avait ordonné:'),
('nb',30,2,'crampon1923','Moïse parla aux chefs des tribus des enfants d''Israël, en disant: « Voici ce que Yahweh ordonne:'),
('nb',30,3,'crampon1923','Si un homme fait un vœu à Yahweh ou s''il fait un serment pour s''imposer à soi-même un engagement, il ne violera point sa parole; tout ce qui est sorti de sa bouche, il le fera.'),
('nb',30,4,'crampon1923','Si une femme, encore jeune fille dans la maison de son père, fait un vœu à Yahweh et se lie par un engagement,'),
('nb',30,5,'crampon1923','et que son père apprenne son vœu et l''engagement qu''elle s''est imposé à elle-même, et que son père garde le silence envers elle, tous ses vœux qu''elle aura faits et tout engagement qu''elle s''est imposé à elle-même seront valables;'),
('nb',30,6,'crampon1923','mais si, le jour où il en a connaissance, son père la désavoue, tous ses vœux et tous les engagements qu''elle s''est imposé à elle-même seront sans valeur; et Yahweh lui pardonnera, parce que son père l''a désavouée.'),
('nb',30,7,'crampon1923','Si elle se marie, et que pèsent sur elle ses vœux ou une parole imprudemment sortie de ses lèvres par laquelle elle s''est imposé à elle-même un engagement,'),
('nb',30,8,'crampon1923','et si son mari, l''apprenant, garde le silence envers elle le jour où il l''apprendra, ses vœux seront valables, ainsi que ses engagements qu''elle s''est imposé à elle-même;'),
('nb',30,9,'crampon1923','mais si, le jour où il l''apprend, son mari la désavoue, il rend nul son vœu qui pèse sur elle et la parole imprudemment sortie de ses lèvres par laquelle elle s''est imposé à elle-même un engagement; et Yahweh lui pardonnera.'),
('nb',30,10,'crampon1923','Le vœu d''une femme veuve ou répudiée, tout engagement qu''elle s''est imposé à elle-même, seront valables pour elle.'),
('nb',30,11,'crampon1923','Si c''est dans la maison de son mari qu''une femme a fait un vœu ou s''est imposé à elle-même un engagement par un serment,'),
('nb',30,12,'crampon1923','et que son mari, l''apprenant, garde le silence envers elle et ne la désavoue pas, tous ses vœux seront valables, ainsi que tous les engagements qu''elle s''est imposé à elle-même;'),
('nb',30,13,'crampon1923','mais si, le jour où il l''apprend, son mari les annule, tout ce qui est sorti de ses lèvres, vœux ou engagements, sera sans valeur: son mari les a annulés; et Yahweh lui pardonnera.'),
('nb',30,14,'crampon1923','Tout vœu et tout serment par lequel elle s''engage à affliger son âme, son mari peut les ratifier et son mari peut les annuler.'),
('nb',30,15,'crampon1923','Si son mari garde d''un jour à l''autre le silence envers elle, il ratifie ainsi tous ses vœux ou tous ses engagements qui pèsent sur elle; il les ratifie, parce qu''il a gardé le silence envers elle le jour où il l''a appris.'),
('nb',30,16,'crampon1923','S''il les annule après le jour où il l''a appris, il portera l''iniquité de sa femme. »'),
('nb',30,17,'crampon1923','Telles sont les lois que Yahweh prescrivit à Moïse, entre un mari et sa femme, entre un père et sa fille, lorsqu''elle est jeune encore et dans la maison de son père.'),
('nb',31,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',31,2,'crampon1923','« Venge les enfants d''Israël sur les Madianites; tu seras ensuite recueilli auprès de ton peuple. »'),
('nb',31,3,'crampon1923','Moïse parla au peuple, en disant: « Armez pour la guerre des hommes d''entre vous, et qu''ils marchent contre Madian, pour exécuter la vengeance de Yahweh sur Madian.'),
('nb',31,4,'crampon1923','Vous enverrez à la guerre mille hommes par tribu, de toutes les tribus d''Israël. »'),
('nb',31,5,'crampon1923','On leva donc d''entre les milliers d''Israël mille hommes par tribu, soit douze mille hommes armés pour la guerre.'),
('nb',31,6,'crampon1923','Moïse les envoya au combat, mille hommes par tribu, eux et Phinées, le fils d''Eléazar, le prêtre, qui avait avec lui les instruments sacrés et les trompettes retentissantes.'),
('nb',31,7,'crampon1923','Ils s''avancèrent contre Madian, selon l''ordre que Yahweh avait donné à Moïse, et ils tuèrent tous les mâles.'),
('nb',31,8,'crampon1923','Outre ceux qui étaient tombés dans la bataille, ils tuèrent les rois de Madian: Evi, Récem, Sur, Hur et Rebé, cinq rois de Madian; ils tuèrent aussi par l''épée Balaam, fils de Béor.'),
('nb',31,9,'crampon1923','Les enfants d''Israël firent prisonnières les femmes des Madianites avec leurs petits enfants, et ils pillèrent toutes leurs bêtes de somme, tous leurs troupeaux et tous leurs biens.'),
('nb',31,10,'crampon1923','Ils livrèrent aux flammes toutes les villes du pays qu''ils habitaient et tous leurs campements.'),
('nb',31,11,'crampon1923','Ayant pris tout le butin et toutes les dépouilles, gens et bestiaux,'),
('nb',31,12,'crampon1923','ils amenèrent les prisonniers, les dépouilles et le butin à Moïse, à Eléazar, le prêtre, et à l''assemblée des enfants d''Israël, au camp, dans les plaines de Moab, près du Jourdain, vis-à-vis de Jéricho.'),
('nb',31,13,'crampon1923','Moïse, Eléazar, le prêtre, et tous les princes de l''assemblée sortirent au-devant d''eux, hors du camp.'),
('nb',31,14,'crampon1923','Et Moïse s''irrita contre les commandants de l''armée, les chefs de milliers et les chefs de centaines, qui revenaient du combat.'),
('nb',31,15,'crampon1923','Il leur dit: « Avez-vous donc laissé la vie à toutes les femmes?'),
('nb',31,16,'crampon1923','Voici, ce sont elles qui, sur la parole de Balaam, ont entraîné les enfants d''Israël à l''infidélité envers Yahweh, dans l''affaire de Phogor; et alors la plaie fut dans l''assemblée de Yahweh.'),
('nb',31,17,'crampon1923','Maintenant, tuez tout mâle parmi les petits enfants, et tuez toute femme qui a connu la couche d''un homme;'),
('nb',31,18,'crampon1923','mais toutes les filles qui n''ont pas connu la couche d''un homme, laissez-les vivre pour vous.'),
('nb',31,19,'crampon1923','Et vous, campez hors du camp pendant sept jours; quiconque a tué quelqu''un et quiconque a touché un mort se purifiera le troisième jour et le septième jour, lui et vos prisonniers.'),
('nb',31,20,'crampon1923','Vous purifierez aussi tout vêtement, tout objet de peau, tout ouvrage de poil de chèvre et tout ustensile de bois. »'),
('nb',31,21,'crampon1923','Eléazar, le prêtre, dit aux hommes de guerre qui étaient allés au combat: « Voici ce qui est commandé par la loi que Yahweh a prescrite à Moïse:'),
('nb',31,22,'crampon1923','l''or, l''argent, l''airain, le fer, l''étain et le plomb,'),
('nb',31,23,'crampon1923','tout objet qui va au feu, vous le ferez passer par le feu, et il sera pur; toutefois il sera purifié encore par l''eau de purification. Tout ce qui ne va pas au feu, vous le ferez passer par l''eau.'),
('nb',31,24,'crampon1923','Vous laverez vos vêtements, le septième jour, et vous serez purs; vous pourrez ensuite entrer dans le camp. »'),
('nb',31,25,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',31,26,'crampon1923','« Fais, toi et Eléazar, le prêtre, et les chefs de maisons de l''assemblée, le compte de ce qui a été pris des dépouilles en hommes et en bestiaux,'),
('nb',31,27,'crampon1923','et partage les dépouilles entre les combattants qui sont allés à la guerre et toute l''assemblée.'),
('nb',31,28,'crampon1923','Tu prélèveras sur la part des soldats qui sont allés à la guerre un tribut pour Yahweh, savoir un sur cinq cents, gens, bœufs, ânes et brebis.'),
('nb',31,29,'crampon1923','Vous le prendrez sur leur moitié et tu le donneras à Eléazar, le prêtre, comme prélèvement de Yahweh.'),
('nb',31,30,'crampon1923','Sur la moitié qui revient aux enfants d''Israël, tu mettras à part un sur cinquante, gens, bœufs, ânes, brebis et tout bétail, et tu le donneras aux Lévites, qui ont la garde de la Demeure de Yahweh. »'),
('nb',31,31,'crampon1923','Moïse et Eléazar, le prêtre, firent comme Yahweh l''avait ordonné à Moïse.'),
('nb',31,32,'crampon1923','Les dépouilles, le reste du butin qu''avaient fait les combattants étaient de six cent soixante-quinze mille brebis,'),
('nb',31,33,'crampon1923','soixante-douze mille bœufs,'),
('nb',31,34,'crampon1923','soixante et un mille ânes,'),
('nb',31,35,'crampon1923','et trente-deux mille d''entre les femmes qui n''avaient pas connu la couche d''un homme.'),
('nb',31,36,'crampon1923','La moitié, part de ceux qui étaient allés à la guerre, fut de trois cent trente-sept mille cinq cents brebis,'),
('nb',31,37,'crampon1923','six cent soixante-quinze brebis pour le tribut de Yahweh;'),
('nb',31,38,'crampon1923','trente-six mille bœufs, dont soixante-douze pour le tribut de Yahweh;'),
('nb',31,39,'crampon1923','trente mille cinq cents ânes, dont soixante-et-un pour le tribut de Yahweh;'),
('nb',31,40,'crampon1923','et seize mille personnes, trente-deux personnes pour le tribut de Yahweh.'),
('nb',31,41,'crampon1923','Moïse donna à Eléazar, le prêtre, le tribut prélevé pour Yahweh, ainsi que Yahweh l''avait ordonné à Moïse.'),
('nb',31,42,'crampon1923','Quant à la moitié revenant aux enfants d''Israël, que Moïse avait séparée de celle des combattants,'),
('nb',31,43,'crampon1923','cette moitié formant la part de l''assemblée fut de trois cent trente-sept mille cinq cents brebis,'),
('nb',31,44,'crampon1923','trente-six mille bœufs,'),
('nb',31,45,'crampon1923','trente mille cinq cents ânes'),
('nb',31,46,'crampon1923','et seize mille personnes.'),
('nb',31,47,'crampon1923','Sur cette moitié qui revenait aux enfants d''Israël, Moïse prit un sur cinquante et le donna aux Lévites, qui ont la garde de la Demeure de Yahweh, ainsi que Yahweh l''avait ordonné à Moïse.'),
('nb',31,48,'crampon1923','Les commandants des milliers de l''armée, les chefs de milliers et les chefs de centaines, s''approchèrent de Moïse'),
('nb',31,49,'crampon1923','et lui dirent: « Tes serviteurs ont compté les combattants qui étaient sous nos ordres, et il ne manque pas un homme d''entre nous.'),
('nb',31,50,'crampon1923','C''est pourquoi nous apportons comme offrande à Yahweh les objets d''or que chacun de nous a trouvés, bracelets, chaînettes, anneaux, pendants d''oreilles et colliers, pour faire l''expiation pour nous devant Yahweh. »'),
('nb',31,51,'crampon1923','Moïse et Eléazar, le prêtre, reçurent d''eux cet or, tous ces objets bien travaillés.'),
('nb',31,52,'crampon1923','Tout l''or prélevé qu''ils présentèrent à Yahweh de la part des chefs de milliers et des chefs de centaines, fut de seize mille sept cent cinquante sicles.'),
('nb',31,53,'crampon1923','Les hommes de la troupe eurent chacun leur butin pour eux.'),
('nb',31,54,'crampon1923','Moïse et Eléazar, le prêtre, ayant pris l''or des chefs de milliers et des chefs de centaines, l''apportèrent dans la tente de réunion, comme mémorial pour les enfants d''Israël devant Yahweh.'),
('nb',32,1,'crampon1923','Les fils de Ruben et les fils de Gad avaient des troupeaux en nombre considérable. Voyant que le pays de Jazer et le pays de Galaad étaient un lieu propre pour les troupeaux,'),
('nb',32,2,'crampon1923','les fils de Gad et les fils de Ruben vinrent auprès de Moïse, d''Eléazar, le prêtre, et des princes de l''assemblée, et ils leur dirent:'),
('nb',32,3,'crampon1923','« Ataroth, Dibon, Jazer, Nemra, Hésebon, Eléalé, Saban, Nébo et Béon,'),
('nb',32,4,'crampon1923','ce pays que Yahweh a frappé devant l''assemblée d''Israël, est un lieu propre pour les troupeaux, et tes serviteurs ont des troupeaux ».'),
('nb',32,5,'crampon1923','Ils ajoutèrent: « Si nous avons trouvé grâce à tes yeux, que ce pays soit donné en possession à tes serviteurs, et ne nous fais point passer le Jourdain. »'),
('nb',32,6,'crampon1923','Moïse répondit aux fils de Gad et aux fils de Ruben: « Vos frères iront-ils à la guerre, et vous, resterez-vous ici?'),
('nb',32,7,'crampon1923','Pourquoi découragez-vous les enfants d''Israël de passer dans le pays que Yahweh leur donne?'),
('nb',32,8,'crampon1923','C''est ainsi qu''ont fait vos pères, quand je les envoyai de Cadès-Barné explorer le pays.'),
('nb',32,9,'crampon1923','Ils montèrent jusqu''à la vallée d''Escol et virent le pays, et ils découragèrent les enfants d''Israël d''entrer dans le pays que Yahweh leur donnait.'),
('nb',32,10,'crampon1923','Et la colère de Yahweh s''enflamma ce jour-là, et il jura en disant:'),
('nb',32,11,'crampon1923','Ces hommes qui sont montés de l''Egypte, depuis l''âge de vingt ans et au-dessus, ne verront point le pays que j''ai promis par serment à Abraham, à Isaac et à Jacob, car ils ne m''ont pas fidèlement suivi,'),
('nb',32,12,'crampon1923','excepté Caleb, fils de Jéphoné, le Cénézéen, et Josué, fils de Nun, qui ont suivi fidèlement Yahweh.'),
('nb',32,13,'crampon1923','Et la colère de Yahweh s''enflamma contre Israël, et il les fit errer dans le désert pendant quarante années, jusqu''à ce que fût anéantie toute la génération qui avait fait le mal aux yeux de Yahweh.'),
('nb',32,14,'crampon1923','Et voici que vous prenez la place de vos pères, comme des rejetons de pécheurs, pour accroître encore l''ardeur de la colère de Yahweh contre Israël.'),
('nb',32,15,'crampon1923','Car si vous refusez de le suivre, il continuera de laisser Israël au désert, et vous causerez la ruine de tout ce peuple. »'),
('nb',32,16,'crampon1923','Ils s''approchèrent de Moïse, et ils dirent: « Nous construirons ici des parcs pour nos troupeaux et des villes pour nos petits enfants;'),
('nb',32,17,'crampon1923','mais nous nous armerons sans tarder pour marcher devant les enfants d''Israël, jusqu''à ce que nous les ayons introduits dans le lieu qu''ils doivent occuper, et nos enfants demeureront dans les villes fortes, à cause des habitants du pays.'),
('nb',32,18,'crampon1923','Nous ne reviendrons point dans nos maisons, avant que les enfants d''Israël aient pris possession chacun de son héritage;'),
('nb',32,19,'crampon1923','car nous ne posséderons rien avec eux de l''autre côté du Jourdain, ni plus loin, puisque notre héritage nous est venu de ce côté du Jourdain, à l''orient. »'),
('nb',32,20,'crampon1923','Moïse leur dit: « Si vous tenez cette conduite, si vous vous armez pour combattre devant Yahweh;'),
('nb',32,21,'crampon1923','si tous les hommes armés d''entre vous passent le Jourdain devant Yahweh, jusqu''à ce qu''il ait chassé ses ennemis de devant sa face,'),
('nb',32,22,'crampon1923','et que vous ne reveniez qu''après que le pays aura été soumis devant Yahweh, vous serez sans reproche devant Yahweh et devant Israël, et cette contrée-ci sera votre propriété devant Yahweh.'),
('nb',32,23,'crampon1923','Mais si vous n''agissez pas ainsi, voici, vous péchez contre Yahweh; et sachez que votre péché vous atteindra.'),
('nb',32,24,'crampon1923','Construisez donc des villes pour vos enfants et des parcs pour vos troupeaux, et exécutez la parole qui est sortie de votre bouche. »'),
('nb',32,25,'crampon1923','Les fils de Gad et les fils de Ruben parlèrent à Moïse en disant: « Tes serviteurs feront ce que mon seigneur ordonne.'),
('nb',32,26,'crampon1923','Nos enfants, nos femmes, nos troupeaux et tout notre bétail resteront ici, dans les villes de Galaad;'),
('nb',32,27,'crampon1923','et tes serviteurs, tout homme armé pour combattre, passeront devant Yahweh pour combattre, comme le dit mon seigneur. »'),
('nb',32,28,'crampon1923','Alors Moïse donna des ordres à leur sujet à Eléazar, le prêtre, à Josué, fils de Nun, et aux chefs de famille des tribus des enfants d''Israël;'),
('nb',32,29,'crampon1923','il leur dit: « Si les fils de Gad et les fils de Ruben passent avec vous le Jourdain, tous les hommes armés pour combattre devant Yahweh, et que le pays sois soumis devant vous, vous leur donnerez en possession la conquête de Galaad.'),
('nb',32,30,'crampon1923','Mais s''ils ne passent point en armes avec vous, ils seront établis au milieu de vous dans le pays de Chanaan. »'),
('nb',32,31,'crampon1923','Les fils de Gad et les fils de Ruben répondirent en disant: « Ce que Yahweh a dit à tes serviteurs, nous le ferons.'),
('nb',32,32,'crampon1923','Nous passerons en armes devant Yahweh au pays de Chanaan, et la possession de notre héritage nous demeurera de ce côté-ci du Jourdain. »'),
('nb',32,33,'crampon1923','Moïse donna aux fils de Gad et aux fils de Ruben, et à la moitié de la tribu de Manassé, fils de Joseph, le royaume de Séhon, roi des Amorrhéens, et le royaume d''Og, roi de Basan, le pays avec ses villes et leurs territoires, les villes du pays d''alentour.'),
('nb',32,34,'crampon1923','Les fils de Gad bâtirent Dibon, Ataroth, Aroër,'),
('nb',32,35,'crampon1923','Ataroth-Sophan, Jazer, Jegbaa,'),
('nb',32,36,'crampon1923','Bethnemra et Betharan, villes fortes, et ils firent des parcs pour le troupeau.'),
('nb',32,37,'crampon1923','Les fils de Ruben bâtirent Hésebon, Eléalé, Cariathaïm,'),
('nb',32,38,'crampon1923','Nabo et Baalméon, dont les noms furent changés, et Sabama, et ils donnèrent des noms aux villes qu''ils bâtirent.'),
('nb',32,39,'crampon1923','Les fils de Machir, fils de Manassé, allèrent contre Galaad et, s''en étant emparés, ils chassèrent les Amorrhéens qui y étaient.'),
('nb',32,40,'crampon1923','Moïse donna Galaad à Machir, fils de Manassé, qui s''y établit.'),
('nb',32,41,'crampon1923','Jaïr, fils de Manassé, alla et prit leurs bourgs, et il les appela Bourgs de Jaïr.'),
('nb',32,42,'crampon1923','Nobé alla et s''empara de Chanath et des villes de son ressort; il l''appela Nobé, de son nom.'),
('nb',33,1,'crampon1923','Voici les campements des enfants d''Israël, quand ils sortirent du pays d''Egypte, selon leurs troupes, sous la conduite de Moïse et d''Aaron.'),
('nb',33,2,'crampon1923','Moïse mit par écrit les lieux d''où ils partirent, selon leurs campements, d''après l''ordre de Yahweh, et voici leurs campements selon leurs départs:'),
('nb',33,3,'crampon1923','Ils partirent de Ramsès le premier mois, le quinzième jour du premier mois. Le lendemain de la Pâque, les enfants d''Israël sortirent la main levée, à la vue de tous les Egyptiens.'),
('nb',33,4,'crampon1923','Et les Egyptiens enterraient ceux que Yahweh avait frappés parmi eux, tous leurs premiers-nés; Yahweh exerça aussi des jugements sur leurs dieux.'),
('nb',33,5,'crampon1923','Etant partis de Ramsès, les enfants d''Israël campèrent à Soccoth.'),
('nb',33,6,'crampon1923','Ils partirent de Soccoth et campèrent à Etham, qui est aux confins du désert.'),
('nb',33,7,'crampon1923','Ils partirent d''Etham et, ayant tourné vers Phihahiroth, qui est vis-à-vis de Béel-séphon, ils campèrent devant Magdalum.'),
('nb',33,8,'crampon1923','Ils partirent de devant Phihahiroth et passèrent au milieu de la mer, vers le désert. Après trois journées de marche dans le désert d''Etham, ils campèrent à Mara.'),
('nb',33,9,'crampon1923','Ils partirent de Mara et arrivèrent à Elim, où il y avait douze sources d''eau et soixante-dix palmiers, et ils y campèrent.'),
('nb',33,10,'crampon1923','Ils partirent d''Elim et campèrent près de la mer Rouge.'),
('nb',33,11,'crampon1923','Ils partirent de la mer Rouge et campèrent dans le désert de Sin.'),
('nb',33,12,'crampon1923','Ils partirent du désert de Sin et campèrent à Daphca.'),
('nb',33,13,'crampon1923','Ils partirent de Daphca et campèrent à Alus.'),
('nb',33,14,'crampon1923','Ils partirent d''Alus et campèrent à Raphidim, et il n''y eut pas là d''eau à boire pour le peuple.'),
('nb',33,15,'crampon1923','Ils partirent de Raphidim et campèrent dans le désert de Sinaï.'),
('nb',33,16,'crampon1923','Ils partirent du désert de Sinaï et campèrent à Kibroth-Hattaava.'),
('nb',33,17,'crampon1923','Ils partirent de Kibroth-Hattaava et campèrent à Haséroth.'),
('nb',33,18,'crampon1923','Ils partirent de Haséroth et campèrent à Rethma.'),
('nb',33,19,'crampon1923','Ils partirent de Rethma et campèrent à Remmonpharès.'),
('nb',33,20,'crampon1923','Ils partirent de Remmonpharès et campèrent à Lebna.'),
('nb',33,21,'crampon1923','Ils partirent de Lebna et campèrent à Ressa.'),
('nb',33,22,'crampon1923','Ils partirent de Ressa et campèrent à Céélatha.'),
('nb',33,23,'crampon1923','Ils partirent de Céélatha et campèrent à la montagne de Sépher.'),
('nb',33,24,'crampon1923','Ils partirent de la montagne de Sépher et campèrent à Arada.'),
('nb',33,25,'crampon1923','Ils partirent d''Arada et campèrent à Macéloth.'),
('nb',33,26,'crampon1923','Ils partirent de Macéloth et campèrent à Thahath.'),
('nb',33,27,'crampon1923','Ils partirent de Thahath et campèrent à Tharé.'),
('nb',33,28,'crampon1923','Ils partirent de Tharé et campèrent à Metcha.'),
('nb',33,29,'crampon1923','Ils partirent de Metcha et campèrent à Hesmona.'),
('nb',33,30,'crampon1923','Ils partirent de Hesmona et campèrent à Moséroth.'),
('nb',33,31,'crampon1923','Ils partirent de Moséroth et campèrent à Bené-Jaacan.'),
('nb',33,32,'crampon1923','Ils partirent de Bené-Jaacan et campèrent à Hor-Gadgad.'),
('nb',33,33,'crampon1923','Ils partirent de Hor-Gadgad et campèrent à Jétébatha.'),
('nb',33,34,'crampon1923','Ils partirent de Jétébatha et campèrent à Hébrona.'),
('nb',33,35,'crampon1923','Ils partirent de Hébrona et campèrent à Asiongaber.'),
('nb',33,36,'crampon1923','Ils partirent d''Asiongaber et campèrent dans le désert de Sin, c''est-à-dire à Cadès.'),
('nb',33,37,'crampon1923','Ils partirent de Cadès et campèrent à la montagne de Hor, à l''extrémité du pays d''Edom.'),
('nb',33,38,'crampon1923','Aaron, le prêtre, monta sur la montagne de Hor, sur l''ordre de Yahweh, et il y mourut, la quarantième année après la sortie des enfants d''Israël du pays d''Egypte, le cinquième mois, le premier jour du mois.'),
('nb',33,39,'crampon1923','Aaron était âgé de cent vingt-trois ans lorsqu''il mourut sur la montagne de Hor.'),
('nb',33,40,'crampon1923','Ce fut alors que le Chanaanéen, roi d''Arad, qui habitait le Négeb dans le pays de Chanaan, apprit l''arrivée des enfants d''Israël.'),
('nb',33,41,'crampon1923','Ils partirent de la montagne de Hor et campèrent à Salmona.'),
('nb',33,42,'crampon1923','Ils partirent de Salmona et campèrent à Phunon.'),
('nb',33,43,'crampon1923','Ils partirent de Phunon et campèrent à Oboth.'),
('nb',33,44,'crampon1923','Ils partirent d''Oboth et campèrent à Ijé-Abarim, à la frontière de Moab.'),
('nb',33,45,'crampon1923','Ils partirent de Ijé-Abarim et campèrent à Dibon-Gad.'),
('nb',33,46,'crampon1923','Ils partirent de Dibon-Gad et campèrent à Helmon-Deblathaïm.'),
('nb',33,47,'crampon1923','Ils partirent d''Helmon-Deblathaïm et campèrent aux monts Abarim, en face de Nébo.'),
('nb',33,48,'crampon1923','Ils partirent des monts Abarim et campèrent dans les plaines de Moab, près du Jourdain, vis-à-vis de Jéricho.'),
('nb',33,49,'crampon1923','Ils campèrent près du Jourdain, depuis Bethsimoth jusqu''à Abel-Settim, dans les plaines de Moab.'),
('nb',33,50,'crampon1923','Yahweh parla à Moïse dans les plaines de Moab, près du Jourdain, vis-à-vis de Jéricho, en disant:'),
('nb',33,51,'crampon1923','« Parle aux enfants d''Israël: Lorsque vous aurez passé le Jourdain et que vous serez entrés dans le pays de Chanaan,'),
('nb',33,52,'crampon1923','vous expulserez devant vous tous les habitants du pays, vous détruirez toutes leurs pierres sculptées, et vous détruirez toutes leurs images d''airain fondu, et vous dévasterez tous leurs hauts lieux.'),
('nb',33,53,'crampon1923','Vous prendrez possession du pays et vous l''habiterez; car je vous ai donné le pays pour le posséder.'),
('nb',33,54,'crampon1923','Vous partagerez le pays par le sort, selon vos familles; vous donnerez un héritage plus grand à ceux qui sont en plus grand nombre, et tu donneras un héritage plus petit à ceux qui sont en plus petit nombre. Ce que le sort assignera à chacun lui appartiendra; vous le recevrez en propriété, selon vos tribus patriarcales.'),
('nb',33,55,'crampon1923','Mais si vous n''expulsez pas devant vous les habitants du pays, ceux d''entre eux que vous laisserez seront comme des épines dans vos yeux et comme des aiguillons dans vos flancs, et ils vous traiteront en ennemis dans le pays que vous allez habiter.'),
('nb',33,56,'crampon1923','Et je vous traiterai vous-même comme j''avais résolu de les traiter. »'),
('nb',34,1,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',34,2,'crampon1923','« Commande aux enfants d''Israël et dis-leur: Quand vous serez entrés dans le pays de Chanaan, voici le pays qui vous tombera en partage: le pays de Chanaan, selon ses limites, savoir:'),
('nb',34,3,'crampon1923','Le côté du midi sera pour vous le désert de Sin, jusqu''à Edom, et votre frontière méridionale partira de l''extrémité méridionale de la mer Salée, vers l''orient,'),
('nb',34,4,'crampon1923','et votre frontière inclinera au sud par la montée d''Akrabbim, passera par Sin, et arrivera jusqu''au midi de Cadès-Barné; elle continuera par Hatsar-Adar et passera vers Asemon;'),
('nb',34,5,'crampon1923','et depuis Asemon, la frontière arrivera jusqu''au Torrent d''Egypte, pour arriver à la mer.'),
('nb',34,6,'crampon1923','Quant à la frontière occidentale, vous aurez pour frontière la grande mer: ce sera votre limite à l''occident.'),
('nb',34,7,'crampon1923','Voici quelle sera votre frontière septentrionale: à partir de la grande mer, vous la tracerez pour vous par le mont Hor;'),
('nb',34,8,'crampon1923','depuis le mont Hor, vous la tracerez jusqu''à l''entrée de Hamath, et la frontière arrivera à Sedada;'),
('nb',34,9,'crampon1923','et la frontière continuera par Zéphron, pour arriver à Hatsar-Enan: ce sera votre limite au septentrion.'),
('nb',34,10,'crampon1923','Vous tracerez votre frontière orientale de Hatsar-Enan à Sépham;'),
('nb',34,11,'crampon1923','et la frontière descendra de Sépham vers Rébla, à l''est d''Aïn; et la frontière descendra et s''étendra le long des collines qui flanquent la mer de Cénéreth à l''orient,'),
('nb',34,12,'crampon1923','et la frontière descendra le long du Jourdain, pour arriver à la mer Salée. Tel sera votre pays selon les frontières tout autour. »'),
('nb',34,13,'crampon1923','Moïse donna cet ordre aux enfants d''Israël, en disant: « C''est là le pays que vous partagerez par le sort, et que Yahweh a ordonné de donner aux neuf tribus et à la demi-tribu.'),
('nb',34,14,'crampon1923','Car la tribu des fils de Ruben, selon leurs maisons patriarcales, et la tribu des fils de Gad, selon leurs maisons patriarcales, ont reçu leur héritage; la demi-tribu de Manassé a reçu son héritage.'),
('nb',34,15,'crampon1923','Les deux tribus et la demi-tribu ont pris leur héritage au delà du Jourdain, vis-à-vis de Jéricho, du côté de l''orient, vers le levant. »'),
('nb',34,16,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',34,17,'crampon1923','« Voici les noms des hommes qui partageront le pays entre vous: Eléazar, le prêtre, et Josué, fils de Nun.'),
('nb',34,18,'crampon1923','Vous prendrez encore un prince de chaque tribu pour vous partager le pays.'),
('nb',34,19,'crampon1923','Voici les noms de ces hommes: Pour la tribu de Juda, Caleb, fils de Jéphoné;'),
('nb',34,20,'crampon1923','pour la tribu des fils de Siméon, Samuel, fils d''Ammiud;'),
('nb',34,21,'crampon1923','pour la tribu de Benjamin, Elidad, fils de Chaselon;'),
('nb',34,22,'crampon1923','pour la tribu des fils de Dan, le prince Bocci, fils de Jogli;'),
('nb',34,23,'crampon1923','pour les fils de Joseph: pour la tribu des fils de Manassé, le prince Hanniel, fils d''Ephod;'),
('nb',34,24,'crampon1923','et pour la tribu des fils d''Ephraïm, le prince Camuel, fils de Sephtan;'),
('nb',34,25,'crampon1923','pour la tribu des fils de Zabulon, le prince Elisaphan, fils de Pharnach;'),
('nb',34,26,'crampon1923','pour la tribu des fils d''Issachar, le prince Phaltiel, fils d''Ozan;'),
('nb',34,27,'crampon1923','pour la tribu des fils d''Aser, le prince Ahiud, fils de Salomi;'),
('nb',34,28,'crampon1923','pour la tribu des fils de Nephthali, le prince Phedaël, fils d''Ammiud. » —'),
('nb',34,29,'crampon1923','Tels sont ceux à qui Yahweh ordonna de partager le pays de Chanaan entre les enfants d''Israël.'),
('nb',35,1,'crampon1923','Yahweh parla à Moïse, dans les plaines de Moab, près du Jourdain, vis-à-vis de Jéricho, en disant:'),
('nb',35,2,'crampon1923','« Ordonne aux enfants d''Israël de céder aux Lévites, sur l''héritage qu''ils posséderont, des villes pour y habiter. Vous donnerez aussi aux Lévites des lieux de pâture autour de ces villes.'),
('nb',35,3,'crampon1923','Ils auront les villes pour y habiter, et leurs lieux de pâture seront pour leur gros bétail, pour leurs autres biens et pour tous leurs animaux.'),
('nb',35,4,'crampon1923','Les lieux de pâture des villes que vous donnerez aux Lévites seront, à partir du mur de la ville, en dehors, de mille coudées tout autour.'),
('nb',35,5,'crampon1923','Vous mesurerez, en dehors de la ville, deux mille coudées pour le côté oriental, deux mille coudées pour le côté méridional, deux mille coudées pour le côté occidental et deux mille coudées pour le côté septentrional; la ville sera au milieu: tels seront les lieux de pâture de leurs villes.'),
('nb',35,6,'crampon1923','Quant aux villes que vous donnerez aux Lévites, ce sont les six villes de refuge, que vous disposerez pour que le meurtrier s''y réfugie; et, en plus, vous donnerez quarante-deux autres villes.'),
('nb',35,7,'crampon1923','Ainsi toutes les villes que vous donnerez aux Lévites seront au nombre de quarante-huit villes avec leurs lieux de pâture.'),
('nb',35,8,'crampon1923','Pour les villes que vous donnerez sur les possessions des enfants d''Israël, vous prendrez plus de ceux qui ont plus, et vous prendrez moins de ceux qui ont moins. Chacun cédera de ses villes aux Lévites à proportion de l''héritage qu''il aura reçu. »'),
('nb',35,9,'crampon1923','Yahweh parla à Moïse, en disant:'),
('nb',35,10,'crampon1923','« Parle aux enfants d''Israël, et dis-leur: Lorsque vous aurez passé le Jourdain et que vous serez entrés dans le pays de Chanaan,'),
('nb',35,11,'crampon1923','vous vous choisirez des villes qui soient pour vous des villes de refuge, où pourra se retirer le meurtrier qui aura tué quelqu''un par mégarde.'),
('nb',35,12,'crampon1923','Ces villes vous serviront de refuge contre le vengeur du sang, afin que le meurtrier ne soit pas mis à mort avant d''avoir comparu en jugement devant l''assemblée.'),
('nb',35,13,'crampon1923','Quant aux villes que vous donnerez, vous aurez six villes de refuge.'),
('nb',35,14,'crampon1923','Vous donnerez trois villes au-delà du Jourdain, et vous donnerez trois villes dans le pays de Chanaan; elles seront villes de refuge.'),
('nb',35,15,'crampon1923','Ces six villes serviront de refuge pour les enfants d''Israël, pour l''étranger et pour celui qui demeure au milieu de vous, afin que tout homme qui aura tué quelqu''un par mégarde puisse s''y retirer.'),
('nb',35,16,'crampon1923','S''il l''a frappé avec un instrument de fer, et que la mort s''ensuive, c''est un meurtrier: le meurtrier sera puni de mort.'),
('nb',35,17,'crampon1923','S''il l''a frappé, ayant à la main une pierre qui peut causer la mort, et que la mort s''ensuive, c''est un meurtrier: le meurtrier sera puni de mort.'),
('nb',35,18,'crampon1923','S''il l''a frappé, ayant à la main un instrument de bois qui peut causer la mort, et que la mort s''ensuive, c''est un meurtrier: le meurtrier sera puni de mort.'),
('nb',35,19,'crampon1923','Le vengeur du sang fera lui-même mourir le meurtrier; quand il le rencontrera, il le tuera.'),
('nb',35,20,'crampon1923','S''il a renversé un homme par haine, ou s''il lui a jeté quelque chose en guet-apens, et que la mort s''ensuive,'),
('nb',35,21,'crampon1923','ou s''il l''a frappé de sa main par inimitié, et que la mort s''ensuive, celui qui a frappé sera puni de mort, c''est un meurtrier: le vengeur du sang fera mourir le meurtrier quand il le rencontrera.'),
('nb',35,22,'crampon1923','Mais s''il l''a renversé par hasard, sans inimitié, ou s''il lui a jeté quelque chose sans intention,'),
('nb',35,23,'crampon1923','ou s''il a fait tomber sur lui par mégarde une pierre qui peut causer la mort, et que la mort s''ensuive, sans qu''il soit son ennemi et qu''il lui cherche du mal,'),
('nb',35,24,'crampon1923','l''assemblée jugera entre celui qui a frappé et le vengeur du sang, selon ces lois.'),
('nb',35,25,'crampon1923','Et l''assemblée délivrera le meurtrier du vengeur du sang et le fera retourner dans la ville de refuge où il s''était enfui; et il y demeurera jusqu''à la mort du grand prêtre qui a été oint de l''huile sainte.'),
('nb',35,26,'crampon1923','Si le meurtrier sort avant ce temps du territoire de la ville de refuge où il s''est enfui,'),
('nb',35,27,'crampon1923','et si le vengeur du sang le rencontre hors du territoire de sa ville de refuge, et si le vengeur du sang tue le meurtrier, il ne sera pas coupable de meurtre;'),
('nb',35,28,'crampon1923','car le meurtrier doit demeurer dans sa ville de refuge jusqu''à la mort du grand prêtre; et, après la mort du grand prêtre, le meurtrier pourra retourner au pays où se trouve sa possession.'),
('nb',35,29,'crampon1923','Ces ordonnances fixeront le droit pour vous et pour vos descendants dans tous les lieux où vous habiterez.'),
('nb',35,30,'crampon1923','Quand un homme en a tué un autre, c''est sur la déposition de témoins qu''on ôtera la vie au meurtrier; mais un seul témoin ne peut déposer pour faire condamner une personne à mort.'),
('nb',35,31,'crampon1923','Vous n''accepterez point de rançon pour la vie d''un meurtrier dont le crime mérite la mort, car il doit être mis à mort.'),
('nb',35,32,'crampon1923','Vous n''accepterez point de rançon qui permette à celui qui s''est enfui dans sa ville de refuge de revenir habiter dans son pays avant la mort du grand prêtre.'),
('nb',35,33,'crampon1923','Vous ne souillerez point le pays où vous serez, car le sang souille le pays, et il n''y a pour le pays d''expiation pour le sang qui y a été répandu, que par le sang de celui qui l''a répandu.'),
('nb',35,34,'crampon1923','Tu ne profaneras point le pays où vous demeurerez, et au milieu duquel j''habite; car je suis Yahweh, qui habite au milieu des enfants d''Israël. »'),
('nb',36,1,'crampon1923','Les Chefs des maisons patriarcales de la famille des fils de Galaad, fils de Machir, fils de Manassé, d''entre les familles des fils de Joseph, s''étant approchés, parlèrent devant Moïse et devant les princes, chefs de maisons patriarcales des enfants d''Israël.'),
('nb',36,2,'crampon1923','Ils dirent: « Yahweh a ordonné à mon seigneur de donner par le sort le pays en héritage aux enfants d''Israël; mon seigneur a aussi reçu de Yahweh l''ordre de donner l''héritage de Salphaad, notre frère, à ses filles.'),
('nb',36,3,'crampon1923','Si elles se marient à l''un des fils d''une autre tribu des enfants d''Israël, leur héritage sera retranché de l''héritage de nos pères et il s''ajoutera à celui de la tribu dont elles feront partie, et il sera retranché du lot de notre héritage.'),
('nb',36,4,'crampon1923','Et quand viendra le jubilé pour les enfants d''Israël, leur héritage sera ajouté à celui de la tribu dont elles feront partie, et leur héritage sera retranché de l''héritage de la tribu de nos pères. »'),
('nb',36,5,'crampon1923','Moïse donna ce commandement aux enfants d''Israël, sur l''ordre de Yahweh; il dit: « La tribu des fils de Joseph a bien parlé.'),
('nb',36,6,'crampon1923','Voici ce qu''ordonne Yahweh au sujet des filles de Salphaad: elles se marieront à qui elles voudront, pourvu qu''elles se marient dans une famille de la tribu de leur père;'),
('nb',36,7,'crampon1923','ainsi l''héritage des enfants d''Israël ne passera pas d''une tribu à une autre tribu, et les enfants d''Israël s''attacheront chacun à l''héritage de la tribu de ses pères.'),
('nb',36,8,'crampon1923','Toute fille possédant un héritage dans quelque tribu des enfants d''Israël se mariera avec un homme d''une famille de la tribu de son père, afin que les enfants d''Israël conservent chacun l''héritage de ses pères.'),
('nb',36,9,'crampon1923','Aucun héritage ne passera d''une tribu à une autre tribu, mais les tribus des enfants d''Israël s''attacheront chacune à son héritage. »'),
('nb',36,10,'crampon1923','Comme Yahweh l''avait ordonné à Moïse, ainsi firent les filles de Salphaad.'),
('nb',36,11,'crampon1923','Maala, Thersa, Hégla, Melcha et Noa, filles de Salphaad, se marièrent avec des fils de leurs oncles;'),
('nb',36,12,'crampon1923','elles se marièrent dans les familles des fils de Manassé, fils de Joseph, et ainsi leur héritage resta dans la tribu de la famille de leur père.'),
('nb',36,13,'crampon1923','Telles sont les ordonnances et les lois que Yahweh donna par Moïse aux enfants d''Israël, dans les plaines de Moab, près du Jourdain, vis-à-vis de Jéricho.'),
('dt',1,1,'crampon1923','Voici les paroles que Moïse adressa à tout Israël, de l''autre côté du Jourdain, dans le désert, dans l''Arabah, vis-à-vis de Souph, entre Pharan, Thophel, Laban, Haséroth et Di-Zahab.'),
('dt',1,2,'crampon1923','— Il y a onze journées de marche depuis Horeb, par le chemin de la montagne de Séïr, jusqu''à Cadès-Barné. —'),
('dt',1,3,'crampon1923','En la quarantième année, au onzième mois, le premier jour du mois, Moïse parla aux enfants d''Israël selon tout ce que Yahweh lui avait ordonné de leur dire:'),
('dt',1,4,'crampon1923','après qu''il eut battu Séhon, roi des Amorrhéens, qui habitait à Hésebon, et Og, roi de Basan, qui habitait à Astaroth et à Edraï.'),
('dt',1,5,'crampon1923','De l''autre côté du Jourdain, dans le pays de Moab, Moïse commença à expliquer cette loi, en disant:'),
('dt',1,6,'crampon1923','Yahweh, notre Dieu, nous a parlé à Horeb, en disant: « Vous avez séjourné assez longtemps dans cette montagne;'),
('dt',1,7,'crampon1923','tournez-vous et partez; allez à la montagne des Amorrhéens et dans tous ses alentours: dans l''Arabah, dans la montagne, dans la Séphéla, dans le Négeb, sur la côte de la mer, au pays des Chananéens, et au Liban, jusqu''au grand fleuve, au fleuve de l''Euphrate.'),
('dt',1,8,'crampon1923','Voici que je mets ce pays devant vous; allez et prenez possession du pays que Yahweh a juré à vos pères, Abraham, Isaac et Jacob, de leur donner, à eux et à leur postérité après eux. »'),
('dt',1,9,'crampon1923','Je vous parlai ainsi dans ce temps-là: « Je ne puis, à moi seul, vous porter.'),
('dt',1,10,'crampon1923','Yahweh, votre Dieu vous a multipliés, et vous êtes aujourd''hui aussi nombreux que les étoiles du ciel.'),
('dt',1,11,'crampon1923','— Que Yahweh, le Dieu de vos pères, vous fasse croître encore mille fois plus, et qu''il vous bénisse comme il vous l''a promis! —'),
('dt',1,12,'crampon1923','Comment porterais-je, à moi seul, votre charge, votre fardeau et vos contestations?'),
('dt',1,13,'crampon1923','Prenez dans vos tribus des hommes sages, intelligents et connus, et je les établirai à votre tête. »'),
('dt',1,14,'crampon1923','Vous me répondîtes en disant: « La chose que tu proposes de faire est bonne ».'),
('dt',1,15,'crampon1923','Je pris donc les chefs de vos tribus, des hommes sages et connus, et je les mis à votre tête comme chefs de milliers, chefs de centaines, chefs de cinquantaines et chefs de dizaines, et comme magistrats dans vos tribus.'),
('dt',1,16,'crampon1923','Dans le même temps, je donnai ce commandement à vos juges: « Ecoutez les débats de vos frères, et jugez selon la justice les différends qu''ils auront chacun avec son frère ou avec l''étranger qui est avec lui.'),
('dt',1,17,'crampon1923','Vous n''aurez point égard, dans vos jugements, à l''apparence des personnes; vous écouterez les petits comme les grands, n''ayant peur d''aucun homme, car le jugement est de Dieu; et si vous trouvez une cause trop difficile, vous la porterez devant moi, pour que je l''entende. »'),
('dt',1,18,'crampon1923','C''est ainsi que je vous prescrivis, dans ce temps-là, toutes les choses que vous auriez à faire.'),
('dt',1,19,'crampon1923','Etant partis d''Horeb, nous traversâmes tout ce vaste et affreux désert que vous avez vu, nous dirigeant vers la montagne des Amorrhéens, comme Yahweh, votre Dieu, nous l''avait ordonné, et nous arrivâmes à Cadès-Barné.'),
('dt',1,20,'crampon1923','Je vous dis alors: « Vous êtes arrivés à la montagne des Amorrhéens, que nous donne Yahweh, notre Dieu.'),
('dt',1,21,'crampon1923','Vois, Yahweh, ton Dieu, met ce pays devant toi; monte et prends-en possession, comme te l''a dit Yahweh, le Dieu de tes pères; ne crains point et ne t''effraie point. »'),
('dt',1,22,'crampon1923','Vous vous approchâtes tous de moi et vous dites: « Envoyons des hommes devant nous, pour explorer le pays et nous faire un rapport sur le chemin par lequel nous y monterons, et sur les villes où nous arriverons. »'),
('dt',1,23,'crampon1923','La chose m''ayant paru bonne, je pris parmi vous douze hommes, un homme par tribu.'),
('dt',1,24,'crampon1923','Ils partirent et, après avoir traversé la montagne, ils arrivèrent à la vallée d''Escol et l''explorèrent.'),
('dt',1,25,'crampon1923','Ils prirent dans leurs mains des fruits du pays et nous les apportèrent, et ils nous firent un rapport, en disant: « C''est un bon pays que nous donne Yahweh, notre Dieu. »'),
('dt',1,26,'crampon1923','Cependant vous ne voulûtes point monter, et vous fûtes rebelles à l''ordre de Yahweh, votre Dieu.'),
('dt',1,27,'crampon1923','Vous murmurâtes dans vos tentes, en disant: « C''est parce que Yahweh nous hait qu''il nous a fait sortir du pays d''Egypte, pour nous livrer entre les mains de l''Amorrhéen, afin de nous détruire.'),
('dt',1,28,'crampon1923','Où montons-nous? Nos frères nous ont fait fondre le cœur, en disant: C''est un peuple plus grand et de plus haute stature que nous; ce sont des grandes villes, dont les murailles s''élèvent jusqu''au ciel, et même nous y avons vu des fils des Enacim. »'),
('dt',1,29,'crampon1923','Je vous dis: « Ne vous effrayez pas et n''ayez pas peur d''eux.'),
('dt',1,30,'crampon1923','Yahweh, votre Dieu, qui marche devant vous, combattra lui-même pour vous, selon tout ce qu''il a fait pour vous sous vos yeux en Egypte,'),
('dt',1,31,'crampon1923','et ensuite au désert, où tu as vu comment Yahweh, ton Dieu, t''a porté, ainsi qu''un homme porte son fils, sur toute la route que vous avez parcourue jusqu''à votre arrivée en ce lieu. »'),
('dt',1,32,'crampon1923','Malgré cela vous n''aviez pas confiance en Yahweh, votre Dieu,'),
('dt',1,33,'crampon1923','qui marchait devant vous sur le chemin pour vous chercher des lieux de campement, dans un feu pendant la nuit pour vous montrer le chemin où vous deviez marcher, et dans une nuée pendant le jour.'),
('dt',1,34,'crampon1923','Yahweh entendit le bruit de vos paroles et, dans sa colère, il jura, en disant:'),
('dt',1,35,'crampon1923','« Aucun des hommes de cette génération mauvaise ne verra le bon pays que j''ai juré de donner à vos pères,'),
('dt',1,36,'crampon1923','excepté Caleb fils de Jéphoné; il le verra, lui, et je lui donnerai, à lui et à ses enfants, le pays qu''il a foulé, parce qu''il a fidèlement suivi Yahweh. »'),
('dt',1,37,'crampon1923','Yahweh s''irrita aussi contre moi, à cause de vous, et il dit: « Toi non plus tu n''y entreras point.'),
('dt',1,38,'crampon1923','Mais Josué, fils de Nun, ton serviteur, y entrera; fortifie-le, car c''est lui qui mettra Israël en possession de ce pays.'),
('dt',1,39,'crampon1923','Et vos petits enfants dont vous avez dit: Ils seront une proie! et vos fils qui ne connaissent aujourd''hui ni le bien ni le mal, eux y entreront, c''est à eux que je le donnerai, ce sont eux qui le posséderont.'),
('dt',1,40,'crampon1923','Vous, retournez en arrière et partez pour le désert, par le chemin de la mer Rouge. »'),
('dt',1,41,'crampon1923','Vous répondîtes en me disant: « Nous avons péché contre Yahweh; nous monterons et nous combattrons, selon tout ce que Yahweh, notre Dieu, nous a ordonné. » Et vous ceignîtes chacun vos armes, et vous vous disposâtes inconsidérément à monter à la montagne.'),
('dt',1,42,'crampon1923','Yahweh me dit: « Dis-leur: Ne montez pas et ne combattez pas, car je ne suis pas au milieu de vous; ne vous faites pas battre par vos ennemis. »'),
('dt',1,43,'crampon1923','Je vous parlai, mais vous n''écoutâtes point; vous résistâtes à l''ordre de Yahweh, et vous fûtes assez présomptueux pour monter à la montagne.'),
('dt',1,44,'crampon1923','Alors l''Amorrhéen qui habite cette montagne, sortit à votre rencontre; il vous poursuivit comme font les abeilles, et vous battit en Seïr, jusqu''à Horma.'),
('dt',1,45,'crampon1923','Vous revîntes et vous pleurâtes devant Yahweh; mais Yahweh n''écouta pas votre voix, et ne vous prêta pas l''oreille.'),
('dt',1,46,'crampon1923','Vous restâtes de longs jours à Cadès, le temps que vous y avez séjourné.'),
('dt',2,1,'crampon1923','Changeant de direction, nous partîmes pour le désert, par le chemin de la mer Rouge, comme Yahweh me l''avait ordonné, et nous tournâmes longtemps autour de la montagne de Séïr.'),
('dt',2,2,'crampon1923','Et Yahweh me dit:'),
('dt',2,3,'crampon1923','« Vous avez assez tourné autour de cette montagne; reprenez la direction du nord.'),
('dt',2,4,'crampon1923','Donne cet ordre au peuple: Vous allez passer sur la frontière de vos frères, les enfants d''Esaü, qui habitent en Séïr. Ils auront peur de vous; mais prenez bien garde'),
('dt',2,5,'crampon1923','d''avoir des démêlés avec eux, car je ne vous donnerai rien dans leur pays, pas même ce que peut couvrir la plante du pied: j''ai donné à Esaü la montagne de Séïr en propriété.'),
('dt',2,6,'crampon1923','Vous achèterez d''eux à prix d''argent la nourriture que vous mangerez, et vous achèterez d''eux à prix d''argent même l''eau que vous boirez.'),
('dt',2,7,'crampon1923','Car Yahweh ton Dieu t''a béni dans tout le travail de tes mains, il a connu ta marche à travers ce grand désert; voilà quarante ans que Yahweh, ton Dieu, est avec toi: tu n''as manqué de rien. »'),
('dt',2,8,'crampon1923','Nous passâmes donc à distance de nos frères, les enfants d''Esaü, qui habitent en Séïr, nous éloignant du chemin de l''Arabah, d''Elath et d''Asiongaber; nous nous détournâmes et nous prîmes la direction du désert de Moab.'),
('dt',2,9,'crampon1923','Yahweh me dit: « N''attaque pas Moab et n''engage pas de combat avec lui, car je ne te donnerai aucune possession dans son pays: c''est aux enfants de Lot que j''ai donné Ar en propriété.'),
('dt',2,10,'crampon1923','— Les Emim y habitaient auparavant, peuple grand, nombreux et de haute taille, comme les Enacim.'),
('dt',2,11,'crampon1923','Eux aussi sont regardés comme des Rephaïm, de même que les Enacim; mais les Moabites les appellent Emim.'),
('dt',2,12,'crampon1923','En Séïr habitaient aussi jadis les Horrhéens; mais les enfants d''Esaü les chassèrent et, les ayant détruits de devant eux, ils s''établirent à leur place, comme l''a fait Israël pour le pays qu''il possède et que Yahweh lui a donné. —'),
('dt',2,13,'crampon1923','Maintenant, levez-vous et passez le torrent de Zared. » Et nous passâmes le torrent de Zared.'),
('dt',2,14,'crampon1923','Le temps que durèrent nos marches, de Cadès-Barné au passage du torrent de Zared, fut de trente-huit ans, jusqu''à ce que toute la génération des hommes de guerre eût disparu du milieu du camp, comme Yahweh le leur avait juré.'),
('dt',2,15,'crampon1923','La main de Yahweh fut aussi sur eux pour les détruire du milieu du camp, jusqu''à ce qu''ils eussent disparu.'),
('dt',2,16,'crampon1923','Lorsque la mort eut fait disparaître tous les hommes de guerre du milieu du peuple,'),
('dt',2,17,'crampon1923','Yahweh me parla, en disant:'),
('dt',2,18,'crampon1923','« Tu vas passer aujourd''hui la frontière de Moab, Ar,'),
('dt',2,19,'crampon1923','et tu approcheras des enfants d''Ammon. Ne les attaque pas et n''aie pas de démêlés avec eux, car je ne te donnerai aucune possession dans le pays des enfants d''Ammon: c''est aux enfants de Lot que je l''ai donné en possession.'),
('dt',2,20,'crampon1923','— On regardait aussi ce pays comme un pays de Rephaïm; des Rephaïm y habitaient auparavant, et les Ammonites les appelaient Zomzommim:'),
('dt',2,21,'crampon1923','peuple grand, nombreux et de haute taille, comme les Enacim, Yahweh les détruisit devant les Ammonites, qui les chassèrent et s''établirent à leur place.'),
('dt',2,22,'crampon1923','C''est ainsi que fit Yahweh pour les enfants d''Esaü qui habitent en Séïr, lorsqu''il détruisit devant eux les Horrhéens; les ayant chassés, ils s''établirent à leur place jusqu''à ce jour.'),
('dt',2,23,'crampon1923','De même les Hévéens, qui habitaient dans des villages jusqu''à Gaza, furent détruits par les Caphtorim, qui, étant sortis de Caphtor, s''établirent à leur place. —'),
('dt',2,24,'crampon1923','Levez-vous, partez et passez le torrent de l''Arnon. Voici que je livre entre tes mains Séhon, roi de Hésebon, Amorrhéens, ainsi que son pays. Commence à t''en emparer, engage le combat avec lui!'),
('dt',2,25,'crampon1923','Dès aujourd''hui je vais répandre la frayeur et la crainte de ton nom sur tous les peuples qui sont sous tous les cieux, en sorte que, au bruit de ta renommée, ils trembleront et seront dans l''angoisse à cause de toi. »'),
('dt',2,26,'crampon1923','Du désert de Cademoth, j''envoyai des messagers à Séhon, roi de Hésebon, avec des paroles de paix, lui faisant dire:'),
('dt',2,27,'crampon1923','« Que je puisse passer par ton pays; je suivrai le grand chemin, sans m''écarter ni à droite ni à gauche.'),
('dt',2,28,'crampon1923','Tu me vendras à prix d''argent la nourriture que je mangerai, et tu me donneras à prix d''argent l''eau que je boirai; je ne veux que passer avec mes pieds:'),
('dt',2,29,'crampon1923','— C''est ce qu''on fait pour moi les enfants d''Esaü qui habitent en Séïr, et les Moabites qui habitent à Ar: — jusqu''à ce que je passe le Jourdain pour entrer dans le pays que Yahweh, notre Dieu, nous donne. »'),
('dt',2,30,'crampon1923','Mais Séhon, roi de Hésebon, ne voulut pas nous laisser passer chez lui, car Yahweh, ton Dieu, avait endurci son esprit et rendu son cœur inflexible, afin de le livrer entre tes mains, comme tu le vois aujourd''hui.'),
('dt',2,31,'crampon1923','Yahweh me dit: « Voici que j''ai commencé de te livrer Séhon et son pays. Commence à le conquérir afin de prendre possession de son pays. »'),
('dt',2,32,'crampon1923','Séhon sortit à notre rencontre, avec tout son peuple, pour nous livrer bataille à Jasa.'),
('dt',2,33,'crampon1923','Et Yahweh, notre Dieu, nous le livra et nous le battîmes, lui et ses fils, et tout son peuple.'),
('dt',2,34,'crampon1923','Nous prîmes alors toutes ses villes et nous dévouâmes par anathème toute ville, les hommes, les femmes et les enfants, sans en laisser échapper un seul.'),
('dt',2,35,'crampon1923','Seulement, nous pillâmes pour nous le bétail et le butin des villes que nous avions prises.'),
('dt',2,36,'crampon1923','Depuis Aroër qui est sur le bord de la vallée d''Arnon, et depuis la ville qui est dans la vallée, jusqu''à Galaad, il n''y eut pas de ville trop inaccessible pour nous; Yahweh, notre Dieu, nous les livra toutes.'),
('dt',2,37,'crampon1923','Mais tu n''approchas pas du pays des enfants d''Ammon, ni d''aucun endroit qui est sur le bord du torrent de Jaboc, ni des villes de la montagne, ni d''aucun des lieux dont Yahweh, notre Dieu, t''avait défendu de t''emparer.'),
('dt',3,1,'crampon1923','Nous étant tournés, nous montâmes par le chemin de Basan, et Og, roi de Basan, sortit à notre rencontre, avec tout son peuple, pour nous livrer bataille à Edraï.'),
('dt',3,2,'crampon1923','Yahweh me dit: « Ne le crains point, car je l''ai livré entre tes mains, lui et tout son peuple, et son pays; tu le traiteras comme tu as traité Séhon, roi des Amorrhéens, qui habitait à Hésebon. »'),
('dt',3,3,'crampon1923','Et Yahweh, notre Dieu, livra aussi entre nos mains Og, roi de Basan, avec tout son peuple; nous le battîmes jusqu''à ce qu''il ne lui restât plus aucun de ses gens.'),
('dt',3,4,'crampon1923','Nous prîmes alors toutes ses villes, et il n''y en eut pas une qui ne tombât entre notre pouvoir: soixante villes, toute la région d''Argob, le royaume d''Og en Basan.'),
('dt',3,5,'crampon1923','Toutes ces villes étaient fortifiées, avec de hautes murailles, des portes et des barres; sans compter les villes sans murailles, en très grand nombre.'),
('dt',3,6,'crampon1923','Nous les dévouâmes par anathème, comme nous l''avions fait pour Séhon, roi de Hésebon, dévouant par anathème villes, hommes, femmes et enfants.'),
('dt',3,7,'crampon1923','Mais nous pillâmes pour nous tout le bétail et le butin des villes.'),
('dt',3,8,'crampon1923','Ainsi, dans ce temps-là, nous prîmes aux deux rois des Amorrhéens le pays qui est au-delà du Jourdain, depuis le torrent de l''Arnon jusqu''à la montagne d''Hermon.'),
('dt',3,9,'crampon1923','— Les Sidoniens appellent l''Hermon Sarion, et les Amorrhéens Sanir; —'),
('dt',3,10,'crampon1923','toutes les villes de la plaine, tout Galaad et tout Basan, jusqu''à Selcha et Edraï, villes du royaume d''Og en Basan.'),
('dt',3,11,'crampon1923','Car Og, roi de Basan, était resté seul de la race des Rephaïm. Voici, son lit, un lit en fer, n''est-il pas à Rabbath, ville des enfants d''Ammon? Sa longueur est de neuf coudées, et sa largeur de quatre coudées, en coudées d''homme.'),
('dt',3,12,'crampon1923','Nous prîmes alors possession de ce pays. Je donnai aux Rubénites et aux Gadites le territoire à partir d''Aroër qui domine la vallée de l''Arnon, ainsi que la moitié de la montagne de Galaad avec ses villes.'),
('dt',3,13,'crampon1923','Je donnai à la demi-tribu de Manassé le reste de Galaad et toute la partie de Basan formant le royaume d''Og. — Toute la contrée d''Argob, avec tout Basan, c''est ce qu''on appelle le pays des Rephaïm.'),
('dt',3,14,'crampon1923','Jaïr, fils de Manassé, obtint toute la contrée d''Argob jusqu''à la frontière des Gessuriens et des Macathiens, et il donna son nom aux bourgs de Basan, appelés Bourgs de Jaïr, jusqu''à ce jour. —'),
('dt',3,15,'crampon1923','Je donnai Galaad à Machir.'),
('dt',3,16,'crampon1923','Aux Rubénites et aux Gadites, je donnai une partie de Galaad et le pays jusqu''au torrent de l''Arnon, le milieu de la vallée servant de limite, et jusqu''au torrent de Jaboc, frontière des enfants d''Ammon,'),
('dt',3,17,'crampon1923','ainsi que l''Arabah, avec le Jourdain pour limite, depuis Cénéreth jusqu''à la mer de l''Arabah, la mer Salée, au pied des pentes du Phasga, vers l''Orient.'),
('dt',3,18,'crampon1923','En ce temps-là, je vous donnai cet ordre: « Yahweh, votre Dieu, vous à donné ce pays pour qu''il soit votre propriété; vous tous, hommes forts, vous marcherez en armes devant vos frères, les enfants d''Israël.'),
('dt',3,19,'crampon1923','Vos femmes seulement, vos petits enfants et vos troupeaux, — je sais que vous avez de nombreux troupeaux, — resteront dans les villes que je vous ai données,'),
('dt',3,20,'crampon1923','jusqu''à ce que Yahweh ait accordé le repos à vos frères comme à vous, et qu''ils possèdent, eux aussi, le pays que Yahweh, votre Dieu, leur donne de l''autre côté du Jourdain. Alors vous retournerez chacun dans l''héritage que je vous ai donné. »'),
('dt',3,21,'crampon1923','En ce temps-là, je donnai aussi des ordres à Josué, en disant: « Tes yeux ont vu tout ce que Yahweh, votre Dieu, a fait à ces deux rois: ainsi fera Yahweh à tous les royaumes contre lesquels tu vas marcher.'),
('dt',3,22,'crampon1923','Ne les craignez point; car Yahweh, votre Dieu, combat lui-même pour vous. »')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('dt',3,23,'crampon1923','En ce temps-là, je suppliai Yahweh, en disant:'),
('dt',3,24,'crampon1923','« Seigneur Yahweh, vous avez commencé à montrer à votre serviteur votre grandeur et votre main puissante; car quel Dieu y a-t-il, au ciel et sur la terre, qui puisse accomplir vos œuvres et vos hauts faits?'),
('dt',3,25,'crampon1923','Que je passe, je vous prie, que je voie ce bon pays au-delà du Jourdain, cette belle montagne et le Liban! »'),
('dt',3,26,'crampon1923','Mais Yahweh s''irrita contre moi, à cause de vous, et il ne m''exauça point. Yahweh me dit: « C''est assez, ne me parle plus de cette affaire.'),
('dt',3,27,'crampon1923','Monte au sommet du Phasga, porte tes regards vers l''occident, vers le nord, vers le midi et vers l''orient, et contemple de tes yeux; car tu ne passeras pas ce Jourdain.'),
('dt',3,28,'crampon1923','Donne des ordres à Josué, fortifie le et encourage-le, car c''est lui qui marchera devant ce peuple et qui le mettra en possession du pays que tu verras. »'),
('dt',3,29,'crampon1923','Nous demeurâmes dans la vallée, vis-à-vis de Beth-Phogor.'),
('dt',4,1,'crampon1923','« Et maintenant, Israël, écoute les lois et les ordonnances que je vous enseigne pour les mettre en pratique, afin que vous viviez, que vous entriez et que vous possédiez le pays que vous donne Yahweh, le Dieu de vos pères.'),
('dt',4,2,'crampon1923','Vous n''ajouterez rien à ce que je vous prescris, et vous n''en retrancherez rien; mais vous observerez les commandements de Yahweh, votre Dieu, que je vous prescris.'),
('dt',4,3,'crampon1923','Vos yeux ont vu ce que Yahweh a fait à cause de Baal-Phogor: Yahweh, ton Dieu, a détruit du milieu de toi tous ceux qui avaient suivi Baal-Phogor;'),
('dt',4,4,'crampon1923','tandis que vous, qui vous êtes attachés à Yahweh, votre Dieu, vous êtes aujourd''hui tous vivants.'),
('dt',4,5,'crampon1923','Je vous ai enseigné des lois et des ordonnances comme Yahweh, mon Dieu, me l''a commandé, afin que vous les mettiez en pratique dans le pays où vous entrez pour le posséder.'),
('dt',4,6,'crampon1923','Vous les observerez et les mettrez en pratique; car ce sera là votre sagesse et votre intelligence, aux yeux des peuples qui entendront parler de toutes ces lois et diront: Certes, cette grande nation est un peuple sage et intelligent!'),
('dt',4,7,'crampon1923','Quelle est, en effet, la grande nation qui ait des dieux près d''elle, comme nous avons Yahweh, notre Dieu, toutes les fois que nous l''invoquons?'),
('dt',4,8,'crampon1923','Et quelle est la grande nation qui ait des lois et des ordonnances justes, comme toute cette loi que je mets aujourd''hui devant vous?'),
('dt',4,9,'crampon1923','Seulement prends garde à toi et garde attentivement ton âme, de peur d''oublier les choses que tes yeux ont vues, et de les laisser sortir de ton cœur, un seul jour de ta vie; mais enseigne-les à tes enfants et aux enfants de tes enfants.'),
('dt',4,10,'crampon1923','Souviens-toi du jour où tu te présentas devant Yahweh, ton Dieu, en Horeb, lorsque Yahweh me dit: « Assemble-moi le peuple; je leur ferai entendre mes paroles, afin qu''ils apprennent à me craindre, tout le temps qu''ils vivront sur la terre, et afin qu''ils les enseignent à leurs enfants.'),
('dt',4,11,'crampon1923','Vous vous approchâtes et vous vous tîntes au pied de la montagne; la montagne était en feu et la flamme s''élevait jusque dans les profondeurs du ciel, parmi des ténèbres, des nuées et de l''obscurité.'),
('dt',4,12,'crampon1923','Alors Yahweh vous parla du milieu du feu; vous entendiez le son des paroles, mais sans voir de figure: vous n''entendîtes qu''une voix.'),
('dt',4,13,'crampon1923','Il promulgua son alliance, qu''il vous ordonna d''observer, savoir les dix commandements, et il les écrivit sur deux tables de pierre.'),
('dt',4,14,'crampon1923','En ce temps-là, Yahweh me commanda de vous enseigner des lois et des ordonnances, pour que vous les pratiquiez dans le pays où vous allez entrer pour en prendre possession.'),
('dt',4,15,'crampon1923','Puisque vous n''avez vu aucune figure le jour où Yahweh vous parla du milieu du feu en Horeb, prenez bien garde à vos âmes,'),
('dt',4,16,'crampon1923','de peur que vous ne vous corrompiez et que vous ne vous fassiez une image taillée, figure de quelque idole, image d''homme ou de femme,'),
('dt',4,17,'crampon1923','toute image d''animal qui vit sur la terre, toute image d''oiseau qui vole dans le ciel,'),
('dt',4,18,'crampon1923','toute image de bête qui rampe sur le sol, toute image de poisson qui vit dans les eaux au-dessous de la terre;'),
('dt',4,19,'crampon1923','de peur que, levant les yeux vers le ciel, et voyant le soleil, la lune et les étoiles, toute l''armée des cieux, tu ne sois attiré à te prosterner devant eux et à leur rendre un culte, eux que Yahweh, ton Dieu, a donnés en partage à tous les peuples qui sont partout sous le ciel.'),
('dt',4,20,'crampon1923','Mais vous, Yahweh vous a pris et vous a fait sortir de la fournaise à fondre le fer, de l''Egypte, pour devenir le peuple de son héritage, comme vous l''êtes aujourd''hui.'),
('dt',4,21,'crampon1923','Et Yahweh s''irrita contre moi, à cause de vous, et il jura que je ne passerais pas le Jourdain, et que je n''entrerais pas dans le bon pays que Yahweh, ton Dieu, te donne en héritage.'),
('dt',4,22,'crampon1923','Je vais mourir dans ce pays-ci, sans passer le Jourdain; mais vous le passerez et vous posséderez ce bon pays.'),
('dt',4,23,'crampon1923','Prenez garde à vous, pour ne pas oublier l''alliance que Yahweh, votre Dieu, a contractée avec vous, et ne pas vous faire d''image taillée, de figure quelconque de ce que Yahweh, ton Dieu, t''a défendu.'),
('dt',4,24,'crampon1923','Car Yahweh, ton Dieu, est un feu dévorant, un Dieu jaloux.'),
('dt',4,25,'crampon1923','Lorsque tu auras des enfants et des enfants de tes enfants, et que vous aurez longtemps habité le pays, si vous vous corrompez et si vous vous faites quelque image taillée, figure de quoi que ce soit, faisant ainsi ce qui est mal aux yeux de Yahweh, ton Dieu, pour l''irriter,'),
('dt',4,26,'crampon1923','— j''en prends aujourd''hui à témoin contre vous le ciel et la terre, — vous périrez bientôt et disparaîtrez du pays dont vous allez prendre possession en passant le Jourdain; vous n''y prolongerez pas vos jours, car vous serez entièrement détruits.'),
('dt',4,27,'crampon1923','Yahweh vous dispersera parmi les peuples, et vous resterez en petit nombre au milieu des nations où Yahweh vous mènera.'),
('dt',4,28,'crampon1923','Et là vous servirez des dieux, ouvrages de mains d''homme, du bois et de la pierre, qui ne voient point, n''entendent point, ne mangent point et ne sentent point.'),
('dt',4,29,'crampon1923','De là vous chercherez Yahweh, ton Dieu, et tu le trouveras, si tu le cherches de tout ton cœur et de toute ton âme.'),
('dt',4,30,'crampon1923','Au milieu de ta détresse, quand toutes ces choses seront venues sur toi, dans les derniers jours, tu retourneras à Yahweh, ton Dieu, et tu écouteras sa voix;'),
('dt',4,31,'crampon1923','car c''est un Dieu compatissant que Yahweh, ton Dieu: il ne t''abandonnera pas et ne te détruira pas; il n''oubliera pas son alliance avec tes pères, qu''il leur a jurée.'),
('dt',4,32,'crampon1923','Interroge les temps anciens qui t''ont précédé, depuis le jour où Dieu créa l''homme sur la terre, et d''une extrémité du ciel à l''autre extrémité: est-il jamais arrivé si grande chose, et a-t-on jamais entendu rien de pareil?'),
('dt',4,33,'crampon1923','Un peuple a-t-il entendu la voix de Dieu parlant du milieu du feu, comme tu l''as entendue, et est-il demeuré vivant?'),
('dt',4,34,'crampon1923','Jamais un dieu essaya-t-il de venir prendre pour lui une nation du milieu d''une autre nation, par des épreuves, des signes, des miracles, par la guerre, à main forte et à bras étendu, et par de grandes épouvantes, selon tout ce qu''a fait pour vous Yahweh, votre Dieu, sous tes yeux, en Egypte?'),
('dt',4,35,'crampon1923','Ces choses t''ont été montrées, afin que tu connusses que c''est Yahweh qui est Dieu, et qu''il n''y en a point d''autre que lui.'),
('dt',4,36,'crampon1923','Du ciel, il t''a fait entendre sa voix pour t''instruire, et sur la terre, il t''a fait voir son grand feu, et tu as entendu ses paroles du milieu du feu.'),
('dt',4,37,'crampon1923','Parce qu''il a aimé tes pères, il a choisi leur postérité après eux, il t''a fait sortir d''Egypte par sa présence, par sa grande puissance,'),
('dt',4,38,'crampon1923','pour chasser devant toi des nations plus nombreuses et plus fortes que toi, pour te faire entrer dans leur pays et te le donner en héritage, comme tu le vois aujourd''hui.'),
('dt',4,39,'crampon1923','Sache donc en ce jour et grave dans ton cœur que c''est Yahweh qui est Dieu, en haut dans le ciel et en bas sur la terre; il n''y en a point d''autre.'),
('dt',4,40,'crampon1923','Observe ses lois et ses commandements que je te prescris aujourd''hui, afin que tu sois heureux, toi et tes enfants après toi, et afin que tu prolonges tes jours, dans toute la suite des âges, sur la terre que te donne Yahweh, ton Dieu. »'),
('dt',4,41,'crampon1923','Alors Moïse mit à part trois villes de l''autre côté du Jourdain, à l''orient,'),
('dt',4,42,'crampon1923','afin qu''elles servissent de refuge au meurtrier qui aurait tué son prochain par mégarde, sans avoir été auparavant son ennemi, et que, en se réfugiant dans l''une de ces villes, il sauvât sa vie.'),
('dt',4,43,'crampon1923','Ce furent: Bosor, dans le désert, dans la plaine, pour les Rubénites; Ramoth, en Galaad, pour les Gadites, et Golan, en Basan pour les Manassites.'),
('dt',4,44,'crampon1923','C''est ici la loi que Moïse mit devant les yeux des enfants d''Israël;'),
('dt',4,45,'crampon1923','— ce sont les préceptes, les lois et les ordonnances que Moïse donna aux enfants d''Israël lors de leur sortie d''Egypte; —'),
('dt',4,46,'crampon1923','de l''autre côté du Jourdain, dans la vallée, vis-à-vis de Beth-Phogor, au pays de Séhon, roi des Amorrhéens, qui habitait à Hésebon, et qui avait été battu par Moïse et les enfants d''Israël, lors de leur sortie d''Egypte.'),
('dt',4,47,'crampon1923','Ils prirent possession de son pays et de celui d''Og, roi de Basan, deux rois des Amorrhéens qui étaient au delà du Jourdain, à l''orient,'),
('dt',4,48,'crampon1923','depuis Aroër sur le bord du torrent de l''Arnon jusqu''à la montagne de Sion, qui est l''Hermon,'),
('dt',4,49,'crampon1923','avec toute l''Arabah, de l''autre côté du Jourdain, à l''orient, jusqu''à la mer de l''Arabah, au pied du Phasga.'),
('dt',5,1,'crampon1923','Moïse convoqua tout Israël et leur dit: « Ecoute, Israël, les lois et les ordonnances que je vous fais entendre aujourd''hui; apprenez-les et mettez les soigneusement en pratique.'),
('dt',5,2,'crampon1923','Yahweh, notre Dieu, a conclu avec nous une alliance en Horeb.'),
('dt',5,3,'crampon1923','Ce n''est point avec nos pères que Yahweh a conclu cette alliance, c''est avec nous, qui sommes ici aujourd''hui tous vivants.'),
('dt',5,4,'crampon1923','Yahweh vous parla face à face sur la montagne, du milieu du feu,'),
('dt',5,5,'crampon1923','— Je me tenais alors entre Yahweh et vous, pour rapporter sa parole; car vous aviez peur du feu, et vous ne montâtes point sur la montagne. — Il dit:'),
('dt',5,6,'crampon1923','“Je suis Yahweh, ton Dieu, qui t''ai fait sortir du pays d''Egypte, de la maison de servitude.'),
('dt',5,7,'crampon1923','Tu n''auras point d''autres dieux devant ma face.'),
('dt',5,8,'crampon1923','Tu ne te feras point d''image taillée, ni aucune figure de ce qui est en haut dans le ciel, ou de ce qui est en bas sur la terre, ou de ce qui est dans les eaux au-dessous de la terre.'),
('dt',5,9,'crampon1923','Tu ne te prosterneras point devant eux et ne les serviras point; car moi, Yahweh, ton Dieu, je suis un Dieu jaloux, punissant l''iniquité des pères sur les enfants, sur la troisième et sur la quatrième génération, pour ceux qui me haïssent,'),
('dt',5,10,'crampon1923','et faisant miséricorde jusqu''à mille générations, pour ceux qui m''aiment et qui gardent mes commandements.'),
('dt',5,11,'crampon1923','Tu ne prendras point le nom de Yahweh, ton Dieu en vain; car Yahweh ne laissera pas impuni celui qui prendra son nom en vain.'),
('dt',5,12,'crampon1923','Observe le jour du sabbat, pour le sanctifier, comme te l''a ordonné Yahweh, ton Dieu.'),
('dt',5,13,'crampon1923','Pendant six jours tu travailleras et tu feras tout ton ouvrage.'),
('dt',5,14,'crampon1923','Mais le septième jour est un sabbat consacré à Yahweh, ton Dieu: tu ne feras aucun ouvrage, ni toi, ni ton fils, ni ta fille, ni ton serviteur, ni ta servante, ni ton bœuf, ni ton âne, ni aucune de tes bêtes, ni l''étranger qui est dans tes portes, afin que ton serviteur et ta servante se reposent comme toi.'),
('dt',5,15,'crampon1923','Tu te souviendras que tu as été esclave au pays d''Egypte, et que Yahweh, ton Dieu, t''en a fait sortir d''une main forte et d''un bras étendu: c''est pourquoi Yahweh, ton Dieu, t''a ordonné d''observer le jour du sabbat.'),
('dt',5,16,'crampon1923','Honore ton père et ta mère, comme Yahweh, ton Dieu te l''a ordonné, afin que tes jours soient prolongés et que tu sois heureux dans le pays que Yahweh, ton Dieu, te donne.'),
('dt',5,17,'crampon1923','Tu ne tueras point. Tu ne commettras point d''adultère. Tu ne déroberas point. Tu ne porteras point de faux témoignage contre ton prochain.'),
('dt',5,18,'crampon1923','Tu ne convoiteras point la femme de ton prochain. Tu ne désireras point la maison de ton prochain, ni son champ, ni son serviteur, ni sa servante, ni son bœuf, ni son âne, ni rien de ce qui appartient à ton prochain. »'),
('dt',5,19,'crampon1923','Telles sont les paroles que Yahweh adressa à toute votre assemblée, sur la montagne, du milieu du feu, de la nuée et de l''obscurité, d''une voix forte; et il n''ajouta rien. Il les écrivit sur deux tables de pierre, qu''il me donna.'),
('dt',5,20,'crampon1923','Lorsque vous eûtes entendu la voix du milieu des ténèbres, la montagne étant toute en feu, vous vous approchâtes de moi, tous vos chefs de tribus et vos anciens,'),
('dt',5,21,'crampon1923','et vous dîtes: « Voici que Yahweh, notre Dieu, nous a montré sa gloire et sa grandeur, et nous avons entendu sa voix du milieu du feu; aujourd''hui nous avons vu Dieu parler à l''homme et l''homme rester vivant.'),
('dt',5,22,'crampon1923','Et maintenant pourquoi mourrions-nous? Car ce grand feu nous dévorera; si nous entendons encore la voix de Yahweh, notre Dieu, nous mourrons.'),
('dt',5,23,'crampon1923','Car parmi toute chair, quel est celui qui a entendu, comme nous, la voix du Dieu vivant parlant du milieu du feu, et qui soit demeuré en vie?'),
('dt',5,24,'crampon1923','Toi, approche-toi, et écoute tout ce que dira Yahweh, notre Dieu, et tu nous rapporteras tout ce que t''aura dit Yahweh, notre Dieu: nous l''écouterons et nous le ferons. »'),
('dt',5,25,'crampon1923','Yahweh entendit vos paroles tandis que vous me parliez, et Yahweh me dit: « J''ai entendu les paroles que ce peuple t''a adressées: tout ce qu''ils ont dit est bien.'),
('dt',5,26,'crampon1923','Oh! S''ils avaient toujours ce même cœur pour me craindre et pour observer mes commandements, afin qu''ils soient heureux à jamais, eux et leurs enfants!'),
('dt',5,27,'crampon1923','Va, dis-leur: Retournez dans vos tentes.'),
('dt',5,28,'crampon1923','Mais toi, reste ici avec moi, et je te dirai tous les commandements, les lois et les ordonnances que tu leur enseigneras, pour qu''ils les mettent en pratique dans le pays que je leur donne en possession.'),
('dt',5,29,'crampon1923','Vous aurez soin de faire ce que Yahweh, votre Dieu, vous a commandé; vous ne vous en détournerez ni à droite ni à gauche,'),
('dt',5,30,'crampon1923','mais vous suivrez en tout la voie que Yahweh, votre Dieu, vous a prescrite, afin que vous viviez et que vous soyez heureux, et que vous prolongiez vos jours dans le pays que vous posséderez.” »'),
('dt',5,31,'crampon1923',''),
('dt',5,32,'crampon1923',''),
('dt',5,33,'crampon1923',''),
('dt',6,1,'crampon1923','Voici le commandement, les lois et les ordonnances que Yahweh, votre Dieu, a ordonné de vous enseigner, pour que vous les mettiez en pratique dans le pays où vous allez passer pour en prendre possession,'),
('dt',6,2,'crampon1923','afin que tu craignes Yahweh, ton Dieu, toi, ton fils et le fils de ton fils, en observant, tous les jours de ta vie, toutes ses lois et tous ses commandements que je te prescris, et afin que tes jours soient prolongés.'),
('dt',6,3,'crampon1923','Tu les écouteras, Israël, et tu auras soin de les mettre en pratique, afin que tu sois heureux et que vous multipliiez beaucoup, comme te l''a dit Yahweh, le Dieu de tes pères, dans un pays où coulent le lait et le miel.'),
('dt',6,4,'crampon1923','Ecoute, Israël: Yahweh, notre Dieu, est seul Yahweh.'),
('dt',6,5,'crampon1923','Tu aimeras Yahweh, ton Dieu, de tout ton cœur, de toute ton âme et de toute ta force.'),
('dt',6,6,'crampon1923','Et ces commandements que je te donne aujourd''hui, seront dans ton cœur.'),
('dt',6,7,'crampon1923','Tu les inculqueras à tes enfants, et tu en parleras quand tu seras dans ta maison, quand tu iras en voyage, quand tu te coucheras et quand tu te lèveras.'),
('dt',6,8,'crampon1923','Tu les attacheras sur ta main pour te servir de signe, et ils seront comme un frontal entre tes yeux.'),
('dt',6,9,'crampon1923','Tu les écriras sur les poteaux de ta maison et sur tes portes.'),
('dt',6,10,'crampon1923','Lorsque Yahweh, ton Dieu, t''aura fait entrer dans le pays qu''il a juré à tes pères, à Abraham, à Isaac et à Jacob, de te donner: grandes et bonnes villes que tu n''as pas bâties,'),
('dt',6,11,'crampon1923','maisons pleines de toutes sortes de biens que tu n''as pas remplies, citernes que tu n''as pas creusées, vignes et oliviers que tu n''as pas plantés; lorsque tu mangeras et te rassasieras,'),
('dt',6,12,'crampon1923','garde-toi d''oublier Yahweh, qui t''a fait sortir du pays d''Egypte, de la maison de servitude.'),
('dt',6,13,'crampon1923','Tu craindras Yahweh ton Dieu, tu le serviras et tu jureras par son nom.'),
('dt',6,14,'crampon1923','Vous n''irez point après d''autres dieux, d''entre les dieux des peuples, qui seront autour de vous.'),
('dt',6,15,'crampon1923','Car Yahweh, ton Dieu, qui est au milieu de toi, est un Dieu jaloux; la colère de Yahweh, ton Dieu, s''enflammerait contre toi, et il t''exterminerait de dessus la terre.'),
('dt',6,16,'crampon1923','Vous ne tenterez point Yahweh, votre Dieu, comme vous l''avez tenté à Massah.'),
('dt',6,17,'crampon1923','Mais vous observerez avec soin les commandements de Yahweh, votre Dieu, ses préceptes et ses lois qu''il t''a prescrites.'),
('dt',6,18,'crampon1923','Tu feras ce qui est droit et bon aux yeux de Yahweh, afin que tu sois heureux, que tu entres, pour le posséder, dans le bon pays que Yahweh a promis par serment à tes pères,'),
('dt',6,19,'crampon1923','lorsqu''il aura chassé tous tes ennemis devant toi comme Yahweh l''a dit.'),
('dt',6,20,'crampon1923','Lorsque ton fils t''interrogera un jour en disant: « Qu''est-ce que ces commandements, ces lois et ces ordonnances que Yahweh, notre Dieu, vous a prescrits? »'),
('dt',6,21,'crampon1923','tu diras à ton fils: « Nous étions esclaves de Pharaon, en Egypte, et Yahweh nous a fait sortir de l''Egypte par sa main puissante.'),
('dt',6,22,'crampon1923','Yahweh a opéré, sous nos yeux, des miracles et des prodiges grands et terribles contre l''Egypte, contre Pharaon et contre toute sa maison;'),
('dt',6,23,'crampon1923','et il nous a fait sortir de là, pour nous amener dans le pays qu''il avait promis par serment à nos pères.'),
('dt',6,24,'crampon1923','Yahweh nous a commandé de mettre en pratique toutes ces lois et de craindre Yahweh, notre Dieu, afin que nous soyons toujours heureux et qu''il nous conserve en vie, comme il le fait aujourd''hui.'),
('dt',6,25,'crampon1923','Et ce sera pour nous la justice, si nous prenons garde à pratiquer tous ces préceptes en présence de Yahweh, notre Dieu, comme il nous l''a ordonné. »'),
('dt',7,1,'crampon1923','Lorsque Yahweh, ton Dieu, t''aura fait entrer dans le pays dont tu vas prendre possession, et qu''il aura chassé devant toi beaucoup de nations, les Héthéens, les Gergéséens, les Amorrhéens, les Chananéens, les Phéréséens, les Hévéens et les Jébuséens, sept nations plus nombreuses et plus puissantes que toi,'),
('dt',7,2,'crampon1923','et que Yahweh, ton Dieu, te les aura livrées et que tu les auras battues, tu les dévoueras par anathème, tu ne concluras pas d''alliance avec elles et tu ne leur feras point grâce.'),
('dt',7,3,'crampon1923','Tu ne contracteras point de mariage avec elles, tu ne donneras point tes filles à leurs fils, et tu ne prendras point leurs filles pour tes fils;'),
('dt',7,4,'crampon1923','car elles détourneraient de marcher après moi tes fils, qui serviraient d''autres dieux; la colère de Yahweh s''enflammerait contre vous, et il te détruirait promptement.'),
('dt',7,5,'crampon1923','Mais voici comment vous agirez à leur égard: Vous renverserez leurs autels, vous briserez leurs stèles, vous abattrez leurs aschérim et vous livrerez au feu leurs images taillées.'),
('dt',7,6,'crampon1923','Car tu es un peuple saint à Yahweh, ton Dieu. Yahweh, ton Dieu, t''a choisi pour être son peuple particulier, parmi tous les peuples qui sont sur la face de la terre.'),
('dt',7,7,'crampon1923','Si Yahweh s''est attaché à vous et vous a choisis, ce n''est pas que vous surpassiez en nombre tous les peuples, car vous êtes le plus petit de tous les peuples.'),
('dt',7,8,'crampon1923','Mais, parce que Yahweh vous aime et parce qu''il a voulu tenir le serment qu''il avait fait à vos pères, Yahweh vous a fait sortir par sa main puissante et vous a rachetés de la maison de servitude, de la main de Pharaon, roi d''Egypte.'),
('dt',7,9,'crampon1923','Sache donc que c''est Yahweh, ton Dieu, qui est Dieu, le Dieu fidèle qui garde l''alliance et la miséricorde jusqu''à mille générations, pour ceux qui l''aiment et qui gardent ses commandements.'),
('dt',7,10,'crampon1923','Mais il rend la pareille en face à ceux qui le haïssent, en les faisant périr; il ne tarde point à l''égard de celui qui le hait, et il lui rend la pareille en face.'),
('dt',7,11,'crampon1923','C''est pourquoi tu observeras les commandements, les lois et les ordonnances que je te prescris aujourd''hui, en les mettant en pratique.'),
('dt',7,12,'crampon1923','Si vous écoutez ces ordonnances, si vous les gardez et les mettez en pratique, en retour Yahweh, ton Dieu, gardera envers toi l''alliance et la miséricorde qu''il a jurées à tes pères.'),
('dt',7,13,'crampon1923','Il t''aimera, te bénira et te multipliera; il bénira le fruit de tes entrailles et le fruit de ton sol, ton blé, ton vin nouveau et ton huile, les portées de tes vaches et les petits de tes brebis, sur la terre qu''il a juré à tes pères de te donner.'),
('dt',7,14,'crampon1923','Tu seras béni plus que tous les peuples; il n''y aura chez toi ni homme ni femme stérile, ni bête stérile parmi tes troupeaux.'),
('dt',7,15,'crampon1923','Yahweh éloignera de toi toute maladie; il ne t''enverra aucune de ces affections malignes d''Egypte que tu connais; mais il en affligera tous ceux qui te haïssent.'),
('dt',7,16,'crampon1923','Tu dévoreras tous les peuples que Yahweh, ton Dieu, va te livrer; ton œil sera sans pitié pour eux, et tu ne serviras point leurs dieux, car ce serait un piège pour toi.'),
('dt',7,17,'crampon1923','Que si tu dis dans ton cœur: « Ces nations sont plus nombreuses que moi; comment pourrai-je les chasser? »'),
('dt',7,18,'crampon1923','Ne les crains point; rappelle à ton souvenir ce que Yahweh, ton Dieu, a fait à Pharaon et à toute l''Egypte:'),
('dt',7,19,'crampon1923','les grandes épreuves que tes yeux ont vues, les miracles et les prodiges, la main forte et le bras étendu, par lesquels Yahweh, ton Dieu, t''a fait sortir: ainsi fera Yahweh, ton Dieu, à tous les peuples dont tu as peur.'),
('dt',7,20,'crampon1923','Yahweh, ton Dieu, enverra même sur eux les frelons, jusqu''à ce que soient détruits ceux qui auront pu échapper et se cacher devant toi.'),
('dt',7,21,'crampon1923','Tu ne t''effraieras point à cause d''eux; car Yahweh, ton Dieu, est au milieu de toi, Dieu grand et terrible!'),
('dt',7,22,'crampon1923','Yahweh, ton Dieu, chassera peu à peu ces nations devant toi; tu ne pourras pas les exterminer promptement, de peur que les bêtes sauvages ne se multiplient contre toi.'),
('dt',7,23,'crampon1923','Yahweh, ton Dieu, te les livrera, et il jettera parmi elles une grande consternation, jusqu''à ce qu''elles soient détruites.'),
('dt',7,24,'crampon1923','Il livrera leurs rois entre tes mains et tu feras disparaître leurs noms de dessous les cieux; personne ne tiendra devant toi, jusqu''à ce que tu les aies détruits.'),
('dt',7,25,'crampon1923','Vous consumerez par le feu les images taillées de leurs dieux; tu ne convoiteras point l''argent ou l''or qui est sur elles, et tu ne le prendras point pour toi, de peur qu''il ne te soit un piège; car il est en abomination à Yahweh, ton Dieu.'),
('dt',7,26,'crampon1923','Tu n''introduiras point une chose abominable dans ta maison, afin que tu ne sois pas, comme elle, dévoué par anathème; tu l''auras en horreur extrême, tu l''auras en extrême abomination, car c''est une chose dévouée par anathème.'),
('dt',8,1,'crampon1923','Vous aurez soin de mettre en pratique tous les commandements que je vous prescris aujourd''hui, afin que vous viviez, que vous multipliiez, que vous entriez et que vous preniez possession du pays que Yahweh a juré de donner à vos pères.'),
('dt',8,2,'crampon1923','Tu te souviendras de tout le chemin par lequel Yahweh, ton Dieu, t''a fait marcher pendant ces quarante années dans le désert, afin de t''humilier, et de t''éprouver, pour connaître les sentiments de ton cœur, si tu garderas ou non ses commandements.'),
('dt',8,3,'crampon1923','Il t''a humilié, il t''a fait avoir faim, et il t''a nourri de la manne, que tu ne connaissais pas et que n''avaient pas connue tes pères, afin de t''apprendre que l''homme ne vit pas de pain seulement, mais que l''homme vit de tout ce qui sort de la bouche de Dieu.'),
('dt',8,4,'crampon1923','Ton vêtement ne s''est pas usé sur toi, et ton pied ne s''est pas enflé, pendant ces quarante années:'),
('dt',8,5,'crampon1923','afin que tu reconnaisses en ton cœur que Yahweh, ton Dieu, t''instruit, comme un homme instruit son enfant,'),
('dt',8,6,'crampon1923','et que tu observes les commandements de Yahweh, ton Dieu, en marchant dans ses voies et en le craignant.'),
('dt',8,7,'crampon1923','Car Yahweh, ton Dieu, va te faire entrer dans un bon pays, pays de torrents, de sources et d''eaux profondes, qui jaillissent dans les vallées et les montagnes;'),
('dt',8,8,'crampon1923','pays de froment, d''orge, de vignes, de figuiers et de grenadiers; pays d''oliviers, d''huile et de miel;'),
('dt',8,9,'crampon1923','pays où tu mangeras du pain en abondance, où tu ne manqueras de rien; pays dont les pierres sont du fer, et des montagnes duquel tu tireras l''airain.'),
('dt',8,10,'crampon1923','Tu mangeras et te rassasieras, et tu béniras Yahweh, ton Dieu, pour le bon pays qu''il t''a donné.'),
('dt',8,11,'crampon1923','Garde-toi d''oublier Yahweh, ton Dieu, négligeant d''observer ses commandements, ses ordonnances et ses lois que je te prescris aujourd''hui,'),
('dt',8,12,'crampon1923','de peur que, quand tu mangeras et te rassasieras, que tu bâtiras et habiteras de belles maisons,'),
('dt',8,13,'crampon1923','que tu verras se multiplier tes bœufs et tes brebis. S''augmenter ton argent, ton or, et s''augmenter tous tes biens,'),
('dt',8,14,'crampon1923','ton cœur ne s''élève et que tu n''oublies Yahweh, ton Dieu, qui t''a fait sortir du pays d''Egypte, de la maison de servitude;'),
('dt',8,15,'crampon1923','qui t''a conduit dans ce grand et affreux désert, où il y a des serpents brûlants et des scorpions, dans des lieux arides et sans eau, et qui a fait jaillir pour toi de l''eau du rocher le plus dur;'),
('dt',8,16,'crampon1923','qui t''a donné à manger dans le désert une manne inconnue à tes pères, afin de t''humilier et de t''éprouver, pour te faire ensuite du bien;'),
('dt',8,17,'crampon1923','et que tu ne dises en ton cœur; « C''est ma force et la vigueur de ma main qui m''ont procuré ces richesses. »'),
('dt',8,18,'crampon1923','Souviens-toi de Yahweh, ton Dieu, car c''est lui qui te donne de la force pour les acquérir, afin d''accomplir, comme tu le vois aujourd''hui, son alliance qu''il a jurée à tes pères.'),
('dt',8,19,'crampon1923','Si, oubliant Yahweh, ton Dieu, il t''arrive d''aller après d''autres dieux, de les servir et de te prosterner devant eux, j''atteste aujourd''hui contre vous que vous périrez certainement.'),
('dt',8,20,'crampon1923','Comme les nations que Yahweh fait périr devant vous, ainsi vous périrez, parce que vous n''aurez pas écouté la voix de Yahweh, votre Dieu.'),
('dt',9,1,'crampon1923','Ecoute, Israël. Tu vas aujourd''hui passer le Jourdain, pour marcher à la conquête de nations plus grandes et plus puissantes que toi, de grandes villes dont les murailles s''élèvent jusqu''au ciel,'),
('dt',9,2,'crampon1923','d''un peuple grand et de haute stature, des enfants des Enacim, que tu connais et dont tu as entendu dire: Qui pourra tenir contre les enfants d''Enac?'),
('dt',9,3,'crampon1923','Sache aujourd''hui que Yahweh, ton Dieu, passera lui-même devant toi comme un feu dévorant; c''est lui qui les détruira, lui qui les humiliera devant toi; tu les chasseras et tu les feras périr promptement, comme Yahweh te l''a dit.'),
('dt',9,4,'crampon1923','Ne dis pas dans ton cœur, lorsque Yahweh, ton Dieu, les chassera de devant toi: « C''est à cause de ma justice que Yahweh m''a fait venir pour prendre possession de ce pays ». Car c''est à cause de la méchanceté de ces nations que Yahweh les chasse de devant toi.'),
('dt',9,5,'crampon1923','Non, ce n''est point à cause de ta justice et de la droiture de ton cœur que tu viens prendre possession de leur pays; mais c''est à cause de la méchanceté de ces nations que Yahweh, ton Dieu, les chasse de devant toi; c''est aussi pour accomplir la parole que Yahweh a jurée à tes pères, à Abraham, à Isaac et à Jacob.'),
('dt',9,6,'crampon1923','Sache donc que ce n''est pas à cause de ta justice que Yahweh, ton Dieu, te donne ce bon pays en propriété; car tu es un peuple au cou raide.'),
('dt',9,7,'crampon1923','Souviens-toi, n''oublie pas combien tu as irrité Yahweh, ton Dieu, dans le désert. Depuis le jour où tu es sorti du pays d''Egypte jusqu''à votre arrivée dans ce lieu, vous avez été rebelles envers Yahweh.'),
('dt',9,8,'crampon1923','Même en Horeb vous avez excité Yahweh à la colère, et Yahweh fut irrité contre vous jusqu''à vouloir vous détruire.'),
('dt',9,9,'crampon1923','Lorsque je montai sur la montagne, pour recevoir les tables de pierre, les tables de l''alliance que Yahweh avait conclue avec vous, je demeurai sur la montagne quarante jours et quarante nuits, sans manger de pain et sans boire d''eau;'),
('dt',9,10,'crampon1923','et Yahweh me donna les deux tables de pierre écrites du doigt de Dieu, et contenant toutes les paroles que Yahweh vous avait dites sur la montagne, du milieu du feu, le jour de l''assemblée.'),
('dt',9,11,'crampon1923','Au bout des quarante jours et des quarante nuits, Yahweh me donna les deux tables de pierre, les tables de l''alliance.'),
('dt',9,12,'crampon1923','Yahweh me dit alors: « Lève-toi, descends vite d''ici, car ton peuple, que tu as fait sortir d''Egypte, s''est corrompu. Ils se sont promptement écartés de la voie que je leur avais prescrite; ils se sont fait une image de fonte. »'),
('dt',9,13,'crampon1923','Et Yahweh me dit: « Je vois que ce peuple est un peuple au cou raide.'),
('dt',9,14,'crampon1923','Laisse-moi, que je les détruise et que j''efface leur nom de dessous les cieux; et je ferai de toi une nation plus puissante et plus nombreuse que ce peuple. »'),
('dt',9,15,'crampon1923','Je me tournai et je descendis de la montagne, et la montagne était toute en feu, et j''avais dans mes deux mains les deux tables de l''alliance.'),
('dt',9,16,'crampon1923','Je regardai, et voici que vous aviez péché contre Yahweh, votre Dieu; vous vous étiez fait un veau de fonte, et vous vous étiez promptement écartés de la voie que Yahweh vous avait prescrite.'),
('dt',9,17,'crampon1923','Alors, saisissant les deux tables, je les jetai de mes mains et je les brisai sous vos yeux.'),
('dt',9,18,'crampon1923','Et je tombai devant Yahweh, comme la première fois, pendant quarante jours et quarante nuits, sans manger de pain, et sans boire d''eau, à cause de tous les péchés que vous aviez commis en faisant ce qui est mal aux yeux de Yahweh, de manière à l''irriter.'),
('dt',9,19,'crampon1923','Car j''étais effrayé en voyant la colère et la fureur dont Yahweh était animé contre vous, jusqu''à vouloir vous détruire; mais cette fois encore Yahweh m''exauça.'),
('dt',9,20,'crampon1923','Yahweh était aussi fortement irrité contre Aaron, au point de vouloir le faire périr, et j''intercédai aussi pour Aaron en ce temps-là.'),
('dt',9,21,'crampon1923','Je pris le péché que vous aviez fait, le veau d''or, je le brûlai au feu, je le broyai jusqu''à ce qu''il fût bien réduit en poudre, et je jetai cette poudre dans le torrent qui descend de la montagne.'),
('dt',9,22,'crampon1923','A Tabéera, à Massah et à Kibroth-Hattaava, vous avez encore excité Yahweh à la colère.'),
('dt',9,23,'crampon1923','Et lorsque Yahweh vous envoya de Cadès-Barné, en disant: Montez et prenez possession du pays que je vous donne, vous fûtes rebelles à l''ordre de Yahweh, votre Dieu, vous n''eûtes pas foi en lui et vous n''obéîtes pas à sa voix.'),
('dt',9,24,'crampon1923','Vous avez été rebelles à Yahweh depuis le jour où je vous ai connus.'),
('dt',9,25,'crampon1923','Je me prosternai donc devant Yahweh pendant les quarante jours et les quarante nuits que je restai prosterné, car Yahweh parlait de vous détruire.'),
('dt',9,26,'crampon1923','Je priai Yahweh et je dis: « Seigneur Yahweh, ne détruisez pas votre peuple, votre héritage, que vous avez racheté par votre grandeur, que vous avez fait sortir d''Egypte par votre main puissante.'),
('dt',9,27,'crampon1923','Souvenez-vous de vos serviteurs, Abraham, Isaac et Jacob; ne regardez point à l''opiniâtreté de ce peuple, à sa méchanceté et à son péché,'),
('dt',9,28,'crampon1923','de peur que le pays d''où vous nous avez fait sortir ne dise: Parce que Yahweh n''avait pas le pouvoir de les faire entrer dans le pays qu''il leur avait promis, et parce qu''il les haïssait, il les a fait sortir pour les faire mourir dans le désert.'),
('dt',9,29,'crampon1923','Et pourtant ils sont votre peuple et votre héritage, que vous avez fait sortir d''Egypte par votre grande puissance et par votre bras étendu! »'),
('dt',10,1,'crampon1923','En ce temps-là, Yahweh me dit: Taille-toi deux tables de pierre, comme les premières, et monte vers moi sur la montagne; tu feras aussi une arche de bois.'),
('dt',10,2,'crampon1923','J''écrirais sur ces tables les paroles qui étaient sur les premières tables, que tu as brisées, et tu les mettras dans l''arche.'),
('dt',10,3,'crampon1923','Je fis une arche de bois d''acacia et, ayant taillé deux tables de pierre comme les premières, je montai sur la montagne, les deux tables dans ma main.'),
('dt',10,4,'crampon1923','Il écrivit sur ces tables ce qui avait été écrit sur les premières, les dix paroles que Yahweh vous avait dites sur la montagne, du milieu du feu, le jour de l''assemblée; et Yahweh me les donna.'),
('dt',10,5,'crampon1923','Je me tournai et, étant descendu de la montagne, je mis les tables dans l''arche que j''avais faite, et elles y sont restées, comme Yahweh me l''avait ordonné.'),
('dt',10,6,'crampon1923','Les enfants d''Israël partirent de Béeroth-Bené-Jakan pour Moséra. Là mourut Aaron, et il y fut enterré; Eléazar, son fils, fut grand prêtre à sa place.'),
('dt',10,7,'crampon1923','De là ils partirent pour Gadgad, et de Gadgad pour Jétébatha, pays riche en cours d''eaux.'),
('dt',10,8,'crampon1923','En ce temps-là, Yahweh sépara la tribu de Lévi, pour porter l''arche de l''alliance de Yahweh, pour se tenir devant Yahweh, pour le servir et pour bénir en son nom: ce qu''elle a fait jusqu''à ce jour.'),
('dt',10,9,'crampon1923','C''est pourquoi Lévi n''a ni part ni héritage avec ses frères: c''est Yahweh qui est son héritage, comme Yahweh, ton Dieu, le lui a dit.'),
('dt',10,10,'crampon1923','Je me tins sur la montagne, comme précédemment, quarante jours et quarante nuits, et Yahweh m''exauça encore cette fois: Yahweh ne voulut pas te détruire.'),
('dt',10,11,'crampon1923','Yahweh me dit: « Lève-toi, va te mettre à la tête du peuple; qu''ils entrent et qu''ils prennent possession du pays que j''ai juré à leurs pères de leur donner. »'),
('dt',10,12,'crampon1923','Et maintenant, Israël, que demande de toi Yahweh, ton Dieu, si ce n''est que tu craignes Yahweh, ton Dieu, en marchant dans toutes ses voies, en aimant et en servant Yahweh, ton Dieu, de tout ton cœur et de toute ton âme,'),
('dt',10,13,'crampon1923','en observant les commandements de Yahweh et ses lois que je te prescris aujourd''hui, afin que tu sois heureux?'),
('dt',10,14,'crampon1923','Vois! A Yahweh, ton Dieu, appartiennent le ciel et le ciel des cieux, la terre et tout ce qu''elle renferme.'),
('dt',10,15,'crampon1923','Et c''est à tes pères seulement que Yahweh s''est attaché pour les aimer; et c''est leur postérité après eux, c''est vous qu''il a choisi d''entre tous les peuples, comme vous le voyez aujourd''hui.'),
('dt',10,16,'crampon1923','Circoncisez donc votre cœur et ne raidissez plus votre cou.'),
('dt',10,17,'crampon1923','Car Yahweh, votre Dieu, est le Dieu des dieux, le Seigneur des seigneurs, le Dieu grand, fort et terrible, qui ne fait point acception des personnes et qui ne reçoit point de présent,'),
('dt',10,18,'crampon1923','qui fait droit à l''orphelin et à la veuve, qui aime l''étranger et lui donne de la nourriture et des vêtements.'),
('dt',10,19,'crampon1923','Vous aimerez l''étranger, car vous avez été étrangers dans le pays d''Egypte.'),
('dt',10,20,'crampon1923','Tu craindras Yahweh, ton Dieu, tu le serviras, tu t''attacheras à lui, et tu jureras par son nom.'),
('dt',10,21,'crampon1923','Il est ta louange, il est ton Dieu; c''est lui qui a fait pour toi ces choses grandes et terribles que tes yeux ont vues.'),
('dt',10,22,'crampon1923','Tes pères descendirent en Egypte au nombre de soixante-dix personnes, et maintenant Yahweh, ton Dieu, a fait de toi une multitude comme les étoiles du ciel.'),
('dt',11,1,'crampon1923','Tu aimeras Yahweh, ton Dieu, et tu observeras ce qu''il demande de toi, ses lois, ses ordonnances et ses commandements, tous les jours de ta vie.'),
('dt',11,2,'crampon1923','Reconnaissez aujourd''hui, — car je ne m''adresse pas à vos enfants, qui ne connaissent pas et qui n''ont pas vu les leçons de Yahweh, votre Dieu, — reconnaissez sa grandeur, sa main forte et son bras étendu;'),
('dt',11,3,'crampon1923','ses prodiges et ses œuvres qu''il a faits au milieu de l''Egypte, contre Pharaon, roi d''Egypte, et contre tout son pays;'),
('dt',11,4,'crampon1923','ce qu''il a fait à l''armée d''Egypte, à ses chevaux et à ses chars, comment il a précipité sur eux les eaux de la mer Rouge, lorsqu''ils vous poursuivaient, et comment Yahweh les a détruits jusqu''à ce jour.'),
('dt',11,5,'crampon1923','Reconnaissez ce qu''il a fait pour vous dans le désert, jusqu''à votre arrivée en ce lieu;'),
('dt',11,6,'crampon1923','ce qu''il a fait à Dathan et Abiron, fils d''Eliab, fils de Ruben, que la terre, ouvrant sa bouche, engloutit, avec leurs maisons, leurs tentes et toutes les personnes de leur suite, au milieu de tout Israël.'),
('dt',11,7,'crampon1923','Car vos yeux ont vu toutes les grandes œuvres que Yahweh a faites.'),
('dt',11,8,'crampon1923','Vous observerez donc tous les commandements que je vous prescris aujourd''hui, afin que vous soyez forts, que vous entriez et que vous vous rendiez maîtres du pays où vous allez passer pour en prendre possession,'),
('dt',11,9,'crampon1923','et afin que vous prolongiez vos jours sur la terre que Yahweh a juré à vos pères de leur donner, à eux et à leur postérité, pays où coulent le lait et le miel.'),
('dt',11,10,'crampon1923','Car le pays où tu vas entrer pour le posséder n''est pas comme le pays d''Egypte, d''où vous êtes sortis, que tu ensemençais et que tu arrosais avec ton pied, comme un jardin potager.'),
('dt',11,11,'crampon1923','Mais le pays où vous allez passer pour le posséder est un pays de montagnes et de vallées, qui boit les eaux de la pluie du ciel;'),
('dt',11,12,'crampon1923','un pays dont Yahweh, ton Dieu, prend soin, et sur lequel Yahweh a continuellement les yeux, depuis le commencement de l''année jusqu''à la fin de l''année.'),
('dt',11,13,'crampon1923','Si vous obéissez à mes commandements que je vous prescris aujourd''hui, aimant Yahweh, votre Dieu, et le servant de tout votre cœur et de toute votre âme,'),
('dt',11,14,'crampon1923','je donnerai à votre pays la pluie en son temps, la pluie de la première et celle de la dernière saison, et tu recueilleras ton blé, ton vin nouveau et ton huile;'),
('dt',11,15,'crampon1923','je mettrai aussi de l''herbe dans tes champs pour ton bétail, et tu mangeras et te rassasieras.'),
('dt',11,16,'crampon1923','Prenez garde à vous, de peur que votre cœur ne soit séduit, que vous ne vous détourniez et ne serviez d''autres dieux et ne vous prosterniez devant eux.'),
('dt',11,17,'crampon1923','La colère de Yahweh s''enflammerait contre vous; il fermerait le ciel, et il n''y aurait point de pluie; la terre ne donnerait pas ses produits et vous péririez promptement dans le bon pays que Yahweh vous donne.'),
('dt',11,18,'crampon1923','Mettez donc sur votre cœur et sur votre âme ces paroles que je vous dis. Vous les lierez comme un signe sur vos mains, et elles seront comme des fronteaux entre vos yeux.'),
('dt',11,19,'crampon1923','Vous les enseignerez à vos enfants, et vous leur en parlerez, soit quand tu resteras dans ta maison, ou que tu iras en voyage, soit quand tu te coucheras ou que tu te lèveras.'),
('dt',11,20,'crampon1923','Tu les écriras sur les poteaux de ta maison et sur tes portes:'),
('dt',11,21,'crampon1923','afin que vos jours et les jours de vos enfants, dans le pays que Yahweh a juré à vos pères de leur donner, soient aussi nombreux que les jours des cieux au-dessus de la terre.'),
('dt',11,22,'crampon1923','Car si vous observez soigneusement tous ces commandements que je vous prescris d''accomplir, aimant Yahweh, votre Dieu, marchant dans toutes ses voies et vous attachant à lui,'),
('dt',11,23,'crampon1923','Yahweh chassera toutes ces nations devant vous, et vous vous rendrez maîtres de nations plus grandes et plus puissantes que vous.'),
('dt',11,24,'crampon1923','Tout lieu que foulera la plante de vos pieds sera à vous; votre frontière s''étendra du désert au Liban, et du fleuve de l''Euphrate jusqu''à la mer occidentale.'),
('dt',11,25,'crampon1923','Nul ne tiendra devant vous; Yahweh, votre Dieu, répandra devant vous, comme il vous l''a dit, la crainte et l''effroi sur tout le pays où vous mettrez le pied.'),
('dt',11,26,'crampon1923','Voici que je mets aujourd''hui devant vous une bénédiction et une malédiction:'),
('dt',11,27,'crampon1923','la bénédiction, si vous obéissez aux commandements de Yahweh, votre Dieu, que je vous prescris aujourd''hui;'),
('dt',11,28,'crampon1923','la malédiction, si vous n''obéissez pas aux commandements de Yahweh, votre Dieu, et si vous vous détournez de la voie que je vous prescris en ce jour, pour aller après d''autres dieux que vous n''avez pas connus.'),
('dt',11,29,'crampon1923','Et lorsque Yahweh, ton Dieu, t''aura fait entrer dans le pays où tu vas pour en prendre possession, tu prononceras la bénédiction sur le mont Garizim, et la malédiction sur le mont Ebal.'),
('dt',11,30,'crampon1923','Ces montagnes ne sont-elles pas de l''autre côté du Jourdain, derrière le chemin de l''occident, au pays des Chananéens qui habitent dans l''Arabah, vis-à-vis de Galgala, près des térébinthes de Moré?'),
('dt',11,31,'crampon1923','Car vous allez passer le Jourdain pour entrer en possession du pays que Yahweh, votre Dieu, vous donne; vous le posséderez et vous y habiterez.'),
('dt',11,32,'crampon1923','Vous aurez donc soin d''observer toutes les lois et toutes les ordonnances que je mets aujourd''hui devant vous. »'),
('dt',12,1,'crampon1923','Voici les lois et les ordonnances que vous aurez soin de mettre en pratique dans le pays que Yahweh, le Dieu de vos pères, vous à donné pour le posséder, tout le temps que vous vivrez sur ce sol.'),
('dt',12,2,'crampon1923','Vous détruirez entièrement tous les lieux où les nations que vous allez chasser servaient leurs dieux, sur les hautes montagnes, sur les collines et sous tout arbre vert.'),
('dt',12,3,'crampon1923','Vous renverserez leurs autels, vous briserez leurs stèles, vous livrerez au feu leurs aschérim, vous mettrez en pièces les images taillées de leurs dieux, et vous ferez disparaître de ces lieux jusqu''à leurs noms.'),
('dt',12,4,'crampon1923','Vous ne ferez pas ainsi à l''égard de Yahweh, votre Dieu.'),
('dt',12,5,'crampon1923','Mais vous le chercherez au lieu que Yahweh, votre Dieu, choisira parmi toutes vos tribus pour y mettre son nom et en faire sa demeure, et c''est là que tu iras.'),
('dt',12,6,'crampon1923','C''est là que vous présenterez vos holocaustes et vos sacrifices, vos dîmes et ce que votre main aura prélevé, vos vœux et vos offrandes volontaires, et les premiers-nés de vos bœufs et de vos brebis.'),
('dt',12,7,'crampon1923','C''est là que vous ferez des repas sacrés devant Yahweh, votre Dieu, et que vous vous réjouirez, vous et vos familles, en jouissant de tous les biens que votre main aura acquis et par lesquels Yahweh, ton Dieu, t''aura béni.'),
('dt',12,8,'crampon1923','Vous ne ferez pas, selon tout ce que nous faisons maintenant ici, chacun ce que bon lui semble,'),
('dt',12,9,'crampon1923','parce que vous n''êtes pas encore arrivés au repos et à l''héritage que te donne Yahweh, ton Dieu.'),
('dt',12,10,'crampon1923','Mais vous passerez le Jourdain et vous habiterez le pays que Yahweh, votre Dieu, vous donnera en héritage, et il vous donnera du repos en vous protégeant contre tous les ennemis qui vous entourent, et vous habiterez en sécurité.'),
('dt',12,11,'crampon1923','Alors dans le lieu que Yahweh, votre Dieu, choisira pour y faire habiter son nom, c''est là que vous présenterez tout ce que je vous commande, vos holocaustes et vos sacrifices, vos dîmes et ce que votre main aura prélevé, et toutes les offrandes de choix pour l''accomplissement de vos vœux que vous ferez à Yahweh.'),
('dt',12,12,'crampon1923','Et vous vous réjouirez en présence de Yahweh, votre Dieu, vous, vos fils et vos filles, vos serviteurs et vos servantes, et le Lévite qui sera dans vos portes, car il n''a reçu ni part ni héritage avec vous.'),
('dt',12,13,'crampon1923','Garde-toi d''offrir tes holocaustes dans tous les lieux que tu verras;'),
('dt',12,14,'crampon1923','mais tu offriras tes holocaustes au lieu que Yahweh aura choisi dans l''une de tes tribus, et c''est là que tu feras tout ce que je te commande.'),
('dt',12,15,'crampon1923','Tu pourras néanmoins, tant que tu le désireras, tuer du bétail et manger de la viande dans toutes tes portes, selon les bénédictions que t''accordera Yahweh, ton Dieu; l''homme impur et l''homme pur pourront en manger, comme on mange de la gazelle et du cerf.'),
('dt',12,16,'crampon1923','Mais vous ne mangerez pas le sang: tu le répandras sur la terre, comme de l''eau.'),
('dt',12,17,'crampon1923','Tu ne pourras pas manger dans tes portes la dîme de ton blé, de ton vin nouveau et de ton huile, ni les premiers-nés de tes bœufs et de tes brebis, ni toutes les offrandes que tu auras vouées, ni tes offrandes volontaires, ni ce que ta main aura prélevé.'),
('dt',12,18,'crampon1923','C''est devant Yahweh, ton Dieu, dans le lieu que Yahweh, ton Dieu, aura choisi, que tu les mangeras, toi, ton fils et ta fille, ton serviteur et ta servante, et le Lévite qui sera dans tes portes; tu te réjouiras devant Yahweh, ton Dieu, en jouissant de tous les biens que ta main aura acquis.'),
('dt',12,19,'crampon1923','Garde-toi de délaisser le Lévite, aussi longtemps que tu vivras sur ton sol.'),
('dt',12,20,'crampon1923','Lorsque Yahweh, ton Dieu, aura élargi tes frontières, comme il te l''a promis, et que tu diras: Je veux manger de la viande, ton âme éprouvant le désir de manger de la viande, tu pourras manger de la viande toutes les fois que tu le désireras.'),
('dt',12,21,'crampon1923','Si le lieu que Yahweh, ton Dieu, choisira pour y mettre son nom est éloigné de toi, tu pourras tuer de tes bœufs et de tes brebis que Yahweh t''a donnés, selon que je te l''ai prescrit, et tu en mangeras dans tes portes, toutes les fois que tu le désireras.'),
('dt',12,22,'crampon1923','Tu en mangeras comme on mange de la gazelle ou du cerf: l''homme pur ou l''homme impur en mangeront l''un et l''autre.'),
('dt',12,23,'crampon1923','Seulement tiens ferme à ne pas manger le sang, car le sang, c''est l''âme, et tu ne mangeras pas l''âme avec la chair.'),
('dt',12,24,'crampon1923','Tu ne le mangeras pas; tu le répandras sur la terre comme de l''eau.'),
('dt',12,25,'crampon1923','Tu ne le mangeras pas, afin que tu sois heureux, toi et tes enfants après toi, en faisant ce qui est droit aux yeux de Yahweh.'),
('dt',12,26,'crampon1923','Mais les saintes offrandes qui te sont demandées et celles que tu as vouées, tu les prendras et tu iras au lieu que Yahweh aura choisi,'),
('dt',12,27,'crampon1923','et tu offriras tes holocaustes, la chair et le sang, sur l''autel de Yahweh, ton Dieu; dans les autres sacrifices, le sang sera répandu sur l''autel de Yahweh, ton Dieu, et tu mangeras la chair.'),
('dt',12,28,'crampon1923','Observe et écoute toutes ces choses que je t''ordonne, afin que tu sois heureux, toi et tes enfants après toi, à perpétuité, en faisant ce qui est bien et droit aux yeux de Yahweh.'),
('dt',12,29,'crampon1923','Lorsque Yahweh, ton Dieu, aura exterminé les nations là où tu vas pour les chasser de devant de toi, que tu les auras chassées et que tu habiteras dans leur pays,'),
('dt',12,30,'crampon1923','prends garde que tu ne sois pris au piège en les imitant, après qu''elles auront été détruites devant toi. Garde-toi de rechercher leurs dieux, en disant: « Comment ces nations servaient-elles leurs dieux? Je veux faire de même, moi aussi. »'),
('dt',12,31,'crampon1923','Tu n''agiras pas ainsi à l''égard de Yahweh, ton Dieu; car elles faisaient pour leurs dieux toutes les abominations que déteste Yahweh, et même elles livrent au feu leurs fils et leurs filles en l''honneur de leurs dieux.'),
('dt',13,1,'crampon1923','Toutes les choses que je vous prescris, vous les observerez en les mettant en pratique, sans y rien ajouter et sans en rien retrancher.'),
('dt',13,2,'crampon1923','S''il s''élève au milieu de toi un prophète ou un songeur qui t''annonce un signe ou un prodige,'),
('dt',13,3,'crampon1923','et que s''accomplisse le signe ou le prodige dont il t''a parlé en disant: « Allons après d''autres dieux, — des dieux que tu ne connais pas! — et servons-les, »'),
('dt',13,4,'crampon1923','tu n''écouteras pas les paroles de ce prophète ou de ce songeur; car Yahweh, votre Dieu, vous éprouve pour savoir si vous aimez Yahweh, votre Dieu, de tout votre cœur et de toute votre âme.'),
('dt',13,5,'crampon1923','C''est après Yahweh, votre Dieu, que vous irez, c''est lui que vous craindrez; vous observerez ses commandements, vous obéirez à sa voix, vous le servirez et vous vous attacherez à lui.'),
('dt',13,6,'crampon1923','Et ce prophète ou ce songeur sera mis à mort, car il a prêché la révolte contre Yahweh, votre Dieu, qui vous a fait sortir du pays d''Egypte et vous a délivrés de la maison de servitude, pour te détourner de la voie dans laquelle Yahweh, ton Dieu, t''a ordonné de marcher. Tu ôteras ainsi le mal du milieu de toi.'),
('dt',13,7,'crampon1923','Si ton frère, fils de ta mère, ou ton fils, ou ta fille, ou la femme qui repose sur ton sein, ou ton ami qui est comme ta propre âme, t''incite en secret, en disant: « Allons, et servons d''autres dieux, » — des dieux que n''ont connus ni toi ni tes pères,'),
('dt',13,8,'crampon1923','d''entre les dieux des peuples qui vous entourent, près de toi ou loin de toi, d''un bout de la terre à l''autre, —'),
('dt',13,9,'crampon1923','tu ne lui céderas pas et tu ne l''écouteras pas; ton œil sera sans pitié pour lui, tu ne l''épargneras pas et tu ne le couvriras pas,'),
('dt',13,10,'crampon1923','mais tu le feras mourir; ta main se lèvera la première contre lui pour le mettre à mort, et la main de tout le peuple ensuite;'),
('dt',13,11,'crampon1923','tu l''accableras de pierres jusqu''à ce qu''il meure, parce qu''il a cherché à te détourner de Yahweh, ton Dieu, qui t''a fait sortir du pays d''Egypte, de la maison de servitude.'),
('dt',13,12,'crampon1923','Tout Israël l''apprendra et sera dans la crainte, afin que l''on ne commette plus une action aussi criminelle au milieu de toi.'),
('dt',13,13,'crampon1923','Si tu entends dire de l''une des villes que Yahweh, ton Dieu, t''a données pour demeure:'),
('dt',13,14,'crampon1923','« Des gens pervers, sortis du milieu de toi, ont séduit les habitants de leur ville, en disant: “Allons et servons d''autres dieux”, — des dieux que vous ne connaissez pas! —'),
('dt',13,15,'crampon1923','tu feras une enquête, tu examineras, tu interrogeras avec soin. Si ce bruit est vrai et le fait établi, si cette abomination a été commise au milieu de toi,'),
('dt',13,16,'crampon1923','alors, tu ne manqueras pas de passer au fil de l''épée les habitants de cette ville, la dévouant par anathème avec tout ce qu''elle contient, et tu passeras aussi son bétail au fil de l''épée.'),
('dt',13,17,'crampon1923','Tu amasseras tout son butin au milieu de la place, et tu brûleras entièrement au feu la ville avec tout son butin, pour Yahweh, ton Dieu; elle sera pour toujours un monceau de ruines, elle ne sera plus rebâtie.'),
('dt',13,18,'crampon1923','Rien de ce qui aura été dévoué par anathème ne s''attachera à ta main, afin que Yahweh revienne de l''ardeur de sa colère, qu''il te fasse grâce et miséricorde, et qu''il te multiplie, comme il l''a juré à tes pères,'),
('dt',13,19,'crampon1923','si tu obéis à la voix de Yahweh, ton Dieu, en observant tous ses commandements que je te prescris aujourd''hui, et en faisant ce qui est droit aux yeux de Yahweh, ton Dieu.'),
('dt',14,1,'crampon1923','Vous êtes les enfants de Yahweh, votre Dieu. Vous ne vous ferez point d''incision et vous ne vous tondrez point une place entre les yeux pour un mort.'),
('dt',14,2,'crampon1923','Car tu es un peuple saint à Yahweh, ton Dieu; et Yahweh t''a choisi pour lui être un peuple particulier entre tous les peuples qui sont sur la face de la terre.'),
('dt',14,3,'crampon1923','Tu ne mangeras aucune chose abominable.'),
('dt',14,4,'crampon1923','Voici les animaux dont vous mangerez: le bœuf, la brebis et la chèvre;'),
('dt',14,5,'crampon1923','le cerf, la gazelle et le daim; le bouquetin, l''antilope, le bœuf sauvage et la chèvre sauvage.'),
('dt',14,6,'crampon1923','Vous mangerez de tout animal qui a la corne divisée et le pied fourchu, et qui rumine.'),
('dt',14,7,'crampon1923','Mais vous ne mangerez pas de ceux qui ruminent seulement, ou qui ont seulement la corne divisée et le pied fourchu; tels sont le chameau, le lièvre et le lapin, qui ruminent, mais qui n''ont pas la corne divisée: ils seront impurs pour vous;'),
('dt',14,8,'crampon1923','tel est encore le porc, qui a la corne divisée, mais qui ne rumine pas: il sera impur pour vous. Vous ne mangerez pas de leur chair, et vous ne toucherez pas leurs corps morts.'),
('dt',14,9,'crampon1923','Voici les animaux que vous mangerez parmi tous ceux qui sont dans les eaux: vous mangerez de tout ce qui a nageoires et écailles;'),
('dt',14,10,'crampon1923','mais tout ce qui n''a pas nageoires et écailles, vous ne le mangerez pas: ce sera impur pour vous.'),
('dt',14,11,'crampon1923','Vous mangerez tout oiseau pur.'),
('dt',14,12,'crampon1923','Voici ceux dont vous ne mangerez pas: l''aigle, l''orfraie et le vautour;'),
('dt',14,13,'crampon1923','le faucon, le milan et toute espèce d''autours;'),
('dt',14,14,'crampon1923','toute espèce de corbeaux;'),
('dt',14,15,'crampon1923','l''autruche, le hibou, la mouette et toute espèce d''éperviers;'),
('dt',14,16,'crampon1923','le chat-huant, l''ibis et la chouette;'),
('dt',14,17,'crampon1923','le pélican, le cormoran et le plongeon;'),
('dt',14,18,'crampon1923','la cigogne et toute espèce de hérons; la huppe et la chauve-souris.'),
('dt',14,19,'crampon1923','Vous regarderez comme impur tout insecte ailé: on n''en mangera pas.'),
('dt',14,20,'crampon1923','Vous mangerez tout oiseau pur.'),
('dt',14,21,'crampon1923','Vous ne mangerez d''aucune bête morte. Tu la donneras à l''étranger qui est dans tes portes, pour qu''il la mange, ou tu la vendras à un étranger; car tu es un peuple saint à Yahweh, ton Dieu. Tu ne feras pas cuire un chevreau dans le lait de sa mère.'),
('dt',14,22,'crampon1923','Tu lèveras la dîme de tout le produit de tes semailles, de ce que ton champ rapportera chaque année.'),
('dt',14,23,'crampon1923','Et tu mangeras devant Yahweh, ton Dieu, dans le lieu qu''il aura choisi pour y faire habiter son nom, la dîme de ton blé, de ton vin nouveau et de ton huile, ainsi que les premiers-nés de tes bœufs et de tes brebis, afin que tu apprennes à craindre Yahweh, ton Dieu, à jamais.'),
('dt',14,24,'crampon1923','Mais si le chemin est trop long pour toi, et que tu ne puisses l''y transporter, parce que le lieu que Yahweh choisira pour y faire habiter son nom sera trop loin de toi, lorsque Yahweh, ton Dieu, t''aura béni:'),
('dt',14,25,'crampon1923','tu échangeras ta dîme pour de l''argent et, ayant serré l''argent dans ta main, tu iras au lieu que Yahweh, ton Dieu, aura choisi.'),
('dt',14,26,'crampon1923','Là, tu achèteras avec l''argent tout ce que désirera ton âme, des bœufs, des brebis, du vin, des liqueurs fermentées, tout ce que demandera ton âme, et tu mangeras là devant Yahweh, ton Dieu, et tu te réjouiras, toi et ta maison.'),
('dt',14,27,'crampon1923','Tu ne délaisseras pas le Lévite qui sera dans tes portes, car il n''a ni part ni héritage avec toi.'),
('dt',14,28,'crampon1923','A la fin de chaque troisième année, tu mettras à part toute la dîme de tes produits de cette année-là, et tu la déposeras dans tes portes.'),
('dt',14,29,'crampon1923','Alors viendra le Lévite, qui n''a ni part ni héritage avec toi, ainsi que l''étranger, l''orphelin et la veuve, qui seront dans tes portes, et ils mangeront et se rassasieront, afin que Yahweh, ton Dieu, te bénisse dans toutes les œuvres que tu entreprendras de tes mains.'),
('dt',15,1,'crampon1923','A la fin de chaque septième année, tu feras rémission.'),
('dt',15,2,'crampon1923','Voici comment se pratiquera la rémission: tout créancier qui aura fait un prêt accordera rémission pour ce qu''il a prêté à son prochain: il ne pressera pas son prochain et son frère, quand on aura publié la rémission de Yahweh.'),
('dt',15,3,'crampon1923','Tu pourras presser l''étranger; mais pour ce qui t''appartient chez ton frère, ta main fera rémission,'),
('dt',15,4,'crampon1923','afin qu''il n''y ait pas de pauvre chez toi. Car Yahweh te bénira certainement dans le pays que Yahweh, ton Dieu, t''a donné en héritage pour le posséder,'),
('dt',15,5,'crampon1923','pourvu seulement que tu obéisses à la voix de Yahweh, ton Dieu, en mettant soigneusement en pratique tous ses commandements que je te prescris aujourd''hui.'),
('dt',15,6,'crampon1923','Car Yahweh, ton Dieu, te bénira, comme il te l''a dit; tu feras des prêts à beaucoup de nations, et toi tu n''emprunteras pas; tu domineras sur beaucoup de nations, et elles ne domineront pas sur toi.'),
('dt',15,7,'crampon1923','S''il y a chez toi un pauvre d''entre tes frères, dans l''une de tes portes, au pays que Yahweh, ton Dieu, te donne, tu n''endurciras pas ton cœur et ne fermeras pas ta main à ton frère pauvre;'),
('dt',15,8,'crampon1923','mais tu lui ouvriras ta main, et tu lui prêteras de quoi pourvoir à ses besoins selon ce qui lui manque.'),
('dt',15,9,'crampon1923','Prends garde qu''il ne s''élève dans ton cœur cette pensée basse: « La septième année, l''année de rémission, approche! » et que ton œil ne soit mauvais envers ton frère pauvre, de peur que tu ne lui donnes rien, et qu''il ne crie à Yahweh contre toi, et que tu ne sois chargé d''un péché.'),
('dt',15,10,'crampon1923','Tu dois lui donner, et, en lui donnant, que ton cœur n''ait pas de regret; car, à cause de cela, Yahweh, ton Dieu, te bénira dans tous tes travaux et dans toutes tes entreprises.'),
('dt',15,11,'crampon1923','Il ne manquera jamais de pauvre au milieu du pays; c''est pourquoi je te donne ce commandement: Tu ouvriras ta main à ton frère, à l''indigent et au pauvre dans ton pays.'),
('dt',15,12,'crampon1923','Si l''un de tes frères hébreux, homme ou femme, se vend à toi, il te servira six ans et, la septième année, tu le renverras libre de chez toi.'),
('dt',15,13,'crampon1923','Et quand tu le renverras libre de chez toi, tu ne le renverras pas à vide;'),
('dt',15,14,'crampon1923','mais tu ne manqueras pas de lui donner des présents de ton menu bétail, de ton aire et de ton pressoir; tu lui donneras une part des biens dont Yahweh, ton Dieu, t''aura béni.'),
('dt',15,15,'crampon1923','Tu te souviendras que tu as été esclave au pays d''Egypte, et que Yahweh, ton Dieu, t''a racheté; c''est pourquoi je te donne aujourd''hui ce commandement.'),
('dt',15,16,'crampon1923','Mais si ton esclave te dit: « Je ne veux pas sortir de chez toi, » parce qu''il t''aime, toi et ta maison, et qu''il se trouve bien chez toi,'),
('dt',15,17,'crampon1923','alors prenant un poinçon, tu lui perceras l''oreille contre la porte de ta maison, et il sera pour toujours ton serviteur; tu feras de même pour ta servante.'),
('dt',15,18,'crampon1923','Tu ne trouveras point pénible de le renvoyer libre de chez toi, car, en te servant six ans, il t''a valu le double du salaire d''un mercenaire, et Yahweh, ton Dieu, te bénira dans tout ce que tu feras.'),
('dt',15,19,'crampon1923','Tu consacreras à Yahweh, ton Dieu, tout premier-né mâle qui naîtra dans ton bétail gros et menu; tu ne travailleras pas avec le premier-né de ton bœuf, et tu ne tondras pas le premier-né de tes brebis,'),
('dt',15,20,'crampon1923','mais tu le mangeras chaque année, toi et ta famille, devant Yahweh, ton Dieu, dans le lieu qu''il aura choisi.'),
('dt',15,21,'crampon1923','Mais s''il a une difformité, s''il est boiteux ou aveugle, ou s''il a toute autre difformité mauvaise, tu ne l''offriras pas en sacrifice à Yahweh, ton Dieu.'),
('dt',15,22,'crampon1923','Tu le mangeras dans tes portes; l''homme impur et l''homme pur en mangeront l''un et l''autre, comme on mange de la gazelle ou du cerf.'),
('dt',15,23,'crampon1923','Seulement tu n''en mangeras pas le sang: tu le répandras sur la terre comme de l''eau.'),
('dt',16,1,'crampon1923','Observe le mois d''Abib et célèbre la Pâque en l''honneur de Yahweh, ton Dieu; car c''est au mois d''Abib que Yahweh, ton Dieu, t''a fait sortir d''Egypte, pendant la nuit.'),
('dt',16,2,'crampon1923','Tu immoleras la Pâque à Yahweh, ton Dieu, les brebis et les bœufs, au lieu que Yahweh, ton Dieu, aura choisi pour y faire habiter son nom.'),
('dt',16,3,'crampon1923','Avec ces victimes, tu ne mangeras pas du pain levé, mais pendant sept jours tu mangeras des pains sans levain, du pain d''affliction, — car c''est en hâte que tu es sorti du pays d''Egypte, — afin que tu te souviennes toute ta vie du jour où tu es sorti d''Egypte.'),
('dt',16,4,'crampon1923','On ne verra pas chez toi de levain, dans toute l''étendue de ton territoire, pendant sept jours, et aucune partie des victimes que tu auras immolées le soir du premier jour ne restera pendant la nuit jusqu''au matin.'),
('dt',16,5,'crampon1923','Tu ne pourras pas sacrifier la Pâque dans chacune de tes villes que te donnera Yahweh, ton Dieu;'),
('dt',16,6,'crampon1923','mais c''est au lieu que Yahweh, ton Dieu, aura choisi pour y faire habiter son nom, que tu sacrifieras la Pâque, le soir, au coucher du soleil, au temps de ta sortie d''Egypte.'),
('dt',16,7,'crampon1923','Tu feras cuire la victime et tu la mangeras au lieu qu''aura choisi Yahweh, ton Dieu; et tu t''en retourneras le matin pour aller dans tes tentes.'),
('dt',16,8,'crampon1923','Pendant six jours, tu mangeras des pains sans levain, et le septième jour sera l''assemblée solennelle en l''honneur de Yahweh, ton Dieu: tu ne feras aucun ouvrage.'),
('dt',16,9,'crampon1923','Tu compteras sept semaines; dès que la faucille sera mise au blé, tu commenceras à compter sept semaines;'),
('dt',16,10,'crampon1923','et tu célébreras la fête des Semaines en l''honneur de Yahweh, ton Dieu, avec les offrandes volontaires de tes mains, que tu feras selon que Yahweh, ton Dieu, t''auras béni.'),
('dt',16,11,'crampon1923','Tu te réjouiras en présence de Yahweh, ton Dieu, dans le lieu que Yahweh ton Dieu, aura choisi pour y faire habiter son nom, toi, ton fils et ta fille, ton serviteur et ta servante, le Lévite qui sera dans tes portes, ainsi que l''étranger, l''orphelin et la veuve qui seront au milieu de toi.'),
('dt',16,12,'crampon1923','Tu te souviendras que tu as été esclave en Egypte, et tu auras soin de mettre ces lois en pratique.'),
('dt',16,13,'crampon1923','Tu célébreras la fête des Tabernacles pendant sept jours, lorsque tu auras recueilli le produit de ton aire et de ton pressoir;'),
('dt',16,14,'crampon1923','tu te réjouiras à cette fête, toi, ton fils et ta fille, ton serviteur et ta servante, ainsi que le Lévite, l''étranger, l''orphelin et la veuve qui seront dans tes portes.'),
('dt',16,15,'crampon1923','Tu célébreras la fête pendant sept jours en l''honneur de Yahweh, ton Dieu, dans le lieu que Yahweh aura choisi; car Yahweh, ton Dieu, te bénira dans toutes tes récoltes et dans tout le travail de tes mains, et tu seras tout entier à la joie.'),
('dt',16,16,'crampon1923','Trois fois par année, tout mâle d''entre vous se présentera devant Yahweh, votre Dieu, dans le lieu qu''il aura choisi: à la fête des Azymes, à la fête des Semaines et à la fête des Tabernacles; il ne paraîtra pas devant Yahweh les mains vides.'),
('dt',16,17,'crampon1923','Chacun fera ses offrandes, selon ce qu''il peut donner, selon les bénédictions que Yahweh, ton Dieu, lui aura accordées.'),
('dt',16,18,'crampon1923','Tu établiras des juges et des magistrats dans toutes les villes que Yahweh, ton Dieu, te donnera, selon tes tribus, et ils jugeront le peuple avec justice.'),
('dt',16,19,'crampon1923','Tu ne feras point fléchir le droit, tu n''auras point égard aux personnes et tu ne recevras point de présents, car les présents aveuglent les yeux des sages et corrompent les paroles des justes.'),
('dt',16,20,'crampon1923','Tu suivras strictement la justice, afin que tu vives et que tu possèdes le pays que te donne Yahweh, ton Dieu.'),
('dt',16,21,'crampon1923','Tu ne planteras pas d''aschéra, aucun bois, à côté de l''autel que tu élèveras à Yahweh, ton Dieu.'),
('dt',16,22,'crampon1923','Tu ne dresseras point de ces stèles, qui sont en aversion à Yahweh, ton Dieu.'),
('dt',17,1,'crampon1923','Tu ne sacrifieras à Yahweh, ton Dieu, ni bœuf ni agneau, qui ait quelque défaut ou difformité; car c''est une abomination à Yahweh, ton Dieu.'),
('dt',17,2,'crampon1923','S''il se trouve au milieu de toi, dans l''une de tes villes que Yahweh, ton Dieu, te donne, un homme ou une femme qui fasse ce qui est mal aux yeux de Yahweh, ton Dieu, en transgressant son alliance,'),
('dt',17,3,'crampon1923','qui aille à d''autres dieux pour les servir et se prosterner devant eux, devant le soleil, ou la lune, ou toute l''armée du ciel, ce que je n''ai pas commandé,'),
('dt',17,4,'crampon1923','quand la chose t''aura été rapportée, quand tu l''auras appris, tu feras d''exactes recherches. Si le bruit est vrai et le fait bien établi, si cette abomination a été commise en Israël,'),
('dt',17,5,'crampon1923','alors tu feras conduire aux portes de ta ville l''homme ou la femme coupables de cette mauvaise action, l''homme ou la femme, et tu les lapideras jusqu''à ce qu''ils meurent.'),
('dt',17,6,'crampon1923','Sur la parole de deux témoins ou de trois témoins on mettra à mort celui qui doit mourir; il ne sera pas mis à mort sur la parole d''un seul témoin.'),
('dt',17,7,'crampon1923','La main des témoins se lèvera la première sur lui pour le faire mourir, et ensuite la main de tout le peuple. Tu ôteras ainsi le mal du milieu de toi.'),
('dt',17,8,'crampon1923','Si une affaire relative à un meurtre, à une contestation, à une blessure, — objets de litiges dans tes portes, — te paraît trop difficile, tu te lèveras et tu monteras au lieu que Yahweh, ton Dieu, aura choisi.'),
('dt',17,9,'crampon1923','Tu iras trouver les prêtres lévitiques; et le juge en fonction à ce moment; tu les consulteras, et ils te feront connaître ce qui est conforme au droit.'),
('dt',17,10,'crampon1923','Tu agiras d''après la sentence qu''ils t''auront fait connaître dans le lieu que Yahweh aura choisi, et tu auras soin d''agir selon tout ce qu''ils enseigneront.'),
('dt',17,11,'crampon1923','Tu agiras selon la loi qu''ils enseigneront, et selon la sentence qu''ils auront prononcée, sans te détourner ni à droite ni à gauche de ce qu''ils t''auront fait connaître.'),
('dt',17,12,'crampon1923','Celui qui, se laissant aller à l''orgueil, agira sans écouter le prêtre qui se tient là pour servir Yahweh, ton Dieu, ou sans écouter le juge, sera puni de mort. Ainsi tu ôteras le mal du milieu d''Israël;'),
('dt',17,13,'crampon1923','et tout le peuple en l''apprenant, craindra et ne se laissera plus aller à l''orgueil.'),
('dt',17,14,'crampon1923','Lorsque tu seras entré dans le pays que Yahweh, ton Dieu, te donne, que tu en auras pris possession, et que tu y auras établi ta demeure, si tu dis: « Je veux mettre un roi sur moi, comme toutes les nations qui m''entourent »,'),
('dt',17,15,'crampon1923','tu mettras sur toi un roi que Yahweh, ton Dieu, aura choisi; c''est du milieu de tes frères que tu prendras un roi, pour l''établir sur toi; tu ne pourras pas te donner pour roi un étranger qui ne serait pas ton frère.'),
('dt',17,16,'crampon1923','Mais qu''il n''ait pas un grand nombre de chevaux, et qu''il ne ramène pas le peuple en Egypte pour avoir beaucoup de chevaux; car Yahweh vous a dit: « Vous ne retournerez plus désormais par ce chemin-là. »'),
('dt',17,17,'crampon1923','Qu''il n''ait pas un grand nombre de femmes, de peur que son cœur ne se détourne; qu''il ne fasse pas de grands amas d''argent et d''or.'),
('dt',17,18,'crampon1923','Dès qu''il sera assis sur le trône de sa royauté, il écrira pour lui sur un livre une copie de cette loi, d''après l''exemplaire qui est chez les prêtres lévitiques.'),
('dt',17,19,'crampon1923','Il l''aura avec lui et il y lira tous les jours de sa vie, afin qu''il apprenne à craindre Yahweh, son Dieu, à observer toutes les paroles de cette loi et toutes ces ordonnances en les mettant en pratique;'),
('dt',17,20,'crampon1923','pour que son cœur ne s''élève pas au-dessus de ses frères, et qu''il ne se détourne des commandements ni à droite ni à gauche, afin qu''il prolonge ses jours dans son royaume, lui et ses fils, au milieu d''Israël.'),
('dt',18,1,'crampon1923','Les prêtres lévitiques, la tribu entière de Lévi, n''auront ni part ni héritage avec Israël; ils se nourriront des sacrifices de Yahweh faits par le feu et de son héritage.'),
('dt',18,2,'crampon1923','Ils n''auront point d''héritage au milieu de leurs frères; Yahweh est leur héritage, comme il leur a dit.'),
('dt',18,3,'crampon1923','Voici quel sera le droit des prêtres sur le peuple, sur ceux qui sacrifieront un bœuf ou une brebis: on donnera au prêtre l''épaule, les mâchoires et l''estomac.'),
('dt',18,4,'crampon1923','Tu lui donneras les prémices de ton blé, de ton vin nouveau et de ton huile, et les prémices de la toison de tes brebis;'),
('dt',18,5,'crampon1923','car c''est lui que Yahweh, ton Dieu, a choisi d''entre toutes les tribus pour se tenir devant Yahweh et faire le service au nom de Yahweh, lui et ses fils, à toujours.'),
('dt',18,6,'crampon1923','Si un lévite quitte l''une de tes villes, le lieu quelconque du territoire d''Israël où il demeure, pour venir, selon tout le désir de son âme, au lieu qu''aura choisi Yahweh,'),
('dt',18,7,'crampon1923','et qu''il fasse le service au nom de Yahweh, son Dieu, comme tous ses frères les lévites qui se tiennent là devant Yahweh,'),
('dt',18,8,'crampon1923','il aura pour sa nourriture une portion égale à la leur, indépendamment des produits de la vente de son patrimoine.'),
('dt',18,9,'crampon1923','Quand tu seras entré dans le pays que te donne Yahweh, ton Dieu, tu n''apprendras pas à imiter les abominations de ces nations-là.'),
('dt',18,10,'crampon1923','Qu''on ne trouve chez toi personne qui fasse passer par le feu son fils ou sa fille, qui s''adonne à la divination, au augures, aux superstitions et aux enchantements,'),
('dt',18,11,'crampon1923','qui ait recours aux charmes, qui consulte les évocateurs et les sorciers, et qui interroge les morts.'),
('dt',18,12,'crampon1923','Car tout homme qui fait ces choses est en abomination à Yahweh, et c''est à cause de ces abominations que Yahweh, ton Dieu, va chasser ces nations devant toi.'),
('dt',18,13,'crampon1923','Tu seras intègre avec Yahweh, ton Dieu.'),
('dt',18,14,'crampon1923','Car ces nations que tu vas chasser écoutent les augures et les devins; mais à toi, Yahweh, ton Dieu, ne le permet pas.'),
('dt',18,15,'crampon1923','Yahweh, ton Dieu, te suscitera du milieu de toi, d''entre tes frères, un prophète tel que moi: vous l''écouterez.'),
('dt',18,16,'crampon1923','C''est ce que tu as demandé à Yahweh, ton Dieu, en Horeb, le jour de l''assemblée, en disant: « Que je n''entende plus la voix de Yahweh, mon Dieu, et que je ne voie plus ce grand feu, de peur de mourir. »'),
('dt',18,17,'crampon1923','Yahweh me dit: « Ce qu''ils ont dit est bien.'),
('dt',18,18,'crampon1923','Je leur susciterai du milieu de leurs frères un prophète tel que toi; je mettrai mes paroles dans sa bouche, et il leur dira tout ce que je lui commanderai.'),
('dt',18,19,'crampon1923','Et si quelqu''un n''écoute pas mes paroles qu''il dira en mon nom, c''est moi qui lui en demanderai compte.'),
('dt',18,20,'crampon1923','Mais le prophète qui s''enorgueillira jusqu''à dire en mon nom une parole que je ne lui aurai pas commandé de dire, ou qui parlera au nom d''autres dieux, ce prophète-là mourra. »'),
('dt',18,21,'crampon1923','Que si tu dis dans ton cœur: « Comment reconnaîtrons-nous la parole que Yahweh n''aura pas dite? »...,'),
('dt',18,22,'crampon1923','quand le prophète aura parlé au nom de Yahweh, si ce qu''il a dit n''arrive pas et ne se réalise pas, c''est là la parole que Yahweh n''a pas dite; c''est par l''orgueil que le prophète l''a dite: tu n''auras pas peur de lui.'),
('dt',19,1,'crampon1923','Lorsque Yahweh, ton Dieu, aura exterminé les nations dont Yahweh, ton Dieu, te donne le pays; lorsque tu les auras chassées et que tu habiteras dans leurs villes et dans leurs maisons,'),
('dt',19,2,'crampon1923','tu sépareras trois villes au milieu du pays que Yahweh, ton Dieu, te donne pour le posséder.'),
('dt',19,3,'crampon1923','Tu tiendras en état les routes qui y conduisent, et tu diviseras en trois parties le territoire du pays que Yahweh, ton Dieu, va te donner en héritage, afin que tout meurtrier puisse s''enfuir dans ces villes.'),
('dt',19,4,'crampon1923','Voici dans quel cas le meurtrier qui s''y réfugiera aura la vie sauve: s''il a tué son prochain par mégarde, sans avoir été auparavant son ennemi.'),
('dt',19,5,'crampon1923','Ainsi un homme va couper du bois dans la forêt avec un autre homme; sa main brandit la hache pour abattre un arbre; le fer s''échappe du manche, atteint son compagnon et le tue: cet homme s''enfuira dans l''une de ces villes et il aura la vie sauve.'),
('dt',19,6,'crampon1923','Autrement le vengeur du sang, poursuivant le meurtrier dans l''ardeur de sa colère, l''atteindrait, si le chemin était trop long, et lui porterait un coup mortel; et pourtant cet homme n''aurait pas mérité la mort, puisqu''il n''avait pas auparavant de haine contre la victime.'),
('dt',19,7,'crampon1923','C''est pourquoi je te donne cet ordre: Mets à part trois villes.'),
('dt',19,8,'crampon1923','Et si Yahweh, ton Dieu, élargit tes frontières, comme il l''a juré à tes pères, et qu''il te donne tout le pays qu''il a promis à tes pères de te donner,'),
('dt',19,9,'crampon1923','— pourvu que tu observes et mettes en pratique tous ces commandements que je te prescris aujourd''hui, aimant Yahweh, ton Dieu, et marchant toujours dans ses voies, — tu ajouteras encore trois villes à ces trois-là,'),
('dt',19,10,'crampon1923','afin que le sang innocent ne soit pas versé au milieu du pays que Yahweh, ton Dieu, te donne pour héritage, et qu''il n''y ait pas de sang sur toi.'),
('dt',19,11,'crampon1923','Mais si un homme ayant de la haine contre son prochain, lui dresse des embûches, se jette sur lui et lui porte un coup mortel, et qu''ensuite il s''enfuie dans l''une de ces villes,'),
('dt',19,12,'crampon1923','les anciens de sa ville l''enverront saisir et le livreront entre les mains du vengeur du sang, afin qu''il meure.'),
('dt',19,13,'crampon1923','Ton œil n''aura pas de pitié pour lui, et tu ôteras d''Israël le sang innocent, et tu prospéreras.'),
('dt',19,14,'crampon1923','Tu ne déplaceras pas la borne de ton prochain, posée par les ancêtres, dans l''héritage que tu auras au pays que Yahweh, ton Dieu, te donne pour le posséder.'),
('dt',19,15,'crampon1923','Un seul témoin ne sera pas admis contre un homme pour constater un crime ou un péché, quel que soit le péché commis. C''est sur la parole de deux témoins ou sur la parole de trois témoins que la chose sera établie.'),
('dt',19,16,'crampon1923','Lorsqu''un témoin à charge s''élèvera contre un homme pour l''accuser d''un crime,'),
('dt',19,17,'crampon1923','les deux hommes en contestation se présenteront devant Yahweh, devant les prêtres et les juges alors en fonction;'),
('dt',19,18,'crampon1923','les juges feront avec soin une enquête et, si le témoin se trouve être un faux témoin, s''il a fait contre son frère une fausse déposition,'),
('dt',19,19,'crampon1923','vous lui ferez subir ce qu''il avait dessein de faire subir à son frère. Tu ôteras ainsi le mal du milieu de toi.'),
('dt',19,20,'crampon1923','Les autres, en l''apprenant craindront, et l''on ne commettra plus un acte aussi mauvais au milieu de toi.'),
('dt',19,21,'crampon1923','Ton œil sera sans pitié: vie pour vie, œil pour œil, dent pour dent, main pour main, pied pour pied.'),
('dt',20,1,'crampon1923','Lorsque tu sortiras pour combattre contre tes ennemis, et que tu verras des chevaux et des chars, un peuple plus nombreux que toi, tu ne les craindras point, car Yahweh, ton Dieu, qui t''a fait monter du pays d''Egypte, est avec toi.'),
('dt',20,2,'crampon1923','Quand vous vous disposerez au combat, le prêtre s''avancera et parlera au peuple.'),
('dt',20,3,'crampon1923','Il leur dira: « Ecoute Israël! Vous vous disposez aujourd''hui au combat contre vos ennemis; que votre cœur ne faiblisse point, soyez sans crainte, ne vous effrayez point et ne soyez point terrifiés devant eux;'),
('dt',20,4,'crampon1923','car Yahweh, votre Dieu, marche avec vous, pour combattre pour vous contre vos ennemis et vous sauver. »'),
('dt',20,5,'crampon1923','Les officiers parleront ensuite au peuple, en disant: « Qui est-ce qui a bâti une maison neuve, et ne l''a pas encore dédiée? Qu''il s''en aille et retourne chez lui, de peur qu''il ne meure dans la bataille et qu''un autre ne la dédie.'),
('dt',20,6,'crampon1923','Qui est-ce qui a planté une vigne, et n''a pas encore joui de ses fruits? Qu''il s''en aille et retourne chez lui, de peur qu''il ne meure dans la bataille et qu''un autre n''en jouisse.'),
('dt',20,7,'crampon1923','Qui est-ce qui s''est fiancé à une femme, et ne l''a pas encore épousée? Qu''il s''en aille et retourne chez lui, de peur qu''il ne meure dans la bataille et qu''un autre ne l''épouse. »'),
('dt',20,8,'crampon1923','Les officiers parleront encore au peuple et diront: « Qui est-ce qui a peur et qui sent son cœur faiblir? Qu''il s''en aille et retourne chez lui, afin que le cœur de ses frères ne défaille pas comme le sien. »'),
('dt',20,9,'crampon1923','Quand les officiers auront achevé de parler au peuple, on placera les chefs des troupes à la tête du peuple.'),
('dt',20,10,'crampon1923','Lorsque tu t''approcheras d''une ville pour l''attaquer, tu lui offriras la paix.'),
('dt',20,11,'crampon1923','Si elle te fait une réponse de paix et t''ouvre ses portes, tout le peuple qui s''y trouvera te sera tributaire et te servira.'),
('dt',20,12,'crampon1923','Si elle ne fait pas la paix avec toi, et qu''elle veuille te faire la guerre, tu l''assiégeras et,'),
('dt',20,13,'crampon1923','quand Yahweh, ton Dieu, l''aura livrée entre tes mains, tu feras passer tous les mâles au fil de l''épée.'),
('dt',20,14,'crampon1923','Mais les femmes, les enfants, le bétail, et tout ce qui sera dans la ville, tout son butin, tu le prendras pour toi, et tu pourras manger le butin de tes ennemis que Yahweh, ton Dieu, t''aura donné.'),
('dt',20,15,'crampon1923','C''est ainsi que tu agiras à l''égard de toutes les villes qui sont très loin de toi, et qui ne sont pas du nombre des villes de ces nations-ci.'),
('dt',20,16,'crampon1923','Mais quant aux villes de ces peuples que Yahweh, ton Dieu, te donne pour héritage, tu n''y laisseras la vie à rien de ce qui respire.'),
('dt',20,17,'crampon1923','Car tu dévoueras ces peuples par anathème: les Héthéens, les Amorrhéens, les Chananéens, les Phérézéens, les Hévéens et les Jébuséens, comme Yahweh, ton Dieu, te l''a ordonné,'),
('dt',20,18,'crampon1923','afin qu''ils ne vous apprennent pas à imiter toutes les abominations qu''ils font envers leurs dieux, et que vous ne péchiez point contre Yahweh, votre Dieu.'),
('dt',20,19,'crampon1923','Si tu assièges une ville pendant de longs jours, combattant contre elle pour t''en emparer, tu ne détruiras pas les arbres en y portant la hache; car tu en mangeras le fruit, et tu ne les abattras pas: l''arbre des champs est-il un homme pour que tu l''assièges?'),
('dt',20,20,'crampon1923','Mais les arbres que tu sais n''être pas des arbres servant à la nourriture, tu pourras les détruire et les abattre, et en construire des machines contre la ville qui est en guerre avec toi, jusqu''à ce qu''elle succombe.'),
('dt',21,1,'crampon1923','Si, sur le sol que Yahweh, ton Dieu, te donne pour le posséder, on trouve un homme tué, gisant dans les champs, sans que l''on sache qui l''a frappé,'),
('dt',21,2,'crampon1923','tes anciens et tes juges iront mesurer les distances jusqu''aux villes des environs de l''endroit où est l''homme tué.'),
('dt',21,3,'crampon1923','Et, quant à la ville la plus proche de l''homme tué, les anciens de cette ville prendront une génisse qui n''aura pas encore été employée au travail et qui n''aura pas tiré au joug.'),
('dt',21,4,'crampon1923','Les anciens de cette ville feront descendre la génisse vers un ruisseau permanent, dans un lieu qui n''a reçu ni culture ni semence, et là ils briseront la nuque de la génisse dans le ruisseau.'),
('dt',21,5,'crampon1923','Les prêtres, fils de Lévi, s''approcheront; car ce sont eux que Yahweh, ton Dieu, a choisis pour le servir et pour bénir au nom de Yahweh, et c''est sur leur parole que se juge toute contestation et toute blessure.'),
('dt',21,6,'crampon1923','Tous les anciens de cette ville, comme étant les plus voisins de l''homme tué, laveront leurs mains sur la génisse à laquelle on a brisé la nuque dans le ruisseau.'),
('dt',21,7,'crampon1923','Puis ils prendront la parole en disant: « Nos mains n''ont pas répandu ce sang, et nos yeux ne l''ont pas vu répandre.'),
('dt',21,8,'crampon1923','Pardonnez à votre peuple d''Israël que vous avez racheté, ô Yahweh, et ne laissez pas le sang innocent au milieu de votre peuple d''Israël! » Et ce sang sera expié pour eux.'),
('dt',21,9,'crampon1923','C''est ainsi que tu ôteras du milieu de toi le sang innocent, en faisant ce qui est droit aux yeux de Yahweh.'),
('dt',21,10,'crampon1923','Quand tu sortiras pour combattre contre tes ennemis, et que Yahweh, ton Dieu, les aura livrés entre tes mains et que tu leur feras des prisonniers,'),
('dt',21,11,'crampon1923','si tu vois parmi les captifs une femme de belle figure, et que, épris d''amour pour elle, tu veuilles l''épouser,'),
('dt',21,12,'crampon1923','tu l''amèneras dans l''intérieur de ta maison. Alors elle se rasera la tête et se coupera les ongles;'),
('dt',21,13,'crampon1923','elle se dépouillera des vêtements de sa captivité, elle demeurera dans ta maison et pleurera pendant un mois son père et sa mère; après quoi, tu iras vers elle, tu seras son mari et elle sera ta femme.'),
('dt',21,14,'crampon1923','Si elle cesse de te plaire, tu la laisseras aller où elle voudra, et tu ne pourras pas la vendre pour de l''argent; tu ne la traiteras pas comme une esclave, car tu l''as eue pour femme.'),
('dt',21,15,'crampon1923','Si un homme a deux femmes, l''une aimée et l''autre haïe, et qu''elles lui aient enfanté des fils, aussi bien celle qui est aimée que celle qui est haïe, si le fils premier-né est le fils de celle qui est haïe,'),
('dt',21,16,'crampon1923','il ne pourra pas, le jour où il mettra ses fils en possession de ses biens, faire premier-né le fils de celle qu''il aime, de préférence au fils de celle qu''il hait, celui-ci étant le premier-né.'),
('dt',21,17,'crampon1923','Mais il reconnaîtra comme premier-né le fils de celle qui est haïe, et lui donnera sur tous ses biens une portion double; car ce fils est les prémices de sa vigueur; c''est à lui qu''appartient le droit d''aînesse.'),
('dt',21,18,'crampon1923','Si un homme a un fils indocile et rebelle, n''écoutant ni la voix de son père, ni la voix de sa mère et, lors même qu''ils le châtient, ne les écoutant pas,'),
('dt',21,19,'crampon1923','son père et sa mère le saisiront et l''amèneront aux anciens de la ville et à la porte du lieu qu''il habite.'),
('dt',21,20,'crampon1923','Ils diront aux anciens de la ville: « Notre fils que voici est indocile et rebelle, il n''écoute pas notre voix, il se livre à la débauche et à l''ivrognerie. »'),
('dt',21,21,'crampon1923','Et tous les hommes de sa ville le lapideront, et il mourra. Tu ôteras ainsi le mal du milieu de toi, et tout Israël, en l''apprenant, craindra.'),
('dt',21,22,'crampon1923','Quand un homme, ayant commis un crime capital, aura été mis à mort, et que tu l''auras pendu à un bois,'),
('dt',21,23,'crampon1923','son cadavre ne passera pas la nuit sur le bois; mais tu ne manqueras pas de l''enterrer le jour même, car un pendu est l''objet de la malédiction de Dieu, et tu ne souilleras pas ton pays, que Yahweh, ton Dieu, te donne pour héritage.'),
('dt',22,1,'crampon1923','Si tu vois le bœuf ou la brebis de ton frère égarés dans les champs, tu ne t''en détourneras point, mais tu les ramèneras à ton frère.'),
('dt',22,2,'crampon1923','Si ton frère n''habite pas près de toi et que tu ne le connaisses pas, tu recueilleras l''animal dans ta maison, et il restera chez toi jusqu''à ce que ton frère le recherche, et alors tu le lui rendras.'),
('dt',22,3,'crampon1923','Tu feras de même pour son âne, et tu feras de même pour son manteau, et tu feras de même pour tout objet perdu, que ton frère aurait perdu et que tu trouverais; tu ne dois pas t''en détourner.'),
('dt',22,4,'crampon1923','Si tu vois l''âne de ton frère ou son bœuf s''abattre dans le chemin, tu ne t''en détourneras point; tu ne manqueras pas de l''aider à les relever.'),
('dt',22,5,'crampon1923','Une femme ne portera pas un habit d''homme, et un homme ne mettra point un vêtement de femme; car quiconque fait ces choses est en abomination à Yahweh, ton Dieu.'),
('dt',22,6,'crampon1923','Si tu rencontres dans ton chemin un nid d''oiseau, sur un arbre ou sur la terre, avec des petits ou des œufs, et la mère couchée sur les petits ou sur les œufs, tu ne prendras pas la mère avec les petits;'),
('dt',22,7,'crampon1923','tu ne manqueras pas de laisser aller la mère, et tu ne prendras pour toi que les petits, afin que tu sois heureux et que tu prolonges tes jours.'),
('dt',22,8,'crampon1923','Quand tu bâtiras une maison neuve, tu feras une balustrade autour de ton toit, afin de ne pas mettre du sang sur ta maison, dans le cas où quelqu''un viendrait à tomber de là.'),
('dt',22,9,'crampon1923','Tu n''ensemenceras pas ta vigne de deux sortes de semences; de peur que le tout ne soit déclaré chose sainte, et la graine que tu as semée, et le produit de la vigne.'),
('dt',22,10,'crampon1923','Tu ne laboureras pas avec un bœuf et un âne attelés ensemble.'),
('dt',22,11,'crampon1923','Tu ne porteras pas un vêtement d''un tissu mélangé de laine et de lin réunis ensemble.'),
('dt',22,12,'crampon1923','Tu feras des glands aux quatre coins du vêtement dont tu te couvriras.'),
('dt',22,13,'crampon1923','Si un homme, après avoir pris une femme et être allé vers elle, vient à éprouver pour elle de l''aversion,'),
('dt',22,14,'crampon1923','et lui impute des choses déshonorantes et porte atteinte à sa réputation, en disant: « J''ai pris cette femme et, quand je suis venu vers elle, je ne l''ai pas trouvée vierge »,'),
('dt',22,15,'crampon1923','le père et la mère de la jeune femme prendront les signes de sa virginité, et les produiront devant les anciens de la ville, à la porte.'),
('dt',22,16,'crampon1923','Le père de la jeune fille dira aux anciens: « J''ai donné ma fille pour femme à cet homme et, l''ayant prise en aversion,'),
('dt',22,17,'crampon1923','il lui impute des choses déshonorantes en disant: Je n''ai pas trouvé ta fille vierge. Or voici les signes de virginité de ma fille. » Et ils déploieront son vêtement devant les anciens de la ville.'),
('dt',22,18,'crampon1923','Alors les anciens de la ville saisiront cet homme et le châtieront;'),
('dt',22,19,'crampon1923','en outre, ils lui imposeront une amende de cent sicles d''argent, qu''ils donneront au père de la jeune femme, pour avoir porté atteinte à la réputation d''une vierge d''Israël. Elle restera sa femme, et il ne pourra pas la renvoyer, tant qu''il vivra.'),
('dt',22,20,'crampon1923','Mais si ce fait est vrai et que la jeune femme ne soit pas trouvée vierge,'),
('dt',22,21,'crampon1923','on fera sortir la jeune femme à l''entrée de la maison de son père, et elle sera lapidée par les gens de sa ville, jusqu''à ce qu''elle meure, parce qu''elle a commis une infamie en Israël, en se prostituant dans la maison de son père. Tu ôteras ainsi le mal du milieu de toi.'),
('dt',22,22,'crampon1923','Si l''on trouve un homme couché avec une femme mariée, ils mourront tous deux, l''homme qui a couché avec la femme, et la femme aussi. Tu ôteras ainsi le mal du milieu d''Israël.'),
('dt',22,23,'crampon1923','Si une jeune fille vierge est fiancée à quelqu''un, et qu''un homme la rencontre dans la ville et couche avec elle,'),
('dt',22,24,'crampon1923','vous les amènerez tous deux à la porte de la ville, et vous les lapiderez, jusqu''à ce qu''ils meurent: la jeune fille pour n''avoir pas crié dans la ville, et l''homme pour avoir déshonoré la femme de son prochain. Tu ôteras ainsi le mal du milieu de toi.'),
('dt',22,25,'crampon1923','Mais si c''est dans les champs que cet homme rencontre la jeune fille fiancée, et qu''il lui fasse violence et couche avec elle, l''homme qui aura couché avec elle mourra seul.'),
('dt',22,26,'crampon1923','Tu ne feras rien à la jeune fille; il n''y a pas en elle de crime digne de mort, car c''est comme lorsqu''un homme se jette sur son prochain et le tue; le cas est le même.'),
('dt',22,27,'crampon1923','L''homme l''a rencontrée dans les champs, la jeune fille fiancée a crié, mais il n''y avait personne pour la secourir.')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('dt',22,28,'crampon1923','Si un homme rencontre une jeune fille vierge non fiancée, la saisit et couche avec elle, et qu''ils soient surpris,'),
('dt',22,29,'crampon1923','l''homme qui a couché avec elle donnera au père de la jeune fille cinquante sicles d''argent, et elle sera sa femme, parce qu''il l''a déshonorée, il ne pourra pas la renvoyer, tant qu''il vivra.'),
('dt',23,1,'crampon1923','Nul ne prendra la femme de son père et ne soulèvera la couverture du lit de son père.'),
('dt',23,2,'crampon1923','Celui dont les testicules ont été écrasés ou dont l''urètre a été coupé n''entrera pas dans l''assemblée de Yahweh.'),
('dt',23,3,'crampon1923','Le fruit d''une union illicite n''entrera pas dans l''assemblée de Yahweh; même sa dixième génération n''entrera pas dans l''assemblée de Yahweh.'),
('dt',23,4,'crampon1923','L''Ammonite et le Moabite n''entreront pas dans l''assemblée de Yahweh; même la dixième génération n''entrera pas dans l''assemblée de Yahweh, ils n''y entreront jamais,'),
('dt',23,5,'crampon1923','parce qu''ils ne sont pas venu au-devant de vous avec du pain et de l''eau, sur le chemin, lorsque vous sortiez d''Egypte, et parce que le roi de Moab a fait venir contre toi à prix d''argent Balaam, fils de Béor, de Péthor en Mésopotamie, pour te maudire.'),
('dt',23,6,'crampon1923','Mais Yahweh, ton Dieu, n''a pas voulu écouter Balaam, et Yahweh, ton Dieu, a changé pour toi la malédiction en bénédiction, car Yahweh, ton Dieu, t''aime.'),
('dt',23,7,'crampon1923','Tu n''auras souci ni de leur prospérité ni de leur bien-être, tant que tu vivras, à perpétuité.'),
('dt',23,8,'crampon1923','Tu n''auras point en abomination l''Edomite, car il est ton frère; tu n''auras point en abomination l''Egyptien, car tu as été étranger dans son pays:'),
('dt',23,9,'crampon1923','les fils qui leur naîtront pourront, à la troisième génération, entrer dans l''assemblée de Yahweh.'),
('dt',23,10,'crampon1923','Quand tu marcheras en campements contre tes ennemis, garde-toi de toute chose mauvaise.'),
('dt',23,11,'crampon1923','S''il y a chez toi un homme qui ne soit pas pur, par suite d''un accident nocturne, il sortira du camp, et ne rentrera pas au milieu du camp;'),
('dt',23,12,'crampon1923','sur le soir, il se baignera dans l''eau et, après le coucher du soleil, il pourra rentrer au milieu du camp.'),
('dt',23,13,'crampon1923','Tu auras un lieu hors du camp, et c''est là dehors que tu iras.'),
('dt',23,14,'crampon1923','Tu auras dans ton bagage une pelle avec laquelle tu feras un creux, quand tu iras t''asseoir à l''écart, et, en partant, tu recouvriras tes excréments.'),
('dt',23,15,'crampon1923','Car Yahweh, ton Dieu, marche au milieu de ton camp, pour te protéger et pour livrer tes ennemis devant toi; ton camp doit donc être saint, afin que Yahweh ne voie chez toi rien de malséant et qu''il ne se détourne pas de toi.'),
('dt',23,16,'crampon1923','Tu ne livreras pas à son maître un esclave qui se sera enfui d''avec son maître et réfugié auprès de toi.'),
('dt',23,17,'crampon1923','Il demeurera avec toi, au milieu de ton pays, dans le lieu qu''il choisira, dans l''une de tes villes, où il se trouvera bien: tu ne l''opprimeras point.'),
('dt',23,18,'crampon1923','Il n''y aura point de prostituée parmi les filles d''Israël, et il n''y aura point de prostitué parmi les fils d''Israël.'),
('dt',23,19,'crampon1923','Tu n''apporteras pas dans la maison de Yahweh, ton Dieu, le salaire d''une prostituée ni le salaire d''un chien, pour l''accomplissement d''un vœu quelconque; car l''un et l''autre sont en abomination à Yahweh, ton Dieu.'),
('dt',23,20,'crampon1923','Tu n''exigeras de ton frère aucun intérêt ni pour argent, ni pour vivres, ni pour aucune chose qui se prête à intérêt.'),
('dt',23,21,'crampon1923','Tu peux exiger un intérêt de l''étranger, mais tu n''en tireras point de ton frère, afin que Yahweh, ton Dieu, te bénisse dans tout ce que tu entreprendras, dans le pays où tu vas entrer pour le posséder.'),
('dt',23,22,'crampon1923','Quand tu auras fait un vœu à Yahweh, ton Dieu, tu ne tarderas point à l''accomplir; sinon, Yahweh, ton Dieu, t''en demanderait certainement compte, et tu serais chargé d''un péché.'),
('dt',23,23,'crampon1923','Si tu t''abstiens de faire des vœux, il n''y aura pas en toi de péché.'),
('dt',23,24,'crampon1923','Mais la parole sortie de tes lèvres, tu la garderas et l''accompliras, selon le vœu que tu auras fait librement à Yahweh, ton Dieu, et que tu auras prononcé de ta bouche.'),
('dt',23,25,'crampon1923','Quand tu entreras dans la vigne de ton prochain, tu pourras manger des raisins selon ton désir et t''en rassasier, mais tu n''en mettras pas dans ton panier.'),
('dt',23,26,'crampon1923','Si tu entres dans les blés de ton prochain, tu pourras cueillir des épis avec la main, mais tu ne mettras pas la faucille dans les blés de ton prochain.'),
('dt',24,1,'crampon1923','Lorsqu''un homme aura pris une femme et l''aura épousée, si elle vient à ne pas à trouver grâce à ses yeux, parce qu''il a découvert en elle quelque chose de repoussant, il écrira pour elle une lettre de divorce et, après la lui avoir remise en main, il la renverra de sa maison.'),
('dt',24,2,'crampon1923','Une fois sortie de chez lui, elle s''en ira et pourra devenir la femme d''un autre homme.'),
('dt',24,3,'crampon1923','Mais si ce dernier mari la prend en aversion, écrit pour elle une lettre de divorce, et que, la lui ayant remise en main, il la renvoie de sa maison; ou bien si ce dernier mari qui l''a prise pour femme vient à mourir,'),
('dt',24,4,'crampon1923','alors le premier mari, qui l''a renvoyée, ne pourra pas la reprendre pour femme, après qu''elle a été souillée, car c''est une abomination devant Yahweh, et tu n''engageras pas dans le péché le pays que Yahweh, ton Dieu, te donne pour héritage.'),
('dt',24,5,'crampon1923','Lorsqu''un homme sera nouvellement marié, il n''ira point à l''armée, et on ne lui imposera aucune charge publique; il sera libre pour sa maison pendant un an, et il réjouira la femme qu''il a prise.'),
('dt',24,6,'crampon1923','On ne prendra pas en gage les deux meules, ni la meule de dessus: ce serait prendre en gage la vie même.'),
('dt',24,7,'crampon1923','Si l''on trouve un homme qui ait enlevé l''un de ses frères, d''entre les enfants d''Israël, et en ait fait son esclave, ou l''ait vendu, ce ravisseur sera puni de mort. Tu ôteras ainsi le mal du milieu de toi.'),
('dt',24,8,'crampon1923','Prends garde à la plaie de la lèpre, observant avec soin et mettant en pratique tout ce que vous enseigneront les prêtres lévitiques; tout ce que je leur ai prescrit, vous le mettrez soigneusement en pratique.'),
('dt',24,9,'crampon1923','Souviens-toi de ce que Yahweh, ton Dieu, a fait à Marie pendant le voyage, lors de votre sortie d''Egypte.'),
('dt',24,10,'crampon1923','Si tu prêtes à ton prochain un objet quelconque, tu n''entreras pas dans sa maison pour prendre son gage;'),
('dt',24,11,'crampon1923','tu attendras dehors, et celui à qui tu fais le prêt t''apportera le gage dehors.'),
('dt',24,12,'crampon1923','Si cet homme est pauvre, tu ne te coucheras point avec son gage;'),
('dt',24,13,'crampon1923','tu ne manqueras pas de lui rendre le gage au coucher du soleil, afin qu''il couche dans son vêtement et qu''il te bénisse, et ce sera là une justice pour toi devant Yahweh, ton Dieu.'),
('dt',24,14,'crampon1923','Tu n''opprimeras point le mercenaire pauvre et indigent, soit l''un de tes frères, soit l''un des étrangers demeurant dans ton pays, dans tes portes.'),
('dt',24,15,'crampon1923','Chaque jour tu lui donneras son salaire, sans que le soleil se couche sur cette dette; car il est pauvre, et son âme l''attend. Autrement il crierait à Yahweh contre toi, et tu serais chargé d''un péché.'),
('dt',24,16,'crampon1923','Les pères ne seront pas mis à mort pour les enfants, et les enfants ne seront pas mis à mort pour les pères; chacun sera mis à mort pour son péché.'),
('dt',24,17,'crampon1923','Tu ne violeras pas le droit de l''étranger ni de l''orphelin, et tu ne prendras point en gage le vêtement de la veuve.'),
('dt',24,18,'crampon1923','Tu te souviendras que tu as été esclave en Egypte, et que Yahweh, ton Dieu, t''a délivré: c''est pourquoi je te commande d''agir en cette manière.'),
('dt',24,19,'crampon1923','Quand tu feras ta moisson dans ton champ, si tu as oublié une gerbe dans le champ, tu ne retourneras pas pour la prendre: elle sera pour l''étranger, pour l''orphelin et pour la veuve, afin que Yahweh, ton Dieu, te bénisse dans tout le travail de tes mains.'),
('dt',24,20,'crampon1923','Quand tu secoueras tes oliviers, tu ne fouilleras pas après coup les branches: le reste sera pour l''étranger, pour l''orphelin et pour la veuve.'),
('dt',24,21,'crampon1923','Quand tu vendangeras ta vigne, tu ne cueilleras pas après coup les grappes qui y seront restées: elles seront pour l''étranger, pour l''orphelin et pour la veuve.'),
('dt',24,22,'crampon1923','Tu te souviendras que tu as été esclave dans le pays d''Egypte: c''est pourquoi je te commande d''agir en cette manière.'),
('dt',25,1,'crampon1923','Quand il s''élèvera une contestation entre des hommes, et qu''ils se seront présentés au jugement, qu''on les aura jugés, qu''on aura absous l''innocent et condamné le coupable,'),
('dt',25,2,'crampon1923','si le coupable a mérité d''être battu, le juge le fera étendre par terre et battre en sa présence d''un nombre de coups proportionné à sa faute.'),
('dt',25,3,'crampon1923','Il ne lui fera pas donner plus de quarante coups, de peur que, si on continuait à le frapper de beaucoup de coups en plus de ceux-là, ton frère ne fût avili à tes yeux.'),
('dt',25,4,'crampon1923','Tu ne muselleras pas le bœuf, quand il foulera le grain.'),
('dt',25,5,'crampon1923','Lorsque des frères demeurent ensemble, et que l''un d''eux meurt sans laisser de fils, la femme du défunt ne se mariera pas au dehors, à un étranger; mais son beau-frère ira vers elle, la prendra pour femme, et remplira envers elle le devoir de beau-frère.'),
('dt',25,6,'crampon1923','Le premier-né qu''elle mettra au monde succédera au frère défunt et prendra son nom, afin que ce nom ne soit pas effacé d''Israël.'),
('dt',25,7,'crampon1923','S''il ne plaît pas à cet homme de prendre sa belle-sœur, sa belle-sœur montera à la porte, vers les anciens, et dira: « Mon beau-frère refuse de faire revivre le nom de son frère en Israël; il ne veut pas remplir, en m''épousant, son devoir de beau-frère. »'),
('dt',25,8,'crampon1923','Alors les anciens de la ville l''appelleront et lui parleront. S''il persiste et dit: « Il ne me plaît pas de la prendre, »'),
('dt',25,9,'crampon1923','sa belle-sœur s''approchera de lui en présence des anciens, lui ôtera son soulier du pied et lui crachera au visage, en disant: « Ainsi sera fait à l''homme qui ne relève pas la maison de son frère. »'),
('dt',25,10,'crampon1923','Et sa maison sera appelée en Israël la maison du déchaussé.'),
('dt',25,11,'crampon1923','Lorsque des hommes se battront ensemble, un homme et son frère, si la femme de l''un s''approche pour délivrer son mari de la main de celui qui le frappe, et que, avançant la main, elle saisisse ce dernier par les parties honteuses,'),
('dt',25,12,'crampon1923','tu lui couperas la main; ton œil sera sans pitié.'),
('dt',25,13,'crampon1923','Tu n''auras pas dans ton sac deux sortes de poids, un gros et un petit.'),
('dt',25,14,'crampon1923','Tu n''auras pas dans ta maison deux sortes d''épha, un grand et un petit.'),
('dt',25,15,'crampon1923','Tu auras un poids exact et juste, tu auras un épha exact et juste, afin que tes jours se prolongent dans la terre que te donne Yahweh, ton Dieu.'),
('dt',25,16,'crampon1923','Car il est en abomination à Yahweh, ton Dieu, celui qui fait ces choses, qui commet une iniquité.'),
('dt',25,17,'crampon1923','Souviens-toi de ce que te fit Amalec pendant le voyage, lorsque tu sortis de l''Egypte,'),
('dt',25,18,'crampon1923','comment il te rencontra en route, et tomba sur toi par derrière, sur tous ceux qui étaient épuisés derrière toi, et toi tu étais fatigué et sans force, et il n''eut aucune crainte de Dieu.'),
('dt',25,19,'crampon1923','Quand Yahweh, ton Dieu, t''aura donné du repos, t''ayant délivré de tous tes ennemis d''alentour, dans le pays que Yahweh, ton Dieu, te donne en héritage pour le posséder, tu effaceras la mémoire d''Amalec de dessous le ciel: ne l''oublie point.'),
('dt',26,1,'crampon1923','Lorsque tu seras entré dans le pays que Yahweh, ton Dieu, te donne pour héritage, que tu en auras pris possession et y seras établi,'),
('dt',26,2,'crampon1923','tu prendras une part des prémices de tous les produits du sol que tu auras retirés de ton pays, que te donne Yahweh, ton Dieu, et, l''ayant mise dans une corbeille, tu iras au lieu que Yahweh, ton Dieu, aura choisi pour y faire habiter son nom.'),
('dt',26,3,'crampon1923','Tu te présenteras au prêtre alors en fonction, et tu lui diras: « Je déclare aujourd''hui à Yahweh, ton Dieu, que je suis entré dans le pays que Yahweh a juré à nos pères de nous donner. »'),
('dt',26,4,'crampon1923','Le prêtre recevra la corbeille de ta main et la déposera devant l''autel de Yahweh, ton Dieu.'),
('dt',26,5,'crampon1923','Et prenant de nouveau la parole, tu diras devant Yahweh, ton Dieu: « Mon père était un Araméen prêt à périr; il descendit en Egypte avec peu de gens et y vécut en étranger; là il devint une nation grande, puissante et nombreuse.'),
('dt',26,6,'crampon1923','Les Egyptiens nous maltraitèrent, nous opprimèrent et nous imposèrent un dur servage.'),
('dt',26,7,'crampon1923','Alors nous criâmes à Yahweh, le Dieu de nos pères, et Yahweh entendit notre voix et vit nos souffrances, notre misère et notre oppression.'),
('dt',26,8,'crampon1923','Et Yahweh nous fit sortir d''Egypte, avec une main forte et le bras étendu, par une grande terreur, avec des signes et des prodiges.'),
('dt',26,9,'crampon1923','Il nous a conduits dans ce lieu et il nous a donné ce pays, un pays où coulent le lait et le miel.'),
('dt',26,10,'crampon1923','Et maintenant voici que j''apporte les prémices des produits du sol que vous m''avez donné, ô Yahweh. » Tu les déposeras devant Yahweh, ton dieu, et tu te prosterneras devant Yahweh, ton Dieu.'),
('dt',26,11,'crampon1923','Puis tu te réjouiras, avec le Lévite et avec l''étranger qui sera au milieu de toi de tous les biens que Yahweh, ton Dieu, t''a donnés, à toi et à ta maison.'),
('dt',26,12,'crampon1923','Lorsque tu auras achevé de lever toute la dîme de tes produits, la troisième année, l''année de la dîme, et que tu la donneras au lévite, à l''étranger, à l''orphelin et à la veuve, pour qu''ils la mangent dans tes portes et qu''ils se rassasient,'),
('dt',26,13,'crampon1923','tu diras devant Yahweh, ton Dieu: « J''ai ôté de ma maison ce qui est consacré, et je l''ai donné au Lévite, à l''étranger, à l''orphelin et à la veuve, selon tous vos préceptes que vous m''avez donnés; je n''ai transgressé ni oublié aucun de vos préceptes.'),
('dt',26,14,'crampon1923','Je n''ai pas mangé de ces choses pendant mon deuil, je n''en ai rien transporté hors de ma maison dans l''état d''impureté, et je n''en ai rien donné à l''occasion d''un mort; j''ai obéi à la voix de Yahweh, mon Dieu, j''ai agi selon tout ce vous m''avez prescrit.'),
('dt',26,15,'crampon1923','Regardez de votre demeure sainte, du ciel, et bénissez votre peuple d''Israël et le sol que vous nous avez donné, comme vous l''avez juré à nos pères, ce pays où coulent le lait et le miel. »'),
('dt',26,16,'crampon1923','Aujourd''hui Yahweh, ton Dieu, te commande de mettre en pratique ces lois et ces ordonnances; tu les observeras et tu les mettras en pratique de tout ton cœur et de toute ton âme.'),
('dt',26,17,'crampon1923','Tu as fait déclarer aujourd''hui à Yahweh qu''il sera ton Dieu, toi t''engageant de ton côté à marcher dans ses voies, à observer ses lois, ses commandements et ses ordonnances, et à obéir à sa voix.'),
('dt',26,18,'crampon1923','Et Yahweh t''a fait déclarer aujourd''hui que tu lui serais un peuple particulier, comme il te l''a dit, observant tous ses commandements,'),
('dt',26,19,'crampon1923','lui s''engageant de son côté à te donner la supériorité sur toutes les nations qu''il a faites, en gloire, en renom et en splendeur, en sorte que tu sois un peuple saint à Yahweh, ton Dieu, comme il l''a dit. »'),
('dt',27,1,'crampon1923','Moïse, avec les anciens d''Israël, donna cet ordre au peuple: « Observez tout le commandement que je vous prescris aujourd''hui.'),
('dt',27,2,'crampon1923','Lorsque vous aurez passé le Jourdain pour entrer dans le pays que te donne Yahweh, ton Dieu, tu dresseras de grandes pierres et tu les enduiras de chaux,'),
('dt',27,3,'crampon1923','et tu écriras dessus toutes les paroles de cette loi, après ton passage, afin que tu entres dans le pays que Yahweh, ton Dieu, te donne, pays où coulent le lait et le miel, comme te l''a dit Yahweh, le Dieu de tes pères.'),
('dt',27,4,'crampon1923','Lors donc que vous aurez passé le Jourdain, vous dresserez sur le mont Hébal ces pierres que je vous prescris aujourd''hui, et tu les enduiras de chaux.'),
('dt',27,5,'crampon1923','Et tu bâtiras là un autel à Yahweh, un autel de pierres sur lesquelles tu ne porteras pas le fer.'),
('dt',27,6,'crampon1923','Tu bâtiras en pierres brutes l''autel de Yahweh, ton Dieu. Et tu offriras dessus des holocaustes à Yahweh, ton Dieu;'),
('dt',27,7,'crampon1923','tu offriras des sacrifices pacifiques, et tu mangeras là et tu te réjouiras devant Yahweh, ton Dieu.'),
('dt',27,8,'crampon1923','Tu écriras sur ces pierres toutes les paroles de cette loi en caractères bien nets. »'),
('dt',27,9,'crampon1923','Moïse et les prêtres lévitiques parlèrent à tout Israël, en disant: « Garde le silence et écoute, ô Israël! Aujourd''hui tu es devenu le peuple de Yahweh, ton Dieu.'),
('dt',27,10,'crampon1923','Tu obéiras donc à la voix de Yahweh, ton Dieu, et tu mettras en pratique ses commandements et ses lois, que je te prescris aujourd''hui. »'),
('dt',27,11,'crampon1923','Le même jour, Moïse donna cet ordre au peuple:'),
('dt',27,12,'crampon1923','« Lorsque vous aurez passé le Jourdain, ceux-ci se tiendront sur le mont Garizim, pour bénir le peuple: Siméon, Lévi, Juda, Issachar, Joseph et Benjamin.'),
('dt',27,13,'crampon1923','Et ceux-là se tiendront sur le mont Hébal pour la malédiction: Ruben, Gad, Aser, Zabulon, Dan et Nephthali.'),
('dt',27,14,'crampon1923','Et les Lévites prendront la parole et diront d''une voix haute à tous les hommes d''Israël:'),
('dt',27,15,'crampon1923','Maudit soit l''homme qui fait une image taillée ou une image de fonte, abomination de Yahweh, œuvre des mains d''un artisan, et qui la place dans un lieu secret! — Et tout le peuple répondra et dira: Amen!'),
('dt',27,16,'crampon1923','Maudit soit celui qui méprise son père et sa mère! — Et tout le peuple dira: Amen!'),
('dt',27,17,'crampon1923','Maudit soit celui qui déplace la borne de son prochain! — Et tout le peuple dira: Amen!'),
('dt',27,18,'crampon1923','Maudit soit celui qui fait égarer un aveugle dans le chemin! — Et tout le peuple dira: Amen!'),
('dt',27,19,'crampon1923','Maudit soit celui qui viole le droit de l''étranger, de l''orphelin et de la veuve! — Et tout le peuple dira: Amen!'),
('dt',27,20,'crampon1923','Maudit soit celui qui couche avec la femme de son père, car il soulève la couverture de son père! — Et tout le peuple dira: Amen!'),
('dt',27,21,'crampon1923','Maudit soit celui qui couche avec une bête quelconque! — Et tout le peuple dira: Amen!'),
('dt',27,22,'crampon1923','Maudit soit celui qui couche avec sa sœur, fille de son père ou fille de sa mère! — Et tout le peuple dira: Amen!'),
('dt',27,23,'crampon1923','Maudit soit celui qui couche avec sa belle-mère! — Et tout le peuple dira: Amen!'),
('dt',27,24,'crampon1923','Maudit soit celui qui frappe en secret son prochain! — Et tout le peuple dira: Amen!'),
('dt',27,25,'crampon1923','Maudit soit celui qui reçoit un présent pour frapper une vie, répandre le sang innocent! — Et tout le peuple dira: Amen!'),
('dt',27,26,'crampon1923','Maudit soit celui qui ne maintient pas les paroles de cette loi, en les mettant en pratique! — Et tout le peuple dira: Amen!'),
('dt',28,1,'crampon1923','Si tu obéis exactement à la voix de Yahweh, ton Dieu, en observant et en mettant en pratique tous ses commandements que je te prescris aujourd''hui, Yahweh, ton Dieu, te donnera la supériorité sur toutes les nations de la terre.'),
('dt',28,2,'crampon1923','Voici toutes les bénédictions qui viendront sur toi et t''atteindront, si tu obéis à la voix de Yahweh, ton Dieu:'),
('dt',28,3,'crampon1923','Tu seras béni dans la ville et tu seras béni dans les champs.'),
('dt',28,4,'crampon1923','Béni sera le fruit de tes entrailles, le fruit de ton sol, le fruit de tes troupeaux, les portées de ton gros et de ton menu bétail.'),
('dt',28,5,'crampon1923','Bénies seront ta corbeille et ta huche.'),
('dt',28,6,'crampon1923','Tu seras béni à ton entrée, et tu seras béni à ta sortie.'),
('dt',28,7,'crampon1923','Yahweh fera que les ennemis qui s''élèveront contre toi soient mis en déroute devant toi; venus contre toi par un seul chemin, ils s''enfuiront devant toi par sept chemins.'),
('dt',28,8,'crampon1923','Yahweh commandera à la bénédiction d''être avec toi dans tes greniers et dans tout travail de tes mains! Il te bénira dans le pays que te donne Yahweh, ton Dieu.'),
('dt',28,9,'crampon1923','Yahweh te fera subsister pour lui comme un peuple saint, ainsi qu''il te l''a juré, si tu observes les commandements de Yahweh, ton Dieu, et si tu marches dans ses voies;'),
('dt',28,10,'crampon1923','et tous les peuples verront que le nom de Yahweh est nommé sur toi, et ils te craindront.'),
('dt',28,11,'crampon1923','Yahweh te comblera de biens, en multipliant le fruit de tes entrailles, le fruit de tes troupeaux et le fruit de ton sol, dans le pays que Yahweh a juré à tes pères de te donner.'),
('dt',28,12,'crampon1923','Yahweh t''ouvrira son bon trésor, le ciel, pour envoyer à ton pays la pluie en son temps, et pour bénir tout le travail de tes mains. Tu prêteras à beaucoup de nations, et tu n''emprunteras point.'),
('dt',28,13,'crampon1923','Yahweh te mettra à la tête, et non à la queue; tu seras toujours en haut, et tu ne seras jamais en bas, si tu obéis aux commandements de Yahweh, ton Dieu, que je te prescris aujourd''hui, si tu les observes et les mets en pratique,'),
('dt',28,14,'crampon1923','et si tu ne t''écartes, ni à droite ni à gauche, de tous les commandements que je vous prescris aujourd''hui, pour aller après d''autres dieux et les servir.'),
('dt',28,15,'crampon1923','Mais si tu n''obéis pas à la voix de Yahweh, ton Dieu, pour observer et mettre en pratique tous ses commandements et toutes ses lois que je te prescris aujourd''hui, voici toutes les malédictions qui viendront sur toi et t''atteindront:'),
('dt',28,16,'crampon1923','Tu seras maudit dans la ville et tu seras maudit dans les champs.'),
('dt',28,17,'crampon1923','Seront maudites ta corbeille et ta huche.'),
('dt',28,18,'crampon1923','Seront maudits le fruit de tes entrailles, le fruit de ton sol, les portées de ton gros et de ton menu bétail.'),
('dt',28,19,'crampon1923','Tu seras maudit à ton entrée, et tu seras maudit à ta sortie.'),
('dt',28,20,'crampon1923','Yahweh enverra contre toi la malédiction, le trouble et la menace, dans tout ce que tu entreprendras de faire, jusqu''à ce que tu sois détruit et jusqu''à ce que tu périsses bientôt, à cause de la perversité de tes actions, par lesquelles tu m''auras abandonné.'),
('dt',28,21,'crampon1923','Yahweh attachera à toi la peste, jusqu''à ce qu''elle t''ait consumé de dessus la terre où tu vas entrer pour la posséder.'),
('dt',28,22,'crampon1923','Yahweh te frappera de langueur, de fièvre, d''inflammation, de chaleur brûlante, de sécheresse, de charbon et de nielle, fléaux qui te poursuivront jusqu''à ce que tu périsses.'),
('dt',28,23,'crampon1923','Ton ciel sur ta tête sera d''airain, et la terre sous tes pieds sera de fer.'),
('dt',28,24,'crampon1923','Yahweh enverra pour pluie à ton pays de la poussière et du sable qui descendront du ciel sur toi jusqu''à ce que tu sois détruit.'),
('dt',28,25,'crampon1923','Yahweh fera que tu sois battu devant tes ennemis; tu sortiras contre eux par un seul chemin, et par sept chemins tu fuiras devant eux, et tu seras un objet de terreur parmi tous les royaumes de la terre.'),
('dt',28,26,'crampon1923','Ton cadavre servira de pâture à tous les oiseaux du ciel et aux bêtes de la terre, et il n''y aura personne pour les effrayer.'),
('dt',28,27,'crampon1923','Yahweh te frappera de l''ulcère d''Egypte, d''hémorroïdes, de dartres et de gale, dont tu ne pourras guérir.'),
('dt',28,28,'crampon1923','Yahweh te frappera de délire, d''aveuglement et d''égarement d''esprit;'),
('dt',28,29,'crampon1923','tu tâtonneras en plein midi, comme l''aveugle dans l''obscurité; tu ne réussiras pas dans tes voies; tu seras tous les jours opprimé et dépouillé, sans personne qui vienne à ton secours.'),
('dt',28,30,'crampon1923','Tu te fianceras à une femme, et un autre la possédera; tu bâtiras une maison, et tu ne l''habiteras pas; tu planteras une vigne, et tu n''en jouiras pas.'),
('dt',28,31,'crampon1923','Ton bœuf sera égorgé sous tes yeux, et tu n''en mangeras pas; ton âne sera enlevé de devant toi, et on ne te le rendra pas; tes brebis seront livrées à tes ennemis, et personne ne viendra à ton secours.'),
('dt',28,32,'crampon1923','Tes fils et tes filles seront livrés à un autre peuple; tes yeux le verront et languiront tout le jour après eux, et ta main sera impuissante.'),
('dt',28,33,'crampon1923','Le fruit de ton sol et tout le produit de ton travail, un peuple que tu n''as pas connu le mangera, et tu seras opprimé et écrasé tous les jours.'),
('dt',28,34,'crampon1923','Tu deviendras fou à la vue des choses que tu verras de tes yeux.'),
('dt',28,35,'crampon1923','Yahweh te frappera aux genoux et aux cuisses d''un ulcère malin, dont tu ne pourras guérir; il te couvrira depuis la plante du pied jusqu''au sommet de la tête.'),
('dt',28,36,'crampon1923','Yahweh te fera marcher, toi et ton roi que tu auras mis à ta tête, vers une nation que tu n''auras pas connue, ni toi, ni tes pères, et là tu serviras d''autres dieux, du bois et de la pierre,'),
('dt',28,37,'crampon1923','et tu deviendras un sujet d''étonnement, de fable et de raillerie, parmi tous les peuples chez lesquels Yahweh te mènera.'),
('dt',28,38,'crampon1923','Tu porteras sur ton champ beaucoup de semence, et tu recueilleras peu, car les sauterelles la dévoreront.'),
('dt',28,39,'crampon1923','Tu planteras des vignes et tu les cultiveras, et tu ne boiras pas de vin et tu ne récolteras rien, car les vers les mangeront.'),
('dt',28,40,'crampon1923','Tu auras des oliviers sur tout ton territoire, et tu ne t''oindras pas d''huile, car tes olives tomberont.'),
('dt',28,41,'crampon1923','Tu engendreras des fils et des filles, et ils ne seront pas à toi, car ils iront en captivité.'),
('dt',28,42,'crampon1923','Les insectes s''empareront de tous tes arbres et des fruits de ton sol.'),
('dt',28,43,'crampon1923','L''étranger qui vit au milieu de toi s''élèvera de plus en plus au-dessus de toi, tandis que toi, tu descendras toujours plus bas;'),
('dt',28,44,'crampon1923','il te prêtera, et tu ne lui prêteras pas: il sera en tête, et tu seras à la queue.'),
('dt',28,45,'crampon1923','Toutes ces malédictions viendront sur toi, elles te poursuivront et t''atteindront, jusqu''à ce que tu sois détruit, parce que tu n''auras pas obéi à la voix de Yahweh, ton Dieu, pour observer ses lois et ses commandements qu''il t''a prescrits.'),
('dt',28,46,'crampon1923','Elles seront pour toi un signe et un prodige, et pour ta postérité à jamais.'),
('dt',28,47,'crampon1923','Parce que tu n''auras pas servi Yahweh, ton Dieu, avec joie et de bon cœur, en retour de l''abondance de toutes choses,'),
('dt',28,48,'crampon1923','tu serviras, dans la faim, dans la soif, dans la nudité, dans la disette de toutes choses, tes ennemis que Yahweh enverra contre toi; il mettra un joug de fer sur ton cou, jusqu''à ce qu''il t''ait détruit.'),
('dt',28,49,'crampon1923','Yahweh fera partir contre toi de loin, des extrémités de la terre, une nation à la marche rapide comme le vol de l''aigle, nation dont tu n''entendras pas le langage,'),
('dt',28,50,'crampon1923','nation à l''aspect farouche, qui n''aura ni égards pour le vieillard, ni pitié pour l''enfant.'),
('dt',28,51,'crampon1923','Elle dévorera le fruit de tes troupeaux et le fruit de ton sol, jusqu''à ce que tu sois détruit; elle ne te laissera ni blé, ni vin nouveau, ni huile, ni les portées de ton gros et de ton menu bétail, jusqu''à ce qu''elle t''ait fait périr.'),
('dt',28,52,'crampon1923','Elle t''assiégera dans toutes tes portes, jusqu''à ce que tombent dans tout ton pays tes murailles, hautes et fortes, dans lesquelles tu auras mis ta confiance; elle t''assiégera dans toutes tes portes, dans tout le pays que Yahweh, ton Dieu, t''aura donné.'),
('dt',28,53,'crampon1923','Tu mangeras le fruit de tes entrailles, la chair de tes fils et de tes filles que Yahweh, ton Dieu, t''aura donnés, tant sera grande l''angoisse et la détresse où te réduira ton ennemi.'),
('dt',28,54,'crampon1923','L''homme d''entre vous le plus délicat et le plus habitué au luxe regardera d''un œil jaloux son frère, la femme qui repose sur son sein et le reste de ses enfants qu''il aura épargnés;'),
('dt',28,55,'crampon1923','il ne donnera à aucun d''eux de la chair de ses enfants dont il se nourrira, parce qu''il ne lui restera plus rien, tant seront grandes l''angoisse et la détresse où te réduira ton ennemi dans toutes tes portes.'),
('dt',28,56,'crampon1923','La femme d''entre vous la plus délicate et la plus habituée au luxe, trop tendre et trop délicate pour essayer de poser à terre la plante de son pied, regardera d''un œil jaloux le mari qui reposait sur son sein, ainsi que son fils et sa fille,'),
('dt',28,57,'crampon1923','à cause de l''arrière-faix sorti d''entre ses pieds et de ses enfants qu''elle aura mis au monde; car, manquant de tout, elle s''en nourrira en secret, tant sera grande l''angoisse et la détresse où te réduira ton ennemi dans tes portes.'),
('dt',28,58,'crampon1923','Si tu n''as pas soin de mettre en pratique toutes les paroles de cette loi, écrites dans ce livre, craignant ce nom glorieux et redoutable: Yahweh, ton Dieu,'),
('dt',28,59,'crampon1923','— Yahweh rendra extraordinaires tes plaies et les plaies de ta postérité, plaies grandes et continues, maladies graves et opiniâtres.'),
('dt',28,60,'crampon1923','Il fera revenir sur toi toutes les maladies d''Egypte, devant lesquelles tu tremblais, et elles s''attacheront à toi.'),
('dt',28,61,'crampon1923','De plus, Yahweh fera venir sur toi toutes sortes de maladies et de plaies, qui ne sont pas écrites dans le livre de cette loi, jusqu''à ce que tu sois détruit.'),
('dt',28,62,'crampon1923','Vous ne resterez plus qu''un petit nombre, après avoir été nombreux comme les étoiles du ciel, parce que tu n''auras pas obéi à la voix de Yahweh, ton Dieu.'),
('dt',28,63,'crampon1923','De même que Yahweh prenait plaisir à vous faire du bien et à vous multiplier, ainsi Yahweh prendra plaisir à vous faire périr et à vous détruire; et vous serez arrachés de la terre où tu vas entrer pour la posséder.'),
('dt',28,64,'crampon1923','Yahweh te dispersera parmi tous les peuples, d''une extrémité de la terre à l''autre, et là, tu serviras d''autres dieux que n''ont connus ni toi ni tes pères, du bois et de la pierre.'),
('dt',28,65,'crampon1923','Parmi ces nations mêmes, tu ne seras pas tranquille, et il n''y aura pas un lieu de repos pour la plante de tes pieds; là Yahweh te donnera un cœur tremblant, des yeux éteints, et une âme languissante.'),
('dt',28,66,'crampon1923','Ta vie sera comme en suspens devant toi, tu trembleras la nuit et le jour, et tu ne croiras pas à ta vie.'),
('dt',28,67,'crampon1923','Le matin tu diras: « Que ne suis-je au soir? » et le soir tu diras: « Que ne suis-je au matin? » — à cause de la crainte qui agitera ton cœur et des choses que tes yeux verront.'),
('dt',28,68,'crampon1923','Et Yahweh te fera retourner sur des navires en Egypte, par le chemin dont je t''avais dit: « Tu ne le verras plus. » Et là vous vous offrirez en vente à vos ennemis, comme esclaves et comme servantes, et il n''y aura personne qui vous achète. »'),
('dt',28,69,'crampon1923','Voici les paroles de l''alliance que Yahweh ordonna à Moïse de conclure avec les enfants d''Israël au pays de Moab, outre l''alliance qu''il avait conclue avec eux en Horeb.'),
('dt',29,1,'crampon1923','Moïse convoqua tout Israël et leur dit: « Vous avez vu tout ce que Yahweh a fait sous vos yeux, dans le pays d''Egypte, à Pharaon, à tous ses serviteurs et à tout son pays,'),
('dt',29,2,'crampon1923','les grandes épreuves que tes yeux ont vues, ces signes et ces grands prodiges.'),
('dt',29,3,'crampon1923','Mais Yahweh ne vous a pas donné, jusqu''à ce jour, un cœur qui comprenne, des yeux qui voient, des oreilles qui entendent.'),
('dt',29,4,'crampon1923','Je vous ai conduits pendant quarante ans dans le désert; vos vêtements ne se sont pas usés sur vous, et ta chaussure ne s''est pas usée à ton pied;'),
('dt',29,5,'crampon1923','vous n''avez pas mangé de pain, et vous n''avez bu ni vin ni cervoise, afin que vous puissiez connaître que je suis Yahweh, votre Dieu.'),
('dt',29,6,'crampon1923','Vous êtes ainsi arrivés dans ce lieu. Séhon, roi de Hésebon, et Og, roi de Basan, sont sortis à notre rencontre, pour nous combattre, et nous les avons battus.'),
('dt',29,7,'crampon1923','Nous avons pris leur pays, et nous l''avons donné en propriété aux Rubénites, aux Gadites et à la moitié de la tribu des Manassites.'),
('dt',29,8,'crampon1923','Observez donc les paroles de cette alliance et mettez-les en pratique, afin de réussir dans tout ce que vous ferez.'),
('dt',29,9,'crampon1923','Vous vous présentez tous aujourd''hui devant Yahweh, votre Dieu, vos chefs, vos tribus, vos anciens, vos officiers, tous les hommes d''Israël,'),
('dt',29,10,'crampon1923','vos enfants, vos femmes et l''étranger qui est au milieu de ton camp, depuis celui qui coupe ton bois jusqu''à celui qui puise ton eau:'),
('dt',29,11,'crampon1923','tu te présentes pour entrer dans l''alliance de Yahweh, ton Dieu, et dans son serment, alliance que Yahweh, ton Dieu, conclut en ce jour avec toi,'),
('dt',29,12,'crampon1923','pour t''établir aujourd''hui comme son peuple et être lui-même ton Dieu, comme il te l''a dit et comme il l''a juré à tes pères, Abraham, Isaac et Jacob.'),
('dt',29,13,'crampon1923','Ce n''est point avec vous seuls que je conclus cette alliance, et que je fais ce serment;'),
('dt',29,14,'crampon1923','mais c''est avec quiconque se tient ici aujourd''hui avec nous devant Yahweh, notre Dieu, et avec quiconque n''est pas ici avec nous en ce jour.'),
('dt',29,15,'crampon1923','Vous savez, en effet, comment nous avons habité dans le pays d''Egypte, et comment nous avons passé au milieu des nations parmi lesquelles vous avez passé:'),
('dt',29,16,'crampon1923','vous avez vu leurs abominations et leur idoles, bois et pierre, argent et or, qui sont chez elles.'),
('dt',29,17,'crampon1923','Qu''il n''y ait donc parmi vous ni homme, ni femme, ni famille, ni tribu, dont le cœur se détourne aujourd''hui de Yahweh, notre Dieu, pour aller servir les dieux de ces nations; qu''il n''y ait point parmi vous de racine produisant du poison et de l''absinthe.'),
('dt',29,18,'crampon1923','Que personne, en entendant les paroles de ce serment, ne se flatte dans son cœur, en disant: « J''aurai la paix, alors même que je marcherai dans l''endurcissement de mon cœur, » de sorte que celui qui est assouvi entraîne celui qui a soif.'),
('dt',29,19,'crampon1923','Yahweh ne consentira pas à pardonner à cet homme; mais alors la colère et la jalousie de Yahweh s''enflammeront contre cet homme, toutes les malédictions écrites dans ce livre reposeront sur lui, et Yahweh effacera son nom de dessous les cieux.'),
('dt',29,20,'crampon1923','Yahweh le séparera, pour le livrer au malheur, de toutes les tribus d''Israël, selon toutes les malédictions de l''alliance écrite dans ce livre de la loi.'),
('dt',29,21,'crampon1923','La génération à venir, vos enfants qui naîtront après vous, et l''étranger qui viendra d''une terre lointaine, — à la vue des plaies de ce pays et de ses maladies, dont Yahweh l''aura frappé,'),
('dt',29,22,'crampon1923','du soufre et du sel, de l''embrasement de toute cette terre, qui ne sera pas ensemencée, ne produira pas de fruits, sur laquelle ne croîtra aucune herbe, comme il arriva au bouleversement de Sodome, de Gomorrhe, d''Adama et de Seboïm, que Yahweh bouleversa dans sa colère et dans sa fureur, —'),
('dt',29,23,'crampon1923','toutes ces nations diront: « Pourquoi Yahweh a-t-il ainsi traité ce pays? D''où vient l''ardeur de cette grande colère? »'),
('dt',29,24,'crampon1923','Et l''on dira: « C''est parce qu''ils ont abandonné l''alliance de Yahweh, le Dieu de leurs pères, qu''il avait conclue avec eux, lorsqu''il les fit sortir du pays d''Egypte;'),
('dt',29,25,'crampon1923','ils sont allés servir d''autres dieux et se prosterner devant eux, des dieux qu''ils ne connaissaient pas et que Yahweh ne leur avait pas donnés en partage.'),
('dt',29,26,'crampon1923','La colère de Yahweh s''est enflammée contre ce pays, et il a fait venir sur lui toutes les malédictions écrites dans ce livre.'),
('dt',29,27,'crampon1923','Yahweh les a arrachés de leur sol avec colère, avec fureur et avec une grande indignation, et il les a jetés sur une autre terre, comme on le voit aujourd''hui. »'),
('dt',29,28,'crampon1923','Les choses cachées sont à Yahweh, notre Dieu; les choses révélées sont pour nous et pour nos enfants, à jamais, afin que nous mettions en pratique toutes les paroles de cette loi.'),
('dt',30,1,'crampon1923','Lorsque toutes ces choses seront venues sur toi, la bénédiction et la malédiction que j''ai mises devant toi, et que tu les auras de nouveau prises à cœur, au milieu de toutes les nations parmi lesquelles t''aura chassé Yahweh, ton Dieu,'),
('dt',30,2,'crampon1923','si tu reviens à Yahweh, ton Dieu, et que tu obéisses à sa voix, toi et tes enfants, de tout ton cœur et de toute ton âme, selon tout ce que je te prescris aujourd''hui,'),
('dt',30,3,'crampon1923','alors Yahweh, ton Dieu, ramènera tes captifs et aura compassion de toi; il te rassemblera de nouveau du milieu de tous les peuples chez lesquels Yahweh, ton Dieu, t''aura dispersé.'),
('dt',30,4,'crampon1923','Quand tes exilés seraient à l''extrémité du ciel, Yahweh, ton Dieu, te rassemblera de là, il ira jusque-là te prendre.'),
('dt',30,5,'crampon1923','Yahweh, ton Dieu, te ramènera dans le pays qu''auront possédé tes pères, et tu le posséderas; il te fera du bien et te rendra plus nombreux que tes pères.'),
('dt',30,6,'crampon1923','Yahweh, ton Dieu, circoncira ton cœur et le cœur de ta postérité, pour que tu aimes Yahweh, ton Dieu, de tout ton cœur et de toute ton âme, afin que tu vives.'),
('dt',30,7,'crampon1923','Yahweh, ton Dieu, fera tomber toutes ces malédictions sur tes ennemis, sur ceux qui t''auront haï et persécuté.'),
('dt',30,8,'crampon1923','Et toi, de nouveau, tu écouteras la voix de Yahweh, et tu mettras en pratique tous ces commandements que je te prescris aujourd''hui;'),
('dt',30,9,'crampon1923','et Yahweh, ton Dieu, te comblera de biens dans tout le travail de tes mains, dans le fruit de tes entrailles, dans le fruit de tes troupeaux et dans le fruit de ton sol; car Yahweh se réjouira de nouveau à ton sujet en te faisant du bien, comme il s''est réjoui au sujet de tes pères,'),
('dt',30,10,'crampon1923','si tu obéis à la voix de Yahweh, ton Dieu, en observant ses commandements et ses préceptes écrits dans ce livre de la loi, si tu reviens à Yahweh, ton Dieu, de tout ton cœur et de toute ton âme.'),
('dt',30,11,'crampon1923','Ce commandement que je te prescris aujourd''hui n''est pas au-dessus de toi ni hors de ta portée.'),
('dt',30,12,'crampon1923','Il n''est pas dans le ciel, pour que tu dises: « Qui montera pour nous au ciel et nous l''ira chercher, et nous le fera entendre, afin que nous l''accomplissions? »'),
('dt',30,13,'crampon1923','Il n''est pas au-delà de la mer, pour que tu dises: « Qui passera pour nous au delà de la mer et nous l''ira chercher, et nous le fera entendre, afin que nous l''accomplissions? »'),
('dt',30,14,'crampon1923','Mais la parole est tout près de toi, dans ta bouche et dans ton cœur, afin que tu l''accomplisses.'),
('dt',30,15,'crampon1923','Vois, j''ai mis aujourd''hui devant toi la vie et le bien, la mort et le mal,'),
('dt',30,16,'crampon1923','en te prescrivant aujourd''hui d''aimer Yahweh, ton Dieu, de marcher dans ses voies et d''observer ses commandements, ses lois et ses ordonnances, afin que tu vives et que tu multiplies, et que Yahweh, ton Dieu, te bénisse dans le pays où tu vas entrer pour le posséder.'),
('dt',30,17,'crampon1923','Mais si ton cœur se détourne, que tu n''écoutes point et que tu te laisses entraîner à te prosterner devant d''autres dieux et à les servir,'),
('dt',30,18,'crampon1923','je vous déclare en ce jour que vous périrez certainement; vous ne prolongerez pas vos jours sur la terre où après avoir passé le Jourdain, tu vas entrer pour la posséder.'),
('dt',30,19,'crampon1923','J''en prends aujourd''hui à témoin contre vous le ciel et la terre: j''ai mis devant toi la vie et la mort, la bénédiction et la malédiction. Choisis donc la vie, afin que tu vives, toi et ta postérité,'),
('dt',30,20,'crampon1923','en aimant Yahweh, ton Dieu, en écoutant sa voix et en t''attachant à lui; car cela, c''est ta vie et de longs jours à demeurer dans la terre que Yahweh a juré de donner à tes pères, Abraham, Isaac et Jacob. »'),
('dt',31,1,'crampon1923','Moïse adressa encore ces paroles à tout Israël.'),
('dt',31,2,'crampon1923','Il leur dit: « Aujourd''hui, je suis âgé de cent vingt ans, je ne puis plus sortir et entrer, et Yahweh m''a dit: Tu ne passeras pas ce Jourdain.'),
('dt',31,3,'crampon1923','C''est Yahweh, ton Dieu, qui passera devant toi; c''est lui qui détruira de devant toi ces nations, et tu les posséderas. Josué sera celui qui passera devant toi, comme Yahweh l''a dit.'),
('dt',31,4,'crampon1923','Yahweh les traitera comme il a traité Séhon et Og, roi des Amorrhéens, qu''il a détruits ainsi que leur pays.'),
('dt',31,5,'crampon1923','Yahweh vous les livrera, et vous les traiterez selon tous les ordres que je vous ai donnés.'),
('dt',31,6,'crampon1923','Soyez forts et remplis de courage; n''ayez ni crainte ni frayeur devant eux, car c''est Yahweh, ton Dieu, qui marche avec toi; il ne te délaissera point et ne t''abandonnera point. »'),
('dt',31,7,'crampon1923','Moïse appela Josué et lui dit en présence de tout Israël: « Sois fort et rempli de courage, car c''est toi qui entreras avec ce peuple dans le pays que Yahweh a juré à leurs pères de leur donner, et c''est toi qui le leur feras posséder.'),
('dt',31,8,'crampon1923','Car c''est Yahweh qui marchera devant toi, lui qui sera avec toi; il ne te délaissera point et ne t''abandonnera point; sois sans crainte et sans peur. »'),
('dt',31,9,'crampon1923','Moïse écrivit cette loi, et la donna aux prêtres, fils de Lévi, qui portaient l''arche de l''alliance de Yahweh, et à tous les anciens d''Israël.'),
('dt',31,10,'crampon1923','Et il leur fit ce commandement: « Après chaque septième année, à l''époque de l''année de rémission, à la fête des tabernacles,'),
('dt',31,11,'crampon1923','quand tout Israël viendra se présenter devant Yahweh, ton Dieu, dans le lieu qu''il aura choisi, tu liras cette loi devant tout Israël, de sorte qu''ils l''entendent.'),
('dt',31,12,'crampon1923','Assemble le peuple, les hommes, les femmes, les enfants, et l''étranger qui sera dans tes portes, afin qu''ils entendent, et afin qu''ils apprennent à craindre Yahweh, votre Dieu, et qu''ils aient soin de mettre en pratique toutes les paroles de cette loi.'),
('dt',31,13,'crampon1923','Et leurs enfants, qui ne la connaîtront pas, l''entendront et apprendront à craindre Yahweh, votre Dieu, tout le temps que vous vivrez sur la terre vers laquelle vous irez pour la posséder, après avoir passé le Jourdain. »'),
('dt',31,14,'crampon1923','Et Yahweh dit à Moïse: « Voici que le moment est proche où tu vas mourir. Appelle Josué, et présentez-vous dans la tente de réunion, pour que je lui donne mes ordres. » Moïse et Josué allèrent se présenter dans la tente de réunion.'),
('dt',31,15,'crampon1923','Et Yahweh apparut, dans la tente, dans une colonne de nuée, et la colonne de nuée se tint à l''entrée de la tente.'),
('dt',31,16,'crampon1923','Et Yahweh dit à Moïse: « Voici, tu vas être couché avec tes pères; et ce peuple se lèvera et se prostituera à des dieux étrangers du pays au milieu duquel il va entrer. Il m''abandonnera et il rompra mon alliance que j''ai conclue avec lui.'),
('dt',31,17,'crampon1923','Et ma colère s''enflammera contre lui en ce jour-là; je les abandonnerai et je leur cacherai ma face; on le dévorera; une multitude de maux et d''afflictions fondront sur lui, et il dira en ce jour-là: N''est-ce pas parce que mon Dieu n''est pas au milieu de moi que ces maux ont fondu sur moi?'),
('dt',31,18,'crampon1923','Et moi je cacherai ma face en ce jour-là, à cause de tout le mal qu''il aura fait, en se tournant vers d''autres dieux.'),
('dt',31,19,'crampon1923','Ecrivez donc ce cantique. Enseigne-le aux enfants d''Israël, mets-le dans leur bouche, afin que ce cantique me serve de témoin contre les enfants d''Israël.'),
('dt',31,20,'crampon1923','Car, quand j''aurai fait entrer ce peuple dans la terre que j''ai promise par serment à ses pères, terre où coulent le lait et le miel; qu''il aura mangé et se sera rassasié et engraissé: alors il se tournera vers d''autres dieux, et ils les serviront, ils me mépriseront et il rompra mon alliance.'),
('dt',31,21,'crampon1923','Et quand une multitude de maux et d''afflictions auront fondu sur lui, ce cantique déposera comme témoin contre lui; car il ne sera pas oublié et ne sortira pas de la bouche de ses descendants. Car je connais les dispositions qui l''animent dès aujourd''hui, avant même que je l''aie fait entrer dans le pays que je lui ai promis par serment. »'),
('dt',31,22,'crampon1923','En ce jour-là, Moïse écrivit ce cantique, et il l''enseigna aux enfants d''Israël.'),
('dt',31,23,'crampon1923','Yahweh donna ses ordres à Josué, fils de Nun, et lui dit: « Sois fort et rempli de courage; car c''est toi qui feras entrer les enfants d''Israël dans le pays que je leur ai promis par serment, et je serai avec toi. »'),
('dt',31,24,'crampon1923','Lorsque Moïse eut complètement achevé d''écrire dans un livre les paroles de cette loi,'),
('dt',31,25,'crampon1923','il donna cet ordre aux Lévites qui portaient l''arche de l''alliance de Yahweh:'),
('dt',31,26,'crampon1923','« Prenez ce livre de la loi et mettez-le à côté de l''arche de l''alliance de Yahweh, votre Dieu, et il sera là comme un témoin contre toi.'),
('dt',31,27,'crampon1923','Car je connais ton esprit rebelle et la raideur de ton cou. Aujourd''hui que je suis encore vivant au milieu de vous, vous avez été rebelles contre Yahweh; combien plus le serez-vous après ma mort? —'),
('dt',31,28,'crampon1923','Assemblez auprès de moi tous les anciens de vos tribus et vos magistrats; je prononcerai ces paroles à leurs oreilles, et je prendrai à témoin contre eux le ciel et la terre.'),
('dt',31,29,'crampon1923','Car je sais qu''après ma mort vous vous corromprez certainement, que vous vous détournerez de la voie que je vous ai prescrite, et que le malheur vous atteindra dans la suite des temps, pour avoir fait ce qui est mal aux yeux de Yahweh, en l''irritant par l''œuvre de vos mains. »'),
('dt',31,30,'crampon1923','Moïse prononça aux oreilles de toute l''assemblée d''Israël les paroles de ce cantique jusqu''au bout:'),
('dt',32,1,'crampon1923','Cieux, prêtez l''oreille, et je parlerai; et que la terre écoute les paroles de ma bouche!'),
('dt',32,2,'crampon1923','Que mon enseignement se répande comme la pluie, que ma parole tombe comme la rosée, comme des ondées sur la verdure, comme des gouttes d''eau sur le gazon!'),
('dt',32,3,'crampon1923','Car je veux proclamer le nom de Yahweh: Rendez gloire à notre Dieu!'),
('dt',32,4,'crampon1923','Le Rocher, son œuvre est parfaite, car toutes ses voies sont justes; c''est un Dieu fidèle et sans iniquité; il est juste et droit.'),
('dt',32,5,'crampon1923','Ils ont péché contre lui, non ses enfants, mais leur souillure, une race fausse et perverse.'),
('dt',32,6,'crampon1923','Est-ce là ce que vous rendez à Yahweh, peuple insensé et dépourvu de sagesse? N''est-il pas ton père, ton créateur, celui qui t''a fait et qui t''a établi?'),
('dt',32,7,'crampon1923','Souviens-toi des anciens jours, considérez les années des générations passées! Interroge ton père, et il te l''apprendra, tes vieillards, et ils te le diront.'),
('dt',32,8,'crampon1923','Quand le Très-Haut assigna un héritage aux nations, quand il sépara les enfants des hommes, il fixa les limites des peuples, d''après le nombre des enfants d''Israël.'),
('dt',32,9,'crampon1923','Car la portion de Yahweh, c''est son peuple, Jacob est le lot de son héritage.'),
('dt',32,10,'crampon1923','Il l''a trouvé dans une terre déserte, dans une solitude, aux hurlements sauvages; il l''a entouré, il a pris soin de lui, il l''a gardé comme la prunelle de son œil.'),
('dt',32,11,'crampon1923','Pareil à l''aigle qui excite sa couvée, et voltige au-dessus de ses petits, Yahweh a déployé ses ailes, il a pris Israël, il l''a porté sur ses plumes;'),
('dt',32,12,'crampon1923','Yahweh seul l''a conduit, nul dieu étranger n''était avec lui.'),
('dt',32,13,'crampon1923','Il l''a fait monter sur les hauteurs du pays, et Israël a mangé les produits des champs; il lui a fait sucer le miel du rocher, l''huile qui sort de la roche la plus dure,'),
('dt',32,14,'crampon1923','la crème de la vache et le lait des brebis, avec la graisse des agneaux, des béliers nés en Basan et des boucs, avec la fleur du froment; et tu as bu le sang de la grappe, le vin écumant.'),
('dt',32,15,'crampon1923','Mais Jésurun est devenu gras, et il a regimbé; — tu es devenu gras, épais, replet! — et il a abandonné le Dieu qui l''avait formé, et méprisé le Rocher de son salut.'),
('dt',32,16,'crampon1923','Ils ont excité sa jalousie par des dieux étrangers, ils l''ont irrité par des abomination;'),
('dt',32,17,'crampon1923','ils ont sacrifié à des démons qui ne sont pas Dieu, à des dieux qu''ils ne connaissaient pas, dieux nouveaux, venus récemment, devant lesquels vos pères n''avaient pas tremblé.'),
('dt',32,18,'crampon1923','Tu as abandonné le Rocher qui t''avait engendré, et oublié le Dieu qui t''avait mis au monde.'),
('dt',32,19,'crampon1923','Yahweh l''a vu, et il en a été indigné, provoqué par ses fils et ses filles.'),
('dt',32,20,'crampon1923','Il a dit: « Je leur cacherai ma face, je verrai quelle sera leur fin; car c''est une race perverse, des fils en qui il n''y a pas de bonne foi.'),
('dt',32,21,'crampon1923','Ils ont excité ma jalousie par ce qui n''est pas Dieu, ils m''ont irrité par leurs vaines idoles; et moi, j''exciterai leur jalousie par ce qui n''est pas un peuple, je les irriterai par une nation insensée.'),
('dt',32,22,'crampon1923','Car le feu de ma colère s''est allumé, il brûle jusqu''au fond du séjour des morts; il dévore la terre et ses produits, il embrase les fondements des montagnes.'),
('dt',32,23,'crampon1923','J''accumulerai sur eux les maux, sur eux j''épuiserai mes flèches.'),
('dt',32,24,'crampon1923','Ils seront exténués par la faim, consumés par la fièvre et par la peste meurtrière; et j''enverrai encore contre eux la dent des bêtes, avec le venin des reptiles qui rampent dans la poussière.'),
('dt',32,25,'crampon1923','Au dehors l''épée ravira les enfants, — et au dedans ce sera l''effroi: le jeune homme comme la jeune fille, l''enfant à la mamelle comme le vieillard.'),
('dt',32,26,'crampon1923','Je dirai: « Je les emporterai d''un souffle, je ferai disparaître leur souvenir du milieu des hommes, »'),
('dt',32,27,'crampon1923','si je ne craignais l''arrogance de l''ennemi, que leurs adversaires ne se méprennent et qu''ils ne disent: « Notre main a été puissante, et ce n''est pas Yahweh qui a fait toutes ces choses. »'),
('dt',32,28,'crampon1923','Car c''est une nation dénuée de sens, et il n''y a point d''intelligence en eux.'),
('dt',32,29,'crampon1923','S''ils étaient sages, ils le comprendraient, ils considéreraient la fin qui les attend.'),
('dt',32,30,'crampon1923','Comment un homme en poursuivrait-il mille, comment deux en feraient-ils fuir dix mille, si leur Rocher ne les avait vendus, si Yahweh ne les avait livrés?'),
('dt',32,31,'crampon1923','Car leur rocher n''est pas comme notre Rocher, nos ennemis en sont juges.'),
('dt',32,32,'crampon1923','Mais leur vigne est du plant de Sodome, et des champs de Gomorrhe; leurs raisins sont des raisins vénéneux, et leurs grappes sont amères;'),
('dt',32,33,'crampon1923','leur vin, c''est le venin des dragons, c''est le poison mortel des aspics.'),
('dt',32,34,'crampon1923','Cela n''est-il pas caché près de moi, scellé dans mes trésors?'),
('dt',32,35,'crampon1923','A moi la vengeance et la rétribution, pour le temps où leur pied trébuchera! Car le jour de leur malheur est proche, et leur destin se précipite. »'),
('dt',32,36,'crampon1923','Car Yahweh fera droit à son peuple, et il se repentira en faveur de ses serviteurs, quand il verra que leur force est épuisée, et qu''il ne reste plus ni esclave, ni libre.'),
('dt',32,37,'crampon1923','Il dira: « Où sont leurs dieux, le rocher près duquel ils se réfugiaient,'),
('dt',32,38,'crampon1923','ces dieux qui mangeaient la graisse de leurs victimes, qui buvaient le vin de leurs libations? Qu''ils se lèvent, qu''ils vous secourent, qu''ils vous couvrent de leur protection!...'),
('dt',32,39,'crampon1923','Voyez maintenant que c''est moi, moi qui suis Dieu, et qu''il n''y a point de Dieu à côté de moi. C''est moi qui fais mourir et qui fais vivre; j''ai blessé, et c''est moi qui guérirai, et il n''y a personne qui délivre de ma main.'),
('dt',32,40,'crampon1923','Oui, je lève ma main vers le ciel, et je dis: Je vis éternellement!'),
('dt',32,41,'crampon1923','Quand j''aiguiserai l''éclair de mon glaive, et que ma main saisira le jugement, je tirerai vengeance de mes ennemis, et je rendrai à ceux qui me haïssent.'),
('dt',32,42,'crampon1923','J''enivrerai mes flèches de sang, et mon épée se repaîtra de chair: du sang des tués et des captifs, de la tête chevelue de l''ennemi. »'),
('dt',32,43,'crampon1923','Nations, poussez des cris de joie en l''honneur de son peuple! Car Yahweh venge le sang de ses serviteurs, il tire vengeance de ses adversaires, et il fait l''expiation pour sa terre, pour son peuple.'),
('dt',32,44,'crampon1923','Moïse vint et prononça toutes les paroles de ce cantique aux oreilles du peuple; avec lui était Josué, fils de Nun.'),
('dt',32,45,'crampon1923','Lorsqu''il eut achevé d''adresser toutes ces paroles à tout Israël,'),
('dt',32,46,'crampon1923','il leur dit: « Prenez à cœur toutes les paroles que je proclame aujourd''hui devant vous, que vous devez prescrire à vos enfants, pour qu''ils mettent soigneusement en pratique toutes les paroles de cette loi.'),
('dt',32,47,'crampon1923','Car ce n''est pas une chose indifférente pour vous; c''est votre vie, et, par l''accomplissement de cette parole, vous prolongerez vos jours sur la terre dont vous allez prendre possession en passant le Jourdain. »'),
('dt',32,48,'crampon1923','Ce même jour, Yahweh parla à Moïse, en disant:'),
('dt',32,49,'crampon1923','« Monte sur cette montagne d''Abarim, sur le mont Nébo, au pays de Moab, vis-à-vis de Jéricho, et regarde le pays de Chanaan, que je donne aux enfants d''Israël pour être leur propriété.'),
('dt',32,50,'crampon1923','Tu mourras sur la montagne où tu vas monter, et tu seras réuni à ton peuple, de même qu''Aaron, ton frère, est mort sur la montagne de Hor et a été réuni à son peuple,'),
('dt',32,51,'crampon1923','parce que vous avez péché contre moi au milieu des enfants d''Israël, aux eaux de Mériba de Cadès, dans le désert de Sin, et que vous ne m''avez pas sanctifié au milieu des enfants d''Israël.'),
('dt',32,52,'crampon1923','Tu verras le pays en face de toi, mais tu n''y entreras point, dans ce pays, que je donne aux enfants d''Israël. »'),
('dt',33,1,'crampon1923','Voici la bénédiction dont Moïse, homme de Dieu, bénit les enfants d''Israël, avant de mourir.'),
('dt',33,2,'crampon1923','Il dit: Yahweh est venu de Sinaï, il s''est levé pour eux de Séïr, il a resplendi de la montagne de Pharan, il est sorti du milieu des saintes myriades; de sa droite jaillissaient pour eux des jets de lumière,'),
('dt',33,3,'crampon1923','Il aime aussi les peuples; tous ses saints sont dans ta main, eux sont assis à tes pieds, et chacun recueille ta parole.'),
('dt',33,4,'crampon1923','Moïse nous a prescrit une loi, héritage de l''assemblée de Jacob.'),
('dt',33,5,'crampon1923','Il devint roi en Jésurun, lorsque s''assemblèrent les chefs du peuple, avec les tribus d''Israël.'),
('dt',33,6,'crampon1923','Que Ruben vive et qu''il ne meure point, et que ses hommes ne soient pas réduits à un petit nombre!'),
('dt',33,7,'crampon1923','Ceci est pour Juda; il dit: Ecoute,ô Yahweh, la voix de Juda, et ramène-le vers son peuple. De son bras il combattra pour Israël, et tu lui viendras en aide contre ses ennemis.'),
('dt',33,8,'crampon1923','Il dit pour Lévi: Ton Urim et ton Thummim sont confiés à ton homme saint, que tu as éprouvé à Massa, avec qui tu as contesté aux eaux de Mériba,'),
('dt',33,9,'crampon1923','qui a dit de son père et de sa mère: « Je ne les ai pas vus, » qui n''a pas reconnu ses frères, et ne sait rien de ses enfants. Car ils ont observé ta parole, et ils ont gardé ton alliance;'),
('dt',33,10,'crampon1923','ils enseignent tes ordonnances à Jacob, et ta loi à Israël; ils présentent l''encens à tes narines, et l''holocauste sur ton autel.'),
('dt',33,11,'crampon1923','Bénis sa force, ô Yahweh; agrée l''œuvre de ses mains; brise les reins de ses adversaires, et de ceux qui le haïssent; qu''ils ne se relèvent plus!'),
('dt',33,12,'crampon1923','Il dit pour Benjamin: Bien-aimé de Yahweh, il habitera en sécurité auprès de lui. Yahweh le protège continuellement, entre ses épaules il repose.'),
('dt',33,13,'crampon1923','Il dit pour Joseph: Béni de Yahweh est son pays; à lui le précieux don du ciel, la rosée, les eaux de l''abîme étendu en bas,'),
('dt',33,14,'crampon1923','les produits excellents que fait mûrir le soleil, les fruits excellents des mois,'),
('dt',33,15,'crampon1923','les meilleurs produits des montagnes antiques, les dons excellents des collines éternelles,'),
('dt',33,16,'crampon1923','les dons excellents de la terre et de son abondance. Que la faveur de celui qui habita dans le buisson vienne sur la tête de Joseph, sur le haut de la tête du prince de ses frères!'),
('dt',33,17,'crampon1923','A son taureau premier-né, à lui est la gloire; ses cornes sont les cornes du buffle; il en frappera tous les peuples ensemble, jusqu''aux extrémités de la terre. Telles sont les myriades d''Ephraïm, tels sont les milliers de Manassé.'),
('dt',33,18,'crampon1923','Il dit pour Zabulon: Réjouis-toi, Zabulon, dans tes courses, et toi, Issachar, dans tes tentes!'),
('dt',33,19,'crampon1923','Ils appellent les peuples à venir sur la montagne; là, ils offriront des sacrifices de justice, car ils suceront l''abondance de la mer, et les richesses cachées dans le sable.'),
('dt',33,20,'crampon1923','Il dit pour Gad: Béni soit celui qui met Gad au large! Il est couché comme une lionne; il déchire le bras, même la tête.'),
('dt',33,21,'crampon1923','Il s''est choisi les prémices du pays: car là était cachée une part de chef, et il a marché en tête du peuple, il a accompli la justice de Yahweh, et ses jugements avec Israël.'),
('dt',33,22,'crampon1923','Il dit pour Dan: Dan est un jeune lion, qui s''élance de Basan.'),
('dt',33,23,'crampon1923','Il dit pour Nephthali: Nephthali, rassasié de faveurs, et comblé des bénédictions de Yahweh, prend possession de la mer et du midi.'),
('dt',33,24,'crampon1923','Il dit pour Aser: Béni soit Aser entre les fils de Jacob! Qu''il soit le favori de ses frères, et qu''il trempe son pied dans l''huile!'),
('dt',33,25,'crampon1923','Que tes verrous soient de fer et d''airain, et que ton repos dure autant que tes jours!'),
('dt',33,26,'crampon1923','Nul, ô Jésurun, n''est semblable à Dieu, qui marche sur les cieux pour venir à ton secours, et, dans sa majesté, sur les nues.'),
('dt',33,27,'crampon1923','C''est un refuge que le Dieu des temps antiques, il te soutient de ses bras éternels; il chasse devant toi l''ennemi, et il dit: « Détruis! »'),
('dt',33,28,'crampon1923','Israël habite en sécurité; la source de Jacob coule à part, dans un pays de blé et de vin, et son ciel distille la rosée.'),
('dt',33,29,'crampon1923','Heureux es-tu, Israël! Qui est, comme toi, un peuple sauvé par Yahweh, le bouclier de ton secours, et l''épée de ta gloire? Tes ennemis feindront devant toi, et toi, tu marcheras sur leurs hauteurs.'),
('dt',34,1,'crampon1923','Moïse monta, des plaines de Moab, sur le mont Nébo, au sommet du Phasga, en face de Jéricho. Et Yahweh lui montra tout le pays: Galaad jusqu''à Dan,'),
('dt',34,2,'crampon1923','tout Nephthali et le pays d''Ephraïm et de Manassé, tout le pays de Juda jusqu''à la mer occidentale,'),
('dt',34,3,'crampon1923','le Négeb, le district du Jourdain, la vallée de Jéricho qui est la ville des palmiers, jusqu''à Ségor.'),
('dt',34,4,'crampon1923','Et Yahweh lui dit: « C''est là le pays au sujet duquel j''ai fait serment à Abraham, à Isaac et à Jacob, en disant: Je le donnerai à ta postérité. Je te l''ai fait voir de tes yeux; mais tu n''y entreras point. »'),
('dt',34,5,'crampon1923','Moïse, le serviteur de Yahweh, mourut là, dans le pays de Moab, selon l''ordre de Yahweh.'),
('dt',34,6,'crampon1923','Et il l''enterra dans la vallée, au pays de Moab, vis-à-vis de Beth-Phogor. Aucun homme n''a connu son sépulcre jusqu''à ce jour.'),
('dt',34,7,'crampon1923','Moïse était âgé de cent vingt ans, lorsqu''il mourut; sa vue n''était point affaiblie, et sa vigueur n''était point passée.'),
('dt',34,8,'crampon1923','Les enfants d''Israël pleurèrent Moïse, dans les plaines de Moab, pendant trente jours, et les jours des pleurs pour le deuil de Moïse furent accomplis.'),
('dt',34,9,'crampon1923','Josué, fils de Nun, était rempli de l''esprit de sagesse, car Moïse avait posé ses mains sur lui. Les enfants d''Israël lui obéirent et firent selon que Yahweh l''avait ordonné à Moïse.'),
('dt',34,10,'crampon1923','Il ne s''est plus levé en Israël de prophète semblable à Moïse, que Yahweh connaissait face à face,'),
('dt',34,11,'crampon1923','ni quant à tous les signes et miracles que Dieu l''envoya faire, dans le pays d''Egypte, sur Pharaon, sur tous ses serviteurs et sur tout son pays,'),
('dt',34,12,'crampon1923','ni quant à toute sa main puissante et à toutes les choses terribles que Moïse accomplit sous les yeux de tout Israël.'),
('jos',1,1,'crampon1923','Après la mort de Moïse, serviteur de Yahweh, Yahweh parla à Josué, fils de Nun, serviteur de Moïse, en ces termes:'),
('jos',1,2,'crampon1923','« Moïse, mon serviteur, est mort; maintenant lève-toi, passe ce Jourdain, toi et tout ce peuple, pour entrer dans le pays que je donne aux enfants d''Israël.'),
('jos',1,3,'crampon1923','Tout lieu que foulera la plante de votre pied, je vous l''ai donné, comme je l''ai dit à Moïse.'),
('jos',1,4,'crampon1923','Depuis le désert et depuis ce Liban jusqu''au grand fleuve, le fleuve d''Euphrate, — tout le pays des Héthéens, — et jusqu''à la grande mer vers le soleil couchant, tout cela sera votre territoire.'),
('jos',1,5,'crampon1923','Nul ne tiendra devant toi pendant tous les jours de ta vie; comme j''ai été avec Moïse, je serai avec toi; je ne te délaisserai, ni ne t''abandonnerai.'),
('jos',1,6,'crampon1923','Fortifie-toi et prends courage; car c''est toi qui mettras ce peuple en possession du pays que j''ai juré à leurs pères de leur donner.'),
('jos',1,7,'crampon1923','Seulement fortifie-toi et aie bon courage, en t''appliquant à agir selon toute la loi que Moïse, mon serviteur, t''a prescrite. Ne t''en détourne ni à droite ni à gauche, afin que tu réussisses en tout ce que tu entreprendras.'),
('jos',1,8,'crampon1923','Que ce livre de la loi ne s''éloigne pas de ta bouche; médite-le jour et nuit, en t''appliquant à agir selon tout ce qui y est écrit; car alors tu prospéreras dans tes voies et tu réussiras.'),
('jos',1,9,'crampon1923','Ne te l''ai-je pas commandé: Fortifie-toi et prends courage? Sois sans crainte et sans peur, car Yahweh, ton Dieu, est avec toi partout où tu iras. »'),
('jos',1,10,'crampon1923','Josué donna cet ordre aux officiers du peuple:'),
('jos',1,11,'crampon1923','« Parcourez le camp, et donnez au peuple ce commandement: Préparez-vous des provisions, car dans trois jours vous passerez ce Jourdain pour aller occuper le pays que Yahweh, votre Dieu, vous donne en possession. »'),
('jos',1,12,'crampon1923','Et aux Rubénites, aux Gadites et à la demi-tribu de Manassé, Josué parla ainsi:'),
('jos',1,13,'crampon1923','« Rappelez-vous ce que vous a prescrit Moïse, serviteur de Yahweh, en disant: Yahweh, votre Dieu, vous a accordé du repos et vous a donné ce pays.'),
('jos',1,14,'crampon1923','Vos femmes, vos petits enfants et vos troupeaux resteront dans le pays que Moïse vous a donné au delà du Jourdain; mais vous passerez en armes devant vos frères, vous tous, les hommes forts et vaillants; et vous les aiderez,'),
('jos',1,15,'crampon1923','jusqu''à ce que Yahweh ait donné du repos à vos frères comme à vous, et qu''ils soient en possession, eux aussi, du pays que leur donne Yahweh, votre Dieu. Puis vous reviendrez au pays qui vous appartient et vous le posséderez, ce pays que Moïse, serviteur de Yahweh, vous a donné au delà du Jourdain, vers le soleil levant. »'),
('jos',1,16,'crampon1923','Ils répondirent à Josué, en disant: « Tout ce que tu nous as commandé, nous le ferons, et partout où tu nous enverras, nous irons.'),
('jos',1,17,'crampon1923','Comme nous avons obéi en toutes choses à Moïse, ainsi nous t''obéirons. Daigne seulement Yahweh, ton Dieu, être avec toi, comme il a été avec Moïse!'),
('jos',1,18,'crampon1923','Quiconque sera rebelle à tes ordres et n''obéira pas à tout ce que tu lui commanderas, sera mis à mort. Seulement, fortifie-toi et prends courage! »'),
('jos',2,1,'crampon1923','Josué, fils de Nun, fit partir en secret de Sétim deux espions, en leur disant: « Allez, examinez le pays, et Jéricho. » S''étant mis en route, ils arrivèrent dans la maison d''une courtisane, nommée Rahab, et ils y couchèrent.'),
('jos',2,2,'crampon1923','On le dit au roi de Jéricho, en ces termes: « Voici que des hommes d''entre les enfants d''Israël sont venus ici pendant la nuit, pour explorer le pays. »'),
('jos',2,3,'crampon1923','Le roi de Jéricho envoya dire à Rahab: « Fais sortir les hommes qui sont venus chez toi et sont entrés dans ta maison, car c''est pour explorer tout le pays qu''ils sont venus. »'),
('jos',2,4,'crampon1923','La femme prit les deux hommes et, les ayant cachés, elle dit: « Il est vrai que ces hommes sont venus chez moi, mais je n''ai pas su d''où ils étaient;'),
('jos',2,5,'crampon1923','et comme on allait fermer le soir la porte de la ville, ils sont sortis; j''ignore où ils sont allés: hâtez-vous de les poursuivre, car vous les atteindrez. »'),
('jos',2,6,'crampon1923','Or elle les avait fait monter sur le toit et les avait cachés sous des tiges de lin, qu''elle avait disposées sur le toit.'),
('jos',2,7,'crampon1923','Ces gens les poursuivirent par le chemin des gués du Jourdain, et, dès que furent sortis ceux qui les poursuivaient, on ferma la porte.'),
('jos',2,8,'crampon1923','Avant que les espions se couchassent, Rahab monta vers eux sur le toit, et leur dit:'),
('jos',2,9,'crampon1923','« Yahweh, je le sais, vous a donné ce pays; la terreur de votre nom nous a saisis, et tous les habitants du pays défaillent devant vous.'),
('jos',2,10,'crampon1923','Car nous avons appris comment Yahweh, lorsque vous sortiez d''Egypte, a mis à sec devant vous les eaux de la mer Rouge, et comment vous avez traité les deux rois des Amorrhéens, au delà du Jourdain, Séhon et Og, que vous avez dévoués par anathème.'),
('jos',2,11,'crampon1923','Et, en l''apprenant, notre cœur s''est fondu, chacun a perdu courage à votre approche; car c''est Yahweh, votre Dieu, qui est Dieu en haut dans le ciel, et en bas sur la terre.'),
('jos',2,12,'crampon1923','Maintenant, je vous prie, jurez-moi par Yahweh que vous aurez pour la maison de mon père la même bonté que j''ai eue pour vous, et donnez-moi un gage assuré'),
('jos',2,13,'crampon1923','que vous laisserez la vie à mon père, à ma mère, à mes frères, à mes sœurs, et à tous ceux qui leur appartiennent, et que vous nous sauverez de la mort. »'),
('jos',2,14,'crampon1923','Ces hommes lui répondirent: « Que nous mourrions pour vous, si vous ne divulguez pas notre affaire! Et quand Yahweh nous donnera ce pays, nous agirons envers toi avec bonté et fidélité. »'),
('jos',2,15,'crampon1923','Elle les fit descendre avec une corde par la fenêtre, car sa maison était attenante à la muraille de la ville, et elle habitait sur la muraille.'),
('jos',2,16,'crampon1923','Elle leur dit: « Allez à la montagne, de peur que ceux qui vous poursuivent ne vous rencontrent, et cachez-vous là pendant trois jours, jusqu''à ce qu''ils soient de retour; après quoi, vous suivrez votre chemin. »'),
('jos',2,17,'crampon1923','Ces hommes lui dirent: « Voici comment nous nous acquitterons de ce serment que tu nous as fait faire:'),
('jos',2,18,'crampon1923','A notre entrée dans le pays, attache ce cordon de fil écarlate à la fenêtre par laquelle tu nous fais descendre, et rassemble auprès de toi, dans ta maison, ton père, ta mère, tes frères, et toute la famille de ton père.'),
('jos',2,19,'crampon1923','Si quelqu''un d''eux sort de la porte de ta maison pour aller dehors, son sang sera sur sa tête, et nous en seront innocents; mais si l''on met la main sur l''un de tous ceux qui seront avec toi dans la maison, son sang sera sur notre tête.'),
('jos',2,20,'crampon1923','Et si tu divulgues notre affaire, nous serons quittes du serment que tu nous as fait prêter. »'),
('jos',2,21,'crampon1923','Elle répondit: « Qu''il en soit selon vos paroles. » Puis elle les congédia, et ils partirent; et elle attacha à la fenêtre le cordon écarlate.'),
('jos',2,22,'crampon1923','Les espions, s''en étant allés, vinrent à la montagne, et ils y restèrent trois jours, jusqu''à ce que ceux qui les poursuivaient fussent de retour à Jéricho. Ceux qui les poursuivaient les avaient cherchés sur tout le chemin, sans les rencontrer.'),
('jos',2,23,'crampon1923','Les deux hommes s''en retournèrent et, étant descendus de la montagne, ils passèrent le Jourdain. Ils vinrent auprès de Josué, fils de Nun, et lui racontèrent tout ce qui leur était arrivé.'),
('jos',2,24,'crampon1923','Ils dirent à Josué: « Certainement Yahweh a livré tout le pays entre nos mains, et même tous les habitants du pays défaillent devant nous. »'),
('jos',3,1,'crampon1923','Josué, s''étant levé de bon matin, partit de Sétim, lui et tous les enfants d''Israël; arrivés au Jourdain, ils firent une halte avant de le traverser.'),
('jos',3,2,'crampon1923','Au bout de trois jours, les officiers parcoururent le camp,'),
('jos',3,3,'crampon1923','et donnèrent cet ordre au peuple: « Lorsque vous verrez l''arche de l''alliance de Yahweh, votre Dieu, portée par les prêtres lévites, partez de ce lieu où vous campez et mettez-vous en marche après elle,'),
('jos',3,4,'crampon1923','— mais qu''il y ait entre vous et elle une distance de deux mille coudées environ, n''en approchez pas, — afin que vous sachiez bien le chemin que vous devez suivre, car vous n''avez jamais passé par ce chemin. »'),
('jos',3,5,'crampon1923','Et Josué dit au peuple: « Sanctifiez-vous, car demain Yahweh fera des prodiges au milieu de vous. »'),
('jos',3,6,'crampon1923','Puis Josué parla aux prêtres, en disant: « Portez l''arche d''alliance, et passez en avant du peuple. » Ils portèrent l''arche d''alliance et s''avancèrent devant le peuple.'),
('jos',3,7,'crampon1923','Yahweh dit à Josué: « Aujourd''hui je commencerai à t''élever aux yeux de tout Israël, afin qu''ils sachent que je serai avec toi comme j''ai été avec Moïse.'),
('jos',3,8,'crampon1923','Toi, donne cet ordre aux prêtres qui portent l''arche d''alliance: Lorsque vous arriverez au bord des eaux du Jourdain, vous vous arrêterez dans le Jourdain. »'),
('jos',3,9,'crampon1923','Josué dit aux enfants d''Israël: « Approchez et écoutez les paroles de Yahweh, votre Dieu. »'),
('jos',3,10,'crampon1923','Et Josué dit: « A ceci vous reconnaîtrez que le Dieu vivant est au milieu de vous, et qu''il ne manquera pas de chasser devant vous les Chananéens, les Héthéens, les Hévéens, les Phérézéens, les Gergéséens, les Amorrhéens et les Jébuséens.'),
('jos',3,11,'crampon1923','Voici que l''arche de l''alliance du Seigneur de toute la terre va passer devant vous dans le Jourdain.'),
('jos',3,12,'crampon1923','Maintenant, prenez douze hommes parmi les tribus d''Israël, un homme par chaque tribu.'),
('jos',3,13,'crampon1923','Et dès que les prêtres qui portent l''arche de Yahweh, le Seigneur de toute la terre, poseront la plante des pieds dans les eaux du Jourdain, les eaux du Jourdain seront coupées, celles qui descendent d''en haut, et elles s''arrêteront en un monceau. »'),
('jos',3,14,'crampon1923','Quand le peuple fut sorti de ses tentes pour passer le Jourdain, les prêtres qui portaient l''arche de l''alliance marchèrent devant le peuple.'),
('jos',3,15,'crampon1923','Au moment où les porteurs de l''arche arrivèrent au Jourdain et où les pieds des prêtres qui portaient l''arche plongèrent au bord de l''eau, — car le Jourdain déborde par-dessus toutes ses rives tout le temps de la moisson, —'),
('jos',3,16,'crampon1923','alors les eaux qui descendent d''en haut s''arrêtèrent; elles s''élevèrent en un monceau, à une très grande distance, près de la ville d''Adom, qui est à côté de Sarthan; et celles qui descendent vers la mer de l''Arabah, la mer Salée, furent complètement coupées; et le peuple passa vis-à-vis de Jéricho.'),
('jos',3,17,'crampon1923','Les prêtres qui portaient l''arche de l''alliance de Yahweh se tinrent de pied ferme sur la terre sèche au milieu du Jourdain, pendant que tout Israël passait à sec, jusqu''à ce que toute la nation eut achevé de passer le Jourdain.'),
('jos',4,1,'crampon1923','Lorsque toute la nation eut achevé de passer le Jourdain, Yahweh dit à Josué:'),
('jos',4,2,'crampon1923','« Prenez douze hommes parmi le peuple, un homme par tribu,'),
('jos',4,3,'crampon1923','et donnez-leur cet ordre: De ce lieu-ci, du milieu du Jourdain, de l''endroit où les prêtres se sont tenus de pied ferme, prenez douze pierres, transportez-les avec vous et déposez-les dans le lieu où vous camperez cette nuit. »'),
('jos',4,4,'crampon1923','Josué appela les douze hommes qu''il avait choisis parmi les enfants d''Israël, un homme par tribu,'),
('jos',4,5,'crampon1923','et il leur dit: « Passez devant l''arche de Yahweh, votre Dieu, au milieu du Jourdain, et que chacun de vous prenne une pierre sur son épaule, selon le nombre des tribus des enfants d''Israël,'),
('jos',4,6,'crampon1923','afin que ce soit un signe au milieu de vous. Lorsque vos enfants vous demanderont un jour: Que signifient pour vous ces pierres?'),
('jos',4,7,'crampon1923','Vous leur direz: Les eaux du Jourdain ont été coupées devant l''arche de l''alliance de Yahweh; lorsqu''elle passa le Jourdain, les eaux du Jourdain furent coupées. Et ces pierres seront à jamais un mémorial pour les enfants d''Israël. »'),
('jos',4,8,'crampon1923','Les enfants d''Israël firent comme Josué avait ordonné. Ils prirent douze pierres du milieu du Jourdain, comme Yahweh l''avait dit à Josué, selon le nombre des tribus des enfants d''Israël, et, les ayant emportées avec eux au lieu où ils devaient passer la nuit, ils les y déposèrent.'),
('jos',4,9,'crampon1923','Josué dressa douze pierres au milieu du Jourdain, à la place où s''étaient arrêtés les pieds des prêtres qui portaient l''arche de l''alliance; et elles y sont restées jusqu''à ce jour.'),
('jos',4,10,'crampon1923','Les prêtres qui portaient l''arche se tinrent au milieu du Jourdain jusqu''à l''entier accomplissement de ce que Yahweh avait ordonné à Josué de dire au peuple, selon tout ce que Moïse avait prescrit à Josué; et le peuple se hâta de passer.'),
('jos',4,11,'crampon1923','Lorsque tout le peuple eut achevé de passer, l''arche de Yahweh et les prêtres passèrent devant le peuple.'),
('jos',4,12,'crampon1923','Les fils de Ruben, les fils de Gad et la demi-tribu de Manassé passèrent en armes devant les enfants d''Israël, comme Moïse le leur avait dit.'),
('jos',4,13,'crampon1923','Environ quarante mille hommes, armés pour le combat, passèrent devant Yahweh dans les plaines de Jéricho.'),
('jos',4,14,'crampon1923','En ce jour-là, Yahweh éleva Josué aux yeux de tout Israël, et ils le craignirent, comme ils avaient craint Moïse, tous les jours de sa vie.'),
('jos',4,15,'crampon1923','Yahweh parla à Josué en disant:'),
('jos',4,16,'crampon1923','« Ordonne aux prêtres qui portent l''arche du témoignage de sortir du Jourdain. »'),
('jos',4,17,'crampon1923','Et Josué donna cet ordre aux prêtres: « Sortez du Jourdain. »'),
('jos',4,18,'crampon1923','Lorsque les prêtres qui portaient l''arche de l''alliance de Yahweh furent sortis du milieu du Jourdain, et que la plante de leur pied se posa sur la terre sèche, les eaux du fleuve retournèrent à leur place et se répandirent comme auparavant par-dessus toutes ses rives.'),
('jos',4,19,'crampon1923','Le peuple sortit du Jourdain le dixième jour du premier mois, et il campa à Galgala à l''extrémité orientale du territoire de Jéricho.'),
('jos',4,20,'crampon1923','Josué dressa à Galgala les douze pierres qu''ils avaient prises du Jourdain,'),
('jos',4,21,'crampon1923','et il dit aux enfants d''Israël: « Lorsque vos enfants demanderont un jour à leurs pères: Que signifient ces pierres?'),
('jos',4,22,'crampon1923','Vous en instruirez vos enfants, en disant: Israël a passé ce Jourdain à sec.'),
('jos',4,23,'crampon1923','Car Yahweh, votre Dieu, a mis à sec devant vous les eaux du Jourdain jusqu''à ce que vous eussiez passé, comme Yahweh, votre Dieu, l''avait fait à la mer Rouge, qu''il mit à sec devant nous jusqu''à ce que nous eussions passé:'),
('jos',4,24,'crampon1923','afin que tous les peuples de la terre apprennent que la main de Yahweh est puissante, et afin que vous ayez toujours la crainte de Yahweh, votre Dieu. »'),
('jos',5,1,'crampon1923','Lorsque tous les rois des Amorrhéens d''au delà du Jourdain, à l''occident, et tous les rois des Chananéens près de la mer, apprirent que Yahweh avait mis à sec les eaux du Jourdain devant les enfants d''Israël, jusqu''à ce que nous eussions passé, leur cœur se fondit et ils perdirent tout courage devant les enfants d''Israël.'),
('jos',5,2,'crampon1923','Dans ce temps-là, Yahweh dit à Josué: « Fais-toi des couteaux de pierre et circoncis de nouveau les enfants d''Israël, une seconde fois. »'),
('jos',5,3,'crampon1923','Josué se fit des couteaux de pierre, et il circoncit les enfants d''Israël sur la colline d''Araloth.'),
('jos',5,4,'crampon1923','Voici la raison pour laquelle Josué les circoncit. Tout le peuple sorti d''Egypte, les mâles, tous les hommes de guerre, étaient morts dans le désert, pendant la route, après leur sortie d''Egypte.'),
('jos',5,5,'crampon1923','Car tout le peuple qui sortit était circoncis; mais tout le peuple né dans le désert, pendant la route, après la sortie d''Egypte, n''avait pas été circoncis.'),
('jos',5,6,'crampon1923','Car les enfants d''Israël marchèrent pendant quarante ans dans le désert jusqu''à ce qu''eût péri toute la nation, savoir les hommes de guerre qui étaient sortis d''Egypte et n''avaient pas écouté la voix de Yahweh, et auxquels Yahweh avait juré de ne pas leur laisser voir le pays qu''il avait promis avec serment à leurs pères de nous donner, pays où coulent le lait et le miel.'),
('jos',5,7,'crampon1923','Il établit leurs enfants à leur place, et ce sont eux que Josué circoncit, car ils étaient incirconcis parce qu''on ne les avait pas circoncis pendant la route.'),
('jos',5,8,'crampon1923','Lorsqu''on eut achevé de circoncire toute la nation, ils restèrent à leur place dans le camp, jusqu''à leur guérison.'),
('jos',5,9,'crampon1923','Et Yahweh dit à Josué: « Aujourd''hui j''ai roulé de dessus vous l''opprobre de l''Egypte. » Et ce lieu reçut le nom de Galgala jusqu''à ce jour.'),
('jos',5,10,'crampon1923','Les enfants d''Israël campèrent à Galgala, et ils firent la Pâque le quatorzième jour du mois, sur le soir, dans les plaines de Jéricho.'),
('jos',5,11,'crampon1923','Ils mangèrent dès le lendemain de la Pâque, du produit du pays des pains sans levain et du grain rôti, ce jour-là même.'),
('jos',5,12,'crampon1923','Et la manne cessa le lendemain de la Pâque, lorsqu''ils mangèrent du produit du pays; les enfants d''Israël n''eurent plus de manne, et ils mangèrent cette année-là des productions du pays de Chanaan.'),
('jos',5,13,'crampon1923','Comme Josué était près de Jéricho, il leva les yeux et regarda, et voici qu''un homme se tenait debout devant lui, son épée nue à la main. Josué alla vers lui et lui dit: « Es-tu pour nous, ou pour nos ennemis? »'),
('jos',5,14,'crampon1923','Il répondit: « Non, mais c''est comme chef de l''armée de Yahweh que je viens maintenant. » Josué tomba le visage contre terre, se prosterna et lui dit: « Qu''est-ce que mon seigneur dit à son serviteur? »'),
('jos',5,15,'crampon1923','Et le chef de l''armée de Yahweh dit à Josué: « Ôte ta chaussure de tes pieds, car le lieu sur lequel tu te tiens est saint. » Et Josué fit ainsi.'),
('jos',6,1,'crampon1923','Jéricho était fermée et entièrement close, à cause des enfants d''Israël; personne n''en sortait, et personne n''y entrait.'),
('jos',6,2,'crampon1923','Yahweh dit à Josué: « Vois, j''ai livré entre tes mains Jéricho et son roi, ainsi que ses vaillants hommes.'),
('jos',6,3,'crampon1923','Marchez autour de la ville, vous tous, les hommes de guerre, faites une fois le tour de la ville; tu feras ainsi pendant six jours.'),
('jos',6,4,'crampon1923','Sept prêtres porteront devant l''arche sept trompettes retentissantes; et le septième jour, vous ferez sept fois le tour de la ville, et les prêtres sonneront des trompettes.'),
('jos',6,5,'crampon1923','Quand ils sonneront de la corne retentissante, et que vous entendrez le son de la trompette, tout le peuple poussera une grande clameur, et le mur de la ville s''écroulera; alors le peuple montera, chacun devant soi. »'),
('jos',6,6,'crampon1923','Josué, fils de Nun, ayant appelé les prêtres, leur dit: « Portez l''arche de l''alliance, et que sept prêtres portent sept trompettes retentissantes devant l''arche de Yahweh. »'),
('jos',6,7,'crampon1923','Il dit au peuple: « Passez, marchez autour de la ville, et que les hommes armés passent devant l''arche de Yahweh. »'),
('jos',6,8,'crampon1923','Lorsque Josué eut parlé au peuple, les sept prêtres qui portaient les sept trompettes retentissantes devant Yahweh, passèrent et sonnèrent des trompettes, et l''arche de l''alliance de Yahweh s''avançait derrière eux.'),
('jos',6,9,'crampon1923','Les hommes armés marchaient devant les prêtres qui sonnaient des trompettes, et l''arrière-garde suivait l''arche; pendant la marche, on sonnait des trompettes.'),
('jos',6,10,'crampon1923','Josué avait donné cet ordre au peuple: « Vous ne crierez point, vous ne ferez point entendre votre voix, et il ne sortira pas une parole de votre bouche, jusqu''au jour où je vous dirai: Criez! Alors vous pousserez des cris! »'),
('jos',6,11,'crampon1923','L''arche de Yahweh s''avança autour de la ville, et en fit une fois le tour; puis on rentra dans le camp, où l''on passa la nuit.'),
('jos',6,12,'crampon1923','Josué se leva le lendemain, et les prêtres portaient l''arche de Yahweh.'),
('jos',6,13,'crampon1923','Les sept prêtres qui portaient les sept trompettes retentissantes devant l''arche de Yahweh se mirent en marche et sonnèrent des trompettes. Les hommes armés marchaient devant eux, et l''arrière-garde suivait l''arche de Yahweh; pendant la marche, on sonnait des trompettes.'),
('jos',6,14,'crampon1923','Ils marchèrent, le second jour, une fois autour de la ville, et revinrent dans le camp. Ils firent de même pendant six jours.'),
('jos',6,15,'crampon1923','Le septième jour, ils se levèrent, comme montait l''aurore, et ils marchèrent de la même manière sept fois autour de la ville; ce jour-là seul ils marchèrent sept fois autour de la ville.'),
('jos',6,16,'crampon1923','A la septième fois, comme les prêtres sonnaient des trompettes, Josué dit au peuple: « Poussez des cris, car Yahweh vous a livré la ville.'),
('jos',6,17,'crampon1923','La ville sera dévouée par anathème à Yahweh, elle et tout ce qui s''y trouve; seule Rahab, la courtisane, vivra, elle et tous ceux qui seront avec elle dans la maison, parce qu''elle a caché les messagers que nous avions envoyés.'),
('jos',6,18,'crampon1923','Mais gardez-vous de ce qui est dévoué par anathème, de peur que, en prenant quelque chose de ce que vous avez dévoué par anathème, vous ne rendiez le camp d''Israël anathème, et vous n''y mettiez le trouble.'),
('jos',6,19,'crampon1923','Tout l''argent et tout l''or, tous les objets d''airain et de fer seront consacrés à Yahweh et entreront dans le trésor de Yahweh. »'),
('jos',6,20,'crampon1923','Le peuple poussa des cris, et les prêtres sonnèrent des trompettes. Et lorsque le peuple entendit le son de la trompette, il poussa une grande clameur, et la muraille s''écroula, et le peuple monta dans la ville, chacun devant soi. S''étant emparés de la ville,'),
('jos',6,21,'crampon1923','ils livrèrent à l''anathème tout ce qui se trouvait dans la ville, hommes et femmes, enfants et vieillards, même les bœufs, les brebis et les ânes, par le tranchant de l''épée.'),
('jos',6,22,'crampon1923','Josué dit aux deux hommes qui avaient exploré le pays: « Entrez dans la maison de la courtisane, et faites-en sortir cette femme avec tous ceux qui lui appartiennent, comme vous le lui avez juré. »'),
('jos',6,23,'crampon1923','Les jeunes gens, les espions, entrèrent et firent sortir Rahab, son père, sa mère, ses frères et tous ceux qui lui appartenaient; ils firent sortir tous les gens de sa famille, et ils les mirent hors du camp d''Israël.'),
('jos',6,24,'crampon1923','Les enfants d''Israël brûlèrent la ville et tout ce qui s''y trouvait, sauf l''argent et l''or, et les objets d''airain et de fer, qu''ils déposèrent dans le trésor de la maison de Yahweh.'),
('jos',6,25,'crampon1923','Josué laissa la vie à Rahab, la courtisane, à la maison de son père, et à tous ceux qui lui appartenaient; et elle a habité au milieu d''Israël jusqu''à ce jour, parce qu''elle avait caché les messagers envoyés par Josué pour explorer Jéricho.'),
('jos',6,26,'crampon1923','En ce temps-là Josué jura, en disant: « Maudit soit devant Yahweh l''homme qui se lèvera et rebâtira cette ville de Jéricho! Au prix de son premier-né il en posera les fondements; au prix de son plus jeune fils il en relèvera les portes. »'),
('jos',6,27,'crampon1923','Yahweh fut avec Josué, et sa renommée se répandit dans tout le pays.'),
('jos',7,1,'crampon1923','Les enfants d''Israël commirent une infidélité au sujet de l''anathème. Achan, fils de Charmi, fils de Zabdi, fils de Zaré, de la tribu de Juda, prit des choses dévouées, et la colère de Yahweh s''enflamma contre les enfants d''Israël.'),
('jos',7,2,'crampon1923','Josué envoya de Jéricho des hommes vers Haï, qui est près de Beth-Aven, à l''orient de Béthel; il leur dit: « Montez et explorez le pays. » Ces hommes montèrent et explorèrent Haï.'),
('jos',7,3,'crampon1923','Revenus auprès de Josué, ils lui dirent: « Que le peuple ne monte pas tout entier! Deux mille hommes ou trois mille hommes n''ont qu''à monter et ils battront Haï; ne fatigue pas tout le peuple pour cette ville, car ses habitants sont peu nombreux. »'),
('jos',7,4,'crampon1923','Environ trois mille hommes du peuple y montèrent, mais ils prirent la fuite devant les hommes d''Haï.'),
('jos',7,5,'crampon1923','Les gens d''Haï leur tuèrent environ trente-six hommes; ils les poursuivirent depuis la porte jusqu''à Sabarim, et les battirent à la descente. Et le cœur du peuple se fondit et il perdit tout courage.'),
('jos',7,6,'crampon1923','Josué déchira ses vêtements et se prosterna, le visage contre terre, devant l''arche de Yahweh, jusqu''au soir, lui et les anciens d''Israël, et ils jetèrent de la poussière sur leur tête.'),
('jos',7,7,'crampon1923','Josué dit: « Ah! Seigneur Yahweh, pourquoi avez-vous fait passer le Jourdain à ce peuple, pour nous livrer entre les mains des Amorrhéens, afin de nous faire périr? Que n''avons-nous su rester de l''autre côté du Jourdain!'),
('jos',7,8,'crampon1923','De grâce, Seigneur, que dirai-je, après qu''Israël a tourné le dos devant ses ennemis?'),
('jos',7,9,'crampon1923','Les Chananéens et tous les habitants du pays l''apprendront; ils nous envelopperont et feront disparaître notre nom de la terre. Et que ferez-vous pour votre grand nom? »'),
('jos',7,10,'crampon1923','Yahweh dit à Josué: « Lève-toi! Pourquoi es-tu ainsi tombé sur ta face?'),
('jos',7,11,'crampon1923','Israël a péché, jusqu''à transgresser mon alliance que je leur ai prescrite d''observer, jusqu''à prendre des choses vouées par l''anathème, à les dérober, à mentir et à les cacher dans leurs bagages!'),
('jos',7,12,'crampon1923','Aussi les enfants d''Israël ne peuvent tenir devant leurs ennemis; mais ils tournent le dos devant leurs ennemis, car ils sont devenus anathème. Je ne serai plus avec vous désormais, si vous n''ôtez pas l''anathème du milieu de vous.'),
('jos',7,13,'crampon1923','Lève-toi, sanctifie le peuple et dis-leur: Sanctifiez-vous pour demain; car ainsi parle Yahweh, le Dieu d''Israël: Il y a un anathème au milieu de toi, Israël; tu ne pourras point tenir devant tes ennemis, jusqu''à ce que vous ayez ôté l''anathème du milieu de vous.'),
('jos',7,14,'crampon1923','Vous vous approcherez le matin selon vos tribus, et la tribu que Yahweh aura saisie s''approchera par familles, et la famille que Yahweh aura saisie s''approchera par maisons, et la maison que Yahweh aura saisie s''approchera par têtes.'),
('jos',7,15,'crampon1923','Celui qui sera saisi comme atteint par l''anathème sera consumé par le feu, lui et tout ce qui lui appartient, parce qu''il transgresse l''alliance de Yahweh et commet une infamie en Israël. »'),
('jos',7,16,'crampon1923','Le lendemain, Josué se leva de bon matin et fit approcher Israël selon ses tribus, et la tribu de Juda fut saisie.'),
('jos',7,17,'crampon1923','Il fit approcher les familles de Juda, et la famille de Zaré fut saisie. Il fit approcher la famille de Zaré par maisons, et Zabdi fut saisi.'),
('jos',7,18,'crampon1923','Il fit approcher la maison de Zabdi par têtes, et Achan, fils de Charmi, fils de Zabdi, fils de Zaré, de la tribu de Juda, fut saisi.'),
('jos',7,19,'crampon1923','Josué dit à Achan: « Mon fils, donne gloire, je te prie, à Yahweh, le Dieu d''Israël, et rends-lui hommage. Avoue-moi ce que tu as fait, ne me le cache point. »'),
('jos',7,20,'crampon1923','Achan répondit à Josué et dit: « C''est la vérité; c''est moi qui ai péché contre Yahweh, le Dieu d''Israël; voici ce que j''ai fait:'),
('jos',7,21,'crampon1923','J''ai vu parmi les dépouilles un beau manteau de Sennaar, deux cents sicles d''argent, et un lingot d''or du poids de cinquante sicles; je les ai convoités et je les ai pris; ils sont cachés dans la terre au milieu de ma tente, et l''argent est dessous. »')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('jos',7,22,'crampon1923','Josué envoya des messagers qui coururent à la tente, et voici, les objets étaient cachés dans la tente d''Achan, et l''argent était dessous.'),
('jos',7,23,'crampon1923','Les ayant pris du milieu de la tente, ils les apportèrent à Josué et à tous les enfants d''Israël, et les déposèrent devant Yahweh.'),
('jos',7,24,'crampon1923','Josué et tout Israël avec lui prirent Achan, fils de Zaré, l''argent, le manteau, le lingot d''or, les fils et les filles d''Achan, ses bœufs, ses ânes, ses brebis, sa tente et tout ce qui lui appartenait, et il les firent monter dans la vallée d''Achor.'),
('jos',7,25,'crampon1923','Là Josué dit: « Pourquoi nous as-tu troublés? Yahweh te troublera aujourd''hui. » Et tout Israël le lapida. On les consuma par le feu, et on les lapida.'),
('jos',7,26,'crampon1923','Et on éleva sur Achan un grand monceau de pierres, qui subsiste encore aujourd''hui. Et Yahweh revint de l''ardeur de sa colère. — A cause de cet événement, on a appelé ce lieu vallée d''Achor jusqu''à ce jour.'),
('jos',8,1,'crampon1923','Yahweh dit à Josué: « Ne crains point et ne t''effraie point. Prends avec toi tous les hommes de guerre, lève-toi et monte contre Haï. Vois, j''ai livré entre tes mains le roi d''Haï et son peuple, sa ville et son territoire.'),
('jos',8,2,'crampon1923','Tu traiteras Haï et son roi comme tu as traité Jéricho et son roi; seulement vous pillerez pour vous son butin et son bétail. Dresse une embuscade derrière la ville. »'),
('jos',8,3,'crampon1923','Josué se leva avec tous les gens de guerre, pour monter contre Haï. Josué choisit trente mille hommes vaillants, et les fit partir de nuit.'),
('jos',8,4,'crampon1923','Il leur donna cet ordre: « Soyez sur vos gardez: vous vous mettrez en embuscade derrière la ville, mais sans vous éloigner beaucoup de la ville, et tous, tenez-vous prêts.'),
('jos',8,5,'crampon1923','Moi, et tout le peuple qui est avec moi, nous nous approcherons de la ville; et quand ils sortiront au-devant de nous, comme la première fois, nous fuirons devant eux.'),
('jos',8,6,'crampon1923','Ils sortiront pour nous poursuivre, jusqu''à ce que nous les ayons attirés loin de la ville, car ils diront: Ils fuient devant nous, comme la première fois. Et nous fuirons devant eux.'),
('jos',8,7,'crampon1923','Alors, sortant de l''embuscade, vous vous emparerez de la ville; Yahweh, votre Dieu, la livrera entre vos mains.'),
('jos',8,8,'crampon1923','Quand vous aurez pris la ville, vous la brûlerez; vous agirez selon la parole de Yahweh. Voyez: je vous ai donné mes ordres. »'),
('jos',8,9,'crampon1923','Josué les fit partir, et ils allèrent se poster en embuscade entre Béthel et Haï, à l''occident d''Haï. Quant à Josué, il passa cette nuit-là au milieu du peuple.'),
('jos',8,10,'crampon1923','Josué se leva de bon matin et, ayant passé le peuple en revue, il monta à la tête du peuple, lui et les anciens d''Israël, contre Haï.'),
('jos',8,11,'crampon1923','Tous les hommes de guerre qui étaient avec lui montèrent et s''approchèrent; arrivés en face d''Haï, ils campèrent au nord de la ville, ayant la vallée entre eux et Haï.'),
('jos',8,12,'crampon1923','Josué prit environ cinq mille hommes, et les mit en embuscade entre Béthel et Haï, à l''occident de la ville.'),
('jos',8,13,'crampon1923','Lorsque le peuple eut ainsi disposé tout le camp, qui était au nord de la ville, et son embuscade à l''occident de la ville, Josué s''avança durant cette nuit au milieu de la vallée.'),
('jos',8,14,'crampon1923','Dès que le roi de Haï vit cela, les hommes de la ville se levèrent en hâte de bon matin, et sortirent à la rencontre d''Israël pour le combattre; le roi s''avança avec tout son peuple vers le lieu convenu, en face de la plaine, ne sachant pas qu''il y avait derrière la ville une embuscade dressée contre lui.'),
('jos',8,15,'crampon1923','Josué et tout Israël se laissèrent battre devant eux, et ils s''enfuirent par le chemin du désert.'),
('jos',8,16,'crampon1923','Alors tout le peuple qui était dans la ville se rassembla pour les poursuivre; ils poursuivirent Josué et se laissèrent attirer loin de la ville.'),
('jos',8,17,'crampon1923','Il ne resta pas un homme dans Haï et dans Béthel qui ne sortit pour poursuivre Israël; laissant la ville ouverte, ils poursuivirent Israël.'),
('jos',8,18,'crampon1923','Yahweh dit à Josué: « Etends vers Haï le javelot que tu as à la main, car je vais la livrer en ton pouvoir. » Et Josué étendit vers la ville le javelot qu''il avait à la main.'),
('jos',8,19,'crampon1923','Dès qu''il eut étendu sa main, les hommes de l''embuscade se levèrent en hâte du lieu où ils étaient et, prenant leur course, ils entrèrent dans la ville et l''occupèrent; et ils se hâtèrent de mettre le feu à la ville.'),
('jos',8,20,'crampon1923','Les hommes d''Haï, regardant derrière eux, aperçurent la fumée de la ville qui montait vers le ciel, et ils ne purent plus se sauver d''aucun côté, le peuple qui fuyait vers le désert se retournant contre ceux qui le poursuivaient.'),
('jos',8,21,'crampon1923','Et Josué et tout Israël, voyant la ville prise par les hommes de l''embuscade, et la fumée de la ville qui montait, se retournèrent et battirent les hommes d''Haï.'),
('jos',8,22,'crampon1923','Les autres sortirent de la ville au-devant d''eux, et les hommes d''Haï se trouvèrent enveloppés par les Israélites, par les uns d''un côté, par les autres de l''autre côté. Et les Israélites les battirent, sans leur laisser ni un survivant ni un fugitif;'),
('jos',8,23,'crampon1923','ils prirent vivant le roi d''Haï et l''amenèrent à Josué.'),
('jos',8,24,'crampon1923','Lorsqu''Israël eut achevé de tuer tous les habitants d''Haï dans la campagne, dans le désert, où ils l''avaient poursuivi, et que tous furent jusqu''au dernier passés au fil de l''épée, tout Israël revint dans la ville et la passa au fil de l''épée.'),
('jos',8,25,'crampon1923','Le nombre total de ceux qui périrent en ce jour fut de douze mille, tant hommes que femmes, tous gens d''Haï.'),
('jos',8,26,'crampon1923','Josué ne retira pas sa main qu''il tenait étendue avec le javelot, jusqu''à ce qu''il eût traité comme anathème tous les habitants d''Haï.'),
('jos',8,27,'crampon1923','Les Israélites prirent seulement pour eux le bétail et le butin de cette ville, selon l''ordre de Yahweh qu''il avait prescrit à Josué.'),
('jos',8,28,'crampon1923','Josué brûla Haï, et en fit pour toujours un monceau de ruines, qui subsiste encore aujourd''hui.'),
('jos',8,29,'crampon1923','Il fit pendre à un arbre le roi d''Haï et l''y laissa jusqu''au soir. Au coucher du soleil, Josué donna l''ordre de descendre son cadavre de l''arbre; on le jeta à l''entrée de la porte de la ville, et on éleva sur lui un grand monceau de pierres, qui subsiste jusqu''à ce jour.'),
('jos',8,30,'crampon1923','Alors Josué bâtit un autel à Yahweh, Dieu d''Israël, sur le mont Hébal,'),
('jos',8,31,'crampon1923','selon l''ordre que Moïse, serviteur de Yahweh, avait donné aux enfants d''Israël, comme il est écrit dans le livre de la loi de Moïse, un autel de pierres brutes, sur lesquelles on n''avait pas brandi le fer. Ils y offrirent des holocaustes à Yahweh, et firent des sacrifices pacifiques.'),
('jos',8,32,'crampon1923','Là Josué écrivit sur les pierres une copie de la loi que Moïse avait écrite en présence des enfants d''Israël.'),
('jos',8,33,'crampon1923','Tout Israël, ses anciens, ses officiers et ses juges, se tenaient des deux côtés de l''arche, devant les prêtres lévitiques, qui portaient l''arche de l''alliance de Yahweh, les étrangers aussi bien que les enfants d''Israël, une moitié du côté du mont Garizim, une moitié du côté du mont Hébal, selon l''ordre que Moïse, serviteur de Yahweh, avait donné auparavant de bénir le peuple d''Israël.'),
('jos',8,34,'crampon1923','Puis Josué lut toutes les paroles de la loi, la bénédiction et la malédiction, suivant tout ce qui est écrit dans le livre de la loi.'),
('jos',8,35,'crampon1923','Pas un mot de tout ce que Moïse avait prescrit que n''ait lu Josué en présence de toute l''assemblée d''Israël, des femmes et des enfants, et des étrangers qui vivaient au milieu d''eux.'),
('jos',9,1,'crampon1923','A la nouvelle de ces événements, tous les rois qui étaient au delà du Jourdain, dans la montagne et dans le bas pays, et sur toute la côte de la grande mer, vis-à-vis du Liban, les Héthéens, les Amorrhéens, les Chananéens, les Phérézéens, les Hévéens et les Jébuséens'),
('jos',9,2,'crampon1923','s''unirent ensemble pour combattre Josué et Israël d''un commun accord.'),
('jos',9,3,'crampon1923','Les habitants de Gabaon, lorsqu''ils apprirent comment Josué avait traité Jéricho et Haï,'),
('jos',9,4,'crampon1923','eurent, de leur côté, recours à la ruse. Ils se mirent en route, avec des provisions de voyage. Ils avaient pris de vieux sacs sur leurs ânes et de vieilles outres à vin déchirées et recousues;'),
('jos',9,5,'crampon1923','ils avaient à leurs pieds de vieilles sandales rapiécées, et sur eux de vieux vêtements; tout le pain qu''ils portaient pour leur nourriture était desséché et en miettes.'),
('jos',9,6,'crampon1923','Ils allèrent auprès de Josué, au camp de Galgala, et ils lui dirent, à lui et à tous les hommes d''Israël: « Nous venons d''un pays éloigné, et maintenant faites alliance avec nous. »'),
('jos',9,7,'crampon1923','Les hommes d''Israël répondirent à ces Hévéens: « Peut-être que vous habitez au milieu de nous; comment pourrions-nous faire alliance avec vous? »'),
('jos',9,8,'crampon1923','Il dirent à Josué: « Nous sommes tes serviteurs. » Josué leur dit: « Qui êtes-vous et d''où venez-vous? »'),
('jos',9,9,'crampon1923','Ils lui dirent: « Tes serviteurs viennent d''un pays très éloigné, à cause du nom de Yahweh, ton Dieu; car nous avons entendu parler de lui, de tout ce qu''il a fait en Egypte,'),
('jos',9,10,'crampon1923','et comment il a traité les deux rois des Amorrhéens au delà du Jourdain, Séhon, roi de Hésebon, et Og, roi de Basan, qui habitait à Astaroth.'),
('jos',9,11,'crampon1923','Et nos anciens et tous les habitants de notre pays nous ont dit: Prenez avec vous des provisions pour le voyage, allez au-devant d''eux et dites-leur: Nous sommes vos serviteurs, et maintenant faites alliance avec nous.'),
('jos',9,12,'crampon1923','Voici notre pain: il était chaud quand nous en avons fait provision dans nos maisons, le jour où nous sommes partis pour venir vers vous, et maintenant le voilà desséché et en miettes.'),
('jos',9,13,'crampon1923','Ces outres à vin, que nous avons remplies toutes neuves, les voilà déchirées; nos vêtements et nos sandales se sont usés par la grande longueur du voyage. »'),
('jos',9,14,'crampon1923','Les hommes d''Israël prirent de leurs provisions, sans consulter la bouche de Yahweh;'),
('jos',9,15,'crampon1923','et Josué leur accorda la paix et conclut avec eux une alliance portant qu''on leur laisserait la vie; et les princes de l''assemblée le leur jurèrent.'),
('jos',9,16,'crampon1923','Trois jours après la conclusion de l''alliance, les enfants d''Israël apprirent qu''ils étaient leurs voisins et qu''ils habitaient au milieu d''eux.'),
('jos',9,17,'crampon1923','Les enfants d''Israël partirent donc, et arrivèrent à leurs villes le troisième jour; leurs villes étaient Gabaon, Caphira, Béroth et Cariathiarim.'),
('jos',9,18,'crampon1923','Ils ne les frappèrent point de l''épée, à cause du serment que les princes de l''assemblée leur avaient fait au nom de Yahweh, le Dieu d''Israël; mais toute l''assemblée murmura contre les princes.'),
('jos',9,19,'crampon1923','Tous les princes dirent alors à toute l''assemblée: « Nous leur avons fait un serment par Yahweh, le Dieu d''Israël; et maintenant, nous ne pouvons les toucher.'),
('jos',9,20,'crampon1923','Voici comment nous les traiterons: nous leur laisserons la vie, pour ne pas attirer sur nous la colère de Yahweh, par suite du serment que nous leur avons fait.'),
('jos',9,21,'crampon1923','Qu''ils vivent donc, » leur disent les princes. Ils furent employés à couper le bois et à puiser l''eau pour toute l''assemblée, comme les princes le leur avaient dit.'),
('jos',9,22,'crampon1923','Josué fit appeler les Gabaonites et leur parla ainsi: « Pourquoi nous avez-vous trompés, en disant: Nous sommes très éloignés de vous, tandis que vous habitez au milieu de nous?'),
('jos',9,23,'crampon1923','Maintenant, vous êtes maudits et personne de vous ne manquera d''être esclave, coupant le bois et puisant l''eau pour la maison de mon Dieu. »'),
('jos',9,24,'crampon1923','Ils répondirent à Josué en disant: « C''est qu''on avait rapporté à tes serviteurs l''ordre donné par Yahweh ton Dieu, à Moïse, son serviteur, de vous livrer tout le pays et d''exterminer tous les habitants du pays devant vous. Et nous avons éprouvé à votre approche une grande crainte pour nos vies; c''est pourquoi nous avons agi de cette manière.'),
('jos',9,25,'crampon1923','Maintenant nous voici entre tes mains; traite-nous comme il te semblera bon et juste de nous traiter. »'),
('jos',9,26,'crampon1923','Josué agit à leur égard ainsi qu''il l''avait dit; il les délivra de la main des enfants d''Israël, pour qu''ils ne les fissent pas mourir.'),
('jos',9,27,'crampon1923','Josué les destina dès ce jour à couper le bois et à puiser l''eau pour l''assemblée et pour l''autel de Yahweh, dans le lieu que Yahweh choisirait: ce qu''ils font encore aujourd''hui.'),
('jos',10,1,'crampon1923','Adonisédec, roi de Jérusalem, apprit que Josué s''était emparé d''Haï et l''avait dévouée par anathème, qu''il avait traité Haï et son roi comme il avait traité Jéricho et son roi, et que les habitants de Gabaon, ayant fait la paix avec Israël, étaient au milieu d''eux.'),
('jos',10,2,'crampon1923','Il eut alors une grande crainte; car Gabaon était une grande ville, comme une des villes royales, plus grande même qu''Haï, et tous ses hommes étaient vaillants.'),
('jos',10,3,'crampon1923','Adonisédec, roi de Jérusalem, envoya dire à Oham, roi d''Hébron, à Pharam, roi de Jérimoth, à Japhia, roi de Lachis, et à Dabir, roi d''Eglon:'),
('jos',10,4,'crampon1923','« Montez vers moi et venez à mon aide, afin que nous frappions Gabaon, car elle a fait la paix avec Josué et avec les enfants d''Israël. »'),
('jos',10,5,'crampon1923','Ainsi cinq rois des Amorrhéens, le roi de Jérusalem, le roi d''Hébron, le roi de Jérimoth, le roi de Lachis et le roi d''Eglon, se rassemblèrent et montèrent avec toutes leurs armées; ils établirent leur camp près de Gabaon et l''assiégèrent.'),
('jos',10,6,'crampon1923','Les gens de Gabaon envoyèrent dire à Josué, au camp de Galgala: « Ne refuse pas ta main à tes serviteurs, hâte-toi de monter vers nous, délivre-nous, donne-nous du secours; car tous les rois des Amorrhéens qui habitent la montagne se sont ligués contre nous. »'),
('jos',10,7,'crampon1923','Josué monta de Galgala, lui et tous les gens de guerre avec lui, et tous les vaillants guerriers.'),
('jos',10,8,'crampon1923','Yahweh dit à Josué: « Ne les crains point, car je les ai livrés entre tes mains, et pas un d''eux ne tiendra devant toi. »'),
('jos',10,9,'crampon1923','Josué vint sur eux subitement; il avait monté de Galgala toute la nuit.'),
('jos',10,10,'crampon1923','Et Yahweh jeta sur eux le trouble devant Israël; Israël leur infligea une grande défaite près de Gabaon, les poursuivit sur le chemin qui monte à Béthoron, et les battit jusqu''à Azéca et Macéda.'),
('jos',10,11,'crampon1923','Comme ils fuyaient devant Israël, à la descente de Béthoron, Yahweh fit tomber du ciel sur eux de grosses pierres jusqu''à Azéca, et ils moururent; ceux qui moururent par les pierres de grêle furent plus nombreux que ceux qui furent tués par l''épée des enfants d''Israël.'),
('jos',10,12,'crampon1923','Alors Josué parla à Yahweh, le jour où Yahweh livra les Amorrhéens aux enfants d''Israël, et il dit à la vue d''Israël: Soleil, arrête-toi sur Gabaon, et toi, lune, sur la vallée d''Ajalon!'),
('jos',10,13,'crampon1923','Et le soleil s''arrêta, et la lune se tint immobile, jusqu''à ce que la nation se fut vengée de ses ennemis. Cela n''est-il pas écrit dans le livre du Juste? Et le soleil s''arrêta au milieu du ciel, et ne se hâta point de se coucher, presque un jour entier.'),
('jos',10,14,'crampon1923','Il n''y eut pas, ni avant ni après, de jour comme celui-là, où Yahweh obéit à la voix d''un homme; car Yahweh combattait pour Israël.'),
('jos',10,15,'crampon1923','Et Josué, et tout Israël avec lui, retourna au camp à Galgala.'),
('jos',10,16,'crampon1923','Les cinq rois s''enfuirent et se cachèrent dans la caverne, à Macéda.'),
('jos',10,17,'crampon1923','On le rapporta à Josué, en disant: « Les cinq rois ont été trouvés cachés dans la caverne à Macéda. »'),
('jos',10,18,'crampon1923','Josué dit: « Roulez de grosses pierres à l''entrée de la caverne, et mettez-y des hommes pour les garder.'),
('jos',10,19,'crampon1923','Et vous, ne vous arrêtez pas; poursuivez vos ennemis et frappez-les en queue; ne les laissez pas entrer dans leurs villes, car Yahweh, votre Dieu, les a livrés entre vos mains. »'),
('jos',10,20,'crampon1923','Lorsque Josué et les enfants d''Israël eurent achevé de leur infliger une très grande défaite jusqu''à les exterminer, ceux qui purent s''échapper s''étant réfugiés dans les villes fortifiées,'),
('jos',10,21,'crampon1923','tout le peuple revint tranquillement au camp, vers Josué, à Macéda, sans que personne remuât la langue contre les enfants d''Israël.'),
('jos',10,22,'crampon1923','Josué dit: « Ouvrez l''entrée de la caverne, faites sortir, pour me les amener, ces cinq rois de la caverne. »'),
('jos',10,23,'crampon1923','Ils firent ainsi, et lui amenèrent les cinq rois, qu''ils avaient fait sortir de la caverne, le roi de Jérusalem, le roi d''Hébron, le roi de Jérimoth, le roi de Lachis et le roi d''Eglon.'),
('jos',10,24,'crampon1923','Lorsqu''ils eurent fait sortir ces rois devant Josué, Josué appela tous les hommes d''Israël et dit aux chefs des gens de guerre qui l''avaient accompagné: « Approchez-vous, mettez vos pieds sur le cou de ces rois. » Ils s''approchèrent et mirent leurs pieds sur leurs cous.'),
('jos',10,25,'crampon1923','Et Josué leur dit: « Ne craignez point et ne vous effrayez point, soyez fermes et courageux, car c''est ainsi que Yahweh traitera tous vos ennemis contre lesquels vous combattez. »'),
('jos',10,26,'crampon1923','Après cela Josué les frappa de l''épée et les fit mourir; il les pendit à cinq arbres, et ils y restèrent pendus jusqu''au soir.'),
('jos',10,27,'crampon1923','Vers le coucher du soleil, Josué les fit descendre des arbres; on les jeta dans la caverne où ils s''étaient cachés, et l''on mit à l''entrée de la caverne de grosses pierres, qui y sont restées jusqu''à ce jour même.'),
('jos',10,28,'crampon1923','Le même jour, Josué s''empara de Macéda et la frappa, elle et son roi, du tranchant de l''épée; il dévoua par anathème la ville et tous les êtres vivants qui s''y trouvaient, sans laisser échapper personne, et il traita le roi de Macéda comme il avait traité le roi de Jéricho.'),
('jos',10,29,'crampon1923','Josué, et tout Israël avec lui, passa de Macéda à Lebna, et il attaqua Lebna.'),
('jos',10,30,'crampon1923','Yahweh la livra aussi, avec son roi, entre les mains d''Israël, et il la frappa du tranchant de l''épée, elle et tous les êtres vivants qui s''y trouvaient, sans en laisser échapper aucun, et il traita son roi comme il avait traité le roi de Jéricho.'),
('jos',10,31,'crampon1923','Josué, et tout Israël avec lui, passa de Lebna à Lachis; il établit son camp devant elle et l''attaqua.'),
('jos',10,32,'crampon1923','Et Yahweh livra Lachis entre les mains d''Israël, qui la prit le second jour, et la frappa du tranchant de l''épée, elle et tous les êtres vivants qui s''y trouvaient, comme il avait fait pour Lebna. —'),
('jos',10,33,'crampon1923','Alors Horam, roi de Gaser, monta pour secourir Lachis; Josué le battit, lui et son peuple, sans laisser échapper personne.'),
('jos',10,34,'crampon1923','Josué, et tout Israël avec lui, passa de Lachis à Eglon; ils établirent leur camp devant elle et l''attaquèrent.'),
('jos',10,35,'crampon1923','Ils la prirent le même jour, et la frappèrent du tranchant de l''épée; tous les êtres vivants qui s''y trouvaient, Josué les dévoua par anathème ce jour-là, selon tout ce qu''il avait fait pour Lachis.'),
('jos',10,36,'crampon1923','Josué, et tout Israël avec lui, monta d''Eglon à Hébron, et ils l''attaquèrent.'),
('jos',10,37,'crampon1923','L''ayant prise, ils la frappèrent du tranchant de l''épée, elle, son roi, toutes les villes de sa dépendance et tous les êtres vivants qui s''y trouvaient, sans laisser échapper personne, comme Josué avait fait pour Eglon; et il la dévoua par anathème, avec tous les êtres vivants qui s''y trouvaient.'),
('jos',10,38,'crampon1923','Josué, et tout Israël avec lui, se tourna vers Dabir, et il l''attaqua.'),
('jos',10,39,'crampon1923','Il la prit, elle, son roi et toutes les villes de sa dépendance; et ils les frappèrent du tranchant de l''épée, et ils dévouèrent par anathème tous les êtres vivants qui s''y trouvaient, sans laisser échapper personne. Josué traita Dabir et son roi comme il avait traité Hébron, et comme il avait traité Lebna et son roi.'),
('jos',10,40,'crampon1923','Josué frappa tout le pays: la Montagne, le Négéb, le bas pays et les coteaux, avec tous leurs rois, sans laisser échapper personne, dévouant par anathème tout ce qui avait vie, comme l''avait ordonné Yahweh, le Dieu d''Israël.'),
('jos',10,41,'crampon1923','Josué les battit de Cadès-Barné à Gaza, et tout le pays de Gosen jusqu''à Gabaon.'),
('jos',10,42,'crampon1923','Josué prit tous ces rois et tout leur pays dans une seule expédition, car Yahweh, le Dieu d''Israël, combattait pour Israël.'),
('jos',10,43,'crampon1923','Puis Josué, et tout Israël avec lui, retourna au camp, à Galgala.'),
('jos',11,1,'crampon1923','Jabin, roi d''Asor, ayant appris ces choses, envoya un message à Jobab, roi de Madon, au roi de Séméron, au roi d''Achsaph,'),
('jos',11,2,'crampon1923','aux rois qui étaient au nord dans la montagne et dans l''Arabah, au sud du Cénéreth, dans le bas pays et sur les hauteurs de Dor à l''occident,'),
('jos',11,3,'crampon1923','aux Chananéens de l''orient et de l''occident, aux Amorrhéens, aux Héthéens, aux Phérézéens, aux Jébuséens dans la montagne, et aux Hévéens du pied de l''Hermon dans le pays de Maspha.'),
('jos',11,4,'crampon1923','Ils sortirent, eux et toutes leurs armées avec eux, peuple innombrable comme le sable qui est sur le bord de la mer, avec une grande multitude de chevaux et de chars.'),
('jos',11,5,'crampon1923','Tous ces rois se rassemblèrent et vinrent camper ensemble près des eaux de Mérom, pour combattre Israël.'),
('jos',11,6,'crampon1923','Yahweh dit à Josué: « Ne les crains point, car demain, à cette heure-ci, je les livrerai tous transpercés devant Israël. Tu couperas les jarrets à leurs chevaux et tu livreras au feu leurs chars. »'),
('jos',11,7,'crampon1923','Josué, et tous les hommes de guerre avec lui, arrivèrent à eux à l''improviste, près des eaux de Mérom, et ils se précipitèrent sur eux.'),
('jos',11,8,'crampon1923','Yahweh les livra entre les mains d''Israël, qui les battit et les poursuivit jusqu''à Sidon la grande, jusqu''aux eaux de Maséréphoth et jusqu''à la vallée de Maspha vers l''orient; il les battit, sans en laisser échapper un seul.'),
('jos',11,9,'crampon1923','Josué les traita comme Yahweh le lui avait dit: il coupa les jarrets à leurs chevaux et il livra au feu leurs chars.'),
('jos',11,10,'crampon1923','En ce même temps, Josué revint et prit Asor, et il frappa son roi de l''épée; car Asor était autrefois la capitale de tous ces royaumes.'),
('jos',11,11,'crampon1923','Les enfants d''Israël frappèrent du tranchant de l''épée tous les êtres vivants qui s''y trouvaient, en les dévouant par anathème; il ne resta rien de ce qui avait vie, et l''on brûla Asor.'),
('jos',11,12,'crampon1923','Josué prit toutes les villes de ces rois et tous leurs rois, et il les frappa du tranchant de l''épée, les dévouant par anathème, comme l''avait ordonné Moïse, serviteur de Yahweh.'),
('jos',11,13,'crampon1923','Mais Israël ne brûla aucune des villes situées sur les collines, à l''exception seulement d''Asor, que brûla Josué.'),
('jos',11,14,'crampon1923','Et tout le butin de ces villes, et leur bétail, les enfants d''Israël le pillèrent pour eux; mais ils frappèrent tous les hommes du tranchant de l''épée, jusqu''à ce qu''ils les eussent détruits, sans rien laisser de ce qui avait vie.'),
('jos',11,15,'crampon1923','Ce que Yahweh avait ordonné à Moïse, son serviteur, Moïse l''avait ordonné à Josué, et Josué l''exécuta; il ne négligea rien de ce que Yahweh avait ordonné à Moïse.'),
('jos',11,16,'crampon1923','C''est ainsi que Josué s''empara de tout ce pays, de la Montagne, de tout le Négéb, de tout le district de Gosen, du bas pays, de l''Arabah, de la montagne d''Israël et de ses plaines,'),
('jos',11,17,'crampon1923','depuis la montagne nue qui s''élève vers Séïr jusqu''à Baal-Gad, dans la vallée du Liban, au pied du mont Hermon; il prit tous leurs rois, les frappa et les mit à mort.'),
('jos',11,18,'crampon1923','Pendant de longs jours Josué fit la guerre contre tous ces rois.'),
('jos',11,19,'crampon1923','Il n''y eut aucune ville qui fit la paix avec les enfants d''Israël, excepté les Hévéens qui habitaient à Gabaon; ils les prirent toutes par la force des armes.'),
('jos',11,20,'crampon1923','Car c''était le dessein de Yahweh que ces peuples endurcissent leur cœur pour faire la guerre à Israël, afin qu''Israël les dévouât par anathème, sans qu''il y eût pour eux de miséricorde, et qu''il les détruisit, comme Yahweh l''avait ordonné à Moïse.'),
('jos',11,21,'crampon1923','Dans le même temps, Josué se mit en marche et il extermina les Enacim de la Montagne, d''Hébron, de Dabir et d''Anab, de toute la montagne de Juda et de toute la montagne d''Israël; Josué les dévoua par anathème avec leurs villes.'),
('jos',11,22,'crampon1923','Il ne resta plus d''Enacim dans le pays des enfants d''Israël; il n''en resta qu''à Gaza, à Geth et à Azoth.'),
('jos',11,23,'crampon1923','Josué s''empara de tout le pays, selon tout ce que Yahweh avait dit à Moïse; et Josué le donna en héritage à Israël, par portions, selon leurs tribus. Et le pays se reposa de la guerre.'),
('jos',12,1,'crampon1923','Voici les rois du pays que les enfants d''Israël battirent et dont ils occupèrent le pays de l''autre côté du Jourdain, vers le soleil levant, depuis le torrent d''Arnon jusqu''au mont Hermon, et toute l''Arabah à l''orient du fleuve:'),
('jos',12,2,'crampon1923','Séhon, roi des Amorrhéens, résidant à Hésebon. Sa domination s''étendait depuis Aroër, qui est sur le bord du torrent d''Arnon, et, à partir du milieu de la vallée, sur la moitié de Galaad, jusqu''au torrent de Jacob, frontière des enfants d''Ammon;'),
('jos',12,3,'crampon1923','sur l''Arabah, jusqu''à la mer de Cénéreth à l''orient, et sur la mer de l''Arabah, la mer Salée, à l''orient, vers Bethsimoth; et du côté du midi au pied des pentes du mont Phasga.'),
('jos',12,4,'crampon1923','Puis le territoire d''Og, roi de Basan, d''entre les restes des Rephaïm, résidant à Astaroth et à Edraï.'),
('jos',12,5,'crampon1923','Sa domination s''étendait sur la montagne d''Hermon, sur Salécha, sur tout Basan jusqu''à la frontière des Gesuriens et des Machatiens, et jusqu''à la moitié de Galaad, territoire de Séhon, roi d''Hésébon.'),
('jos',12,6,'crampon1923','Moïse, serviteur de Yahweh, et les enfants d''Israël les battirent; et Moïse, serviteur de Yahweh, donna leur pays en propriété aux Rubénites, aux Gadites et à la moitié de la tribu de Manassé.'),
('jos',12,7,'crampon1923','Voici les rois que Josué et les enfants d''Israël battirent de ce côté du Jourdain, à l''occident, depuis Baal-Gad, dans la vallée du Liban, jusqu''à la montagne nue qui s''élève vers Séïr. Josué donna ce pays en propriété aux tribus d''Israël selon leurs familles,'),
('jos',12,8,'crampon1923','dans la montagne, dans le bas pays, sur les coteaux, dans le désert et dans le Négeb: pays des Héthéens, des Amorrhéens, des Chananéens, des Phérézéens, des Hévéens et des Jébuséens.'),
('jos',12,9,'crampon1923','Ce sont: le roi de Jéricho, un; le roi d''Haï, près de Béthel, un;'),
('jos',12,10,'crampon1923','le roi de Jérusalem, un; le roi d''Hébron, un;'),
('jos',12,11,'crampon1923','le roi de Jérimoth, un; le roi de Lachis, un;'),
('jos',12,12,'crampon1923','le roi d''Eglon, un; le roi de Gazer, un;'),
('jos',12,13,'crampon1923','le roi de Dabir, un; le roi de Gader, un;'),
('jos',12,14,'crampon1923','le roi de Herma, un; le roi d''Héred, un;'),
('jos',12,15,'crampon1923','le roi de Lebna, un; le roi d''Odollam, un;'),
('jos',12,16,'crampon1923','le roi de Macéda, un; le roi de Béthel, un;'),
('jos',12,17,'crampon1923','le roi de Taphna, un; le roi d''Opher, un;'),
('jos',12,18,'crampon1923','le roi d''Aphec, un; le roi de Lasaron, un;'),
('jos',12,19,'crampon1923','le roi de Madon, un; le roi d''Asor, un;'),
('jos',12,20,'crampon1923','le roi de Séméron, un; le roi d''Achsaph, un;'),
('jos',12,21,'crampon1923','le roi de Thanac, un; le roi de Mageddo, un;'),
('jos',12,22,'crampon1923','le roi de Cadès, un; le roi de Jachanan, au Carmel, un;'),
('jos',12,23,'crampon1923','le roi de Dor, sur les hauteurs de Dor, un; le roi de Gojim, à Galgal, un;'),
('jos',12,24,'crampon1923','le roi de Thersa, un. En tout, trente et un rois.'),
('jos',13,1,'crampon1923','Josué était vieux, avancé en âge; Yahweh lui dit: « Tu es devenu vieux, tu es avancé en âge, et il reste encore un très grand pays à conquérir.'),
('jos',13,2,'crampon1923','Voici le pays qui reste: tous les districts des Philistins et tout le territoire des Gessuriens,'),
('jos',13,3,'crampon1923','depuis le Schichor qui coule à l''orient de l''Egypte, jusqu''à la frontière d''Accaron vers le nord, contrée qui doit être réputée Chananéenne; les cinq princes des Philistins, celui de Gaza, celui d''Azoth, celui d''Ascalon, celui de Geth et celui d''Accaron; les Hévéens'),
('jos',13,4,'crampon1923','au midi; tout le pays des Chananéens, et Maara qui est aux Sidoniens, jusqu''à Aphec, jusqu''à la frontière des Amorrhéens;'),
('jos',13,5,'crampon1923','le pays des Gébalites, et tout le Liban vers le soleil levant, depuis Baal-Gad au pied du mont Hermon jusqu''à l''entrée de Hamath;'),
('jos',13,6,'crampon1923','tous les habitants de la montagne, depuis le Liban jusqu''aux eaux de Maséréphoth, savoir tous les Sidoniens: je les chasserai de devant les enfants d''Israël. Seulement partage par le sort ces pays en héritage à Israël, comme je l''ai commandé.'),
('jos',13,7,'crampon1923','Et maintenant répartis ce pays en héritage aux neuf tribus et à la demi-tribu de Manassé. »'),
('jos',13,8,'crampon1923','Avec l''autre moitié, les Rubénites et les Gadites ont reçu leur héritage, que Moïse leur a donné de l''autre côté du Jourdain, à l''orient, comme le leur a donné Moïse, serviteur de Yahweh:'),
('jos',13,9,'crampon1923','depuis Aroër sur le bord du torrent de l''Arnon, et depuis la ville qui est au milieu de la vallée, toute la plaine de Médaba jusqu''à Dibon;'),
('jos',13,10,'crampon1923','toutes les villes de Séhon, roi des Amorrhéens, qui régnait à Hésebon, jusqu''à la frontière des enfants d''Ammon;'),
('jos',13,11,'crampon1923','Galaad, le territoire des Gessuriens et des Machatiens, toute la montagne d''Hermon, et tout Basan, jusqu''à Salécha:'),
('jos',13,12,'crampon1923','tout le royaume d''Og en Basan, qui régnait à Astaroth et à Edraï: c''était le dernier reste des Rephaïm. Moïse battit ces rois et les chassa.'),
('jos',13,13,'crampon1923','Mais les enfants d''Israël ne chassèrent point les Gessuriens et les Machatiens, et Gessur et Machat habitent au milieu d''Israël jusqu''à ce jour.'),
('jos',13,14,'crampon1923','La tribu de Lévi fut la seule à laquelle Moïse ne donna pas d''héritage; les sacrifices faits par le feu devant Yahweh, le Dieu d''Israël, sont son héritage, comme il le lui avait dit.'),
('jos',13,15,'crampon1923','Moïse avait donné à la tribu des fils de Ruben une part selon leurs familles.'),
('jos',13,16,'crampon1923','Ils eurent pour territoire, à partir d''Aroër sur le bord du torrent de l''Arnon, et de la ville située au milieu de la vallée, toute la plaine près de Médaba,'),
('jos',13,17,'crampon1923','Hésebon et toutes ses villes dans la plaine, Dibon, Bamoth-Baal, Beth-Baal-Maon,'),
('jos',13,18,'crampon1923','Jassa, Cédimoth, Méphaath,'),
('jos',13,19,'crampon1923','Cariathaïm, Sabama, Sarath-Asar dans la montagne de la vallée,'),
('jos',13,20,'crampon1923','Beth-Phogor, les pentes du Phasga, Beth-Jésimoth,'),
('jos',13,21,'crampon1923','toutes les autres villes de la plaine et tout le royaume de Séhon, roi des Amorrhéens, qui régnait à Hésebon: Moïse l''avait battu, lui et les princes de Madian, Evi, Récem, Sur, Hur et Rébé, tributaires de Séhon, qui habitaient le pays.'),
('jos',13,22,'crampon1923','Le devin Balaam, fils de Béor, fut aussi du nombre de ceux que les enfants d''Israël firent périr par l''épée.'),
('jos',13,23,'crampon1923','Ainsi le territoire des fils de Ruben atteignait jusqu''au Jourdain et à son territoire. Tel fut l''héritage — les villes et leurs villages — des fils de Ruben, et leurs familles.'),
('jos',13,24,'crampon1923','Moïse donna à la tribu de Gad, aux fils de Gad, une part selon leurs familles.'),
('jos',13,25,'crampon1923','Ils eurent pour territoire: Jaser, toutes les villes de Galaad, la moitié du pays des enfants d''Ammon, jusqu''à Aroër, qui est vis-à-vis de Rabba,'),
('jos',13,26,'crampon1923','depuis Hésebon jusqu''à Raboth-Masphé et Bétonim, et depuis Manaïm jusqu''à la frontière de Dabir;'),
('jos',13,27,'crampon1923','et, dans la vallée, Beth-Haram, Beth-Nemra, Socoth et Saphon, reste du royaume de Séhon, roi d''Hésebon; le Jourdain et son territoire, jusqu''à l''extrémité de la mer de Cénéreth, de l''autre côté du Jourdain, à l''orient.'),
('jos',13,28,'crampon1923','Tel fut l''héritage — les villes et leurs villages — des fils de Gad, selon leurs familles.'),
('jos',13,29,'crampon1923','Moïse donna à la demi-tribu de Manassé, aux fils de Manassé, une part selon leurs familles.'),
('jos',13,30,'crampon1923','Ils eurent pour territoire, à partir de Manaïm, tout Basan, tout le royaume d''Og, roi de Basan, et tous les bourgs de Jaïr en Basan, soixante villes.'),
('jos',13,31,'crampon1923','La moitié de Galaad, Astaroth et Edraï, villes du royaume d''Og en Basan, furent données aux fils de Machir, fils de Manassé, à la moitié des fils de Machir, selon leurs familles.'),
('jos',13,32,'crampon1923','Telles sont les parts que distribua Moïse, lorsqu''il était dans les plaines de Moab, de l''autre côté du Jourdain, en face de Jéricho, à l''orient.'),
('jos',13,33,'crampon1923','Mais Moïse ne donna pas d''héritage à la tribu de Lévi; Yahweh, le Dieu d''Israël, est son héritage, comme il le lui a dit.'),
('jos',14,1,'crampon1923','Voici ce que les enfants d''Israël reçurent en héritage dans le pays de Chanaan, ce que leur partagèrent le prêtre Eléazar, Josué, fils de Nun, et les chefs de famille des tribus des enfants d''Israël.'),
('jos',14,2,'crampon1923','C''est le sort qui leur assigna leur héritage, comme Yahweh l''avait ordonné par Moïse, pour les neuf tribus et la demi-tribu.'),
('jos',14,3,'crampon1923','Car Moïse avait donné l''héritage des deux tribus et de la demi-tribu de l''autre côté du Jourdain; mais il n''avait pas donné aux Lévites d''héritage parmi eux.'),
('jos',14,4,'crampon1923','Car les fils de Joseph formaient deux tribus, Manassé et Ephraïm; et l''on ne donna pas aux Lévites de part dans le pays, si ce n''est des villes pour habitation et leurs banlieues pour leurs troupeaux et pour leurs biens.'),
('jos',14,5,'crampon1923','Les enfants d''Israël accomplirent l''ordre que Yahweh avait donné à Moïse, et ils partagèrent le pays.'),
('jos',14,6,'crampon1923','Les fils de Juda s''approchèrent de Josué, à Galgala, et Caleb, fils de Jéphoné, le Cénézéen, lui dit: « Tu sais ce que Yahweh a dit à Moïse, homme de Dieu, à mon sujet et à ton sujet, à Cadès-Barné.'),
('jos',14,7,'crampon1923','J''étais âgé de quarante ans lorsque Moïse, serviteur de Yahweh, m''envoya de Cadès-Barné pour explorer le pays, et je lui fis un rapport dans la sincérité de mon cœur.'),
('jos',14,8,'crampon1923','Tandis que mes frères, qui étaient montés avec moi, découragèrent le peuple, moi, je suivis entièrement Yahweh, mon Dieu.'),
('jos',14,9,'crampon1923','Et ce jour-là Moïse fit ce serment: Le pays que ton pied a foulé sera ton héritage et celui de tes enfants à perpétuité, parce que tu as entièrement suivi Yahweh, mon Dieu.'),
('jos',14,10,'crampon1923','Et maintenant, voici que Yahweh m''a conservé en vie, comme il l''a dit, pendant les quarante-cinq ans écoulés depuis que Yahweh adressa cette parole à Moïse, tandis qu''Israël marchait dans le désert; et maintenant, voici que je suis âgé aujourd''hui de quatre-vingt-cinq ans.'),
('jos',14,11,'crampon1923','Je suis encore aujourd''hui aussi robuste qu''au jour où Moïse m''envoya; ma force de maintenant est la même que celle d''alors, soit pour combattre, soit pour sortir et pour entrer.'),
('jos',14,12,'crampon1923','Donne-moi donc cette montagne, dont Yahweh a parlé en ce jour-là; car tu as toi-même entendu ce jour-là que là se trouvent des Enacim et des villes grandes et fortifiées; peut-être Yahweh sera-t-il avec moi, et réussirai-je à les chasser, selon qu''a parlé Yahweh. »'),
('jos',14,13,'crampon1923','Josué bénit Caleb, fils de Jéphoné, et il lui donna Hébron en héritage.'),
('jos',14,14,'crampon1923','C''est pourquoi Hébron appartient en héritage à Caleb, fils de Jéphoné, le Cénézéen, jusqu''à ce jour, parce qu''il avait entièrement suivi Yahweh, le Dieu d''Israël.'),
('jos',14,15,'crampon1923','Hébron s''appelait autrefois Cariath-Arbé; Arbé était l''homme le plus grand parmi les Enacim. Et le pays se reposa de la guerre.'),
('jos',15,1,'crampon1923','La part échue par le sort à la tribu des enfants de Juda, selon leurs familles, s''étendait vers la frontière d''Edom, jusqu''au désert de Sin vers le midi, à l''extrémité méridionale de Chanaan.'),
('jos',15,2,'crampon1923','Leur frontière du midi partait de l''extrémité de la mer Salée, de la langue tournée vers le sud;'),
('jos',15,3,'crampon1923','elle se prolongeait au midi de la montée d''Akrabbim, passait à Sin et montait au midi de Cadès-Barné; de là, elle passait à Esron, montait vers Addar et tournait à Carcaa;'),
('jos',15,4,'crampon1923','elle passait ensuite à Asmon et continuait jusqu''au torrent d''Egypte; et la frontière aboutissait à la mer. « Ce sera votre frontière au midi. »'),
('jos',15,5,'crampon1923','La frontière orientale fut la mer Salée jusqu''à l''embouchure du Jourdain. La frontière septentrionale partait de la langue de la mer Salée qui est à l''embouchure du Jourdain.'),
('jos',15,6,'crampon1923','La frontière montait vers Beth-Agla, passait au nord de Beth-Araba, et la frontière montait jusqu''à la pierre de Boën, fils de Ruben;'),
('jos',15,7,'crampon1923','et la frontière montait à Débéra à partir de la vallée d''Achor, et tournait vers le nord du côté de Galgala, qui est vis-à-vis de la montagne d''Adommim, au sud du torrent. Et la frontière passait près des eaux d''En-Sémès et aboutissait à En-Rogel.'),
('jos',15,8,'crampon1923','Et la frontière montait par la vallée de Ben-Ennom, jusqu''au versant méridional de la montagne des Jébuséens, qui est Jérusalem; et la frontière s''élevait ensuite jusqu''au sommet de la montagne qui est vis-à-vis de la vallée d''Ennom à l''occident, et à l''extrémité de la plaine des Rephaïm au nord.'),
('jos',15,9,'crampon1923','Du sommet de la montagne, la frontière s''étendait jusqu''à la source des eaux de Nephtoa, aboutissait vers les villes de la montagne d''Ephron; et la frontière s''étendait vers Baala, qui est Cariath-Jéarim.'),
('jos',15,10,'crampon1923','De Baala, la frontière tournait à l''occident vers le mont Séïr, passait par le versant septentrional du mont Jarim, qui est Cheslon, descendait à Bethsamès et passait par Thamma.'),
('jos',15,11,'crampon1923','La frontière aboutissait au versant septentrional d''Accaron; et la frontière s''étendait vers Sécrona, passait par le mont Baala, et aboutissait à Jebnéel; et la frontière aboutissait à la mer.'),
('jos',15,12,'crampon1923','La limite occidentale était la Grande mer et son territoire. Telles furent de tous côtés les frontières des fils de Juda, selon leurs familles.'),
('jos',15,13,'crampon1923','On avait donné à Caleb, fils de Jéphoné, une part au milieu des fils de Juda, comme Yahweh l''avait ordonné à Josué, savoir la ville d''Arbé, père d''Enac: c''est Hébron,'),
('jos',15,14,'crampon1923','Caleb en chassa les trois fils d''Enac, Sésaï, Ahiman et Tholmaï, descendants d''Enac.'),
('jos',15,15,'crampon1923','De là il monta contre les habitants de Dabir, qui s''appelait autrefois Cariath-Sépher.'),
('jos',15,16,'crampon1923','Caleb dit: « A celui qui battra Cariath-Sépher et qui la prendra, je donnerai pour femme ma fille Axa. »'),
('jos',15,17,'crampon1923','Othoniel, fils de Cénez, frère de Caleb, s''en empara, et Caleb lui donna sa fille Axa pour femme.'),
('jos',15,18,'crampon1923','Lorsqu''elle alla chez Othoniel, elle l''excita à demander à son père un champ. Elle descendit de dessus son âne, et Caleb lui dit: « Qu''as-tu? »'),
('jos',15,19,'crampon1923','Elle répondit: « Fais-moi un présent, car tu m''as établie dans le pays sec; donne-moi aussi des sources d''eau. » Et il lui donna les sources supérieures et les sources inférieures.'),
('jos',15,20,'crampon1923','Tel fut l''héritage de la tribu des fils de Juda, selon leurs familles.'),
('jos',15,21,'crampon1923','Les villes situées à l''extrémité de la tribu des enfants de Juda, vers la frontière d''Edom, dans le Négeb, étaient: Cabséel, Eder, Jagur,'),
('jos',15,22,'crampon1923','Cina, Dimona, Adada,'),
('jos',15,23,'crampon1923','Cadès, Asor et Jethnam;'),
('jos',15,24,'crampon1923','Ziph, Télem, Baloth,'),
('jos',15,25,'crampon1923','Asor-la-Neuve et Carioth-Hesron, qui est Asor;'),
('jos',15,26,'crampon1923','Amam, Sama, Molada,'),
('jos',15,27,'crampon1923','Asergadda, Hassemon, Bethphélet,'),
('jos',15,28,'crampon1923','Hasersual, Bersabée et Baziothia;'),
('jos',15,29,'crampon1923','Baala, Jim, Esem,'),
('jos',15,30,'crampon1923','Eltholad, Césil, Harma,'),
('jos',15,31,'crampon1923','Siceleg, Médémena, Sensenna,'),
('jos',15,32,'crampon1923','Lebaoth, Sélim, Aen et Rémon: en tout vingt neuf villes et leurs villages.'),
('jos',15,33,'crampon1923','Dans la Séphéla: Estaol, Saréa, Asena,'),
('jos',15,34,'crampon1923','Zanoé, Aen-Gannim, Taphua, Enaïm,'),
('jos',15,35,'crampon1923','Jérimoth, Odollam, Socho, Azéca,'),
('jos',15,36,'crampon1923','Saraïm, Adithaïm, Gédéra et Gédérothaïm: quatorze villes et leurs villages.'),
('jos',15,37,'crampon1923','Sanan, Hadassa, Magdal-Gad,'),
('jos',15,38,'crampon1923','Déléan, Masépha, Jecthel,'),
('jos',15,39,'crampon1923','Lachis, Bascath, Eglon,'),
('jos',15,40,'crampon1923','Chebbon, Léhéman, Cethlis,'),
('jos',15,41,'crampon1923','Gideroth, Beth-Dagon, Naama et Macéda: seize ville et leurs villages.'),
('jos',15,42,'crampon1923','Labana, Ether, Asan,'),
('jos',15,43,'crampon1923','Jephtha, Esna, Nésib,'),
('jos',15,44,'crampon1923','Céïla, Achzib et Marésa: neuf villes et leurs villages.'),
('jos',15,45,'crampon1923','Accaron, avec les villes de sa dépendance et ses villages.'),
('jos',15,46,'crampon1923','A partir d''Accaron, du côté de l''occident, toutes les villes près d''Azoth et leurs villages;'),
('jos',15,47,'crampon1923','Azoth, les villes de sa dépendance et ses villages; Gaza, les villes de sa dépendance et ses villages, jusqu''au torrent d''Egypte et à la Grande mer, qui est la limite.'),
('jos',15,48,'crampon1923','Dans la montagne: Samir, Jéther, Socoth,'),
('jos',15,49,'crampon1923','Danna, Cariath-Senna, qui est Dabir,'),
('jos',15,50,'crampon1923','Anab, Istémo, Anim,'),
('jos',15,51,'crampon1923','Gosen, Olon et Gilo: onze villes et leurs villages.'),
('jos',15,52,'crampon1923','Arab, Duma, Esaan,'),
('jos',15,53,'crampon1923','Janum, Beth-Thaphua, Aphéca,'),
('jos',15,54,'crampon1923','Athmatha, Cariath-Arbé, qui est Hébron, et Sior: neuf villes et leurs villages.'),
('jos',15,55,'crampon1923','Maon, Carmel, Ziph, Jota,'),
('jos',15,56,'crampon1923','Jezraël, Jucadam, Zanoé,'),
('jos',15,57,'crampon1923','Accaïn, Gabaa, Thamma: dix villes et leurs villages.'),
('jos',15,58,'crampon1923','Halhul, Bessur, Gédor,'),
('jos',15,59,'crampon1923','Mareth, Beth-Anoth et Eltécon: six villes, et leurs villages.'),
('jos',15,60,'crampon1923','Cariath-Baal, qui est Cariath-Jéarim, et Arebba: deux villes et leurs villages.'),
('jos',15,61,'crampon1923','Dans le désert: Beth-Araba, Meddin, Sachacha,'),
('jos',15,62,'crampon1923','Nebsan, Ir-Hammélach et En-Gaddi: six villes et leurs villages.'),
('jos',15,63,'crampon1923','Les fils de Juda ne purent pas chasser les Jébuséens qui habitent à Jérusalem, et les Jébuséens ont habité à Jérusalem avec les fils de Juda jusqu''à ce jour.'),
('jos',16,1,'crampon1923','La part échue par le sort aux fils de Joseph commençait, du côté de l''orient, depuis le Jourdain de Jéricho, jusqu''aux eaux de Jéricho; c''était ensuite le désert qui monte de Jéricho à Béthel par la montagne.'),
('jos',16,2,'crampon1923','La frontière aboutissait de Béthel à Luz, et passait vers la frontière des Archéens à Ataroth.'),
('jos',16,3,'crampon1923','De là, elle descendait à l''occident, vers la frontière des Jephlétiens jusqu''à la frontière de Béthoron le Bas et jusqu''à Gazer, et elle aboutissait à la mer.'),
('jos',16,4,'crampon1923','Tel est l''héritage que reçurent les fils de Joseph, Manassé et Ephraïm.'),
('jos',16,5,'crampon1923','Voici la frontière des fils d''Ephraïm, selon leurs familles. La limite de leur héritage était, à l''orient, Ataroth-Addar jusqu''à Béthoron le Haut.'),
('jos',16,6,'crampon1923','La frontière aboutissait, du côté de l''occident, vers Machméthath, au nord; et la frontière tournait à l''orient, vers Thanath-Sélo et passait devant elle, vers l''orient de Janoé.'),
('jos',16,7,'crampon1923','De Janoé, elle descendait à Ataroth et à Naaratha, touchait à Jéricho et aboutissait au Jourdain.'),
('jos',16,8,'crampon1923','De Taphuah, elle allait, du côté de l''occident, au torrent de Cana, pour aboutir à la mer. Tel fut l''héritage des fils d''Ephraïm selon leurs familles.'),
('jos',16,9,'crampon1923','Les fils d''Ephraïm eurent aussi des villes séparées au milieu de l''héritage des fils de Manassé, toutes avec leurs villages.'),
('jos',16,10,'crampon1923','Ils ne chassèrent pas les Chananéens qui habitaient à Gazer, et les Chananéens ont habité jusqu''à ce jour au milieu d''Ephraïm, mais assujettis à la corvée.'),
('jos',17,1,'crampon1923','Il y eut encore une part échue par le sort pour la tribu de Manassé, car il était le premier-né de Joseph. Machir, premier-né de Manassé et père de Galaad, avait reçu Galaad et Basan, car il était homme de guerre.'),
('jos',17,2,'crampon1923','Un lot fut aussi assigné aux autres fils de Manassé, selon leurs familles, aux fils d''Abiézer, aux fils de Hélec, aux fils d''Esriel, aux fils de Séchem, aux fils de Hépher et aux fils de Sémida; ce sont là les enfants mâles de Manassé, fils de Joseph, selon leurs familles.'),
('jos',17,3,'crampon1923','Salphaad, fils de Hépher, fils de Galaad, fils de Machir, fils de Manassé, n''eut pas de fils, mais il eut des filles, et voici les noms de ses filles: Maala, Noa, Hégla, Melcha et Thersa.'),
('jos',17,4,'crampon1923','Elles se présentèrent devant Eléazar, le prêtre, devant Josué, fils de Nun, et devant les princes, en disant: « Yahweh a commandé à Moïse de nous donner un héritage parmi nos frères. » Et on leur donna, selon l''ordre de Yahweh, un héritage au milieu des frères de leur père.'),
('jos',17,5,'crampon1923','Il échut dix portions à Manassé, outre le pays de Galaad et de Basan, qui est de l''autre côté du Jourdain.'),
('jos',17,6,'crampon1923','Car les filles de Manassé reçurent un héritage au milieu de ses fils: le pays de Galaad fut pour les autres fils de Manassé.'),
('jos',17,7,'crampon1923','La limite de Manassé partait d''Aser vers Machméthath, qui est en face de Sichem, et la frontière allait à droite, vers les habitants d''En-Taphua.'),
('jos',17,8,'crampon1923','Le territoire de Taphua échut à Manassé, mais Taphua sur la frontière de Manassé, était aux fils d''Ephraïm.'),
('jos',17,9,'crampon1923','La limite descendait au torrent de Cana, au midi du torrent; les villes de cette région, échues à Ephraïm, étaient au milieu des villes de Manassé; et la limite de Manassé était au nord du torrent et aboutissait à la mer.'),
('jos',17,10,'crampon1923','Ainsi le pays au midi était à Ephraïm, et le pays au nord à Manassé, et la mer formait sa frontière. Vers le nord, ils touchaient à Aser, vers l''orient à Issachar.'),
('jos',17,11,'crampon1923','Manassé obtint dans les territoires d''Issachar et d''Aser Bethsan et les villes de sa dépendance, Jéblaam et les villes de sa dépendance, les habitants de Dor et les villes de sa dépendance, les habitants d''Endor et les villes de sa dépendance, les habitants de Thénac et les villes de sa dépendance, les habitants de Mageddo et les villes de sa dépendance: c''est le district des trois Collines.'),
('jos',17,12,'crampon1923','Les fils de Manassé ne purent pas prendre possession de ces villes, et les Chananéens s''enhardirent à rester dans ce pays.'),
('jos',17,13,'crampon1923','Lorsque les enfants d''Israël furent plus forts, ils soumirent les Chananéens à un tribut, mais ils ne les chassèrent pas.'),
('jos',17,14,'crampon1923','Les fils de Joseph parlèrent à Josué, en disant: « Pourquoi ne m''as-tu donné en héritage qu''un seul lot, une seule part alors que je suis un peuple nombreux et que Yahweh a béni jusqu''à présent? »'),
('jos',17,15,'crampon1923','Josué leur dit: « Si tu es un peuple nombreux, monte à la forêt, et là défriche-toi une place dans le pays des Phérézéens et des Rephaïm, puisque la montagne d''Ephraïm est trop étroite pour toi. »'),
('jos',17,16,'crampon1923','Les fils de Joseph dirent: « La montagne ne nous suffit pas, et il y a des chariots de fer chez tous les Chananéens qui habitent le pays plat, chez ceux qui sont à Bethsan et dans les villes de sa dépendance, et chez ceux qui sont dans la vallée de Jezraël. »'),
('jos',17,17,'crampon1923','Josué répondit à la maison de Joseph, Ephraïm et Manassé: « Tu es un peuple nombreux, et ta force est grande; tu n''auras pas seulement un lot.'),
('jos',17,18,'crampon1923','Car la montagne t''appartiendra; c''est une forêt, tu la défricheras, et les issues en seront à toi; car tu chasseras les Chananéens, quoiqu''ils aient des chars de fer et qu''ils soient forts. »'),
('jos',18,1,'crampon1923','Toute l''assemblée des enfants d''Israël se réunit à Silo, et ils y dressèrent la tente de réunion; le pays était soumis devant eux.'),
('jos',18,2,'crampon1923','Il restait sept tribus d''entre les enfants d''Israël qui n''avaient pas encore reçu leur héritage.'),
('jos',18,3,'crampon1923','Josué dit aux enfants d''Israël: « Jusques à quand négligerez-vous de prendre possession du pays que Yahweh, le Dieu de vos pères, vous a donné?'),
('jos',18,4,'crampon1923','Choisissez trois hommes par tribu, et je les enverrai; ils se lèveront, parcourront le pays, le décriront en vue du partage et reviendront vers moi.'),
('jos',18,5,'crampon1923','Ils le diviseront en sept portions; Juda restera dans ses frontières au midi, et la maison de Joseph restera dans ses frontières au nord.'),
('jos',18,6,'crampon1923','Vous donc, vous dresserez l''état du pays, en en faisant sept parts, et vous me l''apporterez ici; puis je jetterai pour vous le sort ici devant Yahweh, notre Dieu.'),
('jos',18,7,'crampon1923','Car il n''y aura point de part pour les Lévites au milieu de vous, le sacerdoce de Yahweh étant leur héritage; et Gad, Ruben, et la demi-tribu de Manassé ont reçu de l''autre côté du Jourdain, à l''orient, leur héritage, que leur a donné Moïse, serviteur de Yahweh. »'),
('jos',18,8,'crampon1923','Ces hommes s''étant levés se mirent en route, et Josué leur donna ses ordres à leur départ pour dresser l''état du pays, en disant: « Allez, parcourez le pays, décrivez-le et revenez auprès de moi; alors je jetterai pour vous le sort ici, devant Yahweh, à Silo. »'),
('jos',18,9,'crampon1923','Ces hommes partirent et, parcourant le pays, ils le décrivirent dans un livre selon les villes, en le partageant en sept portions; et ils revinrent auprès de Josué, dans le camp, à Silo.'),
('jos',18,10,'crampon1923','Josué jeta pour eux le sort à Silo, en présence de Yahweh, et là Josué partagea le pays aux enfants d''Israël, selon leurs portions.'),
('jos',18,11,'crampon1923','Le sort tomba sur la tribu des fils de Benjamin, selon ses familles, et le territoire qui leur échut par le sort, était entre les fils de Juda et les fils de Joseph.'),
('jos',18,12,'crampon1923','Du côté du nord, leur frontière partait du Jourdain; et la frontière montait au nord sur le versant de Jéricho, puis montait dans la montagne à l''occident, et aboutissait au désert de Bethaven.'),
('jos',18,13,'crampon1923','De là, la frontière passait à Luz, sur le versant de Luz, au midi, c''est Béthel; puis la frontière descendait à Ataroth-Addar, par la montagne qui est au midi de Béthoron le Bas.'),
('jos',18,14,'crampon1923','Et la frontière s''étendait et tournait, du côté de l''occident, vers le midi, depuis la montagne située en face de Béthoron au sud, et aboutissait à Cariath-Baal, qui est Cariath-Jéarim, ville des fils de Juda: voilà pour le côté de l''occident.'),
('jos',18,15,'crampon1923','Pour le côté du midi, la frontière partait de l''extrémité de Cariath-Jéarim, et aboutissait à l''occident, elle aboutissait à la source des eaux de Nephtoa.'),
('jos',18,16,'crampon1923','Et la frontière descendait à l''extrémité de la montagne qui fait face à la vallée du fils d''Ennom, située dans la plaine des Rephaïm, au nord; puis elle descendait, par la vallée d''Ennom, vers le versant méridional des Jébuséens, elle descendait à la source de Rogel.'),
('jos',18,17,'crampon1923','Elle s''étendait au nord, et elle aboutissait à En-Sémès; elle aboutissait à Géliloth, qui est vis-à-vis de la montée d''Adommim, et elle descendait à la pierre de Boën, fils de Ruben.'),
('jos',18,18,'crampon1923','Elle passait par le versant septentrional de la montagne en face de l''Arabah, et descendait à l''Arabah.'),
('jos',18,19,'crampon1923','La frontière passait par le versant septentrional de Beth-Hagla, et la frontière aboutissait à la langue septentrionale de la mer Salée, vers l''embouchure du Jourdain, au midi: c''était la frontière du sud.'),
('jos',18,20,'crampon1923','Le Jourdain formait sa limite du côté de l''orient. Tel fut l''héritage des fils de Benjamin, d''après ses frontières tout autour, selon leurs familles.'),
('jos',18,21,'crampon1923','Les villes de la tribu des fils de Benjamin, selon leurs familles, étaient: Jéricho, Beth-Hagla, Emek-Casis,'),
('jos',18,22,'crampon1923','Beth-Araba, Samaraïm, Béthel,'),
('jos',18,23,'crampon1923','Avim, Aphara, Ophéra,'),
('jos',18,24,'crampon1923','Képhar-Emona, Ophni et Gabée: douze villes et leurs villages.'),
('jos',18,25,'crampon1923','Gabaon, Rama, Béroth,'),
('jos',18,26,'crampon1923','Mesphé, Caphara, Amosa,'),
('jos',18,27,'crampon1923','Récem, Jaréphel, Tharéla,'),
('jos',18,28,'crampon1923','Séla, Eleph, Jébus, qui est Jérusalem, Gabaath, et Cariath: quatorze villes et leurs villages. Tel fut l''héritage des fils de Benjamin, selon leurs familles.'),
('jos',19,1,'crampon1923','La seconde part échut par le sort à Siméon, à la tribu des fils de Siméon, selon leurs familles: leur héritage fut au milieu de l''héritage des fils de Juda.'),
('jos',19,2,'crampon1923','Ils eurent dans leur héritage: Bersabée, Sabée, Molada,'),
('jos',19,3,'crampon1923','Haser-Sual, Bala, Asem,'),
('jos',19,4,'crampon1923','Eltholad, Béthul, Harma,'),
('jos',19,5,'crampon1923','Siceleg, Beth-Marchaboth, Hasersusa,'),
('jos',19,6,'crampon1923','Beth-lebaoth et Sarohen: treize villes et leurs villages.'),
('jos',19,7,'crampon1923','Aïn, Remmon, Athar et Asan, quatre villes et leurs villages;'),
('jos',19,8,'crampon1923','ainsi que tous les villages aux environs de ces villes, jusqu''à Baalath-Béer, qui est la Ramath du midi. — Tel fut l''héritage de la tribu des fils de Siméon selon leurs familles.'),
('jos',19,9,'crampon1923','L''héritage des fils de Siméon fut pris sur la portion des fils de Juda; car la portion des fils de Juda était trop grande pour eux, et c''est au milieu de leur territoire que les fils de Siméon reçurent leur héritage.'),
('jos',19,10,'crampon1923','La troisième part échut par le sort aux fils de Zabulon selon leurs familles; la frontière de leur héritage s''étendait jusqu''à Sarid.'),
('jos',19,11,'crampon1923','Leur frontière montait vers l''occident, vers Mérala, touchait à Debbaseth, touchait au torrent qui coule devant Jéconam.'),
('jos',19,12,'crampon1923','De Sarid, elle revenait à l''orient, vers le soleil levant, jusqu''à la frontière de Céseleth-Thabor, aboutissait vers Dabereth et montait à Japhiré.'),
('jos',19,13,'crampon1923','De là, elle passait, vers l''orient, vers le soleil levant à Geth-Hépher, à Thacasin, et aboutissait à Remmon, qui confine à Noa.'),
('jos',19,14,'crampon1923','La frontière tournait du côté du nord vers Hanathon, et aboutissait à la vallée de Jephtahel.'),
('jos',19,15,'crampon1923','Les villes étaient: Catheth, Naalol, Séméron, Jedala et Bethléhem: douze villes et leurs villages. —'),
('jos',19,16,'crampon1923','Tel fut l''héritage des fils de Zabulon, selon leurs familles: ces villes et leurs villages.'),
('jos',19,17,'crampon1923','La quatrième part échut par le sort à Issachar, aux fils d''Issachar, selon leurs familles.'),
('jos',19,18,'crampon1923','Leur frontière était Jezraël, Casaloth, Sunem,'),
('jos',19,19,'crampon1923','Hapharaïm, Séon, Anaharath,'),
('jos',19,20,'crampon1923','Rabboth, Césion, Abès,'),
('jos',19,21,'crampon1923','Ramèth, En-Gannim, En-Hadda et Beth-Phésès.'),
('jos',19,22,'crampon1923','La frontière touchait à Thabor, à Séhésima et à Beth-Samès, et aboutissait au Jourdain: seize villes et leurs villages. —'),
('jos',19,23,'crampon1923','Tel fut l''héritage de la tribu des fils d''Issachar, selon leurs familles: les villes et leurs villages.'),
('jos',19,24,'crampon1923','La cinquième part échut par le sort à la tribu des fils d''Aser, selon leurs familles.'),
('jos',19,25,'crampon1923','Leur frontière était Halcath, Chali, Béten, Axaph,'),
('jos',19,26,'crampon1923','Elmélech, Amaad et Messal; elle touchait, vers l''occident, au Carmel et à Sihor-Labanath;'),
('jos',19,27,'crampon1923','puis elle tournait vers Beth-Dagon, touchait Zabulon et la vallée de Jephtahel, au nord de Beth-Emec et de Néhiel, et aboutissait à Caboul, à gauche,'),
('jos',19,28,'crampon1923','et à Abran, Rohob, Hamon, et Cana, jusqu''à Sidon la Grande;'),
('jos',19,29,'crampon1923','la frontière tournait ensuite vers Ramath jusqu''à la ville forte de Tyr et la frontière tournait vers Hosa, pour aboutir à la mer, près du district d''Achziba;'),
('jos',19,30,'crampon1923','de plus: Amma, Aphec et Rohob: vingt-deux villes et leurs villages. —'),
('jos',19,31,'crampon1923','Tel fut l''héritage de la tribu des fils d''Aser. Selon leurs familles: ces villes et leurs villages.'),
('jos',19,32,'crampon1923','La sixième part échut par le sort aux fils de Nephthali, selon leurs familles.'),
('jos',19,33,'crampon1923','Leur frontière allait depuis Héleph, à partir du chêne qui est à Saananim, vers Adami-Néceb et Jebnaël, jusqu''à Lécum, et elle aboutissait au Jourdain;'),
('jos',19,34,'crampon1923','la frontière tournait vers l''occident à Azanoth-Thabor, et de là aboutissait à Hucuca; elle touchait à Zabulon au midi, à Aser à l''occident, et à Juda, près du Jourdain, vers le soleil levant.'),
('jos',19,35,'crampon1923','Les villes fortes étaient: Assédim, Ser, Emath, Reccath, Cénéreth,'),
('jos',19,36,'crampon1923','Edéma, Arama, Asor,'),
('jos',19,37,'crampon1923','Cédès, Edraï, En-Hasor,'),
('jos',19,38,'crampon1923','Jéron, Magdalel, Horem, Beth-Anath et Beth-Samès: dix-neuf villes et leurs villages. —'),
('jos',19,39,'crampon1923','Tel fut l''héritage de la tribu des fils de Nephthali, selon leurs familles: les villes et leurs villages.'),
('jos',19,40,'crampon1923','La septième part échut par le sort à la tribu des fils de Dan, selon leurs familles.'),
('jos',19,41,'crampon1923','La frontière de leur héritage comprenait Saraa, Esthaol, Hir-Sémès,'),
('jos',19,42,'crampon1923','Sélébin, Ajalon, Jéthéla,'),
('jos',19,43,'crampon1923','Elon, Themna, Acron,'),
('jos',19,44,'crampon1923','Elthécé, Gebbéthon, Balaath,'),
('jos',19,45,'crampon1923','Jud, Bené-Barach, Geth-Remmon;'),
('jos',19,46,'crampon1923','Mé-Jarcon et Arécon, avec le territoire vis-à-vis de Joppé.'),
('jos',19,47,'crampon1923','Le territoire des fils de Dan s''étendit au dehors de chez eux; car les fils de Dan montèrent et combattirent contre Lésem; ils s''en emparèrent et la frappèrent du tranchant de l''épée; en ayant pris possession, ils s''y établirent, et l''appelèrent Dan, du nom de Dan, leur père. —'),
('jos',19,48,'crampon1923','Tel fut l''héritage de la tribu des fils de Dan, selon leurs familles: les villes et leurs villages.'),
('jos',19,49,'crampon1923','Lorsqu''ils eurent achevé de faire le partage du pays, selon ses limites, les enfants d''Israël donnèrent à Josué, fils de Nun, un héritage au milieu d''eux.'),
('jos',19,50,'crampon1923','Sur l''ordre de Yahweh, ils lui donnèrent la ville qu''il demanda, Thamnath-Saré, dans la montagne d''Ephraïm. Josué rebâtit cette ville et il y demeura.'),
('jos',19,51,'crampon1923','Tels sont les héritages que le prêtre Eléazar, Josué, fils de Nun, et les chefs de famille des tribus des enfants d''Israël répartirent par le sort à Silo, devant Yahweh, à l''entrée de la tente de réunion. Ils achevèrent ainsi le partage du pays.'),
('jos',20,1,'crampon1923','Yahweh parla à Josué, en disant: « Parle aux enfants d''Israël et dis-leur:'),
('jos',20,2,'crampon1923','Désignez-vous, comme je vous l''ai ordonné par Moïse, des villes de refuge'),
('jos',20,3,'crampon1923','où pourra s''enfuir le meurtrier qui aura tué quelqu''un par erreur, sans le savoir, et elles vous serviront de refuge contre le vengeur du sang.'),
('jos',20,4,'crampon1923','Le meurtrier s''enfuira vers une de ces villes; il s''arrêtera à l''entrée de la porte de la ville, et exposera son cas aux anciens de cette ville; ceux-ci le recueilleront auprès d''eux dans la ville, et lui donneront une demeure pour qu''il habite avec eux.'),
('jos',20,5,'crampon1923','Si le vengeur du sang le poursuit, ils ne livreront point le meurtrier entre ses mains, car c''est sans le savoir qu''il a tué son prochain, qu''il ne haïssait pas auparavant.'),
('jos',20,6,'crampon1923','Le meurtrier restera dans cette ville jusqu''à ce qu''il comparaisse devant l''assemblée pour être jugé, jusqu''à la mort du grand prêtre qui sera en fonctions en ces jours-là. Alors le meurtrier s''en retournera et rentrera dans sa ville et dans sa maison, dans la ville d''où il s''était enfui. »'),
('jos',20,7,'crampon1923','Ils consacrèrent Cédès en Gallilée, dans la montagne de Nephthali; Sichem, dans la montagne d''Ephraïm, et Cariath-Arbé, qui est Hébron, dans la montagne de Juda.'),
('jos',20,8,'crampon1923','De l''autre côté du Jourdain, vis-à-vis de Jéricho, à l''orient, ils désignèrent Bosor, dans le désert, dans la plaine, ville de la tribu de Ruben; Ramoth en Galaad, de la tribu de Gad, et Gaulon en Basan, de la tribu de Manassé.'),
('jos',20,9,'crampon1923','Telles furent les villes assignées à tous les enfants d''Israël et à l''étranger qui séjourne au milieu d''eux, afin que quiconque aurait tué quelqu''un par erreur pût s''y réfugier, et qu''il ne mourût pas de la main du vengeur du sang, avant d''avoir comparu devant l''assemblée.'),
('jos',21,1,'crampon1923','Les chefs de famille des Lévites s''approchèrent du prêtre Eléazar, de Josué, fils de Nun, et des chefs de famille des tribus des enfants d''Israël;'),
('jos',21,2,'crampon1923','ils leur parlèrent à Silo, dans le pays de Chanaan, en disant: « Yahweh a ordonné par Moïse qu''on nous donnât des villes pour notre habitation, et leurs banlieues pour notre bétail. »'),
('jos',21,3,'crampon1923','Les enfants d''Israël donnèrent aux Lévites, sur leur héritage, selon l''ordre de Yahweh, les villes suivantes et leurs banlieues.'),
('jos',21,4,'crampon1923','Le sort fut tiré d''abord pour les familles des Caathites; et les fils du prêtre Aaron, d''entre les Lévites, obtinrent par le sort treize villes de la tribu de Juda, de la tribu de Siméon et de la tribu de Benjamin;'),
('jos',21,5,'crampon1923','les autres fils de Caath obtinrent par le sort dix villes des familles de la tribu d''Ephraïm, de la tribu de Dan et de la demi-tribu de Manassé.'),
('jos',21,6,'crampon1923','Les fils de Gerson obtinrent par le sort treize villes des familles de la tribu d''Issachar, de la tribu d''Aser, de la tribu de Nephthali et de la demi-tribu de Manassé en Basan.'),
('jos',21,7,'crampon1923','Les fils de Mérari, selon leurs familles, obtinrent douze villes de la tribu de Ruben, de la tribu de Gad et de la tribu de Zabulon.'),
('jos',21,8,'crampon1923','Les enfants d''Israël donnèrent par le sort aux Lévites, ces villes et leurs banlieues, comme Yahweh l''avait ordonné par Moïse.'),
('jos',21,9,'crampon1923','Ils donnèrent de la tribu des fils de Juda et de la tribu des fils de Siméon les villes suivantes désignées par leurs noms;'),
('jos',21,10,'crampon1923','ce fut pour les fils d''Aaron, d''entre les familles des Caathites, d''entre les fils de Lévi, car le sort fut d''abord tiré pour eux.'),
('jos',21,11,'crampon1923','Ils leurs donnèrent, dans la montagne de Juda, la ville d''Arbé, père d''Enac, laquelle est Hébron, et sa banlieue tout autour.'),
('jos',21,12,'crampon1923','Mais la campagne de cette ville et ses villages, ils les donnèrent en possession à Caleb, fils de Jéphoné.'),
('jos',21,13,'crampon1923','Ils donnèrent aux fils du prêtre Aaron la ville de refuge pour le meurtrier, Hébron et sa banlieue, ainsi que Lebna avec sa banlieue,'),
('jos',21,14,'crampon1923','Jéther et sa banlieue, Estémo et sa banlieue,'),
('jos',21,15,'crampon1923','Holon et sa banlieue, Dabir et sa banlieue,'),
('jos',21,16,'crampon1923','Aïn et sa banlieue, Jéta et sa banlieue, Bethsamès et sa banlieue: neuf villes de ces deux tribus.'),
('jos',21,17,'crampon1923','De la tribu de Benjamin: Gabaon et sa banlieue, Gabaa et sa banlieue,'),
('jos',21,18,'crampon1923','Anathoth et sa banlieue, Almon et sa banlieue: quatre villes.'),
('jos',21,19,'crampon1923','Total des villes des prêtres, fils d''Aaron: treize villes et leurs banlieues.'),
('jos',21,20,'crampon1923','Quant aux familles des fils de Caath, Lévites, aux autres fils de Caath, les villes qui leur échurent par le sort furent de la tribu d''Ephraïm.'),
('jos',21,21,'crampon1923','Les enfants d''Israël leur donnèrent la ville de refuge pour le meurtrier, Sichem et sa banlieue, dans la montagne d''Ephraïm, ainsi que Gazer et sa banlieue,'),
('jos',21,22,'crampon1923','Cibsaïm et sa banlieue, Beth-Horon et sa banlieue: quatre villes.'),
('jos',21,23,'crampon1923','De la tribu de Dan: Elthéco et sa banlieue, Gabathon et sa banlieue,'),
('jos',21,24,'crampon1923','Ajalon et sa banlieue, Geth-Remmon et sa banlieue: quatre villes.'),
('jos',21,25,'crampon1923','De la demi-tribu de Manassé: Thanach et sa banlieue, et Geth-Remmon et sa banlieue: deux villes.'),
('jos',21,26,'crampon1923','Total: dix villes avec leurs banlieues, pour les familles des autres fils de Caath.'),
('jos',21,27,'crampon1923','Aux fils de Gerson, d''entre les familles des Lévites, ils donnèrent, de la demi-tribu de Manassé, la ville de refuge pour le meurtrier, Gaulon, en Basan, et sa banlieue, ainsi que Bosra et sa banlieue: deux villes.'),
('jos',21,28,'crampon1923','De la tribu d''Issachar: Césion et sa banlieue, Dabéreth et sa banlieue,'),
('jos',21,29,'crampon1923','Jaramoth et sa banlieue, En-Gannim et sa banlieue: quatre villes.'),
('jos',21,30,'crampon1923','De la tribu d''Aser: Masal et sa banlieue, Abdon et sa banlieue,'),
('jos',21,31,'crampon1923','Helcath et sa banlieue, Rohob et sa banlieue: quatre villes.'),
('jos',21,32,'crampon1923','De la tribu de Nephthali: la ville de refuge pour le meurtrier, Cédès en Galilée et sa banlieue, ainsi que Hamoth-Dor et sa banlieue, Carthan et sa banlieue: trois villes.'),
('jos',21,33,'crampon1923','Total des villes des Gersonites, selon leurs familles: treize villes et leurs banlieues.'),
('jos',21,34,'crampon1923','Aux familles des fils de Mérari, au reste des Lévites, ils donnèrent, de la tribu de Zabulon: Jecnam et sa banlieue, Cartha et sa banlieue,'),
('jos',21,35,'crampon1923','Damna et sa banlieue, Naalol et sa banlieue: quatre villes.'),
('jos',21,36,'crampon1923','Et de la tribu de Gad: la ville de refuge pour le meurtrier, Ramoth en Galaad et sa banlieue, ainsi que Manaïm et sa banlieue,'),
('jos',21,37,'crampon1923','Hésebon et sa banlieue, Jaser et sa banlieue: en tout quatre villes.'),
('jos',21,38,'crampon1923','Total des villes assignées par le sort aux fils de Mérari, selon leurs familles, formant le reste des familles des Lévites: douze villes.'),
('jos',21,39,'crampon1923','Total des villes des Lévites au milieu des possessions des enfants d''Israël: quarante-huit villes et leurs banlieues.'),
('jos',21,40,'crampon1923','Chacune de ces villes avait sa banlieue tout autour; il en était ainsi pour toutes ces villes.'),
('jos',21,41,'crampon1923','C''est ainsi que Yahweh donna à Israël tout le pays qu''il avait juré de donner à leurs pères; ils en prirent possession et s''y établirent.'),
('jos',21,42,'crampon1923','Yahweh leur accorda du repos tout autour d''eux, comme il l''avait juré à leurs pères; aucun de leurs ennemis ne put leur résister, et Yahweh les livra tous entre leurs mains.'),
('jos',21,43,'crampon1923','De toutes les bonnes paroles que Yahweh avait dites à la maison d''Israël, aucune ne resta sans effet; toutes s''accomplirent.'),
('jos',21,44,'crampon1923',''),
('jos',21,45,'crampon1923',''),
('jos',22,1,'crampon1923','Alors Josué appela les Rubénites, les Gadites et la demi-tribu de Manassé,'),
('jos',22,2,'crampon1923','et il leur dit: « Vous avez observé tout ce que vous a prescrit Moïse, serviteur de Yahweh, et vous avez obéi à ma voix en tout ce que je vous ai commandé.'),
('jos',22,3,'crampon1923','Vous n''avez pas abandonné vos frères durant ce long espace de temps, jusqu''à ce jour, et vous avez fidèlement observé le commandement de Yahweh, votre Dieu.'),
('jos',22,4,'crampon1923','Maintenant que Yahweh, votre Dieu, a donné du repos à vos frères, comme il le leur avait dit, retournez et allez-vous en vers vos tentes, dans le pays qui vous appartient, et que Moïse, serviteur de Yahweh, vous a donné de l''autre côté du Jourdain.'),
('jos',22,5,'crampon1923','Seulement ayez grand soin de mettre en pratique les ordonnances et les lois que Moïse, serviteur de Yahweh, vous a prescrites, aimant Yahweh, votre Dieu, marchant dans toutes ses voies, gardant ses commandements, vous attachant à lui et le servant de tout votre cœur et toute votre âme. »'),
('jos',22,6,'crampon1923','Et Josué les bénit et les congédia; et il s''en allèrent vers leurs tentes.'),
('jos',22,7,'crampon1923','Moïse avait donné à une moitié de la tribu de Manassé un territoire en Basan, et Josué donna à l''autre moitié un territoire parmi ses frères en deçà du Jourdain, à l''occident. En les renvoyant vers leurs tentes, Josué les bénit,'),
('jos',22,8,'crampon1923','et il leur dit: « Vous retournerez à vos tentes avec de grandes richesses, des troupeaux très nombreux et beaucoup d''argent, d''or, d''airain, de fer et de vêtements; partagez avec vos frères les dépouilles de vos ennemis. »'),
('jos',22,9,'crampon1923','Les fils de Ruben, les fils de Gad et la demi-tribu de Manassé, ayant quitté les enfants d''Israël à Silo, qui est dans le pays de Chanaan, s''en retournèrent pour aller dans le pays de Galaad, qui était la propriété qu''ils avaient reçue, comme Yahweh l''avait ordonné par Moïse.'),
('jos',22,10,'crampon1923','Quand ils furent arrivés aux districts du Jourdain qui font partie du pays de Chanaan, les fils de Ruben, les fils de Gad et la demi-tribu de Manassé y bâtirent un autel au bord du Jourdain, un autel grand à voir.'),
('jos',22,11,'crampon1923','Les enfants d''Israël apprirent que l''on disait: « Voilà que les fils de Ruben, les fils de Gad et la demi-tribu de Manassé ont bâti un autel sur le devant du pays de Chanaan, dans les districts du Jourdain, du côté des enfants d''Israël. »'),
('jos',22,12,'crampon1923','Quand les enfants d''Israël l''eurent appris, toute l''assemblée des enfants d''Israël se réunit à Silo, pour monter contre eux et leur faire la guerre.'),
('jos',22,13,'crampon1923','Les enfants d''Israël envoyèrent auprès des fils de Ruben, des fils de Gad et de la demi-tribu de Manassé, au pays de Galaad, Phinées, fils du prêtre Eléazar,'),
('jos',22,14,'crampon1923','et avec lui dix princes, un prince de maison patriarcale, pour chacune des tribus d''Israël: tous étaient chefs de leur maison patriarcale parmi les milliers d''Israël.'),
('jos',22,15,'crampon1923','S''étant rendus auprès des fils de Ruben, des fils de Gad et de la demi-tribu de Manassé, au pays de Galaad, ils leur parlèrent en disant:'),
('jos',22,16,'crampon1923','« Ainsi parle toute l''assemblée de Yahweh: Quelle infidélité avez-vous commise envers le Dieu d''Israël, de vous détourner aujourd''hui de Yahweh en vous bâtissant un autel pour vous révolter aujourd''hui contre Yahweh?'),
('jos',22,17,'crampon1923','N''est-ce pas assez pour nous que le crime de Phogor, dont nous ne nous sommes pas encore purifiés jusqu''à ce jour, malgré la plaie qui frappa l''assemblée de Yahweh,'),
('jos',22,18,'crampon1923','pour que vous vous détourniez aujourd''hui de Yahweh? Si vous vous révoltez aujourd''hui contre Yahweh, demain il s''irritera contre toute l''assemblée d''Israël.'),
('jos',22,19,'crampon1923','Que si vous regardez comme impur le pays qui est en votre possession, passez dans le pays qui est la possession de Yahweh, où est fixée la demeure de Yahweh, et établissez-vous au milieu de nous; mais ne vous révoltez pas contre Yahweh et ne vous révoltez pas contre nous, en vous bâtissant un autel outre l''autel de Yahweh, notre Dieu.'),
('jos',22,20,'crampon1923','Achan, fils de Zaré, ne commit-il pas une infidélité au sujet des choses vouées par anathème, et la colère de Yahweh n''a-t-elle pas éclaté sur toute l''assemblée d''Israël? Et il ne fut pas le seul qui périt à cause de son crime. »'),
('jos',22,21,'crampon1923','Les fils de Ruben, les fils de Gad et la demi-tribu de Manassé répondirent et dirent aux chefs des milliers d''Israël:'),
('jos',22,22,'crampon1923','« Le Tout-Puissant, Dieu, Yahweh, le Tout-Puissant, Dieu, Yahweh le sait, et Israël le saura! Si c''est par rébellion et par infidélité envers Yahweh, ô Dieu, ne nous sauvez point en ce jour!...'),
('jos',22,23,'crampon1923','Que si nous nous sommes bâti un autel, pour nous détourner de Yahweh, et si c''est pour y offrir des holocaustes et des oblations, pour y faire des sacrifices pacifiques; que Yahweh nous en demande compte!'),
('jos',22,24,'crampon1923','et si ce n''est pas par crainte de ce qui arriverait que nous avons fait cela, nous disant: Vos fils diront un jour à nos fils: Qu''y a-t-il de commun entre vous et Yahweh, le Dieu d''Israël?'),
('jos',22,25,'crampon1923','Yahweh a mis le Jourdain comme limite entre nous et vous, fils de Ruben et fils de Gad; vous n''avez point de part à Yahweh. — Ainsi vos fils seraient cause que nos fils cesseraient de craindre Yahweh. —'),
('jos',22,26,'crampon1923','Et nous nous sommes dit: Mettons-nous à bâtir un autel, non pour des holocaustes et pour des sacrifices;'),
('jos',22,27,'crampon1923','mais afin qu''il soit un témoin entre nous et vous, et nos descendants après nous, que nous servons Yahweh devant sa face par nos holocaustes, par nos sacrifices et nos victimes pacifiques, afin que vos fils ne disent pas un jour à nos fils: Vous n''avez point de part à Yahweh.'),
('jos',22,28,'crampon1923','Nous avons dit: Si un jour ils parlaient ainsi à nous ou à nos descendants, nous leur répondrions: Voyez la forme de l''autel de Yahweh que nos pères ont construit, non pour servir à des holocaustes et à des sacrifices, mais pour être un témoin entre nous et vous.'),
('jos',22,29,'crampon1923','Loin de nous de vouloir nous révolter contre Yahweh et nous détourner aujourd''hui de Yahweh, en bâtissant un autel pour des holocaustes, pour des oblations et pour des sacrifices, outre l''autel de Yahweh, notre Dieu, qui est devant sa demeure! »'),
('jos',22,30,'crampon1923','Lorsque le prêtre Phinées et les princes de l''assemblée, chefs des milliers d''Israël, qui étaient avec lui, eurent entendu les paroles que prononcèrent les fils de Ruben, les fils de Gad et les fils de Manassé, ils furent satisfaits.'),
('jos',22,31,'crampon1923','Et Phinées, fils du prêtre Eléazar, dit aux fils de Ruben, aux fils de Gad et aux fils de Manassé: « Nous reconnaissons maintenant que Yahweh est au milieu de nous, puisque vous n''avez pas commis cette infidélité envers Yahweh; vous avez ainsi délivré les enfants d''Israël de la main de Yahweh! »'),
('jos',22,32,'crampon1923','Phinées, fils du prêtre Eléazar, et les princes quittèrent les fils de Ruben et les fils de Gad, et revinrent du pays de Galaad dans le pays de Chanaan, vers les enfants d''Israël, auxquels ils firent leur rapport.'),
('jos',22,33,'crampon1923','La chose plut aux enfants d''Israël; ils bénirent Dieu et ne parlèrent plus de monter en armes contre eux, pour dévaster le pays qu''habitaient les fils de Ruben et les fils de Gad.'),
('jos',22,34,'crampon1923','Les fils de Ruben et les fils de Gad appelèrent l''autel Ed, car, dirent-ils, il est témoin entre nous que Yahweh est le vrai Dieu.'),
('jos',23,1,'crampon1923','Un long temps s''était écoulé depuis que Yahweh avait donné du repos à Israël, en le délivrant de tous ses ennemis d''alentour, et Josué était vieux, avancé en âge.'),
('jos',23,2,'crampon1923','Alors Josué convoqua tout Israël, ses anciens, ses chefs, ses juges et ses officiers, et leur dit: « Je suis devenu vieux, avancé en âge.'),
('jos',23,3,'crampon1923','Vous avez vu tout ce que Yahweh, votre Dieu a fait à toutes ces nations devant vous; car c''est Yahweh, votre Dieu, qui a combattu pour vous.'),
('jos',23,4,'crampon1923','Voyez: je vous ai distribué par le sort en héritage pour vos tribus, ces nations qui sont restées et toutes celles que j''ai exterminées, depuis le Jourdain jusqu''à la grande mer vers le soleil couchant.'),
('jos',23,5,'crampon1923','Yahweh, votre Dieu, les repoussera devant vous, et les chassera devant vous, et vous posséderez leur pays, comme Yahweh, votre Dieu, vous l''a dit.'),
('jos',23,6,'crampon1923','Montrez donc un grand courage pour observer et mettre en pratique tout ce qui est écrit dans le livre de la loi de Moïse, sans vous en détourner ni à droite ni à gauche,'),
('jos',23,7,'crampon1923','sans vous mêler avec ces nations qui sont restées parmi vous; n''invoquez point le nom de leurs dieux, ne jurez point par eux, ne les servez point et ne vous prosternez point devant eux;'),
('jos',23,8,'crampon1923','mais attachez-vous à Yahweh, votre Dieu, comme vous l''avez fait jusqu''à ce jour.'),
('jos',23,9,'crampon1923','Yahweh a chassé devant vous des nations grandes et puissantes, et personne n''a pu tenir devant vous jusqu''à ce jour.'),
('jos',23,10,'crampon1923','Un seul d''entre vous en poursuivait mille, car Yahweh, votre Dieu, combattait pour vous, comme il vous l''a dit.'),
('jos',23,11,'crampon1923','Prenez donc garde à vous mêmes, pour que vous aimiez Yahweh, votre Dieu.'),
('jos',23,12,'crampon1923','Car si vous vous détournez et que vous vous attachiez au reste de ces nations qui sont demeurées parmi vous, si vous contractez des mariages avec elles et que vous vous mêliez à elles et qu''elles se mêlent à vous,'),
('jos',23,13,'crampon1923','sachez bien que Yahweh, votre Dieu, ne continuera pas de chasser ces nations devant nous; mais elles seront pour vous un filet et un piège, une verge sur vos flancs et des épines dans vos yeux, jusqu''à ce que vous ayez péri de dessus cette excellente terre que vous a donnée Yahweh, votre Dieu.'),
('jos',23,14,'crampon1923','Voici que je m''en vais aujourd''hui par le chemin de toute la terre; reconnaissez de tout votre cœur et de toute votre âme, que, de toutes les bonnes paroles que Yahweh, votre Dieu, a prononcées sur vous, aucune parole n''est restée sans effet; toutes se sont accomplies pour vous, aucune parole n''en est tombée.'),
('jos',23,15,'crampon1923','De même donc que toutes les bonnes paroles que Yahweh, votre Dieu, vous a adressées, se sont accomplies pour vous, de même aussi Yahweh accomplira sur vous toutes les paroles de menace, jusqu''à ce qu''il vous ait détruits de dessus cette excellente terre que Yahweh, votre Dieu, vous a donnée.'),
('jos',23,16,'crampon1923','Si vous transgressez l''alliance de Yahweh, votre Dieu, qu''il vous a prescrite, et si vous allez servir d''autres dieux, et vous prosterner devant eux, la colère de Yahweh s''enflammera contre vous, et vous périrez bientôt de dessus le bon pays qu''il vous a donné. »'),
('jos',24,1,'crampon1923','Josué assembla toutes les tribus d''Israël à Sichem, et il convoqua les anciens d''Israël, ses chefs, ses juges et ses officiers. Ils se présentèrent devant Dieu,'),
('jos',24,2,'crampon1923','et Josué dit à tout le peuple: « Ainsi parle Yahweh, Dieu d''Israël: Vos pères, Tharé, père d''Abraham et père de Nachor, habitaient à l''origine de l''autre côté du fleuve, et ils servaient d''autres dieux.'),
('jos',24,3,'crampon1923','Je pris votre père Abraham de l''autre côté du fleuve et je le conduisis dans tout le pays de Chanaan; je multipliai sa postérité, et je lui donnai Isaac.'),
('jos',24,4,'crampon1923','A Isaac je donnai Jacob et Esaü, et je donnai pour possession à Esaü la montagne de Séïr; et Jacob et ses fils descendirent en Egypte. —'),
('jos',24,5,'crampon1923','Puis j''envoyai Moïse et Aaron, et je frappai l''Egypte comme je l''ai fait au milieu d''elle, et ensuite je vous en fis sortir.'),
('jos',24,6,'crampon1923','Je fis sortir d''Egypte vos pères, et vous arrivâtes à la mer. Les Egyptiens poursuivirent vos pères, avec des chars et des cavaliers, jusqu''à la mer Rouge.'),
('jos',24,7,'crampon1923','Ils crièrent à Yahweh; et Yahweh mit des ténèbres entre vous et les Egyptiens; il ramena sur eux la mer, et elle les couvrit. Vos yeux ont vu ce que j''ai fait en Egypte, et vous restâtes longtemps dans le désert. —'),
('jos',24,8,'crampon1923','Je vous menai au pays des Amorrhéens, qui habitaient de l''autre côté du Jourdain, et ils combattirent contre vous. Je les livrai entre vos mains; vous prîtes possession de leur pays, et je les détruisis de devant vous.'),
('jos',24,9,'crampon1923','Balac, fils de Séphor, roi de Moab, se leva et combattit Israël; il fit appeler Balaam, fils de Béor, pour qu''il vous maudît.'),
('jos',24,10,'crampon1923','Mais je ne voulus pas écouter Balaam; il vous bénit, et je vous délivrai de la main de Balac. —'),
('jos',24,11,'crampon1923','Vous passâtes le Jourdain et vous arrivâtes à Jéricho. Les hommes de Jéricho combattirent contre vous, puis les Amorrhéens, les Phérézéens, les Chananéens, les Héthéens, les Gergéséens, les Hévéens et les Jébuséens, et je les livrai entre vos mains.'),
('jos',24,12,'crampon1923','J''envoyai devant vous les frelons qui les chassèrent de devant vous, ainsi que les deux rois des Amorrhéens; ce ne fut ni par ton épée ni par ton arc.'),
('jos',24,13,'crampon1923','Je vous donnai ainsi une terre que vous n''aviez pas cultivée, des villes que vous n''aviez pas bâties et que vous habitez, des vignes et des oliviers que vous n''aviez pas plantés et dont vous mangez les fruits.'),
('jos',24,14,'crampon1923','Craignez donc Yahweh et servez-le avec intégrité et vérité; ôtez les dieux qu''ont servis vos pères de l''autre côté du fleuve et en Egypte, et servez Yahweh.'),
('jos',24,15,'crampon1923','Que si vous ne trouvez pas bon de servir Yahweh, choisissez aujourd''hui qui vous voulez servir, soit les dieux que servaient vos pères au delà du fleuve, soit les dieux des Amorrhéens dont vous habitez le pays. Pour moi et ma maison, nous servirons Yahweh. »'),
('jos',24,16,'crampon1923','Le peuple répondit et dit: « Loin de nous de vouloir abandonner Yahweh pour servir d''autres dieux!'),
('jos',24,17,'crampon1923','Car c''est Yahweh, notre Dieu, qui nous a fait monter, nous et nos pères, du pays d''Egypte, de la maison de servitude; et qui a opéré sous nos yeux ces grands prodiges, et qui nous a gardés tout le long du chemin que nous avons parcouru, et parmi tous les peuples au milieu desquels nous avons passé.'),
('jos',24,18,'crampon1923','Yahweh a chassé de devant nous tous les peuples, et les Amorrhéens qui habitaient ce pays. Nous aussi, nous servirons Yahweh, car il est notre Dieu. »'),
('jos',24,19,'crampon1923','Josué dit au peuple: « Vous ne pouvez pas servir Yahweh, car c''est un Dieu saint, c''est un Dieu jaloux; il ne pardonnera pas vos transgressions et vos péchés.'),
('jos',24,20,'crampon1923','Si vous abandonnez Yahweh et que vous serviez des dieux étrangers, il se retournera, il vous fera du mal et vous consumera, après vous avoir fait du bien. »'),
('jos',24,21,'crampon1923','Le peuple dit à Josué: « Non! car nous servirons Yahweh. »')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('jos',24,22,'crampon1923','Josué dit au peuple: « Vous êtes témoins contre vous-même que vous avez choisi Yahweh pour le servir. » Ils répondirent: « Nous en sommes témoins. »'),
('jos',24,23,'crampon1923','Il dit: « Et maintenant ôtez les dieux étrangers qui sont au milieu de vous, et tournez vos cœurs vers Yahweh, le Dieu d''Israël. »'),
('jos',24,24,'crampon1923','Et le peuple dit à Josué: « Nous servirons Yahweh, notre Dieu, et nous obéirons à sa voix. »'),
('jos',24,25,'crampon1923','C''est ainsi que Josué conclut en ce jour-là une alliance avec le peuple, et qu''il lui donna à Sichem des lois et des ordonnances.'),
('jos',24,26,'crampon1923','Josué écrivit ces paroles dans le livre de la loi de Dieu. Il prit une grande pierre et la dressa là, sous le chêne qui était dans le lieu consacré à Yahweh.'),
('jos',24,27,'crampon1923','Et Josué dit à tout le peuple: « Voici, cette pierre servira de témoin contre nous, car elle a entendu toutes les paroles que Yahweh nous a dites; elle servira de témoin contre vous, afin que vous ne reniiez pas votre Dieu. »'),
('jos',24,28,'crampon1923','Et Josué renvoya le peuple, chacun dans son héritage.'),
('jos',24,29,'crampon1923','Après cela, Josué, fils de Nun, serviteur de Yahweh, mourut, âgé de cent dix ans.'),
('jos',24,30,'crampon1923','On l''ensevelit dans le territoire qu''il avait eu en partage, à Thamnath-Saré, dans la montagne d''Ephraïm, au nord du mont Gaas.'),
('jos',24,31,'crampon1923','Israël servit Yahweh pendant toute la vie de Josué, et pendant toute la vie des anciens qui survécurent à Josué et qui connaissaient tout ce que Yahweh avait fait en faveur d''Israël.'),
('jos',24,32,'crampon1923','Les ossements de Joseph, que les enfants d''Israël avaient emportés d''Egypte, furent enterrés à Sichem, dans la pièce de terre que Jacob avait achetée cent kesitas des fils de Hémor, père de Sichem, et ils devinrent la propriété des fils de Joseph.'),
('jos',24,33,'crampon1923','Eléazar, fils d''Aaron, mourut, et on l''enterra à Gabaa, ville de Phinées, son fils, auquel elle avait été donnée, dans la montagne d''Ephraïm.'),
('jg',1,1,'crampon1923','Après la mort de Josué, les enfants d''Israël consultèrent Yahweh, en disant: " Qui de nous montera le premier contre les Chananéens pour les combattre? "'),
('jg',1,2,'crampon1923','Yahweh répondit: " Juda montera; voici que j''ai livré le pays entre ses mains. "'),
('jg',1,3,'crampon1923','Et Juda dit à Siméon, son frère: " Monte avec moi dans le pays que le sort m''a assigné, et nous combattrons les Chananéens; j''irai aussi avec toi dans le pays que le sort t''a assigné. " Et Siméon alla avec lui.'),
('jg',1,4,'crampon1923','Juda monta, et Yahweh livra entre leurs mains les Chananéens et les Phérézéens; ils battirent dix mille hommes à Bézec.'),
('jg',1,5,'crampon1923','Ayant trouvé à Bézec Adoni-Bésec, ils l''attaquèrent et ils battirent les Chananéens et les Phérézéens.'),
('jg',1,6,'crampon1923','Adoni-Bésec prit la fuite, mais ils le poursuivirent et, l''ayant saisi, ils lui coupèrent les pouces des mains et des pieds.'),
('jg',1,7,'crampon1923','Adoni-Bésec dit: " Soixante-dix rois, ayant les pouces des pieds et des mains coupés, ramassaient les miettes sous ma table; ce que j''ai fait, Dieu me le rend. " On l''emmena à Jérusalem, et il y mourut.'),
('jg',1,8,'crampon1923','Les fils de Juda attaquèrent Jérusalem et, l''ayant prise, ils la frappèrent du tranchant de l''épée et mirent le feu à la ville.'),
('jg',1,9,'crampon1923','Ensuite les fils de Juda descendirent pour combattre les Chananéens qui habitaient la montagne, le Négéb et la Séphéla.'),
('jg',1,10,'crampon1923','Juda marcha contre les Chananéens qui habitaient à Hébron, appelée autrefois Cariath-Arbé, et il battit Sésaï, Ahiman et Tholmaï.'),
('jg',1,11,'crampon1923','Il marcha de là contre les habitants de Dabir, qui s''appelait autrefois Cariath-Sépher.'),
('jg',1,12,'crampon1923','Caleb dit: " A celui qui frappera Cariath-Sépher et qui la prendra, je donnerai pour femme ma fille Axa. "'),
('jg',1,13,'crampon1923','Othoniel, fils de Cénez, frère cadet de Caleb, s''en empara, et Caleb lui donna sa fille Axa pour femme.'),
('jg',1,14,'crampon1923','Lorsqu''elle alla chez Othoniel, elle l''excita à demander à son père un champ. Elle descendit de son âne, et Caleb lui dit: " Qu''as-tu? "'),
('jg',1,15,'crampon1923','Elle lui répondit: " Fais-moi une faveur, car tu m''as établie dans un pays desséché; donne-moi des sources d''eau. " Et Caleb lui donna les sources supérieures et les sources inférieures.'),
('jg',1,16,'crampon1923','Les fils du Cinéen, beau-frère de Moïse, montèrent de la ville des palmiers, avec les fils de Juda, dans le désert de Juda, au midi d''Arad, et ils vinrent s''établir avec le peuple.'),
('jg',1,17,'crampon1923','Juda se mit en marche avec Siméon, son frère, et ils battirent les Chananéens qui habitaient Séphaath; ils dévouèrent la ville par anathème, et on l''appela Horma.'),
('jg',1,18,'crampon1923','Juda s''empara aussi de Gaza et de son territoire, d''Ascalon et de son territoire, d''Accaron et de son territoire.'),
('jg',1,19,'crampon1923','Yahweh fut avec Juda; et Juda prit possession de la montagne, mais il ne put chasser les habitants de la plaine, parce qu''ils avaient des chars de fer.'),
('jg',1,20,'crampon1923','On donna Hébron à Caleb, comme l''avait dit Moïse, et il en chassa les trois fils d''Enac.'),
('jg',1,21,'crampon1923','Les fils de Benjamin ne chassèrent point les Jébuséens qui habitaient Jérusalem, et les Jébuséens ont habité à Jérusalem avec les fils de Benjamin, jusqu''à ce jour.'),
('jg',1,22,'crampon1923','La maison de Joseph, elle aussi, monta contre Béthel, et Yahweh fut avec eux.'),
('jg',1,23,'crampon1923','La maison de Joseph fit faire une reconnaissance à Béthel, ville dont le nom était autrefois Luz.'),
('jg',1,24,'crampon1923','Les gardes, ayant aperçu un homme qui sortait de la ville, ils lui dirent: " Montre-nous par où on peut entrer dans la ville, et nous te ferons grâce. "'),
('jg',1,25,'crampon1923','Il leur montra par où ils pourraient entrer dans la ville, et ils frappèrent la ville du tranchant de l''épée, mais ils laissèrent aller cet homme avec toute sa famille.'),
('jg',1,26,'crampon1923','Cet homme se rendit dans le pays des Héthéens; il bâtit une ville et la nomma Luz, et c''est son nom jusqu''à ce jour.'),
('jg',1,27,'crampon1923','Manassé ne chassa pas les habitants de Bethsan et des villes de sa dépendance, ni ceux de Thanac et des villes de sa dépendance, ni les habitants de Dor et des villes de sa dépendance, ni les habitants de Jéblaam et des villes de sa dépendance, ni les habitants de Mageddo et des villes de sa dépendance; et les Chananéens s''enhardirent à rester dans ce pays.'),
('jg',1,28,'crampon1923','Lorsqu''Israël fut devenu assez fort, il assujettit les Chananéens à un tribut, et ne les chassa point.'),
('jg',1,29,'crampon1923','Ephraïm ne chassa point les Chananéens qui habitaient à Gaser, et les Chananéens habitèrent au milieu d''Ephraïm, à Gaser.'),
('jg',1,30,'crampon1923','Zabulon ne chassa point les habitants de Cétron, ni les habitants de Naalol; et les Chananéens habitèrent au milieu de Zabulon, mais ils furent soumis à un tribut.'),
('jg',1,31,'crampon1923','Aser ne chassa point les habitants d''Accho, ni les habitants de Sidon, ni ceux d''Ahalab, d''Achazib, d''Helba, d''Aphec et de Rohob;'),
('jg',1,32,'crampon1923','et les fils d''Aser demeurèrent au milieu des Chananéens, habitants du pays, car ils ne les chassèrent point.'),
('jg',1,33,'crampon1923','Nephthali ne chassa point les habitants de Beth-Samès, ni les habitants de Beth-Anath, et il demeura au milieu des Chananéens, habitants du pays; mais les habitants de Beth-Samès et de Beth-Anath furent soumis à un tribut en sa faveur.'),
('jg',1,34,'crampon1923','Les Amorrhéens refoulèrent dans la montagne les fils de Dan, et ne les laissèrent pas descendre dans la plaine.'),
('jg',1,35,'crampon1923','Les Amorrhéens s''enhardirent à rester à Har-Harés, à Ajalon et à Salebim; mais la main de la maison de Joseph s''appesantit sur eux, et ils furent soumis à un tribut.'),
('jg',1,36,'crampon1923','Le territoire des Amorrhéens s''étendait de la montée d''Acrabbim, de Séla, et au-dessus.'),
('jg',2,1,'crampon1923','L''ange de Yahweh monta de Galgala à Bokim, et dit: " Je vous ai fait monter hors d''Egypte et je vous ai amenés dans le pays que j''ai juré à vos pères de vous donner. J''ai dit: Jamais je ne romprai mon alliance avec vous;'),
('jg',2,2,'crampon1923','et vous, vous ne ferez, point alliance avec les habitants de ce pays, vous renverserez leurs autels. Mais vous n''avez pas obéi à ma voix. Pourquoi avez-vous fait cela?'),
('jg',2,3,'crampon1923','Et moi aussi, j''ai dit: Je ne les chasserai point devant vous; ils seront à vos côtés, et leurs dieux vous seront un piège. "'),
('jg',2,4,'crampon1923','Comme l''ange de Yahweh disait ces paroles à tous les enfants d''Israël, le peuple éleva la voix et pleura.'),
('jg',2,5,'crampon1923','Ils donnèrent à ce lieu le nom de Bokim, et ils y offrirent des sacrifices à Yahweh.'),
('jg',2,6,'crampon1923','Josué renvoya le peuple, et les enfants d''Israël s''en allèrent chacun dans son héritage pour prendre possession du pays.'),
('jg',2,7,'crampon1923','Le peuple servit Yahweh pendant toute la vie de Josué, et pendant toute la vie des anciens qui survécurent à Josué et qui avaient vu toute la grande œuvre que Yahweh avait accomplie en faveur d''Israël.'),
('jg',2,8,'crampon1923','Josué, fils de Nun, serviteur de Yahweh, mourut âgé de cent dix ans.'),
('jg',2,9,'crampon1923','On l''ensevelit dans le territoire qu''il avait eu en partage, à Thamnath-Hérès, dans la montagne d''Ephraïm, au nord du mont Gaas.'),
('jg',2,10,'crampon1923','Toute cette génération fut aussi recueillie auprès de ses pères, et il s''éleva après elle une autre génération qui ne connaissait pas Yahweh, ni l''œuvre qu''il avait faite en faveur d''Israël.'),
('jg',2,11,'crampon1923','Les enfants d''Israël firent ce qui est mal aux yeux de Yahweh, et ils servirent les Baals.'),
('jg',2,12,'crampon1923','Ils abandonnèrent Yahweh, le Dieu de leurs pères, qui les avait fait sortir du pays d''Egypte, et ils allèrent après d''autres dieux, d''entre les dieux des peuples qui les entouraient; ils se prosternèrent devant eux et ils irritèrent Yahweh.'),
('jg',2,13,'crampon1923','Abandonnant Yahweh, ils servirent Baal et les Astartés.'),
('jg',2,14,'crampon1923','La colère de Yahweh s''enflamma contre Israël; il les livra aux mains des pillards qui les pillèrent, et il les vendit entre les mains de leurs ennemis d''alentour,et ils ne purent plus tenir devant leurs ennemis.'),
('jg',2,15,'crampon1923','Partout où ils allaient, la main de Yahweh était contre eux pour leur malheur, comme Yahweh l''avait dit, comme Yahweh le leur avait juré, et ils en vinrent à une grande détresse.'),
('jg',2,16,'crampon1923','Yahweh suscitait des juges qui les délivraient de la main de ceux qui les pillaient.'),
('jg',2,17,'crampon1923','Mais ils n''écoutèrent pas leurs juges, car ils se prostituèrent à d''autres dieux et se prosternèrent devant eux. Ils se détournèrent promptement de la voie qu''avaient suivie leurs pères en obéissant aux commandements de Yahweh; ils ne firent pas de même.'),
('jg',2,18,'crampon1923','Lorsque Yahweh leur suscitait des juges, Yahweh était avec le juge et il les délivrait de la main de leurs ennemis, tant que le juge vivait; car Yahweh se repentait à cause de leurs gémissements devant ceux qui les opprimaient et les tourmentaient.'),
('jg',2,19,'crampon1923','Mais, à la mort du juge, ils se corrompaient de nouveau plus que leurs pères, en allant après d''autres dieux pour les servir et se prosterner devant eux; ils n''abandonnaient pas leurs errements et leur opiniâtreté.'),
('jg',2,20,'crampon1923','Alors la colère de Yahweh s''enflamma contre Israël, et il dit: " Puisque cette nation a transgressé mon alliance que j''avais prescrite à ses pères, et puisqu''ils n''ont pas obéi à ma voix,'),
('jg',2,21,'crampon1923','moi, je ne chasserai plus devant eux une seule des nations que Josué a laissées quand il est mort,'),
('jg',2,22,'crampon1923','afin de mettre par elles Israël à l''épreuve, pour voir s''ils seront attentifs, ou non, à suivre la voie de Yahweh, comme leurs pères y ont été attentifs. "'),
('jg',2,23,'crampon1923','Et Yahweh laissa en repos, sans se hâter de les chasser, ces nations qu''il n''avait pas livrées entre les mains de Josué.'),
('jg',3,1,'crampon1923','Voici les nations que Yahweh laissa en repos pour éprouver par elles Israël, tous ceux qui n''avaient pas connu toutes les guerres de Chanaan,'),
('jg',3,2,'crampon1923','et cela uniquement pour l''instruction des générations d''Israël, afin de leur apprendre la guerre, à ceux-là du moins qui ne l''avaient pas connue auparavant.'),
('jg',3,3,'crampon1923','Ces nations étaient: les cinq princes des Philistins, tous les Chananéens et les Sidoniens, et les Hévéens qui habitaient la montagne du Liban, depuis la montagne de Baal-Hermon jusqu''à l''entrée de Hamath.'),
('jg',3,4,'crampon1923','Ces peuples devaient servir à mettre Israël à l''épreuve, pour savoir s''ils obéiraient aux commandements que Yahweh avait prescrits à leurs pères par Moïse.'),
('jg',3,5,'crampon1923','Et les enfants d''Israël habitèrent au milieu des Chananéens, des Héthéens, des Amorrhéens, des Phérézéens, des Hévéens et des Jébuséens;'),
('jg',3,6,'crampon1923','ils prirent leurs filles pour femmes, et donnèrent à leurs fils leurs propres filles, et ils servirent leurs dieux.'),
('jg',3,7,'crampon1923','Les enfants d''Israël firent ce qui est mal aux yeux de Yahweh; oubliant Yahweh, ils servirent les Baals et les Aschéroth.'),
('jg',3,8,'crampon1923','La colère de Yahweh s''enflamma contre Israël, et il les vendit entre les mains de Chusan-Rasathaïm, roi de Mésopotamie, et les enfants d''Israël furent asservis huit ans à Chusan-Rasathaïm.'),
('jg',3,9,'crampon1923','Les enfants d''Israël, crièrent vers Yahweh, et Yahweh leur suscita un libérateur qui les délivra, Othoniel, fils de Cènez, frère cadet de Caleb.'),
('jg',3,10,'crampon1923','L''Esprit de Yahweh vint sur lui; il jugea Israël et partit pour la guerre; Yahweh livra entre ses mains Chusan-Rasathaïm, roi de Mésopotamie, et sa main fut puissante contre Chusan-Rasathaïm.'),
('jg',3,11,'crampon1923','Le pays fut en repos pendant quarante ans, et Othoniel, fils de Cénez, mourut.'),
('jg',3,12,'crampon1923','Les enfants d''Israël firent de nouveau ce qui est mal aux yeux de Yahweh, et Yahweh fortifia Eglon, roi de Moab, contre Israël, parce qu''ils faisaient ce qui est mal aux yeux de Yahweh.'),
('jg',3,13,'crampon1923','Eglon s''adjoignit les fils d''Ammon et Amalec, et il se mit en marche. Il battit Israël, et ils s''emparèrent de la ville des Palmiers.'),
('jg',3,14,'crampon1923','Les enfants d''Israël furent asservis dix-huit ans à Eglon, roi de Moab.'),
('jg',3,15,'crampon1923','Les enfants d''Israël crièrent vers Yahweh, et Yahweh leur suscita un libérateur, Aod, fils de Géra, Benjamite, qui ne se servait pas de la main droite. Les enfants d''Israël envoyèrent par lui un présent à Eglon, roi de Moab.'),
('jg',3,16,'crampon1923','Aod se fit une épée à deux tranchants, longue d''une coudée, et il la ceignit sous ses vêtements, sur sa hanche droite.'),
('jg',3,17,'crampon1923','Il offrit le Présent à Eglon. roi de Moab; or Eglon était un homme très gras.'),
('jg',3,18,'crampon1923','Lorsqu''il eut achevé d''offrir le présent, il renvoya les gens qui avaient apporté le présent.'),
('jg',3,19,'crampon1923','Et lui-même revint depuis les idoles qui sont près de Galgala, et il dit: " O roi, j''ai quelque chose de secret à te dire. " Le roi dit: " Silence! " Et tous ceux qui étaient auprès de lui sortirent.'),
('jg',3,20,'crampon1923','Aod l''aborda comme il était assis seul dans sa chambre d''été, et il dit: " J''ai pour toi une parole de Dieu. " Eglon se leva de son siège.'),
('jg',3,21,'crampon1923','Alors Aod, avançant la main gauche, tira l''épée qui était sur sa hanche droite, et la lui enfonça dans le ventre.'),
('jg',3,22,'crampon1923','La poignée même entra après la lame, et la graisse se referma sur la lame; car il ne retira pas l''épée de son ventre, et la lame sortit par derrière.'),
('jg',3,23,'crampon1923','Aod sortit par l''escalier extérieur, ferma sur Eglon les portes de la chambre haute et tira le verrou.'),
('jg',3,24,'crampon1923','Quand il fut sorti, les serviteurs du roi vinrent et regardèrent; et voici que les portes de la chambre haute étaient fermées au verrou. Ils dirent: " Sans doute il se couvre les pieds dans la chambre d''été. "'),
('jg',3,25,'crampon1923','Ils attendirent longtemps jusqu''à en avoir honte, et, comme il n''ouvrait pas les portes de la chambre haute, ils prirent la clef et ouvrirent; et voici que leur maître gisait par terre, sans vie.'),
('jg',3,26,'crampon1923','Pendant leurs délais, Aod prit la fuite, dépassa les idoles et se sauva à Séïrath.'),
('jg',3,27,'crampon1923','Aussitôt arrivé, il sonna de la trompette dans la montagne d''Ephraïm. Les enfants d''Israël descendirent avec lui de la montagne, et il se mit à leur tête.'),
('jg',3,28,'crampon1923','Il leur dit: " Suivez-moi! car Yahweh a livré entre vos mains vos ennemis, les Moabites. " Ils descendirent à sa suite, s''emparèrent des gués du Jourdain vis-à-vis de Moab, et ne laissèrent passer personne.'),
('jg',3,29,'crampon1923','Ils battirent Moab en ce temps-là, environ dix mille hommes, tous robustes et tous vaillants, et pas un n''échappa.'),
('jg',3,30,'crampon1923','En ce jour, Moab fut humilié sous la main d''Israël, et le pays fut en repos pendant quatre-vingt ans.'),
('jg',3,31,'crampon1923','Après lui, il y eut Samgar, fils d''Anath, qui battit six cents hommes des Philistins avec un aiguillon à bœufs; lui aussi fut un libérateur d''Israël.'),
('jg',4,1,'crampon1923','Les enfants d''Israël firent encore ce qui est mal aux yeux de Yahweh, après la mort d''Aod.'),
('jg',4,2,'crampon1923','Et Yahweh les vendit entre les mains de Jabin, roi de Chanaan, qui régnait à Asor; le chef de son armée était Sisara, et il habitait à Haroseth-Goïm.'),
('jg',4,3,'crampon1923','Les enfants d''Israël crièrent vers Yahweh, car Jabin avait neuf cents chars de fer et, depuis vingt ans, il opprimait durement les enfants d''Israël.'),
('jg',4,4,'crampon1923','En ce temps-là, Débora, prophétesse, femme de Lapidoth, rendait la justice en Israël.'),
('jg',4,5,'crampon1923','Elle siégeait sous le palmier de Débora, entre Rama et Béthel, dans la montagne d''Ephraïm; et les enfants d''Israël montaient vers elle pour être jugés.'),
('jg',4,6,'crampon1923','Elle envoya appeler Barac, fils d''Abinoëm, de Cédés en Nephthali, et elle lui dit: " N''est-ce pas l''ordre qu''a donné Yahweh, le Dieu d''Israël? Va, rends-toi sur le mont Thabor, et prends avec toi dix mille hommes des fils de Nephthali et des fils de Zabulon.'),
('jg',4,7,'crampon1923','Je t''amènerai, au torrent de Cison, Sisara, le chef de l''armée de Jabin, avec ses chars et ses troupes, et je le livrerai entre tes mains. "'),
('jg',4,8,'crampon1923','Barac lui dit: " Si tu viens avec moi, j''irai; mais si tu ne viens pas avec moi, je n''irai pas. "'),
('jg',4,9,'crampon1923','Elle répondit: " Oui, j''irai avec toi, mais, dans l''expédition que tu vas faire, la gloire ne sera pas pour toi; car Yahweh livrera Sisara entre les mains d''une femme. " Et Débora se leva et elle se rendit avec Barac à Cédès.'),
('jg',4,10,'crampon1923','Barac convoqua Zabulon et Nephthali à Cédès; et dix mille hommes partirent à sa suite, et Débora partit avec lui.'),
('jg',4,11,'crampon1923','Héber, le Cinéen, s''était emparé des Cinéens, des fils de Hobab, beau-frère de Moïse, et il avait dressé sa tente jusqu''au chêne de Sennim, prés de Cédès.'),
('jg',4,12,'crampon1923','On informa Sisara que Barac, fils d''Abinoëm, était parti vers le mont Thabor;'),
('jg',4,13,'crampon1923','et Sisara, fit venir d''Haroseth-Goïm, vers le torrent de Cison, tous ses chars, neuf cents chars de fer, et tout le peuple qui était avec lui.'),
('jg',4,14,'crampon1923','Alors Débora dit à Barac: " Lève-toi, car voici le jour où Yahweh a livré Sisara entre tes mains. Est-ce que Yahweh n''est pas sorti devant toi? " Et Barac descendit du mont Thabor, ayant dix mille hommes à sa suite.'),
('jg',4,15,'crampon1923','Yahweh mit en déroute Sisara, tous ses chars et toute son armée, par le tranchant de l''épée, devant Barac; et Sisara descendit de son char et s''enfuit à pied.'),
('jg',4,16,'crampon1923','Barac poursuivit les chars et l''armée jusqu''à Haroseth-Goïm, et toute l''armée de Sisara tomba sous le tranchant de l''épée; pas un homme n''échappa.'),
('jg',4,17,'crampon1923','Sisara se réfugia à pied dans la tente de Jahel, femme de Héber, le Cinéen; car il y avait paix entre Jabin, roi d''Asor, et la maison de Héber, le Cinéen.'),
('jg',4,18,'crampon1923','Jahel sortit au-devant de Sisara et lui dit: " Entre, mon seigneur, entre chez moi, ne crains point. " Il entra chez elle dans la tente, et elle le cacha sous une couverture.'),
('jg',4,19,'crampon1923','Il lui dit: " Donne-moi, je te prie, un peu d''eau à boire, car j''ai soif. " Elle ouvrit l''outre du lait, lui donna à boire et le couvrit.'),
('jg',4,20,'crampon1923','Il lui dit: " Tiens-toi à l''entrée de la tente et, si l''on vient l''interroger, en disant: Y a-t-il un homme ici? tu répondras: Non. "'),
('jg',4,21,'crampon1923','Jahel, femme de Héber, saisit un pieu de la tente et, ayant pris en main le marteau, elle s''approcha de lui doucement et lui enfonça dans la tempe le pieu, qui pénétra dans le sol, car il dormait profondément, étant accablé de fatigue; et il mourut.'),
('jg',4,22,'crampon1923','Et voici, comme Barac poursuivait Sisara, Jahel sortit à sa rencontre et lui dit: " Viens, et je te montrerai l''homme que tu cherches. " Il entra chez elle et vit Sisara étendu mort, le pieu dans la tempe.'),
('jg',4,23,'crampon1923','En ce jour, Dieu humilia Jabin, roi de Chanaan, devant les enfants d''Israël.'),
('jg',4,24,'crampon1923','Et la main des enfants d''Israël s''appesantit de plus en plus sur Jabin, roi de Chanaan, jusqu''à ce qu''ils eussent détruit Jabin, roi de Chanaan.'),
('jg',5,1,'crampon1923','En ce jour-là, Débora et Barac, fils d''Abinoëm, chantèrent en disant:'),
('jg',5,2,'crampon1923','Les chefs se sont mis à la tête en Israël; le peuple s''est volontairement offert pour le combat, bénissez-en Yahweh!'),
('jg',5,3,'crampon1923','Ecoutez, ô rois: princes, prêtez l''oreille. C''est moi, c''est moi qui chanterai Yahweh; je dirai un cantique à Yahweh, le Dieu d''Israël.'),
('jg',5,4,'crampon1923','Yahweh, quand tu sortis de Séïr, quand tu t''avanças des campagnes d''Edom, la terre trembla, les cieux mêmes se fondirent, et les nuées se fondirent en eau.'),
('jg',5,5,'crampon1923','Devant Yahweh s''ébranlèrent les montagnes, ce Sinaï, devant Yahweh, le Dieu d''Israël.'),
('jg',5,6,'crampon1923','Aux jours de Samgar, fils d''Anath, aux jours de Jahel, les routes étaient désertes, et les voyageurs prenaient des sentiers détournés.'),
('jg',5,7,'crampon1923','Les campagnes étaient dans l''abandon en Israël, jusqu''à ce que je me sois levée, moi Débora, que je me sois levée, une mère en Israël.'),
('jg',5,8,'crampon1923','On choisissait des dieux nouveaux; alors la guerre était aux portes, et l''on ne voyait ni bouclier ni lance chez quarante milliers en Israël!'),
('jg',5,9,'crampon1923','Mon cœur s''élance vers les conducteurs d''Israël, vers ceux du peuple qui se sont offerts: Bénissez Yahweh!'),
('jg',5,10,'crampon1923','Vous qui montez de blanches ânesses, qui vous asseyez sur des tapis, et vous qui parcourez les chemins, chantez!'),
('jg',5,11,'crampon1923','Que de leur voix les archers, près des abreuvoirs, célèbrent les justices de Yahweh, les justices envers ses campagnes en Israël! Alors le peuple de Yahweh est descendu dans ses portes.'),
('jg',5,12,'crampon1923','Eveille-toi, éveille-toi, Débora! Eveille-toi, éveille-toi, dis au cantique! Lève-toi, Barac, et fais tes prisonniers, fils d''Abinoëm!'),
('jg',5,13,'crampon1923','En ce moment descends, reste des nobles du peuple! Yahweh, descends vers moi parmi ces héros!'),
('jg',5,14,'crampon1923','D''Ephraïm sont venus ceux qui ont leur racine en Amalec; derrière toi, Benjamin s''est joint à tes troupes; de Machir, des chefs sont descendus; de Zabulon des conducteurs, avec le bâton du scribe.'),
('jg',5,15,'crampon1923','Les princes d''Issachar sont avec Débora, Issachar est à côté de Barac; dans la plaine il est envoyé sur ses pas. Près des ruisseaux de Ruben, il y eut de grandes résolutions du cœur:'),
('jg',5,16,'crampon1923','Pourquoi es-tu resté au milieu de tes pâturages, à écouter le chalumeau de tes pâtres? Près des ruisseaux de Ruben, il y eut de grandes résolutions du cœur!'),
('jg',5,17,'crampon1923','Galaad n''a pas quitté sa demeure, au delà du Jourdain; et Dan, pourquoi s''est-il tenu dans ses vaisseaux? Aser est resté tranquille sur le rivage de la mer, et il est demeuré dans ses ports.'),
('jg',5,18,'crampon1923','Mais Zabulon est un peuple qui expose son âme à la mort, ainsi que Nephtali, sur ses hauts plateaux.'),
('jg',5,19,'crampon1923','Les rois sont venus, ils ont livré bataille; alors ils ont livré bataille, les rois de Chanaan, à Thanac, au bord des eaux de Mageddo; ils n''ont pas remporté un seul lingot d''argent.'),
('jg',5,20,'crampon1923','Du ciel on a combattu pour nous, de leurs sentiers les étoiles ont combattu contre Sisara.'),
('jg',5,21,'crampon1923','Le torrent de Cison a roulé leurs cadavres. le torrent des anciens temps, le torrent de Cison. — O mon âme, avance hardiment! —'),
('jg',5,22,'crampon1923','Alors retentirent les sabots des chevaux, dans la course, la course rapide de leurs guerriers.'),
('jg',5,23,'crampon1923','Maudissez Méroz, dit l''ange de Yahweh, maudissez, maudissez ses habitants! Car ils ne sont pas venus au secours de Yahweh, au secours de Yahweh, avec les vaillants.'),
('jg',5,24,'crampon1923','Bénie soit entre les femmes Jahel, femme de Héber, le Cinéen; entre les troupes qui habitent sous la tente bénie soit-elle!'),
('jg',5,25,'crampon1923','Il demanda de l''eau, elle donna du lait; dans la coupe d''honneur, elle offrit le lait le plus pur.'),
('jg',5,26,'crampon1923','D''une main elle saisit le pieu, et de sa droite, le marteau de l''ouvrier. Elle frappe Sisara, elle lui brise la tête, elle fracasse et transperce sa tempe;'),
('jg',5,27,'crampon1923','à ses pieds, il s''affaisse, il tombe, il est étendu; à ses pieds il s''affaisse, il tombe: là où il s''affaisse, là il gît inanimé.'),
('jg',5,28,'crampon1923','Par la fenêtre, à travers le treillis, elle regarde, la mère de Sisara, et pousse des cris: " Pourquoi son char tarde-t-il à venir? Pourquoi est-elle si lente la marche de ses chariots? "'),
('jg',5,29,'crampon1923','Les plus avisées de ses dames lui répondent, et elle se répète à elle-même leurs paroles:'),
('jg',5,30,'crampon1923','" N''ont-ils pas trouvé, ne se partagent-ils pas le butin? Une jeune fille, deux jeunes filles pour chaque guerrier; des vêtements de couleur pour butin à Sisara, des vêtements de couleur variée pour butin; un vêtement de couleur, deux vêtements de couleur variée, pour les épaules de l''épouse! "'),
('jg',5,31,'crampon1923','Qu''ainsi périssent tous tes ennemis, ô Yahweh! Et que ceux qui l''aiment soient comme le soleil, quand il se lève dans sa force!'),
('jg',5,32,'crampon1923','Le pays fut en repos pendant quarante ans.'),
('jg',6,1,'crampon1923','Les enfants d''Israël firent ce qui est mal aux yeux de Yahweh, et Yahweh les livra entre les mains de Madian, pendant sept ans.'),
('jg',6,2,'crampon1923','La main de Madian fut puissante contre Israël. A cause de Madian, les enfants d''Israël se firent les antres qui sont dans les montagnes, les cavernes et les hauteurs fortifiées.'),
('jg',6,3,'crampon1923','Quand Israël avait semé, Madian montait avec Amalec et les fils de l''Orient, et ils marchaient contre lui.'),
('jg',6,4,'crampon1923','Campés en face d''Israël, ils dévastaient les productions de le terre jusque prés de Gaza, et ne laissaient aucune subsistance en Israël, ni brebis, ni bœufs, ni ânes.'),
('jg',6,5,'crampon1923','Car ils montaient avec leurs troupeaux et leurs tentes, et venaient nombreux comme des nuées de sauterelles; eux et leurs chameaux étaient innombrables, et ils venaient dans le pays pour le dévaster.'),
('jg',6,6,'crampon1923','Israël fut très affaibli à cause de Madian, et les enfants d''Israël crièrent vers Yahweh.'),
('jg',6,7,'crampon1923','Lorsque les enfants d''Israël eurent crié vers Yahweh au sujet de Madian,'),
('jg',6,8,'crampon1923','Yahweh envoya un prophète aux enfants d''Israël. Il leur dit: " Ainsi parle Yahweh le Dieu d''Israël: Je vous ai fait monter de l''Egypte, et je vous ai fait sortir de la maison de servitude.'),
('jg',6,9,'crampon1923','Je vous ai délivrés de la main des Egyptiens et de la main de tous vos oppresseurs; je les ai chassés devant vous, et je vous ai donné leur pays.'),
('jg',6,10,'crampon1923','Je vous ai dit: je suis Yahweh, votre Dieu; vous ne craindrez point les dieux des Amorrhéens dans le pays desquels vous habitez. Mais vous n''avez pas écouté ma voix. "'),
('jg',6,11,'crampon1923','Et l''Ange de Yahweh vint, et il s''assit sous le térébinthe d''Ephra, qui apporterait à Joas, de la famille d''Abiéser. Gédéon, son fils, battait le froment dans le pressoir, pour le mettre à l''abri de Madian.'),
('jg',6,12,'crampon1923','L''Ange de Yahweh lui apparut et lui dit: " Yahweh est avec toi, vaillant héros. "'),
('jg',6,13,'crampon1923','Gédéon lui dit: " Ah! mon seigneur, si Yahweh est avec nous, pourquoi toutes ces choses nous sont-elles arrivées? Et où sont tous ses prodiges que nos pères nous ont racontés, en disant: Yahweh ne nous a-t-il pas fait monter de l''Egypte? Et maintenant Yahweh nous abandonne et nous livre entre les mains de Madian. "'),
('jg',6,14,'crampon1923','Yahweh se tourna vers lui et dit: " Va avec cette force que tu as, et délivre Israël de la main de Madian; ne t''ai-je pas envoyé? "'),
('jg',6,15,'crampon1923','Gédéon lui dit: " Ah! Seigneur, avec quoi délivrerai-je Israël? Voici, ma famille est la plus pauvre en Manassé, et je suis le plus petit dans la maison de mon père. "'),
('jg',6,16,'crampon1923','Yahweh lui dit: " Je serai avec toi, et tu battras Madian comme un seul homme. "'),
('jg',6,17,'crampon1923','Gédéon lui dit: " Si j''ai trouvé grâce à vos yeux, donnez-moi un signe que c''est vous qui me parlez.'),
('jg',6,18,'crampon1923','Ne vous éloignez point d''ici jusqu''à ce que je revienne auprès de vous, que j''apporte mon offrande et que je la dépose devant vous. " Et Yahweh dit: " Je resterai jusqu''à ce que tu reviennes. "'),
('jg',6,19,'crampon1923','Gédéon, étant entré, apprêta un chevreau et, avec un épha de farine, il fit des pains sans levain; puis, ayant mis la chair dans une corbeille et le jus dans un vase, il les lui apporta sous le térébinthe et les lui offrit.'),
('jg',6,20,'crampon1923','L''Ange de Yahweh lui dit: " Prends la chair et les pains sans levain, pose-les sur ce rocher, et verse le jus. " Et il fit ainsi.'),
('jg',6,21,'crampon1923','L''Ange de Yahweh étendit l''extrémité du bâton qu''il avait à la main, et toucha la chair et les pains sans levain. Aussitôt le feu s''éleva du rocher, et consuma la chair et les pains sans levain, et l''Ange de Yahweh disparut à ses yeux.'),
('jg',6,22,'crampon1923','Gédéon vit que c''était l''Ange de Yahweh et Gédéon dit: " Malheur à moi, Seigneur Yahweh, car j''ai vu l''Ange de Yahweh face à face. "'),
('jg',6,23,'crampon1923','Yahweh lui dit: " Sois en paix, ne crains point, tu ne mourras pas. "'),
('jg',6,24,'crampon1923','Gédéon bâtit là un autel à Yahweh et l''appela: " Yahweh-Schalôm; " cet autel existe encore aujourd''hui à Ephra d''Abiéser.'),
('jg',6,25,'crampon1923','Cette nuit-là, Yahweh dit à Gédéon: " Prends le jeune taureau de ton père, et le second taureau de sept ans. Renverse l''autel de Baal qui est à ton père, et coupe l''aschéra qui est auprès.'),
('jg',6,26,'crampon1923','Tu bâtiras ensuite, au sommet de ce lieu fort, un autel à Yahweh, ton Dieu, et tu le disposeras; tu prendras le second taureau et tu offriras un holocauste avec le bois de l''aschéra que tu auras coupée. "'),
('jg',6,27,'crampon1923','Gédéon prit dix hommes parmi ses serviteurs, et exécuta ce que Yahweh lui avait dit: mais, comme il n''osait le faire de jour par crainte de la maison de son père et des gens de la ville, il le fit de nuit.'),
('jg',6,28,'crampon1923','Lorsque les gens de la ville se levèrent le lendemain matin, voici que l''autel de Baal était renversé, que l''aschéra qui était auprès était coupée, et que le second taureau était offert en holocauste sur l''autel récemment bâti.'),
('jg',6,29,'crampon1923','Ils se dirent l''un à l''autre: " Qui a fait cela? " et ils s''informèrent et firent des recherches. On leur dit: " C''est Gédéon, fils de Joas, qui a fait cela. "'),
('jg',6,30,'crampon1923','Alors les gens de la ville dirent à Joas: " Fais sortir ton fils et qu''il meure, car il a renversé l''autel de Baal et coupé l''aschéra qui était auprès. "'),
('jg',6,31,'crampon1923','Joas dit à tous ceux qui se tenaient là contre lui: " Est-ce à vous de prendre parti pour Baal? Ou bien est-ce à vous de le secourir? Quiconque prendra parti pour Baal sera mis à mort avant demain matin. Si Baal est Dieu, que lui-même prenne en main sa cause, puisqu''on a renversé son autel! "'),
('jg',6,32,'crampon1923','En ce jour, un donna à Gédéon le nom de Jérobaal, en disant: " Que Baal se défende contre lui, puisqu''il a renversé son autel! "'),
('jg',6,33,'crampon1923','Tout Madian, Amalec et les fils de l''Orient se rassemblèrent et, ayant passé le Jourdain, ils campèrent dans la plaine de Jezraël.'),
('jg',6,34,'crampon1923','L''Esprit de Yahweh revêtit Gédéon; il sonna de la trompette, et les Abiésérites s''assemblèrent pour marcher à sa suite.'),
('jg',6,35,'crampon1923','Il envoya des messagers dans tout Manassé, qui s''assembla aussi pour le suivre. Il envoya des messagers dans Aser, dans Zabulon et dans Nephtali, et ils montèrent à leur rencontre.'),
('jg',6,36,'crampon1923','Gédéon dit à Dieu: " Si vous voulez sauver Israël par ma main, comme vous l''avez dit,'),
('jg',6,37,'crampon1923','voici, je mettrai une toison de laine sur l''aire: si la toison seule se couvre de rosée, et que tout le sol alentour reste sec, je connaîtrai que vous délivrerez Israël par ma main, comme vous l''avez dit. "'),
('jg',6,38,'crampon1923','Et il arriva ainsi. Le jour suivant, s''étant levé de bon matin, il pressa la toison, et en fit sortir la rosée, plein une coupe d''eau.'),
('jg',6,39,'crampon1923','Gédéon dit à Dieu: " Que votre colère ne s''enflamme pas contre moi; que je puisse encore parler une fois: je voudrais une fois encore seulement faire une épreuve avec la toison: que la toison seule reste sèche, et que la rosée tombe sur tout le sol alentour. "'),
('jg',6,40,'crampon1923','Et Dieu fit ainsi cette nuit-là: la toison seule resta sèche, et tout le sol se couvrit de rosée.'),
('jg',7,1,'crampon1923','Jérobaal, qui est Gédéon, avec tout le peuple qui était avec lui, se leva de bon matin et alla camper au-dessus de la source de Harad. Le camp de Madian était au nord de celui de Gédéon, vers la colline de Moré, dans la plaine.'),
('jg',7,2,'crampon1923','Yahweh dit à Gédéon: " Le peuple que tu as avec toi est trop nombreux pour que je livre Madian entre ses mains, de peur qu''Israël n''en tire gloire contre moi, en disant: C''est ma main qui m''a délivré.'),
('jg',7,3,'crampon1923','Fais donc publier ceci aux oreilles du peuple: Que celui qui a peur et qui tremble s''en retourne et se retire de la montagne de Gelboé. " Vingt-deux mille hommes parmi le peuple s''en retournèrent, et il en resta dix mille.'),
('jg',7,4,'crampon1923','Yahweh dit à Gédéon: " Le peuple est encore trop nombreux. Fais-les descendre près de l''eau, et là je t''en ferai un triage. Celui dont je te dirai: Qu''il aille avec toi, ira avec toi; et celui dont je te dirai: Qu''il n''aille pas avec toi, n''ira pas avec toi. "'),
('jg',7,5,'crampon1923','Gédéon fit descendre le peuple près de l''eau, et Yahweh dit à Gédéon: " Tous ceux qui laperont l''eau avec la langue, comme lape le chien, mets-les à part; de même tous ceux qui se mettront à genoux pour boire. "'),
('jg',7,6,'crampon1923','Ceux qui lapèrent l''eau dans leur main, en la portant à leur bouche, furent au nombre de trois cents hommes; tout le reste du peuple s''était mis à genoux pour boire.'),
('jg',7,7,'crampon1923','Et Yahweh dit à Gédéon: " C''est avec ces trois cents hommes qui ont lapé que je vous sauverai et que je livrerai Madian entre tes mains; que tout le reste du peuple s''en aille chacun chez soi. "'),
('jg',7,8,'crampon1923','Les trois cents prirent des vivres du peuple et ses trompettes; puis Gédéon renvoya tout le reste des hommes d''Israël chacun dans sa tente, et il garda les trois cents hommes. Le camp des Madianites était au-dessous de lui, dans la plaine.'),
('jg',7,9,'crampon1923','Pendant cette nuit, Yahweh dit à Gédéon: " Lève-toi, descends au camp, car je l''ai livré entre tes mains.'),
('jg',7,10,'crampon1923','Si tu crains de l''attaquer, descends avec Phara, ton serviteur;'),
('jg',7,11,'crampon1923','tu écouteras ce qu''ils disent, et ensuite tes mains seront fortifiées et tu descendras sans crainte au camp. " Il descendit avec Phara, son serviteur, jusqu''aux avant-postes du camp.'),
('jg',7,12,'crampon1923','— Madian, Amalec et tous les fils de l''Orient étaient répandus dans la plaine, nombreux comme les sauterelles, et leurs chameaux étaient sans nombre comme le sable sur le bord de la mer. —'),
('jg',7,13,'crampon1923','Gédéon arriva, et voici qu''un homme racontait à son camarade un songe; il disait: " J''ai eu un songe et voici: un pain d''orge roulait dans le camp de Madian; il vint jusqu''à la tente, la heurta, et elle tomba; il l''a renversée sens dessus dessous, et la tente est tombée. "'),
('jg',7,14,'crampon1923','Son camarade répondit et dit: " Ce n''est pas autre chose que l''épée de Gédéon, fils de Joas, homme d''Israël; Dieu a livré entre ses mains Madian et tout le camp. "'),
('jg',7,15,'crampon1923','Lorsque Gédéon eut entendu le récit du songe et son explication, il se prosterna et, étant revenu au camp d''Israël, il dit: " Levez-vous, car Yahweh a livré entre nos mains le camp de Madian. "'),
('jg',7,16,'crampon1923','Il divisa en trois colonnes les trois cents hommes, et leur remit à tous des trompettes et des cruches vides, avec des flambeaux dans les cruches,'),
('jg',7,17,'crampon1923','et il leur dit: " Vous me regarderez, et vous ferez comme moi. Dès que j''arriverai aux abords du camp, vous ferez ce que je ferai.'),
('jg',7,18,'crampon1923','Quand je sonnerai de la trompette, moi et tous ceux qui sont avec moi, vous aussi vous sonnerez de la trompette tout autour du camp, et vous direz: Pour Yahweh et pour Gédéon! "'),
('jg',7,19,'crampon1923','Gédéon et les cent hommes qui étaient avec lui arrivèrent aux abords du camp au commencement de la veille du milieu, comme on venait de relever les sentinelles; ils sonnèrent de la trompette et brisèrent les cruches qu''ils avaient à la main.'),
('jg',7,20,'crampon1923','Alors les trois corps sonnèrent de la trompette et brisèrent les cruches et, saisissant les flambeaux de la main gauche, et de la droite les trompettes pour en sonner, ils s''écrièrent: " Epée pour Yahweh et pour Gédéon! "'),
('jg',7,21,'crampon1923','Ils restèrent chacun à sa place autour du camp; et tout le camp se mit à courir, à crier et à fuir.'),
('jg',7,22,'crampon1923','Pendant que les trois cents hommes sonnaient de la trompette, Yahweh fit tourner aux Madianites l''épée les uns contre les autres et contre tout le camp. Le camp s''enfuit jusqu''à Beth-Setta vers Saréra, jusqu''au bord d''Abel-Méhula, près de Tebbath.'),
('jg',7,23,'crampon1923','Les hommes d''Israël se rassemblèrent, ceux de Nephthali, d''Aser et de tout Manassé, et ils poursuivirent Madian.'),
('jg',7,24,'crampon1923','Gédéon envoya des messagers dans toute la montagne d''Ephraïm, pour dire: " Descendez à la rencontre de Madian, et occupez avant eux le passage des eaux jusqu''à Bethbéra, ainsi que les gués du Jourdain. " Tous les hommes d''Ephraïm se rassemblèrent, et ils occupèrent les eaux jusqu''à Bethbéra, ainsi que les gués du Jourdain.'),
('jg',7,25,'crampon1923','Ayant saisi deux princes de Madian, Oreb et Zeb, ils tuèrent Oreb au rocher d''Oreb, et ils tuèrent Zeb au pressoir de Zeb. Ils poursuivirent Madian, et ils apportèrent les têtes d''Oreb et de Zeb à Gédéon, de l''autre côté du Jourdain.'),
('jg',8,1,'crampon1923','Les hommes d''Ephraïm dirent à Gédéon: " Que signifie ta conduite envers nous, de ne pas nous appeler quand tu allais combattre Madian? " Et ils le querellèrent avec violence.'),
('jg',8,2,'crampon1923','Gédéon leur répondit: " Qu''ai-je fait en comparaison de vous? Le grappillage d''Ephraïm ne vaut-il pas mieux que la vendange d''Abiéser?'),
('jg',8,3,'crampon1923','C''est entre vos mains que Yahweh a livré les princes de Madian, Oreb et Zeb. Que pouvais-je faire en comparaison de vous? " Lorsqu''il eut ainsi parlé, leur colère contre lui s''apaisa.'),
('jg',8,4,'crampon1923','Gédéon arriva au Jourdain, et il le passa, lui et les trois cents hommes qui étaient avec lui, fatigués et continuant à poursuivre.'),
('jg',8,5,'crampon1923','Il dit aux gens de Soccoth: " Donnez, je vous prie, des galettes de pain au peuple qui m''accompagne, car ils sont fatigués, et je suis à la poursuite de Zébée et de Salmana, rois de Madian. "'),
('jg',8,6,'crampon1923','Les chefs de Soccoth répondirent: " Le poing de Zébée et de Salmana est-il déjà dans ta main, pour que nous donnions du pain à ta troupe? "'),
('jg',8,7,'crampon1923','Gédéon leur dit: " Eh bien, lorsque Yahweh aura livré entre mes mains Zébée et Salmana, je déchirerai votre chair avec des épines du désert et des chardons. "'),
('jg',8,8,'crampon1923','De là il monta à Phanuel, et il adressa aux gens de Phanuel la même parole. Les gens de Phanuel lui répondirent comme avaient répondu les gens de Soccoth.'),
('jg',8,9,'crampon1923','Et il dit aux gens de Phanuel: " Quand je reviendrai vainqueur, je raserai cette tour. "'),
('jg',8,10,'crampon1923','Zébée et Salmana étaient à Carcor, et leur armée avec eux, quinze mille hommes environ, tous ceux qui étaient restés de l''armée entière des fils de l''Orient; car il était tombé cent vingt mille hommes tirant l''épée.'),
('jg',8,11,'crampon1923','Gédéon monta par le chemin de ceux qui habitent sous des tentes, à l''orient de Nobé et de Jegbaa, et il battit le camp, qui se croyait en sûreté.'),
('jg',8,12,'crampon1923','Zébée et Salmana prirent la fuite; il les poursuivit et s''empara des deux rois de Madian, Zébée et Salmana, et il mit en déroute tout le camp.'),
('jg',8,13,'crampon1923','Gédéon, fils de Joas, revint de la bataille par la montée de Harès.'),
('jg',8,14,'crampon1923','Ayant saisi un jeune homme d''entre les gens de Soccoth, il l''interrogea, et celui-ci lui écrivit les noms des chefs et des anciens de Soccoth, soixante-dix-sept hommes.'),
('jg',8,15,'crampon1923','Alors Gédéon vint vers les gens de Soccoth et dit: " Voici Zébée et Salmana, au sujet desquels vous m''avez insulté, en disant: Le poing de Zébée et de Salmana est-il déjà dans ta main pour que nous donnions du pain à tes gens fatigués? "'),
('jg',8,16,'crampon1923','Il saisit les anciens de la ville et, ayant pris des épines du désert et des ronces, il en châtia les gens de Soccoth.'),
('jg',8,17,'crampon1923','Il rasa aussi la tour de Phanuel, et tua les hommes de la ville.'),
('jg',8,18,'crampon1923','Il dit à Zébée et à Salmana: " Comment étaient les hommes que vous avez tués au Thabor? " ils dirent: " Ils étaient comme toi; chacun d''eux avait l''air d''un fils de roi. "'),
('jg',8,19,'crampon1923','Il dit: " C''étaient mes frères, fils de ma mère: Yahweh est vivant! si vous les aviez laissés vivre, je ne vous tuerais pas. "'),
('jg',8,20,'crampon1923','Et il dit à Jéther, son premier-né: " Lève-toi, tue-les. " Mais le jeune homme ne tira pas son épée, parce qu''il avait peur, car il était encore un jeune garçon.'),
('jg',8,21,'crampon1923','Zébée et Salmana dirent: " Lève-toi toi-même et tombe sur nous; car tel est l''homme, telle est sa force. " Gédéon se leva et tua Zébée et Salmana; et il prit les croissants qui étaient aux cous de leurs chameaux.'),
('jg',8,22,'crampon1923','Les hommes d''Israël dirent à Gédéon: " Règne sur nous, toi et ton fils, et le fils de ton fils, car tu nous as délivrés des mains de Madian. "'),
('jg',8,23,'crampon1923','Gédéon leur dit: " Je ne dominerai point sur vous et mon fils ne dominera point sur vous: c''est Yahweh qui dominera sur vous. "'),
('jg',8,24,'crampon1923','Gédéon leur dit: " J''ai une demande à vous faire: donnez-moi chacun les anneaux de votre butin. " — Les ennemis avaient des anneaux d''or, car ils étaient Ismaélites. —'),
('jg',8,25,'crampon1923','Ils dirent: " Nous les donnerons volontiers. " Et ils étendirent un manteau, sur lequel chacun jeta les anneaux de son butin.'),
('jg',8,26,'crampon1923','Le poids des anneaux d''or qu''avait demandés Gédéon fut de mille sept cents sicles d''or, sans les croissants, les pendants d''oreilles et les vêtements de pourpre que portaient les rois de Madian, et sans les colliers qui étaient aux cous de leurs chameaux.'),
('jg',8,27,'crampon1923','Avec cet or, Gédéon fit un éphod, et il le déposa dans sa ville, à Ephra. Tout Israël alla se prostituer là après cet éphod, et il fut un piège pour Gédéon et pour sa maison.'),
('jg',8,28,'crampon1923','Madian fut humilié devant les enfants d''Israël et il ne leva plus la tête; et le pays fut en repos pendant quarante ans, aux jours de Gédéon.'),
('jg',8,29,'crampon1923','Jérobaal, fils de Joas, s''en retourna et demeura dans sa maison.'),
('jg',8,30,'crampon1923','Gédéon eut soixante-dix fils, issus de lui, car il eut de nombreuses femmes.'),
('jg',8,31,'crampon1923','Sa concubine, qui était à Sichem, lui enfanta, elle aussi, un fils qui reçut le tient d''Abimélech.'),
('jg',8,32,'crampon1923','Gédéon, fils de Joas, mourut dans une heureuse vieillesse, et il fut enterré dans le sépulcre de Joas, son père, à Ephra d''Abiéser.'),
('jg',8,33,'crampon1923','Lorsque Gédéon fut mort, les enfants d''Israël se prostituèrent de nouveau aux Baals, et ils prirent Baal-Berith pour leur dieu.'),
('jg',8,34,'crampon1923','Les enfants d''Israël ne se souvinrent plus de Yahweh, leur Dieu, qui les avait délivrés de la main de tous leurs ennemis autour d''eux;'),
('jg',8,35,'crampon1923','et ils ne montrèrent point d''attachement à la maison de Jérobaal-Gédéon, selon tout le bien qu''il avait fait à Israël.'),
('jg',9,1,'crampon1923','Abimélech, fils de Jérobaal, se rendit à Sichem vers les frères de sa mère, et il leur adressa ces paroles, ainsi qu''à toute la famille de la maison du père de sa mère:'),
('jg',9,2,'crampon1923','" Dites, je vous prie, aux oreilles de tous les habitants de Sichem: Lequel vaut mieux pour vous que soixante-dix hommes, tous fils de Jérobaal, dominent sur vous, ou qu''un seul homme domine sur vous? Souvenez-vous que je suis vos os et votre chair. "'),
('jg',9,3,'crampon1923','Les frères de sa mère ayant répété à son sujet toutes ces paroles aux oreilles de tous les habitants de Sichem, le cœur de ces derniers s''inclina vers Abimélech, car ils se disaient: " C''est notre frère. "'),
('jg',9,4,'crampon1923','Ils lui donnèrent soixante-dix sicles d''argent, tirés de la maison de Baal-Berith, et Abimélech s''en servit pour soudoyer des gens de rien et des aventuriers, qui s''attachèrent à lui.'),
('jg',9,5,'crampon1923','Il vint dans la maison de son père à Ephra, et il tua ses frères, fils de Jérobaal, au nombre de soixante-dix, sur une même pierre; il n''échappa que Joatham, le plus jeune fils de Jerobaal, parce qu''il s''était caché.'),
('jg',9,6,'crampon1923','Alors tous les habitants de Sichem et toute la maison de Mello s''assemblèrent; ils vinrent et proclamèrent roi Abimélech, prés du térébinthe du monument qui se trouve à Sichem.'),
('jg',9,7,'crampon1923','Lorsque Joatham en eut été informé, il alla se placer sur le sommet du mont Garizim et, élevant la voix, il leur cria en disant: " Ecoutez-moi, habitants de Sichem, afin que Dieu vous écoute!'),
('jg',9,8,'crampon1923','Les arbres se mirent en chemin pour oindre un roi qui les commandât. Ils dirent à l''olivier: Règne sur nous.'),
('jg',9,9,'crampon1923','Mais l''olivier leur dit: Renoncerais-je à mon huile, qui fait ma gloire devant Dieu et devant les hommes, pour aller me balancer au-dessus des autres arbres?'),
('jg',9,10,'crampon1923','Et les arbres dirent au figuier: Viens, toi, règne sur nous.'),
('jg',9,11,'crampon1923','Mais le figuier leur dit: Renoncerais-je à ma douceur et à mon excellent fruit, pour aller me balancer au-dessus des autres arbres?'),
('jg',9,12,'crampon1923','Et les arbres dirent à la vigne: Viens, toi, règne sur nous.'),
('jg',9,13,'crampon1923','Mais la vigne leur dit: Renoncerais-je à mon vin, qui réjouit Dieu et les hommes, pour aller me balancer au-dessus des autres arbres?'),
('jg',9,14,'crampon1923','Alors tous les arbres dirent au buisson d''épines: Viens, toi, règne sur nous.'),
('jg',9,15,'crampon1923','Et le buisson d''épines dit aux arbres: Si vraiment vous voulez m''oindre pour votre roi, venez, confiez-vous à mon ombrage; sinon, qu''un feu sorte du buisson d''épines et dévore les cèdes du Liban!...'),
('jg',9,16,'crampon1923','Maintenant, si c''est avec équité et droiture que vous avez agi en faisant roi Abimélech, si vous vous êtes bien conduits envers Jérobaal et sa maison, et si vous l''avez traité selon le mérite de ses mains,'),
('jg',9,17,'crampon1923','— car mon père a combattu pour vous, il a exposé sa vie et vous a délivrés de la main de Madian;'),
('jg',9,18,'crampon1923','et vous, vous vous êtes levés aujourd''hui contre la maison de mon père, vous avez tué ses fils, au nombre de soixante-dix, sur une même pierre, et vous avez établi roi sur les hommes de Sichem Abimélech, fils de sa servante, parce qu''il est votre frère, —'),
('jg',9,19,'crampon1923','si c''est avec équité et droiture que vous avez agi en ce jour envers Jérobaal et sa maison, eh bien, qu''Abimélech fasse votre joie, et que vous fassiez la sienne aussi!'),
('jg',9,20,'crampon1923','Sinon, qu''un feu sorte d''Abimélech et dévore les habitants de Sichem et la maison de Mello, et qu''un feu sorte des habitants de Sichem et de la maison de Mello et dévore Abimélech! "'),
('jg',9,21,'crampon1923','Joatham se retira et prit la fuite; il se rendit à Béra et il y demeura, par crainte d''Abimélech, son frère.'),
('jg',9,22,'crampon1923','Abimélech domina trois ans sur Israël.'),
('jg',9,23,'crampon1923','Et Dieu envoya un esprit mauvais entre Abimélech et les habitants de Sichem, et les habitants de Sichem devinrent infidèles à Abimélech:'),
('jg',9,24,'crampon1923','afin que le crime commis sur les soixante-dix fils de Jérobaal fût vengé et que leur sang retombe sur Abimélech, leur frère, qui les avait tués, et sur les hommes de Sichem qui l''avaient aidé à tuer ses frères.'),
('jg',9,25,'crampon1923','Les hommes de Sichem placèrent en embuscade contre lui, sur les sommets des montagnes, des gens qui dépouillaient tous ceux qui passaient près d''eux sur le chemin; et cela fut rapporté à Abimélech.'),
('jg',9,26,'crampon1923','Gaal, fils d''Obed, vint avec ses frères, et ils passèrent à Sichem. Les hommes de Sichem prirent confiance en lui.'),
('jg',9,27,'crampon1923','Ils sortirent dans la campagne, vendangèrent leurs vignes, foulèrent les raisins et firent une fête; puis, étant entrés dans la maison de leur dieu, ils mangèrent et burent, et ils maudirent Abimélech.'),
('jg',9,28,'crampon1923','Et Gaal, fils d''Obed, dit: " Qui est Abimélech, et qui est Sichem, pour que nous le servions? N''est-il pas fils de Jérobaal, et Zébul n''est-il pas son officier? Servez les hommes d''Emor, père de Sichem; mais nous, pourquoi servirions-nous Abimélech?'),
('jg',9,29,'crampon1923','Ah! que ne suis-je le chef de ce peuple! Je chasserais Abimélech. " Et il dit à Abimélech: " Renforce ton armée et sors! "'),
('jg',9,30,'crampon1923','Zébul, gouverneur de la ville, apprit les propos de Gaal, fils d''Obed, et sa colère s''enflamma.'),
('jg',9,31,'crampon1923','Il envoya secrètement des messagers à Abimélech, pour lui dire: " Voici que Gaal, fils d''Obed, est venu à Sichem avec ses frères, et voici qu''ils soulèvent la ville contre toi.'),
('jg',9,32,'crampon1923','Lève-toi de nuit, toi et le peuple qui est avec toi, et mets-toi en embuscade dans la campagne.'),
('jg',9,33,'crampon1923','Le matin, au lever du soleil, lève-toi et fonds sur la ville; et lorsque Gaal et le peuple qui est avec lui sortiront contre toi, tu lui feras selon ce que l''occasion te permettra. "'),
('jg',9,34,'crampon1923','Abimélech et tout le peuple qui était avec lui se levèrent de nuit, et ils se mirent en embuscade près de Sichem, divisés en quatre corps.'),
('jg',9,35,'crampon1923','Gaal, fils d''Obed, sortit, et il se plaça à l''entrée de la porte de la ville. Aussitôt Abimélech et tout le peuple qui était avec lui se levèrent de l''embuscade.'),
('jg',9,36,'crampon1923','En voyant le peuple, Gaal dit à Zébul: " Voici des gens qui descendent du sommet des montagnes. " Zébul lui répondit: " C''est l''ombre des montagnes que tu prends pour des hommes. "'),
('jg',9,37,'crampon1923','Gaal reprit la parole et dit: " Voici une troupe qui descend du milieu du pays, et un corps qui arrive par le chemin du chêne des devins. "'),
('jg',9,38,'crampon1923','Zébul lui répondit: " Où donc est ta bouche avec laquelle tu disais: Qui est Abimélech, pour que nous le servions? N''est-ce point là le peuple que tu méprisais? Sors maintenant et livre-lui bataille! "'),
('jg',9,39,'crampon1923','Gaal fit une sortie, à la tête des hommes de Sichem, et livra bataille à Abimélech.'),
('jg',9,40,'crampon1923','Abimélech le poursuivit, et Gaal s''enfuit devant lui, et beaucoup de ses hommes tombèrent morts jusqu''à l''entrée de la porte.'),
('jg',9,41,'crampon1923','Abimélech s''arrêta à Ruma; et Zébul chassa Gaal et ses frères, qui ne purent plus rester à Sichem.'),
('jg',9,42,'crampon1923','Le lendemain, le peuple sortit dans la campagne. Abimélech en ayant été informé,'),
('jg',9,43,'crampon1923','prit sa troupe, la partagea en trois corps, et se mit en embuscade dans la campagne. Dès qu''il aperçut le peuple sortant de la ville, il se leva contre eux et les battit.'),
('jg',9,44,'crampon1923','Abimélech et les corps qui étaient avec lui se jetèrent en avant et se placèrent à l''entrée de la porte de la ville; deux de ces corps se jetèrent sur tous ceux qui étaient dans la campagne et les battirent.'),
('jg',9,45,'crampon1923','Et Abimélech donna l''assaut à la ville pendant toute la journée; il s''en empara et tua le peuple qui s''y trouvait; puis il rasa la ville et y sema du sel.'),
('jg',9,46,'crampon1923','A cette nouvelle, tous les hommes de la tour de Sichem se rendirent dans la forteresse de la maison du dieu Berith.'),
('jg',9,47,'crampon1923','Dès qu''on eut annoncé à Abimélech que tous les habitants de la tour de Sichem s''y étaient rassemblés,'),
('jg',9,48,'crampon1923','Abimélech monta sur le mont Selmon, lui et tout le peuple qui était avec lui. Abimélech prit en main une hache, coupa une branche d''arbre, la souleva et la mit sur son épaule. Il dit au peuple qui était avec lui: " Ce que vous m''avez vu faire, hâtez-vous de le faire comme moi. "'),
('jg',9,49,'crampon1923','Et tous les gens aussi coupèrent chacun une branche et suivirent Abimélech; ils placèrent les branches contre la forteresse, et ils la livrèrent au feu avec ceux qu''elle renfermait. Et tous les gens de la tour de Sichem périrent aussi, mille environ, hommes et femmes.'),
('jg',9,50,'crampon1923','De là, Abimélech marcha contre Thébés; il assiégea Thébés et s''en empara.'),
('jg',9,51,'crampon1923','Il y avait au milieu de la ville une forte tour où se réfugièrent tous les habitants de la ville, hommes et femmes; ayant fermé la porte sur eux, ils montèrent sur le toit de la tour.'),
('jg',9,52,'crampon1923','Abimélech vint jusqu''à la tour; il l''attaqua et s''approcha de la porte de la tour pour y mettre le feu.'),
('jg',9,53,'crampon1923','Alors une femme lança sur la tête d''Abimélech un morceau de meule de moulin et lui brisa le crâne.'),
('jg',9,54,'crampon1923','Il appela aussitôt le jeune homme qui portait ses armes, et lui dit: " Tire ton épée et donne-moi la mort, afin qu''on ne dise pas de moi: C''est une femme qui l''a tué. " Le jeune homme le transperça, et il mourut.'),
('jg',9,55,'crampon1923','Quand les hommes d''Israël virent qu''Abimélech était mort, ils s''en allèrent chacun dans sa maison.'),
('jg',9,56,'crampon1923','Ainsi Dieu fit retomber sur Abimélech le mal qu''il avait fait à son père, en tuant ses soixante-dix frères;'),
('jg',9,57,'crampon1923','et Dieu fit retomber sur la tête des gens de Sichem toute leur méchanceté. Ainsi s''accomplit sur eux la malédiction de Joatham, fils de Jérobaal.'),
('jg',10,1,'crampon1923','Après Abimélech, Thola, fils de Phua, fils de Dodo, homme d''Issachar, se leva pour délivrer Israël; il demeurait à Samir, dans la montagne d''Ephraïm.'),
('jg',10,2,'crampon1923','Il fut juge en Israël pendant vingt-trois ans; puis il mourut et fut enterré à Samir.'),
('jg',10,3,'crampon1923','Après lui se leva Jaïr, de Galaad, qui jugea Israël pendant vingt-deux ans.'),
('jg',10,4,'crampon1923','Il avait trente fils, qui montaient trente ânons, et qui possédaient trente villes appelées encore aujourd''hui Bourgs de Jaïr, et situées dans le pays de Galaad.'),
('jg',10,5,'crampon1923','Et Jaïr mourut, et il fut enterré à Camon.'),
('jg',10,6,'crampon1923','Les enfants d''Israël firent encore ce qui est mal aux yeux de Yahweh; ils servirent les Baals et les Astartés, les dieux de Syrie, les dieux de Sidon, les dieux de Moab, les dieux des fils d''Ammon et les dieux des Philistins, et ils abandonnèrent Yahweh et ne le servirent plus.'),
('jg',10,7,'crampon1923','La colère de Yahweh s''enflamma contre Israël, et il les vendit entre les mains des Philistins et entre les mains des fils d''Ammon.'),
('jg',10,8,'crampon1923','Ces derniers opprimèrent et écrasèrent les enfants d''Israël en cette année-là; et cette oppression dura dix-huit ans pour tous les enfants d''Israël qui habitaient de l''autre côté du Jourdain, dans le pays des Amorrhéens en Galaad.'),
('jg',10,9,'crampon1923','Les fils d''Ammon passèrent le Jourdain pour combattre aussi Juda, Benjamin et la maison d''Ephraïm; et Israël fut réduit à une grande détresse.'),
('jg',10,10,'crampon1923','Les enfants d''Israël crièrent vers Yahweh, en disant: " Nous avons péché contre vous, car nous avons abandonné notre Dieu et nous avons servi les Baals. "'),
('jg',10,11,'crampon1923','Yahweh dit aux enfants d''Israël: " Est-ce que je ne vous ai pas délivrés des Egyptiens, des Amorrhéens, des fils d''Ammon, des Philistins?'),
('jg',10,12,'crampon1923','Et lorsque les Sidoniens, Amalec et Maon vous ont opprimés, et que vous avez crié vers moi, ne vous ai-je pas sauvés de leurs mains?'),
('jg',10,13,'crampon1923','Mais vous, vous m''avez abandonné et vous avez servi d''autres dieux; c''est pourquoi je ne vous délivrerai plus.'),
('jg',10,14,'crampon1923','Allez, invoquez les dieux que vous vous êtes choisis; qu''ils vous délivrent au temps de votre détresse! "'),
('jg',10,15,'crampon1923','Les enfants d''Israël dirent à Yahweh: " Nous avons péché, traitez-nous tous comme il vous semblera bon. Seulement daignez nous délivrer en ce jour. "'),
('jg',10,16,'crampon1923','Et ils ôtèrent du milieu d''eux les dieux étrangers, et ils servirent Yahweh, et son âme ne put supporter les souffrances d''Israël.'),
('jg',10,17,'crampon1923','Les fils d''Ammon se rassemblèrent et campèrent en Galaad, et les enfants d''Israël se réunirent et campèrent à Maspha.'),
('jg',10,18,'crampon1923','Le peuple, les chefs de Galaad se dirent les uns aux autres: " Quel est l''homme qui commencera l''attaque contre les fils d''Ammon? Il deviendra chef de tous les habitants de Galaad. "'),
('jg',11,1,'crampon1923','Jephté, le Galaadite, était un vaillant guerrier. Il était fils d''une courtisane et c''est Galaad qui avait engendré Jephté.'),
('jg',11,2,'crampon1923','La femme de Galaad lui enfanta des fils, et les fils de cette femme grandirent et chassèrent Jephté, en lui disant: " Tu n''hériteras pas dans la maison de notre père, car tu es fils d''une autre femme. "'),
('jg',11,3,'crampon1923','Et Jephté s''enfuit loin de ses frères, et il habita dans le pays de Tob. Des gens de rien se rassemblèrent autour de Jephté, et ils faisaient avec lui des excursions.'),
('jg',11,4,'crampon1923','Quelque temps après, les fils d''Ammon firent la guerre à Israël.'),
('jg',11,5,'crampon1923','Pendant que les fils d''Ammon faisaient la guerre à Israël, les anciens de Galaad allèrent chercher Jephté au pays de Tob.'),
('jg',11,6,'crampon1923','Ils dirent à Jephté: " Viens, tu seras notre général, et nous combattrons les fils d''Ammon. "'),
('jg',11,7,'crampon1923','Jephté dit aux anciens de Galaad: " Ne m''avez-vous pas haï et chassé de la maison de mon père? Pourquoi venez-vous à moi, maintenant que vous êtes dans la détresse? "'),
('jg',11,8,'crampon1923','Les anciens de Galaad dirent à Jephté: " C''est à cause de cela que nous revenons à toi maintenant, pour que tu marches avec nous, que tu combattes les fils d''Ammon, et que tu sois notre chef, le chef de tous les habitants de Galaad. "'),
('jg',11,9,'crampon1923','Jephté répondit aux anciens de Galaad: " Si vous me ramenez pour combattre les fils d''Ammon, et que Yahweh les livre entre mes mains, je serai votre chef. "'),
('jg',11,10,'crampon1923','Les anciens de Galaad dirent à Jephté: " Que Yahweh soit témoin entre nous: nous ferons certainement ce que tu dis. "'),
('jg',11,11,'crampon1923','Et Jephté partit avec les anciens de Galaad. Le peuple l''établit sur lui pour chef et général, et Jephté répéta toutes ses paroles devant Yahweh à Maspha.'),
('jg',11,12,'crampon1923','Jephté envoya des messagers au roi des fils d''Ammon, pour lui dire: " Qu''y a-t-il entre moi et toi, que tu sois venu contre moi pour faire la guerre à mon pays? "'),
('jg',11,13,'crampon1923','Le roi des fils d''Ammon répondit aux messagers de Jephté: " C''est qu''Israël, lorsqu''il monta d''Egypte, s''empara de mon pays, depuis l''Arnon jusqu''au Jaboc et au Jourdain. Rends-le maintenant de bon gré. "'),
('jg',11,14,'crampon1923','Jephté envoya de nouveau des messagers au roi des fils d''Ammon,'),
('jg',11,15,'crampon1923','et il lui dit: " Ainsi parle Jephté: Israël ne s''est emparé ni du pays de Moab, ni du pays des fils d''Ammon.'),
('jg',11,16,'crampon1923','Car lorsqu''Israël monta d''Egypte, il marcha dans le désert jusqu''à la mer Rouge, et il arriva à Cadès.'),
('jg',11,17,'crampon1923','Alors Israël envoya des messagers au roi d''Edom, pour lui dire: Laisse-moi, je te prie, passer par ton pays; mais le roi d''Edom n''y consentit pas. Il en envoya aussi au roi de Moab, qui refusa également; et Israël resta à Cadés.'),
('jg',11,18,'crampon1923','Puis, marchant par le désert, il tourna le pays d''Edom et le pays de Moab, et arriva à l''orient du pays de Moab. Et ils campèrent au delà de l''Arnon, et ils ne vinrent pas sur la frontière de Moab, car l''Arnon est la frontière de Moab.'),
('jg',11,19,'crampon1923','De là, Israël envoya des messagers à Séhon, roi des Amorrhéens, roi de Hésebon; et Israël lui dit: Laisse-nous, je te prie, passer par ton pays jusqu''à notre lieu.'),
('jg',11,20,'crampon1923','Mais Séhon ne se fia pas assez à Israël pour le laisser passer sur son territoire. Séhon rassembla tout son peuple; ils campèrent à Jasa, et il combattit contre Israël.'),
('jg',11,21,'crampon1923','Et Yahweh, le Dieu d''Israël, livra Séhon et tout son peuple entre les mains d''Israël, qui les battit; et Israël s''empara de tout le pays des Amorrhéens qui habitaient dans cette contrée;'),
('jg',11,22,'crampon1923','ils s''emparèrent de tout le territoire des Amorrhéens, depuis l''Arnon jusqu''au Jaboc, et depuis le désert jusqu''au Jourdain.'),
('jg',11,23,'crampon1923','Maintenant que Yahweh, le Dieu d''Israël, a chassé les Amorrhéens devant son peuple d''Israël, toi tu chasserais celui-ci!'),
('jg',11,24,'crampon1923','Ce dont ton Dieu Chamos t''a mis en possession, ne le possèdes-tu pas? Et tout ce que Yahweh, notre Dieu, a mis devant nous en notre possession, nous ne le posséderions pas!'),
('jg',11,25,'crampon1923','Vaudrais-tu donc mieux que Balac, fils de Séphor, roi de Moab? A-t-il contesté avec Israël, ou lui a-t-il fait la guerre?'),
('jg',11,26,'crampon1923','Voilà trois cents ans qu''Israël habite à Hésebon et dans les villes de sa dépendance, à Aroër et dans les villes de sa dépendance, ainsi que dans toutes les villes qui sont sur les bords de l''Arnon; pourquoi ne les lui avez-vous pas enlevées pendant ce temps-là?'),
('jg',11,27,'crampon1923','Moi, je n''ai pas péché contre toi; mais toi, tu agis mal envers moi en me faisant la guerre. Que Yahweh, le Juge suprême, juge aujourd''hui entre les enfants d''Israël et les fils d''Ammon. "'),
('jg',11,28,'crampon1923','Le roi des fils d''Ammon, n''écouta pas les paroles que Jephté lui avait envoyé dire.'),
('jg',11,29,'crampon1923','L''Esprit de Yahweh fut sur Jephté. Il traversa Galaad et Manassé, et passa jusqu''à Maspha de Galaad; et de Maspha de Galaad il marcha contre les fils d''Ammon.'),
('jg',11,30,'crampon1923','Jephté fit un vœu à Yahweh, en disant:'),
('jg',11,31,'crampon1923','" Si vous livrez entre mes mains les fils d''Ammon, celui qui sortira des portes de ma maison à ma rencontre, quand je reviendrai heureusement de chez les fils d''Ammon, sera à Yahweh, et je l''offrirai en holocauste. "'),
('jg',11,32,'crampon1923','Jephté s''avança contre les fils d''Ammon, et Yahweh les livra entre ses mains.'),
('jg',11,33,'crampon1923','Il les battit depuis Aroër jusque vers Mennith, leur prenant vingt villes, et jusqu''à Abel-Keramin; ce fut une très grande défaite. Et les fils d''Ammon furent abaissés devant les enfants d''Israël.'),
('jg',11,34,'crampon1923','Jephté remonta dans sa maison à Maspha; et voici que sa fille sortit à sa rencontre avec des tambourins et des danses. C''était son unique enfant; hors d''elle, il n''avait ni fils ni fille.'),
('jg',11,35,'crampon1923','Dès qu''il la vit, il déchira ses vêtements et dit: " Ah! ma fille, tu me renverses et tu es parmi ceux qui me troublent. J''ai ouvert ma bouche à Yahweh, et je ne puis revenir en arrière. "'),
('jg',11,36,'crampon1923','Elle lui dit: " Mon père, tu as ouvert ta bouche à Yahweh; fais-moi selon ce qui est sorti de ta bouche, puisque Yahweh t''a vengé de tes ennemis, les fils d''Ammon. "'),
('jg',11,37,'crampon1923','Et elle dit à son père: " Que cette grâce seulement me soit accordée; laisse-moi libre pendant deux mois; je m''en irai, je descendrai pour aller sur les montagnes, et je pleurerai ma virginité avec mes compagnes. "'),
('jg',11,38,'crampon1923','Il répondit: " Va, " et il la laissa aller pour deux mois. Elle s''en alla, elle et ses compagnes, et elle pleura sa virginité sur les montagnes.'),
('jg',11,39,'crampon1923','Les deux mois écoulés, elle revint vers son père, et il accomplit à son égard le vœu qu''il avait fait; et elle n''avait pas connu d''homme. De là vint cette coutume en Israël:'),
('jg',11,40,'crampon1923','chaque année les filles d''Israël vont célébrer la fille de Jephté, le Galaadite, quatre jours par an.'),
('jg',12,1,'crampon1923','Les hommes d''Ephraïm, s''étant rassemblés, passèrent vers Saphon et dirent à Jephté: " Pourquoi es-tu allé combattre les fils d''Ammon, sans nous avoir appelés à marcher avec toi? Nous allons brûler sur toi ta maison. "'),
('jg',12,2,'crampon1923','Jephté leur répondit: " J''étais, moi et mon peuple, en grande contestation avec les fils d''Ammon; alors je vous ai appelés, mais vous ne m''avez pas délivré de leurs mains.'),
('jg',12,3,'crampon1923','Voyant que tu ne venais pas à mon secours, j''ai risqué ma vie et j''ai marché contre les fils d''Ammon; et Yahweh les a livrés entre mes mains. Pourquoi donc êtes-vous montés aujourd''hui vers moi, pour me faire la guerre? "'),
('jg',12,4,'crampon1923','Jephté rassembla tous les hommes de Galaad, et livra bataille à Ephraïm. Les hommes de Galaad battirent ceux d''Ephraïm, car ceux-ci avaient dit: " Vous n''êtes, ô Galaadites, que des fugitifs d''Ephraïm, au milieu d''Ephraïm et de Manassé! "'),
('jg',12,5,'crampon1923','Galaad s''empara des gués du Jourdain du côté d''Ephraïm, et quand l''un des fuyards d''Ephraïm disait: " Laissez-moi passer, " les hommes de Galaad lui demandaient: " Es-tu Ephraïmite? " Il répondait: " Non ".'),
('jg',12,6,'crampon1923','Ils lui disaient alors: " Eh bien, dis: Schibboleth. " Et il disait: " Sibboleth, " ne réussissant pas à bien prononcer. Ils le saisissaient alors et l''égorgeaient près des gués du Jourdain. Il périt en ce temps-là quarante-deux mille hommes d''Ephraïm.'),
('jg',12,7,'crampon1923','Jephté jugea Israël pendant six ans; puis Jephté le Galaadite mourut et fut enterré dans l''une des villes de Galaad.'),
('jg',12,8,'crampon1923','Après lui, Abesan, de Bethléem, fut juge en Israël.'),
('jg',12,9,'crampon1923','Il eut trente fils; il maria trente filles hors de sa maison, et il fit venir du dehors trente filles pour ses fils. Il fut juge en Israël pendant sept ans;'),
('jg',12,10,'crampon1923','ensuite Abesan mourant et fut enterré à Bethléem.'),
('jg',12,11,'crampon1923','Après lui, Ahialon, de Zabulon, fut juge en Israël; il fut juge en Israël pendant dix ans;'),
('jg',12,12,'crampon1923','puis Ahialon, de Zabulon, mourut et fut enterré à Ajalon, dans le pays de Zabulon.'),
('jg',12,13,'crampon1923','Après lui, Abdon, fils d''Illel, de Pharathon fut juge en Israël.'),
('jg',12,14,'crampon1923','Il eut quarante fils et trente petits-fils, qui montaient sur soixante-dix ânons. Il fut juge en Israël pendant huit ans;'),
('jg',12,15,'crampon1923','puis Abdon, fils d''Illel, de Pharathon, mourut et fut enterré à Pharathon, dans le pays d''Ephraïm, sur la montagne des Amalécites.'),
('jg',13,1,'crampon1923','Les enfants d''Israël firent encore ce qui est mal aux yeux de Yahweh, et Yahweh les livra entre les mains des Philistins, pendant quarante ans.'),
('jg',13,2,'crampon1923','Il y avait un homme de Saraa, de la famille des Danites, nommé Manué; sa femme était stérile, et n''avait pas enfanté.'),
('jg',13,3,'crampon1923','L''Ange de Yahweh apparut à la femme et lui dit: " Voici donc, tu es stérile et sans enfant; mais tu concevras et enfanteras un fils.'),
('jg',13,4,'crampon1923','Et maintenant, prends bien garde, ne bois ni vin ni liqueur forte et ne mange rien d''impur,'),
('jg',13,5,'crampon1923','car tu vas concevoir et enfanter un fils. Le rasoir ne passera point sur sa tête, car cet enfant sera nazaréen de Dieu, dès le sein de sa mère, et c''est lui qui commencera à délivrer Israël de la main des Philistins. "'),
('jg',13,6,'crampon1923','La femme alla dire à son mari: " Un homme de Dieu est venu vers moi; il avait l''aspect d''un ange de Dieu, un aspect redoutable. Je ne lui ai pas demandé d''où il était, et il ne m''a pas fait connaître son nom;'),
('jg',13,7,'crampon1923','mais il m''a dit: " Tu vas concevoir et enfanter un fils; et maintenant, ne bois ni vin ni liqueur forte, et ne mange rien d''impur, parce que cet enfant sera nazaréen de Dieu dès le sein de sa mère, jusqu''au jour de sa mort. "'),
('jg',13,8,'crampon1923','Alors Manué invoqua Yahweh et dit: " Je vous prie, Seigneur, que l''homme de Dieu que vous avez envoyé vienne encore vers nous, et qu''il nous enseigne ce que nous devons faire pour l''enfant qui naîtra! "'),
('jg',13,9,'crampon1923','Dieu exauça la prière de Manué, et l''Ange de Dieu vint encore vers la femme; elle était assise dans un champ, et Manué, son mari, n''était pas avec elle.'),
('jg',13,10,'crampon1923','La femme courut aussitôt informer son mari et lui dit: " Voici, l''homme qui est venu l''autre jour vers moi m''est apparu. "'),
('jg',13,11,'crampon1923','Manué se leva et, suivant sa femme, il alla vers l''homme et lui dit: " Est-ce toi qui as parlé à cette femme? " Il répondit: " C''est moi. "'),
('jg',13,12,'crampon1923','Manué dit: " Maintenant, quand ta parole s''accomplira, que faudra-t-il observer à l''égard de cet enfant, et qu''y aura-t-il à faire pour lui? "'),
('jg',13,13,'crampon1923','L''Ange de Yahweh répondit à Manué: " La femme s''abstiendra de tout ce que je lui ai dit:'),
('jg',13,14,'crampon1923','elle ne mangera rien de ce qui provient de la vigne, elle ne boira ni vin ni liqueur forte, et elle ne mangera rien d''impur: tout ce que je lui ai prescrit, elle l''observera. "'),
('jg',13,15,'crampon1923','Manué dit à l''Ange de Yahweh: " Permets que nous te retenions et que nous t''apprêtions un chevreau. "'),
('jg',13,16,'crampon1923','L''Ange de Yahweh répondit à Manué: " Quand tu me retiendrais, je ne mangerais pas de ton mets; mais si tu veux préparer un holocauste, à Yahweh, offre-le. " — Manué ne savait pas que c''était l''Ange de Yahweh —'),
('jg',13,17,'crampon1923','Et Manué dit à l''Ange de Yahweh: " Quel est ton nom, afin que nous t''honorions, quand ta parole s''accomplira? "'),
('jg',13,18,'crampon1923','L''Ange de Yahweh lui répondit: " Pourquoi m''interroges-tu sur mon nom? Il est Merveilleux. "'),
('jg',13,19,'crampon1923','Manué prit le chevreau avec l''oblation et l''offrit à Yahweh sur le rocher, et Yahweh fit un prodige pendant que Manué et sa femme regardaient.'),
('jg',13,20,'crampon1923','Comme la flamme montait de dessus l''autel vers le ciel, l''Ange de Yahweh monta dans la flamme de l''autel. A cette vue, Manué et sa femme tombèrent la face contre terre.'),
('jg',13,21,'crampon1923','Et l''Ange de Yahweh n''apparut plus à Manué et à sa femme. Alors Manué comprit que c''était l''Ange de Yahweh.'),
('jg',13,22,'crampon1923','Et Manué dit à sa femme: " Nous allons mourir, car nous avons vu Dieu. "'),
('jg',13,23,'crampon1923','Sa femme lui répondit: " Si Yahweh voulait nous faire mourir, il n''aurait pas reçu de nos mains l''holocauste et l''oblation, il ne nous aurait pas fait voir tout cela, il ne nous aurait pas fait entendre aujourd''hui de pareilles choses. "'),
('jg',13,24,'crampon1923','La femme enfanta un fils et lui donna le nom de Samson. L''enfant grandit et Yahweh le bénit;'),
('jg',13,25,'crampon1923','l''esprit de Yahweh commença à le pousser à Machanêh-Dan, entre Saraa et Esthaol.'),
('jg',14,1,'crampon1923','Samson descendit à Thamna, et il vit à Thamna une femme d''entre les filles des Philistins.'),
('jg',14,2,'crampon1923','Lorsqu''il fut remonté, il le déclara à son père et à sa mère, en disant: " J''ai vu à Thamna une femme d''entre les filles des Philistins; prenez-la maintenant pour être ma femme. "'),
('jg',14,3,'crampon1923','Son père et sa mère lui dirent: " N''y a-t-il point de femme parmi les filles de tes frères et dans tout notre peuple, que tu ailles prendre une femme chez les Philistins, qui sont incirconcis? " Et Samson dit à son père: " Prends celle-là pour moi, car elle me plaît. "'),
('jg',14,4,'crampon1923','Son père et sa mère ne savaient pas que cela venait de Yahweh; car il cherchait une occasion de querelle venant des Philistins. — En ce temps-là les Philistins dominaient sur Israël.'),
('jg',14,5,'crampon1923','Samson descendit avec son père et sa mère à Thamna. Lorsqu''ils arrivèrent aux vignes de Thamna, voici qu''un jeune lion rugissant vint à sa rencontre.'),
('jg',14,6,'crampon1923','L''Esprit de Yahweh saisit Samson; et, sans avoir rien à la main, Samson déchira le lion comme on déchire un chevreau. Et il ne raconta pas à son père et à sa mère ce qu''il avait fait.'),
('jg',14,7,'crampon1923','Il descendit et parla à la femme, et elle lui plut.'),
('jg',14,8,'crampon1923','Quelque temps après, s''étant rendu de nouveau à Thamna pour la prendre, il fit un détour pour voir le cadavre du lion, et voici qu''il y avait un essaim d''abeilles et du miel dans le corps du lion.'),
('jg',14,9,'crampon1923','Il en prit dans ses mains et en mangea chemin faisant; et lorsqu''il fut arrivé près de son père et de sa mère, il leur en donna et ils en mangèrent; mais il ne leur dit pas qu''il avait pris le miel dans le corps du lion.'),
('jg',14,10,'crampon1923','Le père de Samson descendit chez la femme; et là, Samson donna un festin, car c''était la coutume des jeunes gens.'),
('jg',14,11,'crampon1923','Dès qu''on le vit, on invita trente compagnons pour être avec lui.'),
('jg',14,12,'crampon1923','Samson leur dit: " Je vais vous proposer une énigme. Si vous me l''expliquez pendant les sept jours du festin et si vous la devinez, je vous donnerai trente tuniques et trente vêtements de rechange;'),
('jg',14,13,'crampon1923','mais si vous me pouvez pas me l''expliquer, c''est vous qui me donnerez trente tuniques et trente vêtements de rechange. " Ils lui dirent: " Propose ton énigme, que nous l''entendions. "'),
('jg',14,14,'crampon1923','Il leur dit: " De celui qui mange est sorti ce qui se mange, du fort est sorti le doux. " Pendant trois jours, ils ne purent expliquer l''énigme.'),
('jg',14,15,'crampon1923','Le septième jour, ils dirent à la femme de Samson: " Persuade à ton mari de nous expliquer l''énigme; sinon, nous te brûlerons, toi et la maison de ton père. C''est pour nous dépouiller que vous nous avez invités, sans doute? "'),
('jg',14,16,'crampon1923','La femme de Samson pleurait auprès de lui et disait: " Tu n''as pour moi que de la haine, et tu me m''aimes pas. Tu as proposé une énigme aux fils de mon peuple, et tu ne me l''as pas expliquée! " Il lui répondit: " Je ne l''ai expliquée ni à mon père ni à ma mère, et je te l''expliquerais! "'),
('jg',14,17,'crampon1923','Elle pleura ainsi devant lui pendant les sept jours que dura le festin; le septième jour, comme elle le tourmentait, il lui expliqua l''énigme, et elle l''expliqua aux enfants de son peuple.'),
('jg',14,18,'crampon1923','Les gens de la ville dirent à Samson, le septième jour, avant le coucher du soleil: " Quoi de plus doux que le miel, et quoi de plus fort que le lion? " Et il leur dit: " Si vous n''aviez pas labouré avec ma génisse, vous n''auriez pas deviné mon énigme. "'),
('jg',14,19,'crampon1923','L''Esprit de Yahweh le saisit, et il descendit à Ascalon. Il y tua trente hommes et, ayant pris leurs dépouilles, il donna les vêtements de rechange à ceux qui avaient expliqué l''énigme. Puis, enflammé de colère, il monta à la maison de son père.'),
('jg',14,20,'crampon1923','La femme de Samson fut donnée à l''un de ses compagnons qu''il s''était choisi pour ami.'),
('jg',15,1,'crampon1923','Quelque temps après, à l''époque de la moisson des blés, Samson alla voir sa femme, en apportant un chevreau. Il dit: " Je veux entrer auprès de ma femme dans sa chambre. " Mais son père ne lui accorda pas l''entrée;'),
('jg',15,2,'crampon1923','et son père dit: " J''ai pensé que tu avais pour elle de la haine, et je l''ai donnée à ton ami. Est-ce que sa jeune sœur n''est pas plus belle qu''elle? Qu''elle soit ta femme à sa place. "'),
('jg',15,3,'crampon1923','Samson leur dit: " Cette fois je serai innocent envers les Philistins, si je leur fais du mal. "'),
('jg',15,4,'crampon1923','Et Samson s''en alla. Il attrapa trois cents renards et, ayant pris des torches, il tourna les renards queue contre queue, et mit une torche entre les deux queues, au milieu.'),
('jg',15,5,'crampon1923','Il alluma ensuite les torches et lâcha les renards dans les moissons des Philistins; il embrasa depuis les tas de gerbes jusqu''aux blés sur pied et aux plantations d''oliviers.'),
('jg',15,6,'crampon1923','Les Philistins dirent: " Qui a fait cela? " On répondit: " C''est Samson, le gendre du Thamnéen, parce que celui-ci lui a pris sa femme et l''a donnée à son ami. " Et les Philistins étant montés, ils la brûlèrent, elle et son père.'),
('jg',15,7,'crampon1923','Samson leur dit: " C''est ainsi que vous agissez! Eh bien, je ne cesserai qu''après m''être vengé de vous. "'),
('jg',15,8,'crampon1923','Et il les battit rudement, cuisse et hanche; il descendit ensuite et demeura dans la caverne du rocher d''Etam.'),
('jg',15,9,'crampon1923','Alors les Philistins montèrent et campèrent en Juda, se répandant en Léchi.'),
('jg',15,10,'crampon1923','Les hommes de Juda dirent: " Pourquoi êtes-vous tournés contre nous? " Ils répondirent: " Nous sommes montés pour lier Samson, afin de le traiter comme il nous a traités. "'),
('jg',15,11,'crampon1923','Trois mille hommes de Juda descendirent à la caverne du rocher d''Etam, et dirent à Samson: " Ne sais-tu pas que les Philistins sont nos maîtres? Qu''est-ce que tu nous as fait là? " Il leur répondit: " Je les ai traités comme ils m''ont traité. "'),
('jg',15,12,'crampon1923','Ils lui dirent: " Nous sommes descendus pour te lier, afin de te livrer entre les mains des Philistins. " Samson leur dit: " Jurez-moi que vous ne voulez pas me tuer. "'),
('jg',15,13,'crampon1923','Ils lui répondirent en disant: " Non; nous voulons seulement te lier et te livrer entre leurs mains, mais nous ne te ferons pas mourir. " Et l''ayant lié de deux cordes neuves, ils le firent monter du rocher.'),
('jg',15,14,'crampon1923','Lorsqu''il arriva à Léchi, les Philistins poussèrent à sa rencontre des cris de joie. Alors l''Esprit de Yahweh le saisit, et les cordes qu''il avait aux bras devinrent comme des fils de lin brûlés par le feu, et ses liens tombèrent de ses mains.'),
('jg',15,15,'crampon1923','Trouvant une mâchoire d''âne fraîche, il étendit la main, la saisit et en frappa mille hommes.'),
('jg',15,16,'crampon1923','Et Samson dit: " Avec une mâchoire d''âne, je les ai bien asinés (rossés), avec une mâchoire d''âne, j''ai frappé mille hommes. "'),
('jg',15,17,'crampon1923','Quand il eut achevé de parler, il jeta de sa main la mâchoire, et nomma ce lieu Ramath-Léchi.'),
('jg',15,18,'crampon1923','Dévoré par la soif, il invoqua Yahweh, et dit: " C''est vous qui avez accordé par la main de votre serviteur cette grande délivrance; et maintenant, faut-il que je meure de soif et que je tombe entre les mains des incirconcis? "'),
('jg',15,19,'crampon1923','Et Dieu fendit le rocher creux qui est à Léchi, et il en sortit de l''eau. Samson but, son esprit se ranima et il reprit vie. C''est pourquoi on a appelé cette source En-Hakkoré; elle existe à Léchi, jusqu''à ce jour.'),
('jg',15,20,'crampon1923','Samson jugea Israël, au temps des Philistins, pendant vingt ans.'),
('jg',16,1,'crampon1923','Samson alla à Gaza; il y vit une courtisane, et il entra chez elle.'),
('jg',16,2,'crampon1923','On l''annonça aux gens de Gaza, en disant: " Samson est venu ici. " Et ils l''environnèrent et se tinrent en embuscade toute la nuit à la porte de la ville. Ils se tinrent tranquilles toute la nuit, en disant: " Attendons jusqu''à ce que luise le matin, et nous le tuerons. "'),
('jg',16,3,'crampon1923','Samson demeura couché jusqu''à minuit; à minuit, il se leva et, saisissant les battants de la porte de la ville et les deux poteaux, il les arracha avec la barre, les mit sur ses épaules et les porta sur le sommet de la montagne qui regarde Hébron.'),
('jg',16,4,'crampon1923','Après cela, il aima une femme dans la vallée de Sorec; elle se nommait Dalila.'),
('jg',16,5,'crampon1923','Les princes des philistins montèrent vers elle et lui dirent: " Flatte-le et vois où gît sa grande force, et comment nous pourrons nous rendre maîtres de lui, afin de le lier et de le dompter, et nous te donnerons chacun mille et cent sicles d''argent. "'),
('jg',16,6,'crampon1923','Dalila dit à Samson: " Dis-moi, je te prie, ou gît ta grande force, et avec quoi il faudrait te lier pour te dompter? "'),
('jg',16,7,'crampon1923','Samson lui dit: " Si l''on me liait avec sept cordes fraîches, qui ne seraient pas encore sèches, je deviendrais faible et je serais comme un autre homme. "'),
('jg',16,8,'crampon1923','Les princes des Philistins apportèrent à Dalila sept cordes fraîches, qui n''étaient pas encore sèches; et elle le lia avec ces cordes.'),
('jg',16,9,'crampon1923','— Or elle avait des gens en embuscade dans la chambre. — Elle lui dit: " Les Philistins sont sur toi, Samson! " Et il rompit les cordes, comme se rompt un cordon d''étoupe quand il sent le feu; et l''on ne connut pas le secret de sa force.'),
('jg',16,10,'crampon1923','Dalila dit à Samson: " Voici, tu t''es joué de moi et tu m''as dit des mensonges. Maintenant, je te prie, indique-moi avec quoi il faut te lier. "'),
('jg',16,11,'crampon1923','Il lui dit: " Si on me liait avec des cordes neuves, n''ayant servi à aucun usage, je deviendrais faible et je serais comme un autre homme. "'),
('jg',16,12,'crampon1923','Dalila prit des cordes neuves, avec lesquelles elle le lia. Et elle lui dit: " Les Philistins sont sur toi, Samson! " — Or des gens se tenaient en embuscade dans la chambre. — Et il rompit comme un fil les cordes qu''il avait aux bras.'),
('jg',16,13,'crampon1923','Dalila dit à Samson: " Jusqu''à présent tu t''es joué de moi, et tu m''as dit des mensonges. Indique-moi avec quoi il faut te lier. " Il lui dit: " Tu n''as qu''à tisser les sept tresses de ma tête avec le tissu. "'),
('jg',16,14,'crampon1923','Et elle les fixa avec la cheville. Puis elle lui dit: " Les Philistins sont sur toi, Samson! " Et, se réveillant de son sommeil, il arracha la cheville du métier et le tissu.'),
('jg',16,15,'crampon1923','Elle lui dit: " Comment peux-tu dire: je t''aime! puisque ton cœur n''est pas avec moi? Voilà trois fois que tu t''es joué de moi, et que tu ne m''as pas indiqué où gît ta grande force. "'),
('jg',16,16,'crampon1923','Elle le tourmentait ainsi chaque jour et le fatiguait de ses instances; à la fin, son âme s''impatienta jusqu''à en mourir;'),
('jg',16,17,'crampon1923','il lui ouvrit tout son cœur et lui dit: " Le rasoir n''a jamais passé sur ma tête, car je suis nazaréen de Dieu dès le sein de ma mère. Si j''étais rasé, ma force m''abandonnerait, je deviendrais faible et je serais comme tous les autres hommes. "'),
('jg',16,18,'crampon1923','Dalila vit qu''il lui avait ouvert tout son cœur; elle envoya appeler les princes des Philistins et leur fit dire: " Montez cette fois, car il m''a ouvert tout son cœur. " Et les princes des Philistins montèrent vers elle. apportant l''argent dans leurs mains.'),
('jg',16,19,'crampon1923','Elle l''endormit sur ses genoux et, ayant appelé l''homme, elle fit raser les sept tresses de la tête de Samson et commença à le dompter, et sa force se retira de lui.'),
('jg',16,20,'crampon1923','Elle dit alors: " Les Philistins sont sur toi, Samson! " Il se réveilla de son sommeil et dit: " Je me tirerai d''affaire comme les autres fois, et je me dégagerai; " car il ne savait pas que Yahweh s''était retiré de lui.'),
('jg',16,21,'crampon1923','Les Philistins le saisirent et lui crevèrent les yeux et, l''ayant fait descendre à Gaza, ils le lièrent d''une double chaîne d''airain. Il tournait la meule dans la prison.'),
('jg',16,22,'crampon1923','Cependant les cheveux de sa tête commençaient à repousser depuis qu''il avait été rasé.'),
('jg',16,23,'crampon1923','Les princes des Philistins s''assemblèrent pour offrir un grand sacrifice à Dagon, leur dieu, et pour se réjouir. Ils disaient: " Notre dieu a livré entre nos mains Samson, notre ennemi. "'),
('jg',16,24,'crampon1923','Le peuple le vit, et ils louèrent leur dieu, car ils disaient: " Notre dieu a livré entre nos mains notre ennemi, celui qui ravageait notre pays, et qui nous tuait tant de gens. "'),
('jg',16,25,'crampon1923','Quand leurs cœurs furent devenus joyeux, ils dirent: " Qu''on fasse venir Samson, et qu''il nous divertisse! " Ils tirèrent Samson de la prison, et il dansa devant eux. On l''avait placé entre les colonnes.'),
('jg',16,26,'crampon1923','Samson dit au jeune homme qui le tenait par la main: " Laisse-moi toucher les colonnes sur lesquelles se tient la maison et m''y appuyer.'),
('jg',16,27,'crampon1923','Or la maison était remplie d''hommes et de femmes; tous les princes des Philistins étaient là, et il y avait sur le toit environ trois mille personnes, hommes et femmes, qui regardaient Samson danser.'),
('jg',16,28,'crampon1923','Alors Samson invoqua Yahweh et dit: " Seigneur Yahweh, souvenez-vous de moi, je vous prie, et donnez-moi de la force cette fois seulement, ô Dieu. afin que d''un seul coup je me venge des Philistins pour mes deux yeux. "'),
('jg',16,29,'crampon1923','Et Samson, embrassant les deux colonnes du milieu sur lesquelles se tenait la maison, s''appuya sur elles, sur l''une de la main droite, sur l''autre de la main gauche.'),
('jg',16,30,'crampon1923','Et Samson dit: " Que je meure avec les Philistins! ". Et il se pencha avec force, et la maison s''écroula sur les princes et sur tout le peuple qui s''y trouvait. Ceux qu''il fit périr en mourant furent plus nombreux que ceux qu''il avait tués pendant sa vie.'),
('jg',16,31,'crampon1923','Ses frères et toute la maison de son père descendirent à Gaza et l''emportèrent. Lorsqu''ils furent remontés, ils l''enterrèrent entre Saraa et Esthaol, dans le sépulcre de Manué, son père. Il avait jugé Israël pendant vingt ans.'),
('jg',17,1,'crampon1923','Il y avait un homme de la montagne d''Ephraïm, nommé Michas.'),
('jg',17,2,'crampon1923','Il dit à sa mère: " Les mille et cent sicles d''argent qu''on t''a pris, et au sujet desquels tu as prononcé une malédiction, — et tu l''as même prononcée à mes oreilles, — voici, cet argent est entre mes mains, c''est moi qui l''ai pris. " Et sa mère dit: " Que mon fils soit béni de Yahweh! "'),
('jg',17,3,'crampon1923','Il rendit à sa mère les mille et cent sicles d''argent; et sa mère dit: " Je consacre de ma main cet argent à Yahweh pour mon fils, afin d''en faire une image taillée et un objet en fonte; et maintenant je te le rends. "'),
('jg',17,4,'crampon1923','Lorsqu''il eut rendu l''argent à sa mère, sa mère prit deux cents sicles et les donna au fondeur, qui en fit une image taillée et un objet en fonte; et ils furent dans la maison de Michas.'),
('jg',17,5,'crampon1923','Car ce Michas avait une maison de Dieu; il fit un éphod et des théraphim, et il consacra un de ses fils, qui lui servit de prêtre.'),
('jg',17,6,'crampon1923','En ce temps-là, il n''y avait pas de roi en Israël; chacun faisait ce qui était bon à ses yeux.'),
('jg',17,7,'crampon1923','Il y avait un jeune homme de Bethléem de Juda, de la famille de Juda; il était Lévite et séjournait dans celle ville.'),
('jg',17,8,'crampon1923','Cet homme partit de la ville de Bethléem de Juda, pour trouver un lieu de séjour. Il arriva ainsi dans la montagne d''Ephraïm, jusqu''à la maison de Michas.'),
('jg',17,9,'crampon1923','Michas lui dit: " D''où viens-tu? " Il lui répondit: " Je suis Lévite, de Bethléem de Juda, et je voyage pour trouver un lieu de séjour. "'),
('jg',17,10,'crampon1923','Michas lui dit: " Reste avec moi; sois pour moi un père et un prêtre, et je te donnerai dix sicles d''argent par an, une provision de vêtements et la nourriture. " Et le Lévite entra.'),
('jg',17,11,'crampon1923','Le Lévite consentit à demeurer chez cet homme, et le jeune homme fut pour lui comme l''un de ses fils.'),
('jg',17,12,'crampon1923','Michas installa le Lévite, et le jeune homme lui servit de prêtre et demeura dans la maison de Michas.'),
('jg',17,13,'crampon1923','Et Michas dit: " Je sais maintenant que Yahweh me fera du bien, puisque j''ai ce Lévite pour prêtre. "'),
('jg',18,1,'crampon1923','En ce temps-là, il n''y avait pas de roi en Israël; en ce temps-là la tribu des Danites se cherchait une possession pour s''établir, car jusqu''à ce jour il ne lui était pas échu d''héritage au milieu des tribus d''Israël.'),
('jg',18,2,'crampon1923','Les fils de Dan, ayant pris d''entre eux tous cinq hommes de leur famille, hommes vaillants, les envoyèrent de Saraa et d''Esthaol pour explorer le pays et le reconnaître. Ils leur dirent: " Allez, reconnaissez le pays. " Les cinq hommes arrivèrent dans la montagne d''Ephraïm jusqu''à la maison de Michas, et ils y passèrent la nuit.'),
('jg',18,3,'crampon1923','Comme ils étaient prés de la maison de Michas, reconnaissant la voix du jeune Lévite, ils s''approchèrent et lui dirent: " Qui t''a amené ici? Que fais-tu dans ce lieu et qu''as-tu ici? "')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('jg',18,4,'crampon1923','Il leur répondit: " Michas a fait pour moi telle et telle chose, il me donne un salaire, et je lui sers de prêtre. "'),
('jg',18,5,'crampon1923','Ils lui dirent: " Eh bien, consulte Dieu, afin que nous sachions si notre voyage aura du succès. "'),
('jg',18,6,'crampon1923','Et le prêtre leur répondit: " Allez en paix; le voyage que vous faites est sous le regard de Yahweh. "'),
('jg',18,7,'crampon1923','S''étant mis en route, les cinq hommes arrivèrent à Laïs. Ils virent le peuple qui était dans cette ville, vivant en sécurité à la manière des Sidoniens, paisible et tranquille, et il n''y avait personne dans le pays qui, investi de l''autorité, les molestât en aucune manière; ils étaient éloignés des Sidoniens, et n''avaient affaire avec personne.'),
('jg',18,8,'crampon1923','Ils revinrent vers leurs frères à Saraa et Esthaol, et leurs frères leur dirent: " Que dites-vous? "'),
('jg',18,9,'crampon1923','Ils répondirent: " Debout, et montons contre ceux; car nous avons vu le pays et voici, qu''il est très bon. Et vous restez là sans mot dire? Ne soyez point paresseux à vous mettre en marche pour aller prendre possession de ce pays.'),
('jg',18,10,'crampon1923','En y entrant, vous arriverez chez un peuple en sécurité. Le pays est vaste, et Dieu l''a livré entre vos mains; c''est un lieu où rien ne manque de tout ce qu''il y a sur la terre. "'),
('jg',18,11,'crampon1923','Six cents hommes de la famille de Dan partirent de Saraa et d''Esthaol, munis de leurs armes de guerre.'),
('jg',18,12,'crampon1923','Ils montèrent et campèrent à Cariathiarim en Juda; c''est pourquoi ce lieu a été appelé jusqu''à ce jour Machanêh-Dan; voici qu''il est à l''occident de Cariathiarim.'),
('jg',18,13,'crampon1923','Ils passèrent de là dans la montagne d''Ephraïm, et ils arrivèrent jusqu''à la maison de Michas.'),
('jg',18,14,'crampon1923','Les cinq hommes qui avaient été explorer le pays de Laïs prirent la parole et dirent à leurs frères: " Savez-vous qu''il y a dans ces maisons un éphod, des théraphim, une image taillée et un objet en fonte? Voyez maintenant ce que vous avez à faire. "'),
('jg',18,15,'crampon1923','Ils se dirigèrent de ce côte-là et, entrant dans la maison du jeune Lévite, la maison de Michas, ils lui demandèrent comment il se portait.'),
('jg',18,16,'crampon1923','Les six cents hommes d''entre les fils de Dan, munis de leurs armes de guerre, se tenaient à l''entrée de la porte.'),
('jg',18,17,'crampon1923','Et les cinq hommes qui avaient été explorer le pays montèrent et, étant entrés dans le sanctuaire, ils prirent l''image taillée, l''éphod, les théraphim et l''objet en fonte, pendant que le prêtre était à l''entrée de la porte avec les six cents hommes munis de leurs armes de guerre.'),
('jg',18,18,'crampon1923','Lorsqu''ils furent entrés dans la maison de Michas et qu''ils eurent pris l''image taillée, l''éphod, les théraphim et l''objet en fonte, le prêtre leur dit: " Que faites-vous? "'),
('jg',18,19,'crampon1923','Ils lui répondirent: " Tais-toi, mets ta main sur ta bouche et viens avec nous, et tu seras pour nous un père et un prêtre. Vaut-il mieux que tu sois prêtre pour la maison d''un seul homme, ou que tu sois prêtre pour une tribu et pour une famille en Israël? "'),
('jg',18,20,'crampon1923','Le cœur du prêtre devint joyeux; il prit l''éphod, les théraphim et l''image taillée, et il vint au milieu de la troupe.'),
('jg',18,21,'crampon1923','Ils se remirent en route et partirent, ayant placé devant eux les enfants, le bétail et toutes les choses de prix.'),
('jg',18,22,'crampon1923','Ils étaient déjà loin de la maison de Michas, lorsque les gens qui habitaient les maisons voisines de la maison de Michas se rassemblèrent et poursuivirent les fils de Dan.'),
('jg',18,23,'crampon1923','Ils crièrent après les fils de Dan, et ceux-ci, se retournant, dirent à Michas: " Que te faut-il, que tu aies attroupé ces hommes? "'),
('jg',18,24,'crampon1923','Il répondit: " Mes dieux que j''ai faits, vous les avez enlevés, avec le prêtre, et vous êtes partis: que me reste-t-il? Comment donc pouvez-vous me dire: Que te faut-il? "'),
('jg',18,25,'crampon1923','Les fils de Dan lui dirent: " Ne nous fais pas entendre ta voix, de peur que des hommes irrités se jettent sur vous et que tu perdes ta vie et celle des gens de ta maison. "'),
('jg',18,26,'crampon1923','Et les fils de Dan continuèrent leur route. Voyant qu''ils étaient plus forts que lui, Michas s''en retourna et revint dans sa maison.'),
('jg',18,27,'crampon1923','C''est ainsi que les Danites enlevèrent ce qu''avait fait Michas, et le prêtre qui était à son service; et ils marchèrent contre Laïs, contre un peuple tranquille et en sécurité; ils le passèrent au fil de l''épée et brûlèrent la ville.'),
('jg',18,28,'crampon1923','Il n''y eut personne pour la délivrer, car elle était éloignée de Sidon, et ses habitants n''avaient point affaire avec d''autres hommes: elle était dans la vallée qui s''étend vers Beth-Rohob. Les fils de Dan rebâtirent la ville et y habitèrent;'),
('jg',18,29,'crampon1923','ils l''appelèrent Dan, d''après le nom de Dan, leur père, qui était né d''Israël; mais la ville s''appelait primitivement Laïs.'),
('jg',18,30,'crampon1923','Les fils de Dan dressèrent pour eux l''image taillée, et Jonathan, fils de Gersam, fils de Moïse, lui et ses fils, furent prêtres de la tribu des Danites, jusqu''au jour de la captivité du pays.'),
('jg',18,31,'crampon1923','Ils dressèrent pour eux l''image taillée qu''avait faite Michas, pendant tout le temps que la maison de Dieu fut à Silo.'),
('jg',19,1,'crampon1923','Dans ce temps, alors qu''il n''y avait pas de roi en Israël, un Lévite, qui séjournait à l''extrémité de la montagne d''Ephraïm, prit pour concubine une femme de Bethléem de Juda.'),
('jg',19,2,'crampon1923','Sa concubine lui fut infidèle, et elle le quitta pour aller dans la maison de son père à Bethléem de Juda, où elle resta l''espace de quatre mois.'),
('jg',19,3,'crampon1923','Son mari se leva et alla vers elle, pour parler à son cœur et la ramener à lui; il avait avec lui son serviteur et deux ânes. Elle le fit entrer dans la maison de son père; et quand le père de la jeune femme le vit, il alla avec joie au-devant de lui.'),
('jg',19,4,'crampon1923','Son beau-père, le père de la jeune femme, le retint, et il demeura chez lui trois jours; ils mangèrent et burent, et ils y séjournèrent.'),
('jg',19,5,'crampon1923','Le quatrième jour, ils se levèrent de bon matin et le Lévite se disposait à partir. Mais le père de la jeune femme dit à son gendre: " Fortifie ton cœur en prenant un morceau de pain, et vous partirez ensuite. "'),
('jg',19,6,'crampon1923','S''étant assis, ils mangèrent tous deux ensemble et burent. Puis le père de la jeune femme dit au mari: " Consens, je te prie, à passer la nuit, et que ton cœur se réjouisse. "'),
('jg',19,7,'crampon1923','Le mari se leva pour s''en aller; mais, sur les instances de son beau-père, il revint et y passa encore la nuit.'),
('jg',19,8,'crampon1923','Le cinquième jour, il se leva de bon matin pour partir. Alors le père de la jeune femme dit: " Fortifie ton cœur, je te prie, et diffère jusqu''au déclin du jour. " Et ils mangèrent tous deux.'),
('jg',19,9,'crampon1923','Le mari se levait pour s''en aller, lui, sa concubine et son serviteur; mais son beau-père, le père de la jeune femme, lui dit: " Voici, le jour s''incline vers le soir; je vous prie, passez donc ici la nuit; voici que le jour baisse, passe ici la nuit, et que ton cœur se réjouisse; demain vous vous lèverez de bon matin pour vous mettre en route, et tu t''en iras à ta tente. "'),
('jg',19,10,'crampon1923','Le mari ne consentit pas à passer la nuit; il se leva et partit. Il vint jusqu''en face de Jébus, qui est Jérusalem, ayant avec lui les deux ânes bâtés et sa concubine.'),
('jg',19,11,'crampon1923','Lorsqu''ils furent près de Jébus, le jour avait beaucoup baissé. Le serviteur dit alors à son maître: " Viens, je te prie, détournons-nous vers cette ville des Jébuséens, et nous y passerons la nuit. "'),
('jg',19,12,'crampon1923','Son maître lui répondit: " Nous ne nous détournerons pas vers une ville étrangère, où il n''y a pas d''enfants d''Israël; nous passerons jusqu''à Gabaa. "'),
('jg',19,13,'crampon1923','il dit encore à son serviteur: " Allons, tâchons d''atteindre l''une de ces localités pour y passer la nuit, Gabaa ou Rama. "'),
('jg',19,14,'crampon1923','Ils continuèrent à marcher, et le soleil se coucha lorsqu''ils furent près de Gabaa, qui appartient à Benjamin.'),
('jg',19,15,'crampon1923','Ils se détournèrent de ce côté, pour aller passer la nuit à Gabaa. Le Lévite, étant entré, s''arrêta sur la place de la ville, et il n''y eut personne qui les reçut dans sa maison pour y passer la nuit.'),
('jg',19,16,'crampon1923','Mais voici qu''un vieillard revenait le soir de travailler aux champs; c''était un homme de la montagne d''Ephraïm, qui séjournait à Gabaa, et les gens du lieu étaient Benjamites.'),
('jg',19,17,'crampon1923','Ayant levé les yeux, il vit le voyageur sur la place de la ville, et le vieillard dit: " Où vas-tu et d''où viens-tu? "'),
('jg',19,18,'crampon1923','Il lui répondit: " Nous allons de Bethléem de Juda jusqu''à l''extrémité de la montagne d''Ephraïm, d''où je suis. J''étais allé à Bethléem de Juda, et maintenant je vais à la maison de Yahweh, et il n''y a personne qui me reçoive dans sa maison.'),
('jg',19,19,'crampon1923','Nous avons cependant de la paille et du fourrage pour nos ânes, et aussi du pain et du vin pour moi, pour ta servante et pour le jeune homme qui est avec tes serviteurs; nous ne manquons de rien. "'),
('jg',19,20,'crampon1923','Le vieillard dit: " La paix soit avec toi! Seulement je pourvoirai à tous tes besoins; mais ne passe pas la nuit sur la place. "'),
('jg',19,21,'crampon1923','Il le fit entrer dans sa maison, et il donna du fourrage aux ânes; les voyageurs se lavèrent les pieds, puis ils mangèrent et burent.'),
('jg',19,22,'crampon1923','Pendant qu''ils réjouissaient leur cœur, voici, que des hommes de la ville, gens pervers, entourèrent la maison et, frappant avec force à la porte, ils dirent au vieillard, maître de la maison: " Fais sortir l''homme qui est entré chez toi, afin que nous le connaissions. "'),
('jg',19,23,'crampon1923','Le maître de la maison sortit vers eux et leur dit: " Non, mes frères, ne faites pas le mal, je vous prie; puisque cet homme est entré dans ma maison, ne commettez pas cette infamie.'),
('jg',19,24,'crampon1923','Voici ma fille qui est vierge, et sa concubine; je vous les amènerai dehors, vous leur ferez violence et vous les traiterez comme il vous plaira; mais ne commettez pas sur cet homme une action aussi infâme. "'),
('jg',19,25,'crampon1923','Ces hommes ne voulurent pas l''écouter. Alors l''homme prit sa concubine et la leur amena dehors. Ils la connurent et ils abusèrent d''elle toute la nuit jusqu''au matin, et ils la renvoyèrent au lever de l''aurore.'),
('jg',19,26,'crampon1923','Vers le matin, cette femme vint tomber à l''entrée de la maison de l''homme chez qui était son mari, et elle resta là jusqu''au jour.'),
('jg',19,27,'crampon1923','Son mari se leva le matin et, ayant ouvert la porte de la maison, il sortit pour continuer sa route. Et voici que la femme, sa concubine, était étendue à l''entrée de la maison, les mains sur le seuil.'),
('jg',19,28,'crampon1923','Il lui dit: " Lève-toi et allons-nous-en. " Et personne ne répondit. Alors le mari la mit sur son âne et partit pour aller dans sa demeure.'),
('jg',19,29,'crampon1923','Arrivé chez lui, il prit un couteau et, saisissant sa concubine, il la coupa membre par membre en douze morceaux, et l''envoya dans tout le territoire d''Israël.'),
('jg',19,30,'crampon1923','Tous ceux qui virent cela dirent: " Jamais chose pareille n''est arrivée et ne s''est vue depuis que les enfants d''Israël sont montés du pays d''Egypte jusqu''à ce jour; réfléchissez-y, consultez-vous et prononcez. "'),
('jg',20,1,'crampon1923','Tous les enfants d''Israël sortirent, depuis Dan jusqu''à Bersabée et au pays de Galaad, et l''assemblée se réunit comme un seul homme devant Yahweh à Maspha.'),
('jg',20,2,'crampon1923','Les chefs de tout le peuple, toutes les tribus d''Israël, se présentèrent dans l''assemblée du peuple de Dieu: quatre cent mille hommes de pied tirant l''épée.'),
('jg',20,3,'crampon1923','Et les fils de Benjamin apprirent que les enfants d''Israël étaient montés à Maspha. Les enfants d''Israël dirent: " Parlez: comment ce crime a-t-il été commis! "'),
('jg',20,4,'crampon1923','Alors le Lévite, le mari de la femme qui avait été tuée, prit la parole et dit: " J''étais entré à Gabaa de Benjamin, moi et ma concubine, pour y passer la nuit.'),
('jg',20,5,'crampon1923','Les habitants de Gabaa se sont levés contre moi et ont entouré pendant la nuit la maison où j''étais; ils avaient l''intention de me tuer, et ils ont fait violence à ma concubine, et elle est morte.'),
('jg',20,6,'crampon1923','J''ai saisi ma concubine, je l''ai coupée en morceaux, et je l''ai envoyée dans tout le territoire de l''héritage d''Israël; car ils ont commis un crime et une infamie en Israël.'),
('jg',20,7,'crampon1923','Vous voici tous, enfants d''Israël; consultez-vous, et décidez ici même. "'),
('jg',20,8,'crampon1923','Tout le peuple se leva comme un seul homme en disant: " Nul d''entre nous n''ira dans sa tente, nul ne retournera dans sa maison.'),
('jg',20,9,'crampon1923','Voici maintenant ce que nous ferons à Gabaa: Contre elle d''après le sort!'),
('jg',20,10,'crampon1923','Nous prendrons dans toutes les tribus d''Israël dix hommes sur cent, cent sur mille, et mille sur dix mille; ils iront chercher des vivres pour le peuple, afin qu''à leur arrivée on traite Gabaa de Benjamin selon toute l''infamie qu''elle a commise en Israël. "'),
('jg',20,11,'crampon1923','C''est ainsi que tous les hommes d''Israël s''assemblèrent contre la ville, unis comme un seul homme.'),
('jg',20,12,'crampon1923','Les tribus d''Israël envoyèrent des hommes dans toutes les familles de Benjamin pour dire: " Qu''est-ce que ce crime qui a été commis chez vous?'),
('jg',20,13,'crampon1923','Livrez maintenant les hommes pervers qui sont à Gabaa, afin que nous les fassions mourir et que nous ôtions le mal du milieu d''Israël. " Mais les Benjamites ne voulurent pas écouter la voix de leurs frères les enfants d''Israël.'),
('jg',20,14,'crampon1923','Les fils de Benjamin, sortant de leurs villes, s''assemblèrent à Gabaa pour partir en guerre contre les enfants d''Israël.'),
('jg',20,15,'crampon1923','Les fils de Benjamin, sortis des villes, furent recensés en ce jour au nombre de vingt-six mille, tirant l''épée, sans compter les habitants de Gabaa, formant sept cents hommes d''élite.'),
('jg',20,16,'crampon1923','Parmi tout ce peuple il y avait sept cents hommes d''élite qui ne se servaient pas de la main droite; tous ces combattants pouvaient lancer avec la fronde une pierre à un cheveu, sans le manquer.'),
('jg',20,17,'crampon1923','Le nombre des hommes d''Israël recensés, non compris ceux de Benjamin, fut de quatre cent mille tirant l''épée, tous gens de guerre.'),
('jg',20,18,'crampon1923','Et les enfants d''Israël, s''étant levés, montèrent à Béthel, et consultèrent Dieu, en disant: " Qui de nous montera le premier pour combattre les fils de Benjamin? " Yahweh répondit: " Que Juda monte le premier. "'),
('jg',20,19,'crampon1923','Les enfants d''Israël se mirent en marche dès le matin, et ils campèrent contre Gabaa.'),
('jg',20,20,'crampon1923','Les hommes d''Israël s''avancèrent pour combattre ceux de Benjamin, et les hommes d''Israël se rangèrent en bataille contre eux, devant Gabaa.'),
('jg',20,21,'crampon1923','Alors les fils de Benjamin sortirent de Gabaa, et ils couchèrent par terre ce jour-là vingt-deux mille hommes d''Israël.'),
('jg',20,22,'crampon1923','Le peuple, savoir les hommes d''Israël, affermirent leur courage, et ils se rangèrent de nouveau en bataille dans le lieu où ils s''étaient placés le premier jour.'),
('jg',20,23,'crampon1923','Et les enfants d''Israël montèrent et ils pleurèrent devant Yahweh jusqu''au soir; et ils consultèrent Yahweh, en disant: " Marcherai-je encore pour combattre les fils de Benjamin, mon frère? " Yahweh répondit: " Montez contre lui. "'),
('jg',20,24,'crampon1923','Les enfants d''Israël s''approchèrent des fils de Benjamin, le second jour;'),
('jg',20,25,'crampon1923','et, ce second jour, les fils de Benjamin sortirent de Gabaa à leur rencontre, et ils couchèrent encore par terre dix-huit mille hommes des enfants d''Israël, tous tirant l''épée.'),
('jg',20,26,'crampon1923','Tous les enfants d''Israël et tout le peuple montèrent et vinrent à Béthel; ils pleurèrent, assis là devant Yahweh; ils jeûnèrent en ce jour jusqu''au soir, et ils offrirent des holocaustes et des sacrifices pacifiques devant Yahweh.'),
('jg',20,27,'crampon1923','Et les enfants d''Israël consultèrent Yahweh, — en ces jours-là, l''arche de l''alliance de Dieu était là,'),
('jg',20,28,'crampon1923','et Phinées, fils d''Eléazar, fils d''Aaron, se tenait devant elle, en ces jours, — et ils dirent: " Marcherai-je encore pour combattre les fils de Benjamin, mon frère, ou bien dois-je cesser? " Yahweh répondit: " Montez, car demain je les livrerai en ta main. "'),
('jg',20,29,'crampon1923','Alors Israël plaça une embuscade autour de Gabaa,'),
('jg',20,30,'crampon1923','et, le troisième jour, les enfants d''Israël montèrent contre les fils de Benjamin; ils se rangèrent en bataille devant Gabaa, comme les autres fois.'),
('jg',20,31,'crampon1923','Et les fils de Benjamin sortirent à la rencontre du peuple, en se laissant attirer loin de la ville. Ils commencèrent à frapper et à tuer parmi le peuple, comme les autres fois, sur les routes dont l''une monte à Béthel et l''autre à Gabaa, dans la campagne; ils tuèrent environ trente hommes d''Israël.'),
('jg',20,32,'crampon1923','Les fils de Benjamin disaient: " Les voilà battus devant nous comme auparavant! " Et les enfants d''Israël disaient: " Fuyons, et attirons-les loin de la ville, sur ces route. "'),
('jg',20,33,'crampon1923','Tous les hommes d''Israël quittèrent leur position et se rangèrent à Baal-Thamar; en même temps l''embuscade d''Israël s''élança de son poste, de la plaine de Gabaa.'),
('jg',20,34,'crampon1923','Dix mille hommes d''élite de tout Israël arrivèrent ainsi de devant Gabaa. Le combat fut rude, et les fils de Benjamin ne se doutaient pas que le malheur allait les atteindre.'),
('jg',20,35,'crampon1923','Yahweh battit Benjamin devant Israël, et les enfants d''Israël tuèrent ce jour-là à Benjamin vingt-cinq mille et cent hommes, tous tirant l''épée.'),
('jg',20,36,'crampon1923','Les fils de Benjamin virent donc qu''ils étaient battus. Les hommes d''Israël n''avaient, en effet, cédé du terrain à Benjamin que parce qu''ils avaient confiance dans l''embuscade qu''ils avaient placée contre Gabaa.'),
('jg',20,37,'crampon1923','Quant aux hommes de l''embuscade, ils se jetèrent promptement sur Gabaa; puis, s''avançant, les hommes de l''embuscade frappèrent toute la ville du tranchant de l''épée.'),
('jg',20,38,'crampon1923','Or il y avait ce signe convenu, entre les hommes d''Israël et ceux de l''embuscade. que ceux-ci feraient monter de la ville un nuage de fumée.'),
('jg',20,39,'crampon1923','Les hommes d''Israël firent alors volte-face dans la bataille. Les Benjamites leur avaient tué déjà environ trente hommes, et ils disaient: " Certainement les voilà battus devant nous comme dans le premier combat! "'),
('jg',20,40,'crampon1923','Mais le nuage commençait à s''élever de la ville comme une colonne de fumée, et les Benjamites, regardant derrière eux, aperçurent la ville entière qui montait en feu vers le ciel.'),
('jg',20,41,'crampon1923','Les hommes d''Israël firent volte-face, et les hommes de Benjamin furent épouvantés en voyant que le malheur les atteignait.'),
('jg',20,42,'crampon1923','Ils tournèrent le dos devant les hommes d''Israël, par le chemin du désert; mais les combattants les serrèrent de prés, et ils tuèrent ceux des villes chacun en leurs propres endroits.'),
('jg',20,43,'crampon1923','Ils cernèrent Benjamin, ils le poursuivirent, ils l''écrasèrent là où il faisait halte, jusqu''en face de Gabaa, du côté du soleil levant.'),
('jg',20,44,'crampon1923','Il tomba dix-huit mille hommes de Benjamin, tous hommes vaillants.'),
('jg',20,45,'crampon1923','Ceux qui restaient tournèrent le dos et s''enfuirent vers le désert, vers le rocher de Remmon. Les hommes d''Israël tuèrent cinq mille hommes sur les routes; ils les serrèrent de près jusqu''à Gédéon, et ils en tuèrent deux mille.'),
('jg',20,46,'crampon1923','Le nombre total des Benjamites qui périrent ce jour-là fut de vingt-cinq mille hommes tirant l''épée, tous hommes vaillants.'),
('jg',20,47,'crampon1923','Six cents hommes qui avaient tourné le dos et s''étaient enfuis au désert, vers le rocher de Remmon, demeurèrent au rocher de Remmon pendant quatre mois.'),
('jg',20,48,'crampon1923','Les hommes d''Israël revinrent vers les fils de Benjamin, et ils les frappèrent du tranchant de l''épée, depuis les villes, hommes et troupeaux, jusqu''à tout ce qu''on put trouver. Ils mirent aussi le feu à toutes les villes qu''ils trouvèrent.'),
('jg',21,1,'crampon1923','Les hommes d''Israël avaient juré à Maspha, en disant: " Aucun de nous ne donnera sa fille pour femme à un Benjamite. "'),
('jg',21,2,'crampon1923','Le peuple vint à Béthel, et il y resta devant Dieu jusqu''au soir. Elevant la voix, ils firent de grandes lamentations, et ils dirent:'),
('jg',21,3,'crampon1923','" Pourquoi, ô Yahweh, Dieu d''Israël, est-il arrivé en Israël qu''il manque aujourd''hui une tribu d''Israël? "'),
('jg',21,4,'crampon1923','Le lendemain, le peuple s''étant levé dès le matin, ils bâtirent là un autel, et ils offrirent des holocaustes et des sacrifices pacifiques.'),
('jg',21,5,'crampon1923','Et les enfants d''Israël dirent: " Quel est celui d''entre toutes les tribus d''Israël qui n''est pas monté à l''assemblée devant Yahweh? " Car on avait fait un serment solennel contre celui qui ne monterait pas vers Yahweh à Maspha, en disant: " Il sera puni de mort. "'),
('jg',21,6,'crampon1923','Les enfants d''Israël avaient compassion de Benjamin, leur frère, et ils disaient: " Une tribu a été retranchée aujourd''hui d''Israël!'),
('jg',21,7,'crampon1923','Que ferons-nous pour eux, pour procurer des femmes à ceux qui restent? Car nous avons juré par Yahweh de ne pas leur donner de nos filles pour femmes "'),
('jg',21,8,'crampon1923','Ils dirent donc: " Y a-t-il une seule d''entre les tribus d''Israël qui ne soit pas montée vers Yahweh à Maspha? " Et voici, personne de Jabès en Galaad n''était venu au camp, à l''assemblée.'),
('jg',21,9,'crampon1923','On fit le recensement du peuple, et voici qu''il n''y avait là aucun des habitants de Jabès en Galaad.'),
('jg',21,10,'crampon1923','Alors l''assemblée envoya contre eux douze mille hommes d''entre les vaillants, en leur donnant cet ordre: " Allez, et frappez du tranchant de l''épée les habitants de Jabès en Galaad, avec les femmes et les enfants.'),
('jg',21,11,'crampon1923','Voici ce que vous ferez: vous dévouerez à l''anathème tout homme, et toute femme qui a connu la couche d''un homme. "'),
('jg',21,12,'crampon1923','Ils trouvèrent parmi les habitants de Jabès en Galaad quatre cents jeunes filles vierges, qui n''avaient pas connu d''homme en partageant sa couche, et ils les amenèrent dans le camp à Silo, qui est au pays de Chanaan.'),
('jg',21,13,'crampon1923','Alors toute l''assemblée envoya des messagers pour parler aux fils de Benjamin qui étaient réfugiés au rocher de Remmon, et pour leur annoncer la paix.'),
('jg',21,14,'crampon1923','Les Benjamites revinrent en ce temps-là, et on leur donna les femmes à qui on avait laissé la vie parmi les femmes de Jabès en Galaad; mais il ne s''en trouva pas assez pour eux.'),
('jg',21,15,'crampon1923','Le peuple avait compassion de Benjamin, car Yahweh avait fait une brèche dans les tribus d''Israël.'),
('jg',21,16,'crampon1923','Les anciens de l''assemblée dirent: " Que ferons-nous pour procurer des femmes à ceux qui restent, puisque les femmes de Benjamin ont été détruites? "'),
('jg',21,17,'crampon1923','Et ils dirent: " Que l''héritage de ceux qui ont échappé demeure à Benjamin, afin qu''une tribu ne soit pas effacée d''Israël.'),
('jg',21,18,'crampon1923','Mais nous, nous ne pouvons pas leur donner de nos filles pour femmes, car les enfants d''Israël ont juré, en disant: " Maudit soit celui qui donnera sa fille pour femme à un Benjamite? "'),
('jg',21,19,'crampon1923','Et ils dirent: " Voici une fête de Yahweh, qui se célèbre chaque année à Silo, ville située au nord de Béthel, à l''orient de la route qui monte de Béthel à Sichem, et au midi de Lébona. "'),
('jg',21,20,'crampon1923','Puis ils donnèrent cet ordre aux fils de Benjamin: " Allez, et placez-vous en embuscade dans les vignes.'),
('jg',21,21,'crampon1923','Vous regarderez, et, lorsque les filles de Silo sortiront pour danser en chœur, vous sortirez des vignes, et vous enlèverez chacun votre femme d''entre les filles de Silo, et vous vous en irez dans le pays de Benjamin.'),
('jg',21,22,'crampon1923','Si leurs pères ou leurs frères viennent réclamer auprès de nous, nous leur dirons: Laissez-les-nous, car nous n''avons pas pris une femme pour chacun dans la guerre. Et ce n''est pas vous qui les leur avez données; en ce cas, vous seriez coupables. "'),
('jg',21,23,'crampon1923','Les fils de Benjamin firent ainsi: ils prirent des femmes selon leur nombre parmi les danseuses, qu''ils enlevèrent, et, s''étant mis en route, ils retournèrent dans leur héritage; ils rebâtirent les villes et ils y habitèrent.'),
('jg',21,24,'crampon1923','En ce temps-là, les enfants d''Israël s''en allèrent de là, chacun dans sa tribu et dans sa famille, et ils retournèrent de là, chacun dans son héritage. En ces jours-là, il n''y avait pas de roi en Israël; chacun faisait ce qui était bon...'),
('jg',21,25,'crampon1923',''),
('rt',1,1,'crampon1923','Au temps où les Juges gouvernaient, il y eut une famine dans le pays. Un homme de Bethléem de Juda s''en alla, avec sa femme et ses deux fils, séjourner dans les champs de Moab.'),
('rt',1,2,'crampon1923','Le nom de cet homme était Elimélech, le nom de sa femme était Noémi, et les noms de ses deux fils étaient Mahalon et Cheljon; ils étaient Ephratéens, de Bethléem de Juda. Ils allèrent aux champs de Moab, et s''y établirent.'),
('rt',1,3,'crampon1923','Elimélech mari de Noémi, mourut, et elle resta seule avec ses deux fils,'),
('rt',1,4,'crampon1923','Il prirent des femmes moabites, dont l''une se nommait Orpha et l''autre se nommait Ruth, et ils demeurèrent là environ dix ans.'),
('rt',1,5,'crampon1923','Mahalon et Cheljon moururent aussi tous deux, et la femme resta privée de ses deux fils et de son mari.'),
('rt',1,6,'crampon1923','Alors, s''étant levée, elle et ses belles-filles, elle quitta les champs de Moab, car elle avait appris dans la campagne de Moab que Yahweh avait visité son peuple et lui avait donné du pain.'),
('rt',1,7,'crampon1923','Elle sortit donc du lieu où elle s''était établie, avec ses deux belles-filles et elles se mirent en route pour retourner au pays de Juda.'),
('rt',1,8,'crampon1923','Noémi dit à ses deux belles-filles: " Allez, retournez chacune dans la maison de votre mère. Que Yahweh use de bonté envers vous, comme vous l''avez fait envers ceux qui sont morts et envers moi!'),
('rt',1,9,'crampon1923','Que Yahweh vous fasse trouver à chacune du repos dans la maison d''un époux! " Et elle les baisa. Elles élevèrent la voix et pleurèrent,'),
('rt',1,10,'crampon1923','et elles lui dirent: " Non; nous retournerons avec toi vers ton peuple. "'),
('rt',1,11,'crampon1923','Noémi dit: " Retournez, mes filles; pourquoi viendriez-vous avec moi? Ai-je encore dans mon sein des fils qui puissent devenir vos maris?'),
('rt',1,12,'crampon1923','Retournez, mes filles, allez. Je suis trop âgée pour me remarier. Et quand je dirais: J''ai de l''espérance; quand je serais cette nuit même à un mari et que j''enfanterais des fils,'),
('rt',1,13,'crampon1923','attendriez-vous pour cela jusqu''à ce qu''ils fussent grands? vous abstiendriez-vous pour cela de vous remarier? Non, mes filles. Il m''est très amer à cause de vous que la main de Yahweh se soit appesantie sur moi. "'),
('rt',1,14,'crampon1923','Et, élevant la voix, elles pleurèrent encore. Puis Orpha baisa sa belle-mère, mais Ruth s''attacha à elle.'),
('rt',1,15,'crampon1923','Noémi dit à Ruth: " Voici que ta belle-sœur s''en est retournée vers son peuple et vers son dieu; retourne avec ta belle-sœur. "'),
('rt',1,16,'crampon1923','Ruth répondit: " Ne me presse pas de te laisser en m''en retournant loin de toi. Où tu iras, j''irai; où tu demeureras, je demeurerai; ton peuple sera mon peuple, et ton Dieu sera mon Dieu;'),
('rt',1,17,'crampon1923','où tu mourras, je mourrai et j''y serai ensevelie. Que Yahweh me traite dans toute sa rigueur, si autre chose que la mort me sépare de toi! "'),
('rt',1,18,'crampon1923','Voyant que Ruth était décidée à l''accompagner, Noémi cessa ses instances.'),
('rt',1,19,'crampon1923','Elles s''en allèrent toutes deux, jusqu''à ce qu''elles arrivassent à Bethléem. Lorsqu''elles entrèrent dans Bethléem, toute la ville fut émue à cause d''elles, et les femmes disaient: " Est-ce là Noémi? "'),
('rt',1,20,'crampon1923','Elle leur dit: " Ne m''appelez pas Noémi; appelez-moi Marah, car le Tout-Puissant m''a remplie d''amertume.'),
('rt',1,21,'crampon1923','Je m''en suis allée les mains pleines, et Yahweh me ramène les mains vides. Pourquoi m''appelleriez-vous Noémi, après que Yahweh a témoigné contre moi et que le Tout-Puissant m''a affligée? "'),
('rt',1,22,'crampon1923','C''est ainsi que Noémi revint et, avec elle, sa belle-fille, Ruth la Moabite, qui était arrivée des champs de Moab. Elles arrivèrent à Bethléem au commencement de la moisson des orges.'),
('rt',2,1,'crampon1923','Noémi avait un parent du côté de son mari; C''était un homme puissant et riche, de la famille d''Elimélech et son nom était Booz.'),
('rt',2,2,'crampon1923','Ruth, la Moabite, dit à Noémi: " je voudrais bien aller aux champs glaner des épis derrière celui aux yeux duquel j''aurai trouvé grâce. " Elle lui répondit: " Va, ma fille. "'),
('rt',2,3,'crampon1923','Ruth s''en alla et vint glaner dans un champ derrière les moissonneurs; et il se rencontra qu''elle arriva dans la pièce de terre qui appartenait à Booz, qui était de la famille d''Elimélech.'),
('rt',2,4,'crampon1923','Et voilà que Booz vint de Bethléem, et il dit aux moissonneurs: " Yahweh soit avec vous! " Ils lui répondirent: " Yahweh te bénisse! "'),
('rt',2,5,'crampon1923','Et Booz dit à son serviteur établi sur les moissonneurs: " A qui est cette jeune fille? "'),
('rt',2,6,'crampon1923','Le serviteur établi sur les moissonneurs répondit: " C''est une jeune Moabite, qui est revenue avec Noémi des champs de Moab.'),
('rt',2,7,'crampon1923','Elle nous a dit: Laissez-moi glaner et ramasser des épis entre les gerbes, derrière les moissonneurs, Et, depuis ce matin qu''elle est arrivée, jusqu''à présent, elle a été debout, et ce repos qu''elle prend dans la maison est court. "'),
('rt',2,8,'crampon1923','Booz dit à Ruth: " Ecoute, ma fille, ne va pas glaner dans un autre champ; ne t''éloigne pas d''ici, et reste ainsi avec mes servantes.'),
('rt',2,9,'crampon1923','Regarde le champ que l''on moissonnera, et va derrière elles. N''ai-je pas défendu aux serviteurs de te toucher? Et quand tu auras soif, tu iras aux cruches, et tu boiras de ce que les serviteurs auront puisé. "'),
('rt',2,10,'crampon1923','Alors, tombant sur sa face, elle se prosterna contre terre et lui dit: " Comment ai-je trouvé grâce à tes yeux, pour que tu t''intéresses à moi, qui suis une étrangère? "'),
('rt',2,11,'crampon1923','Booz lui répondit: " On m''a rapporté tout ce que tu as fait pour ta belle-mère après la mort de ton mari, et comment tu as quitté ton père et ta mère et le pays de ta naissance, et tu es venue vers un peuple que tu ne connaissais pas auparavant.'),
('rt',2,12,'crampon1923','Que Yahweh te rende ce que tu as fait, et que ta récompense soit pleine, de la part de Yahweh, le Dieu d''Israël, sous les ailes duquel tu es venue te réfugier! "'),
('rt',2,13,'crampon1923','Et elle dit: " Oh! que je trouve grâce à tes yeux, mon seigneur! Car tu m''as consolée, et tu as parlé au cœur de ta servante, bien que je ne sois pas même comme l''une de tes servantes. "'),
('rt',2,14,'crampon1923','Au moment du repas, Booz dit à Ruth: " Approche, mange du pain et trempe ton morceau dans le vinaigre. " Elle s''assit à côté des moissonneurs; Booz lui donna du grain rôti; elle mangea et se rassasia, et elle garda le reste;'),
('rt',2,15,'crampon1923','ensuite elle se leva pour glaner. Et Booz donna cet ordre à ses serviteurs: " qu''elle glane aussi entre les gerbes, et ne lui faites pas de honte;'),
('rt',2,16,'crampon1923','et même vous tirerez pour elle quelques épis des javelles, que vous laisserez par terre, afin qu''elle les ramasse, et vous ne lui ferez point de reproches. "'),
('rt',2,17,'crampon1923','Elle glana dans le champ jusqu''au soir, et elle battit ce qu''elle avait glané; il y eut environ un épha d''orge.'),
('rt',2,18,'crampon1923','Elle l''emporta et revint à la ville, et sa belle-mère vit ce qu''elle avait glané. Elle tira aussi ce qu''elle avait gardé de reste après son repas, et le donna.'),
('rt',2,19,'crampon1923','Sa belle-mère lui dit: " Où as-tu glané aujourd''hui, et où as-tu travaillé? Béni soit celui qui s''est intéressé à toi! " Et Ruth fit connaître à sa belle-mère chez qui elle avait travaillé, en disant: " L''homme chez qui j''ai travaillé aujourd''hui s''appelle Booz. "'),
('rt',2,20,'crampon1923','Noémi dit à sa belle-fille: " Qu''il soit béni de Yahweh de ce qu''il n''a pas cessé d''être miséricordieux envers les vivants, aussi bien qu''envers ceux qui sont morts! " Noémi lui dit encore: " Cet homme est pour nous un proche parent et l''un de ceux qui ont sur nous droit de rachat. "'),
('rt',2,21,'crampon1923','Ruth, la Moabite, dit: Il m''a dit encore: Reste avec mes serviteurs jusqu''à ce qu''ils aient achevé toute ma moisson. "'),
('rt',2,22,'crampon1923','Et Noémi dit à Ruth, sa belle-fille: " Il est bon, ma fille, que tu sortes avec ses servantes, afin qu''on ne te maltraite pas dans un autre champ. "'),
('rt',2,23,'crampon1923','Elle resta donc avec les servantes de Booz pour glaner, jusqu''à la fin de la moisson des orges et de la moisson du froment; et elle demeurait avec sa belle-mère.'),
('rt',3,1,'crampon1923','Noémi, sa belle-mère lui dit: " Ma fille, je veux te chercher un lieu de repos où tu sois heureuse.'),
('rt',3,2,'crampon1923','Et maintenant, Booz, avec les servantes duquel tu as été, n''est-il pas notre parent? Voici qu''il doit vanner cette nuit l''orge qui est dans l''aire.'),
('rt',3,3,'crampon1923','Lave-toi et oins-toi, mets tes plus beaux vêtements, et descends vers l''aire. Ne te laisse pas apercevoir de lui, jusqu''à ce qu''il ait achevé de manger et de boire.'),
('rt',3,4,'crampon1923','Et quand il ira se coucher, observe le lieu où il se couche; puis entre, soulève la couverture de ses pieds et couche-toi; lui-même te dira ce que tu as à faire. "'),
('rt',3,5,'crampon1923','Elle lui répondit: " Je ferai tout ce que tu me dis. "'),
('rt',3,6,'crampon1923','Elle descendit dans l''aire et fit tout ce que lui avait ordonné sa belle-mère.'),
('rt',3,7,'crampon1923','Booz mangea et but, et son cœur fut joyeux. Il alla se coucher à l''extrémité du tas de gerbes; alors Ruth s''approcha doucement, découvrit ses pieds et se coucha.'),
('rt',3,8,'crampon1923','Au milieu de la nuit, cet homme eut une frayeur; il se pencha et, voici qu''une femme était couchée à ses pieds.'),
('rt',3,9,'crampon1923','Il dit: " Qui es-tu? ". Elle répondit: " Je suis Ruth, ta servante; étends sur ta servante le pan de ton manteau, car tu as droit de rachat. "'),
('rt',3,10,'crampon1923','Il dit: " Bénie sois-tu de Yahweh, ma fille! Ton dernier amour surpasse le premier, car tu n''as pas recherché des jeunes gens, pauvres ou riches.'),
('rt',3,11,'crampon1923','Maintenant, ma fille, ne crains point; tout ce que tu diras, je le ferai pour toi; car tout le peuple de Bethléem sait que tu es une femme vertueuse.'),
('rt',3,12,'crampon1923','Maintenant. c''est en vérité que j''ai un droit de rachat, mais il y en a un autre plus proche que moi.'),
('rt',3,13,'crampon1923','Passe ici la nuit; et demain, s''il veut te racheter, c''est bien, qu''il te rachète; mais s''il ne veut pas te racheter, je te rachèterai, moi. Yahweh est vivant! Reste couchée jusqu''au matin! "'),
('rt',3,14,'crampon1923','Elle resta donc couchée à ses pieds jusqu''au matin, et elle se leva avant qu''un homme pût en reconnaître un autre. Booz dit: " Qu''on ne sache pas que cette femme est entrée dans l''aire. "'),
('rt',3,15,'crampon1923','Et il ajouta: " Donne le manteau qui est sur toi, et tiens-le. " Elle le tint: et il mesura six mesures d''orge, qu''il chargea sur elle; puis il rentra dans la ville.'),
('rt',3,16,'crampon1923','Ruth étant revenue auprès de sa belle-mère, Noémi lui dit: " Qu''as-tu fait, ma fille? " Ruth lui raconta tout ce que cet homme avait fait pour elle:'),
('rt',3,17,'crampon1923','" Il m''a donné, ajouta-t-elle, ces six mesures d''orge, en me disant: Tu ne retourneras pas les mains vides chez ta belle-mère. "'),
('rt',3,18,'crampon1923','Et Noémi dit: " Reste ici, ma fille, jusqu''à ce que tu saches comment finira l''affaire; car cet homme ne se donnera point de repos qu''il n''ait terminé cette affaire aujourd''hui. "'),
('rt',4,1,'crampon1923','Booz monta à la porte de la ville et s''y assit. Or voici que celui qui avait droit de rachat et dont Booz avait parlé, vint à passer. Il lui dit: " Arrête-toi, assieds-toi ici, toi un tel. " Cet homme s''arrêta et s''assit.'),
('rt',4,2,'crampon1923','Alors Booz prit dix hommes parmi les anciens de la ville, et il dit: " Asseyez-vous ici. " Et ils s''assirent.'),
('rt',4,3,'crampon1923','Il dit à celui qui avait le droit de rachat: " La portion de champ qui appartenait à notre frère Elimélech, a été vendue par Noémi, qui est revenue des champs de Moab.'),
('rt',4,4,'crampon1923','Et j''ai dit: je veux t''en informer et te dire: Achète-la en présence de ceux qui siègent ici, et en présence des anciens de mon peuple. Si tu veux racheter, rachète; si tu ne veux pas, déclare-le-moi, afin que je le sache; car il n''y a personne avant toi qui ait le droit de rachat; moi, je viens après toi. " Il répondit: " Je rachèterai. "'),
('rt',4,5,'crampon1923','Et Booz dit: " Le jour où tu acquerras le champ de la main de Noémi, tu l''acquerras en même temps de Ruth la Moabite, femme du défunt, pour faire revivre le nom du défunt dans son héritage. "'),
('rt',4,6,'crampon1923','Celui qui avait le droit de rachat répondit: " Je ne puis pas le racheter pour mon compte, de peur de détruire mon propre héritage. Fais usage de mon droit de rachat, car je ne puis racheter. "'),
('rt',4,7,'crampon1923','C''était autrefois la coutume en Israël, en cas de rachat et d''échange, pour valider toute affaire, que l''homme ôtât son soulier et le donnât à l''autre cela servait de témoignage en Israël.'),
('rt',4,8,'crampon1923','Celui qui avait le droit de rachat dit à Booz " Acquiers pour ton compte. " Et il ôta son soulier.'),
('rt',4,9,'crampon1923','Et Booz dit aux anciens et à tout le peuple: " Vous êtes témoins aujourd''hui que j''ai acquis de la main de Noémi tout ce qui appartenait à Elimélech, et tout ce qui appartenait à Cheljon et à Mahalon,'),
('rt',4,10,'crampon1923','et que j''ai acquis en même temps pour femme Ruth la Moabite, femme de Mahalon, pour faire revivre le nom du défunt dans son héritage, afin que le nom du défunt ne soit point retranche d''entre ses frères et de la porte de son lieu. Vous en êtes témoins en ce jour! "'),
('rt',4,11,'crampon1923','Tout le peuple qui était à la porte et les anciens dirent: " Nous en sommes témoins. Que Yahweh rende la femme qui entre dans ta maison semblable à Rachel et à Lia, qui toutes les deux ont bâti la maison d''Israël! Sois fort dans Ephrata, et fais-toi un nom dans Bethléem!'),
('rt',4,12,'crampon1923','Puisse ta maison être semblable à la maison de Pharès, — que Thamar enfanta à Juda, — par la postérité que Yahweh te donnera de cette jeune femme! "'),
('rt',4,13,'crampon1923','Booz prit Ruth, et elle fut sa femme, et il alla vers elle. Yahweh donna à Ruth de concevoir, et elle enfanta un fils.'),
('rt',4,14,'crampon1923','Les femmes dirent à Noémi: " Béni soit Yahweh, qui ne t''a point laissé manquer aujourd''hui d''un rédempteur! Que son nom devienne célèbre en Israël!'),
('rt',4,15,'crampon1923','Il restaurera ton âme et sera le soutien de ta vieillesse! Car ta belle-fille, qui t''aime, l''a enfanté, elle qui vaut mieux pour toi que sept fils. "'),
('rt',4,16,'crampon1923','Noémi prit l''enfant, le mit sur son sein, et elle lui servit de nourrice.'),
('rt',4,17,'crampon1923','Les voisines lui donnèrent un nom, en disant: " Un fils est né à Noémi! " Et elles l''appelèrent Obed. Ce fut le père d''Isaï, père de David.'),
('rt',4,18,'crampon1923','Voici la postérité de Pharès: Pharès engendra Esron;'),
('rt',4,19,'crampon1923','Esron engendra Aram; Aram engendra Aminadab;'),
('rt',4,20,'crampon1923','Aminadab engendra Nahasson; Nahasson engendra Salmon;'),
('rt',4,21,'crampon1923','Salmon engendra Booz; Booz engendra Obed;'),
('rt',4,22,'crampon1923','Obed engendra Isaï: Isaï engendra David. "'),
('1s',1,1,'crampon1923','Il y avait un homme de Ramathaïm-Sophim, de la montagne d''Ephraïm, nommé Elcana, fils de Jéroham, fils d''Eliu, fils de Thohu, fils de Suph, Ephratéen.'),
('1s',1,2,'crampon1923','Il avait deux femmes, dont l''une s''appelait Anne, et l''autre Phénenna; et Phénenna avait des enfants, mais Anne était sans enfants.'),
('1s',1,3,'crampon1923','Cet homme montait de sa ville, chaque année, pour adorer Yahweh des armées et lui offrir des sacrifices à Silo. Là étaient les deux fils d''Héli, Ophni et Phinées, prêtres de Yahweh.'),
('1s',1,4,'crampon1923','Le jour où Elcana offrait son sacrifice, il donnait des portions de la victime à Phénenna, sa femme, et à tous ses fils et à toutes ses filles;'),
('1s',1,5,'crampon1923','et il donnait à Anne une double portion, car il aimait Anne, et Yahweh l''avait rendue stérile.'),
('1s',1,6,'crampon1923','Sa rivale l''affligeait encore extrêmement, afin de l''aigrir de ce que Yahweh l''avait rendue stérile.'),
('1s',1,7,'crampon1923','Et chaque année Elcana faisait ainsi, toutes les fois qu''elle montait à la maison de Yahweh, et Phénenna la mortifiait de la même manière. Alors elle pleurait et ne mangeait point.'),
('1s',1,8,'crampon1923','Elcana, son mari, lui disait: « Anne, pourquoi pleures-tu et ne manges-tu pas? Pourquoi ton cœur est-il triste? Est-ce que je ne suis pas pour toi mieux que dix fils? »'),
('1s',1,9,'crampon1923','Anne se leva, après qu''on eut mangé et bu à Silo. — Héli, le grand prêtre, était assis sur un siège devant un des poteaux du temple de Yahweh. —'),
('1s',1,10,'crampon1923','L''âme pleine d''amertume, elle pria Yahweh et versa beaucoup de larmes;'),
('1s',1,11,'crampon1923','et elle fit un vœu, en disant: « Yahweh des armées, si vous daignez regarder l''affliction de votre servante, si vous vous souvenez de moi et n''oubliez point votre servante, et si vous donnez à votre servante un enfant mâle, je le donnerai à Yahweh pour tous les jours de sa vie, et le rasoir ne passera pas sur sa tête. »'),
('1s',1,12,'crampon1923','Comme elle restait longtemps en prière devant Yahweh, Héli observa sa bouche.'),
('1s',1,13,'crampon1923','Anne parlait en son cœur et remuait seulement les lèvres, sans que sa voix se fit entendre. Héli pensa donc qu''elle était ivre,'),
('1s',1,14,'crampon1923','et il lui dit: « Jusques à quand seras-tu dans l''ivresse? Fais passer ton vin. »'),
('1s',1,15,'crampon1923','Anne répondit: « Non, mon seigneur je suis une femme affligée dans son cœur; je n''ai bu ni vin ni boisson enivrante, mais j''épanchais mon âme devant Yahweh.'),
('1s',1,16,'crampon1923','Ne prends pas ta servante pour une femme de Bélial, car c''est dans l''excès de ma peine et de ma douleur que j''ai parlé jusqu''ici. »'),
('1s',1,17,'crampon1923','Héli reprit la parole et lui dit: « Va en paix, et que le Dieu d''Israël exauce la prière que tu lui as adressée! »'),
('1s',1,18,'crampon1923','Elle dit: « Que ta servante trouve grâce à tes yeux! » Et cette femme alla son chemin; elle mangea, et son visage n''était plus le même.'),
('1s',1,19,'crampon1923','Ils se levèrent de bon matin et, s''étant prosternés devant Yahweh, ils s''en retournèrent et revinrent dans leur maison à Rama.'),
('1s',1,20,'crampon1923','Elcana connut Anne, sa femme, et Yahweh se souvint d''elle. Après le temps révolu, Anne ayant conçu, enfanta un fils, qu''elle nomma Samuel, « car, dit-elle, je l''ai demandé à Yahweh. »'),
('1s',1,21,'crampon1923','Son mari Elcana monta avec toute sa maison pour offrir à Yahweh le sacrifice annuel et pour accomplir son vœu.'),
('1s',1,22,'crampon1923','Mais Anne ne monta pas, et elle dit à son mari: « Quand l''enfant sera sevré, je le mènerai pour qu''il paraisse devant Yahweh et qu''il demeure là toujours. »'),
('1s',1,23,'crampon1923','Elcana, son mari, lui dit: « Fais ce qui te semblera bon, reste ici jusqu''à ce que tu l''aies sevré. Daigne seulement Yahweh accomplir sa parole! » Et la femme resta et allaita son fils, jusqu''à ce qu''elle le sevrât.'),
('1s',1,24,'crampon1923','Quand elle l''eut sevré, elle le fit monter avec elle, ayant pris trois taureaux, un épha de farine et une outre de vin, et elle le mena dans la maison de Yahweh à Silo; l''enfant était encore tout jeune.'),
('1s',1,25,'crampon1923','Ils égorgèrent le taureau, et ils conduisirent l''enfant à Héli.'),
('1s',1,26,'crampon1923','Anne dit: « Pardon, mon seigneur. Aussi vrai que ton âme vit, mon seigneur, je suis cette femme qui me tenais ici près de toi pour prier Yahweh.'),
('1s',1,27,'crampon1923','C''est pour cet enfant que je priais, et Yahweh m''a accordé la demande que je lui avais faite.'),
('1s',1,28,'crampon1923','Moi aussi je le donne à Yahweh; tous les jours de sa vie, il sera donné à Yahweh. » Et ils se prosternèrent là devant Yahweh.'),
('1s',2,1,'crampon1923','Anne pria et dit: Mon cœur tressaille de joie en Yahweh, ma corne a été élevée par Yahweh, ma bouche est ouverte sur mes ennemis, car je me suis réjouie de ton secours.'),
('1s',2,2,'crampon1923','Nul n''est saint comme Yahweh, car il n''y a pas d''autre Dieu que toi; il n''y a pas de rocher comme notre Dieu.'),
('1s',2,3,'crampon1923','Ne prononcez pas tant de paroles hautaines, qu''un langage arrogant ne sorte pas de votre bouche. Car Yahweh est un Dieu qui sait tout, et les actions de l''homme ne subsistent pas.'),
('1s',2,4,'crampon1923','L''arc des puissants est brisé, et les faibles ont la force pour ceinture.'),
('1s',2,5,'crampon1923','Ceux qui étaient rassasiés se louent pour du pain, et ceux qui étaient affamés n''ont plus faim; même la stérile enfante sept fois, et celle qui avait beaucoup de fils se flétrit.'),
('1s',2,6,'crampon1923','Yahweh fait mourir et il fait vivre, il fait descendre au séjour des morts et il en fait remonter.'),
('1s',2,7,'crampon1923','Yahweh appauvrit et il enrichit, il abaisse et il élève.'),
('1s',2,8,'crampon1923','De la poussière il retire le pauvre, du fumier il relève l''indigent, pour les faire asseoir avec les princes, et il leur donne en partage un trône de gloire. Car à Yahweh sont les colonnes de la terre, et sur elles il a posé le globe.'),
('1s',2,9,'crampon1923','Il gardera les pas de ses pieux, mais les méchants périront dans les ténèbres. Car l''homme ne l''emportera pas par la force.'),
('1s',2,10,'crampon1923','Yahweh! Ses ennemis seront brisés; du haut du ciel il tonnera sur eux, Yahweh jugera les extrémités de la terre. Il donnera la puissance à son roi, et il élèvera la corne de son oint.'),
('1s',2,11,'crampon1923','Elcana s''en alla dans sa maison à Rama, et l''enfant resta au service de Yahweh, devant le prêtre Héli.'),
('1s',2,12,'crampon1923','Or les fils d''Héli étaient des hommes de Bélial, ils ne connaissaient point Yahweh.'),
('1s',2,13,'crampon1923','Et voici la manière d''agir de ces prêtres à l''égard du peuple. Lorsque quelqu''un offrait un sacrifice, le serviteur du prêtre venait, pendant qu''on faisait bouillir la chair, tenant à la main une fourchette à trois dents;'),
('1s',2,14,'crampon1923','il la plongeait dans la chaudière, dans le chaudron, dans la marmite ou dans le pot, et tout ce que la fourchette amenait, le prêtre le prenait pour lui. C''est ainsi qu''ils agissaient à l''égard de tous les Israélites qui venaient là, à Silo.'),
('1s',2,15,'crampon1923','Même avant qu''on fît brûler la graisse, le serviteur du prêtre venait et disait à l''homme qui offrait le sacrifice: « Donne-moi de la chair à rôtir pour le prêtre; il ne recevra pas de toi de chair bouillie, mais seulement de la chair crue. »'),
('1s',2,16,'crampon1923','Et si l''homme lui disait: « Qu''on fasse d''abord fumer la graisse; tu prendras ensuite ce que tu voudras, » le serviteur répondait: « Non, tu en donneras maintenant; sinon, j''en prendrai de force. »'),
('1s',2,17,'crampon1923','Le péché de ces jeunes gens était très grand devant Yahweh, parce que ces hommes attiraient le mépris sur les offrandes de Yahweh.'),
('1s',2,18,'crampon1923','Samuel faisait le service devant Yahweh: l''enfant était revêtu d''un éphod de lin.'),
('1s',2,19,'crampon1923','Sa mère lui faisait une petite robe, qu''elle lui apportait chaque année, lorsqu''elle montait avec son mari, pour offrir le sacrifice annuel.'),
('1s',2,20,'crampon1923','Héli bénit Elcana et sa femme, en disant: « Que Yahweh te donne des enfants de cette femme, pour le don qu''elle a fait à Yahweh! » Et ils s''en retournèrent chez eux.'),
('1s',2,21,'crampon1923','Yahweh visita Anne, et elle conçut et enfanta trois fils et deux filles. Et le jeune Samuel grandissait en la présence de Yahweh.'),
('1s',2,22,'crampon1923','Héli était très vieux, et il apprit comment ses fils agissaient à l''égard de tout Israël, et qu''ils couchaient avec les femmes qui servaient à l''entrée de la tente de réunion.'),
('1s',2,23,'crampon1923','Il leur dit: « Pourquoi faites-vous de telles choses? Car j''apprends de tout le peuple vos mauvaises actions.'),
('1s',2,24,'crampon1923','Non, mes enfants, la rumeur que j''entends n''est pas bonne; on fait pécher le peuple de Yahweh.'),
('1s',2,25,'crampon1923','Si un homme pèche contre un autre homme, Dieu intervient comme arbitre; mais si c''est contre Yahweh qu''il pèche, qui intercédera pour lui? » Et ils n''écoutaient point la voix de leur père, car Yahweh voulait les faire mourir.'),
('1s',2,26,'crampon1923','Le jeune Samuel continuait à grandir, et il était agréable à Yahweh et aux hommes.'),
('1s',2,27,'crampon1923','Un homme de Dieu vint auprès d''Héli et lui dit: « Ainsi parle Yahweh: Ne me suis-je pas clairement révélé à la maison de ton père, lorsqu''ils étaient en Egypte dans la maison de Pharaon?'),
('1s',2,28,'crampon1923','Je l''ai choisi d''entre toutes les tribus d''Israël pour être mon prêtre, pour monter à mon autel, pour faire fumer l''encens, pour porter l''éphod devant moi; et j''ai donné à la maison de ton père toutes les offrandes des enfants d''Israël faites par le feu.'),
('1s',2,29,'crampon1923','Pourquoi avez-vous foulé aux pieds mes sacrifices et mes oblations, que j''ai ordonné d''offrir dans ma demeure? Et pourquoi as-tu honoré tes fils plus que moi, en vous engraissant du meilleur de toutes les offrandes d''Israël, mon peuple?'),
('1s',2,30,'crampon1923','C''est pourquoi, voici la parole de Yahweh, le Dieu d''Israël: J''avais déclaré que ta maison et la maison de ton père marcheraient devant moi à perpétuité. Et maintenant, dit Yahweh, qu''il n''en soit plus ainsi! Car j''honorerai ceux qui m''honorent, et ceux qui me méprisent seront méprisés.'),
('1s',2,31,'crampon1923','Voici que les jours viennent où je retrancherai ton bras et le bras de la maison de ton père, en sorte qu''il n''y aura plus de vieillard dans ta maison.'),
('1s',2,32,'crampon1923','Tu verras ta demeure humiliée, pendant que Dieu comblera de biens Israël; et il n''y aura plus jamais de vieillard dans ta maison.'),
('1s',2,33,'crampon1923','Je ne ferai pas disparaître de mon autel tout homme des tiens, afin que tes yeux se consument et que ton âme défaille; mais tout rejeton de ta maison mourra dans la force de l''âge.'),
('1s',2,34,'crampon1923','Et tu auras pour signe ce qui arrivera à tes deux fils, à Ophni et Phinées: ils mourront tous deux le même jour.'),
('1s',2,35,'crampon1923','Et je me susciterai un prêtre fidèle, qui agira selon mon cœur et selon mon âme, je lui bâtirai une maison stable, et il marchera toujours devant mon oint.'),
('1s',2,36,'crampon1923','Et quiconque restera de ta maison viendra se prosterner devant lui, pour avoir une pièce d''argent et un morceau de pain, et il dira: Mets-moi, je te prie, à quelqu''une des fonctions du sacerdoce, afin que j''aie un morceau de pain à manger. »'),
('1s',3,1,'crampon1923','Le jeune Samuel servait Yahweh en la présence d''Héli. La parole de Yahweh était rare en ces jours-là, et la vision n''était pas fréquente.'),
('1s',3,2,'crampon1923','En ce même temps, comme Héli était couché à sa place, — or ses yeux avaient commencé à se troubler et il ne pouvait plus voir;'),
('1s',3,3,'crampon1923','la lampe de Dieu ne s''était pas encore éteinte, et Samuel était couché dans le temple de Yahweh, où était l''arche de Dieu, —'),
('1s',3,4,'crampon1923','Yahweh appela Samuel; il répondit: « Me voici! »'),
('1s',3,5,'crampon1923','Et il courut auprès d''Héli, et lui dit: « Me voici, car tu m''as appelé. » Héli répondit: « Je n''ai point appelé; retourne te coucher. » Et il alla se coucher.'),
('1s',3,6,'crampon1923','Yahweh appela de nouveau Samuel; et Samuel se leva et, étant allé auprès d''Héli, il dit: « Me voici, car tu m''as appelé. » Héli répondit: « Je n''ai point appelé, mon fils; retourne te coucher. »'),
('1s',3,7,'crampon1923','Samuel ne connaissait pas encore Yahweh, car la parole de Yahweh ne lui avait pas encore été révélée.'),
('1s',3,8,'crampon1923','Yahweh appela de nouveau Samuel pour la troisième fois. Il se leva et, étant allé auprès d''Héli, il dit: « Me voici, car tu m''as appelé. » Héli comprit alors que c''était Yahweh qui appelait l''enfant.'),
('1s',3,9,'crampon1923','Et Héli dit à Samuel: « Va, couche-toi, et si l''on t''appelle encore, tu diras: Parlez, Yahweh, car votre serviteur écoute. » Et Samuel s''en alla et se coucha à sa place.'),
('1s',3,10,'crampon1923','Yahweh vint et se tint là, et il appela comme les autres fois: « Samuel! Samuel! » Samuel répondit: « Parlez, car votre serviteur écoute. »'),
('1s',3,11,'crampon1923','Et Yahweh dit à Samuel: « Voici que je vais faire dans Israël une chose que personne n''entendra sans que les deux oreilles lui tintent.'),
('1s',3,12,'crampon1923','En ce jour-là j''accomplirai sur Héli tout ce que j''ai prononcé touchant sa maison; je commencerai et j''achèverai.'),
('1s',3,13,'crampon1923','Je lui ai déclaré que j''allais juger sa maison pour jamais, à cause du crime dont il avait connaissance, et par lequel ses fils se sont rendus indignes sans qu''il les ait réprimés.'),
('1s',3,14,'crampon1923','C''est pourquoi j''ai juré à la maison d''Héli que jamais le crime de la maison d''Héli ne sera expié, ni par des sacrifices ni par des oblations. »'),
('1s',3,15,'crampon1923','Samuel resta couché jusqu''au matin, puis il ouvrit les portes de la maison de Yahweh. Et Samuel craignait de raconter la vision à Héli.'),
('1s',3,16,'crampon1923','Mais Héli appela Samuel, en disant: « Samuel, mon fils! » Il répondit: « Me voici. »'),
('1s',3,17,'crampon1923','Et Héli dit: « Quelle est la parole que Yahweh t''a dite? Je te prie, ne me cache rien. Que Yahweh te traite dans toute sa rigueur si tu me caches quelque chose de toute la parole qu''il t''a dite! »'),
('1s',3,18,'crampon1923','Samuel lui raconta toutes les paroles sans lui rien cacher. Et Héli dit: « C''est Yahweh; ce qui lui semblera bon, qu''il le fasse! »'),
('1s',3,19,'crampon1923','Samuel devint grand; Yahweh était avec lui, et il ne laissa tomber à terre aucune de ses paroles.'),
('1s',3,20,'crampon1923','Tout Israël, depuis Dan jusqu''à Bersabée, reconnut que Samuel était un vrai prophète de Yahweh.'),
('1s',3,21,'crampon1923','Et Yahweh continuait d''apparaître à Silo, car Yahweh se manifestait à Samuel, à Silo, par la parole de Yahweh.'),
('1s',4,1,'crampon1923','La parole de Samuel fut adressée à tout Israël. Israël sortit au devant des Philistins, pour combattre; ils campèrent près d''Eben-Ezer, et les Philistins étaient campés à Aphec.'),
('1s',4,2,'crampon1923','Les Philistins, s''étant rangés en bataille contre Israël, le combat s''engagea, et Israël fut battu par les Philistins, et ils tuèrent environ quatre mille hommes en bataille rangée dans la plaine.'),
('1s',4,3,'crampon1923','Le peuple rentra au camp, et les anciens d''Israël dirent: « Pourquoi Yahweh nous a-t-il battus aujourd''hui devant les Philistins? Faisons venir vers nous de Silo l''arche de l''Alliance de Yahweh; qu''elle vienne au milieu de nous, et qu''elle nous délivre de la main de nos ennemis. »'),
('1s',4,4,'crampon1923','Le peuple envoya à Silo, et l''on apporta de cette ville l''arche de l''alliance de Yahweh des armées, qui est assis sur les Chérubins. Les deux fils d''Héli, Ophni et Phinées, étaient là avec l''arche de l''alliance de Dieu.'),
('1s',4,5,'crampon1923','Lorsque l''arche de l''alliance de Yahweh entra dans le camp, tout Israël poussa de si grands cris de joie que la terre en retentit.'),
('1s',4,6,'crampon1923','Le bruit de ces clameurs fut entendu des Philistins, et ils dirent: « Que signifie le bruit de ces grands cris de joie au camp des Hébreux? » Et ils apprirent que l''arche de Yahweh était venue au camp.'),
('1s',4,7,'crampon1923','Les Philistins eurent peur, parce qu''ils disaient: « Dieu est venu dans le camps. » Et ils dirent: « Malheur à nous! car chose pareille n''a jamais eu lieu jusqu''à présent.'),
('1s',4,8,'crampon1923','Malheur à nous! Qui nous délivrera de la main de ces dieux puissants? Ce sont ces dieux qui ont frappé les Egyptiens de toutes sortes de plaies dans le désert.'),
('1s',4,9,'crampon1923','Montrez-vous forts et agissez en hommes, Philistins, de peur que vous ne soyez asservis aux Hébreux, comme ils vous sont asservis. Soyez des hommes et combattez. »'),
('1s',4,10,'crampon1923','Les Philistins livrèrent bataille, et Israël fut battu, et chacun s''enfuit dans sa tente; il y eut une très grande défaite, et il tomba du côté d''Israël trente mille hommes de pied.'),
('1s',4,11,'crampon1923','L''arche de Dieu fut prise, et les deux fils d''Héli, Ophni et Phinées, périrent.'),
('1s',4,12,'crampon1923','Un homme de Benjamin accourut du champ de bataille, et vint à Silo le même jour, les vêtements déchirés et la tête couverte de poussière.'),
('1s',4,13,'crampon1923','Lorsqu''il arriva, Héli était assis sur un siège près du chemin, dans l''attente, car son cœur tremblait à cause de l''arche de Dieu. Cet homme étant entré dans la ville pour porter ces nouvelles, toute la ville poussa une clameur.'),
('1s',4,14,'crampon1923','En entendant le bruit de cette clameur, Héli dit: « Quel est ce bruit de tumulte? » Et aussitôt l''homme vint apporter la nouvelle à Héli.'),
('1s',4,15,'crampon1923','Or Héli était âgé de quatre-vingt-dix-huit ans; il avait les yeux fixes et ne pouvait plus voir.'),
('1s',4,16,'crampon1923','L''homme dit à Héli: « J''arrive du champ de bataille, et c''est du champ de bataille que je me suis enfui aujourd''hui. » Héli dit: « Que s''est-il passé mon fils? »'),
('1s',4,17,'crampon1923','Le messager répondit: « Israël a fui devant les Philistins, et il y a eu un grand massacre parmi le peuple; et même tes deux fils, Ophni et Phinées, sont morts, et l''arche de Dieu a été prise. »'),
('1s',4,18,'crampon1923','A peine eut-il nommé l''arche de Dieu, qu''Héli tomba de son siège à la renverse, à côté de la porte; il se rompit la nuque et mourut; car c''était un homme vieux et pesant. Il avait jugé Israël pendant quarante ans.'),
('1s',4,19,'crampon1923','Sa belle-fille, femme de Phinées, était enceinte et sur le point d''accoucher. Lorsqu''elle entendit la nouvelle de la prise de l''arche de Dieu, de la mort de son beau-père et de son mari, elle se courba et enfanta, car les douleurs lui survinrent.'),
('1s',4,20,'crampon1923','Comme elle allait mourir, les femmes qui se trouvaient près d''elle lui dirent: « Ne crains point, car tu as enfanté un fils. » Mais elle ne répondit pas et n''y fit pas attention.'),
('1s',4,21,'crampon1923','Elle appela l''enfant Ichabod, en disant: « La gloire est emportée d''Israël: » à cause de la prise de l''arche de Dieu et à cause de la mort de son beau-père et de son mari.'),
('1s',4,22,'crampon1923','Elle dit: « La gloire est emportée d''Israël, car l''arche de Dieu est prise! »'),
('1s',5,1,'crampon1923','Les Philistins, s''étant emparés de l''arche de Dieu, la transportèrent d''Eben-Ezer à Azot.'),
('1s',5,2,'crampon1923','Les Philistins prirent l''arche de Dieu, la firent entrer dans la maison de Dagon, et la placèrent auprès de Dagon.'),
('1s',5,3,'crampon1923','Le lendemain, les Azotiens se levèrent de bon matin, et voici que Dagon était étendu la face contre terre devant l''arche de Yahweh. Ils prirent Dagon et le remirent à sa place.'),
('1s',5,4,'crampon1923','Le jour suivant, ils se levèrent de bon matin et voici que Dagon était encore étendu la face contre terre devant l''arche de Yahweh; la tête de Dagon et ses deux mains détachées gisaient sur le seuil,'),
('1s',5,5,'crampon1923','et il ne lui restait que le tronc en forme de poisson. C''est pourquoi les prêtres de Dagon et tous ceux qui entrent dans la maison de Dagon à Azot ne posent pas le pied sur le seuil de Dagon, jusqu''à ce jour.'),
('1s',5,6,'crampon1923','La main de Yahweh, s''appesantit sur les Azotiens et les désola; il les frappa de tumeurs, à Azot et dans son territoire.'),
('1s',5,7,'crampon1923','Voyant ce qui arrivait, les Azotiens dirent: « Que l''arche du Dieu d''Israël ne reste pas chez nous, car il appesantit sa main sur nous et sur Dagon, notre dieu. »'),
('1s',5,8,'crampon1923','Et ils convoquèrent chez eux par des envoyés tous les princes des Philistins, et ils dirent: « Que ferons-nous de l''arche du Dieu d''Israël? » Les princes répondirent: « Que l''on transporte à Geth l''arche du Dieu d''Israël! » Et l''on y transporta l''arche du Dieu d''Israël.'),
('1s',5,9,'crampon1923','Mais, dès qu''on l''eut transportée, la main de Yahweh fut sur la ville, et il y eut une très grande épouvante; il frappa les gens de la ville, depuis le petit jusqu''au grand, et il leur poussa des tumeurs.'),
('1s',5,10,'crampon1923','Alors ils envoyèrent l''arche de Dieu à Accaron. Lorsque l''arche de Dieu entra dans Accaron, les Accaronites poussèrent des cris, en disant: « On a transporté chez nous l''arche du Dieu d''Israël, pour nous faire mourir, nous et notre peuple. »'),
('1s',5,11,'crampon1923','Et ils convoquèrent par des envoyés tous les princes des Philistins, et ils dirent: « Renvoyez l''arche du Dieu d''Israël; qu''elle retourne en son lieu, afin qu''elle ne nous fasse pas mourir, nous et notre peuple. »'),
('1s',5,12,'crampon1923','Car il y avait dans toute la ville une frayeur mortelle, et la main de Dieu s''y appesantissait fortement. Les gens qui ne mourraient pas étaient frappés de tumeurs, et les cris de détresse de la ville montaient jusqu''au ciel.'),
('1s',6,1,'crampon1923','L''arche de Yahweh fut sept mois dans le pays des Philistins.'),
('1s',6,2,'crampon1923','Et les Philistins appelèrent les prêtres et les devins et leur dirent: « Que ferons-nous de l''arche de Yahweh? Faites-nous connaître comment nous devons la renvoyer en son lieu. » Ils répondirent:'),
('1s',6,3,'crampon1923','« Si vous renvoyez l''arche du Dieu d''Israël, ne la renvoyez pas à vide, mais ne manquez pas de lui faire une offrande de réparation; vous guérirez alors et vous saurez pourquoi sa main ne s''est pas retirée de vous. »'),
('1s',6,4,'crampon1923','Les Philistins dirent: « Quelle offrande de réparation lui feront-nous? »'),
('1s',6,5,'crampon1923','Ils répondirent: « Cinq tumeurs d''or et cinq souris d''or, selon le nombre des princes des Philistins, car une même plaie a été sur vous et sur vos princes. Faites donc des figures de vos tumeurs et des figures de vos souris qui ravagent le pays, et donnez ainsi gloire au Dieu d''Israël: peut-être cessera-t-il d''appesantir sa main sur vous, sur vos dieux et sur votre pays.'),
('1s',6,6,'crampon1923','Pourquoi endurciriez-vous votre cœur, comme l''Egypte et Pharaon ont endurci le leur? N''ont-il pas, lorsqu''il eut exercé ses châtiments sur eux, laissé partir les enfants d''Israël?'),
('1s',6,7,'crampon1923','Maintenant donc faites un chariot neuf, et prenez deux vaches qui allaitent et qui n''aient point porté le joug; attelez les vaches au chariot, et ramenez loin d''elles leurs petits à l''étable.'),
('1s',6,8,'crampon1923','Vous prendrez l''arche de Yahweh et vous la mettrez sur le chariot; puis, ayant placé à côté d''elle, dans un coffret, les objets d''or que vous aurez donnés en offrande de réparation, vous la renverrez et elle s''en ira.'),
('1s',6,9,'crampon1923','Suivez-la du regard: si elle monte par le chemin de sa frontière, vers Beth-Samès, c''est Yahweh qui nous a fait ce grand mal; sinon, nous saurons que ce n''est pas sa main qui nous a frappés, et que cela nous est arrivé par hasard. »'),
('1s',6,10,'crampon1923','Ces gens firent ainsi; ayant pris deux vaches qui allaitaient, ils les attelèrent au chariot et ils enfermèrent leurs petits dans l''étable.'),
('1s',6,11,'crampon1923','Ils mirent sur le chariot l''arche de Yahweh, et le coffret avec les souris d''or et les figures de leurs tumeurs.'),
('1s',6,12,'crampon1923','Les vaches prirent tout droit le chemin de Beth-Samès; elles suivirent toujours la même route en marchant et en mugissant, sans se détourner ni à droite ni à gauche. Les princes des Philistins allèrent derrière elles jusqu''à la frontière de Beth-Samès.'),
('1s',6,13,'crampon1923','Les gens de Beth-Samès étaient à moissonner le blé dans la vallée. Levant les yeux, ils aperçurent l''arche, et se réjouirent en la voyant.'),
('1s',6,14,'crampon1923','Le chariot arriva dans le champ de Josué le Bethsamite et s''y arrêta. Il y avait là une grosse pierre. On fendit le bois du chariot et l''on offrit les vaches en holocauste à Yahweh.'),
('1s',6,15,'crampon1923','Les Lévites, après avoir descendu l''arche de Yahweh, et le coffret qui était auprès, renfermant les objets d''or, posèrent le tout sur la grosse pierre. Les gens de Beth-Samès offrirent en ce jour-là des holocaustes et des sacrifices à Yahweh.'),
('1s',6,16,'crampon1923','Les cinq princes des Philistins, ayant vu cela, retournèrent le même jour à Accaron.'),
('1s',6,17,'crampon1923','Voici les tumeurs d''or que les Philistins donnèrent à Yahweh en offrande de réparation: une pour Azot, une pour Gaza, une pour Ascalon, une pour Geth, une pour Accaron.'),
('1s',6,18,'crampon1923','Ils offrirent aussi des souris d''or selon le nombre de toutes les villes des Philistins appartenant aux cinq chefs, tant des villes fortifiées que des villages sans murs: témoin la grosse pierre sur laquelle on déposa l''arche de Yahweh, et qui est restée jusqu''à ce jour dans le champ de Josué le Bethsamite.'),
('1s',6,19,'crampon1923','Yahweh frappa les gens de Beth-Samès, parce qu''ils avaient regardé l''arche de Yahweh; il frappa cinquante mille soixante-dix hommes parmi le peuple. Et le peuple fit un grand deuil de ce que Yahweh avait frappé le peuple d''une grande plaie.'),
('1s',6,20,'crampon1923','Les gens de Beth-Samès dirent: « Qui peut subsister en la présence de Yahweh, ce Dieu saint? Et vers qui va-t-il monter en s''éloignant de nous? »'),
('1s',6,21,'crampon1923','Ils envoyèrent des messagers aux habitants de Cariathiarim, pour leur dire: « Les Philistins ont ramené l''arche de Yahweh; descendez et faites-la monter vers vous. »'),
('1s',7,1,'crampon1923','Les gens de Cariathiarim vinrent et firent monter l''arche de Yahweh; ils la conduisirent dans la maison d''Abinadab, sur la colline, et ils consacrèrent son fils Eléazar pour garder l''arche de Yahweh.'),
('1s',7,2,'crampon1923','Depuis le jour où l''arche fut déposée à Cariathiarim, il se passa un long temps, vingt années, et toute la maison d''Israël poussa des gémissements vers Yahweh.'),
('1s',7,3,'crampon1923','Et Samuel dit à toute la maison d''Israël: « Si c''est de tout votre cœur que vous revenez à Yahweh, ôtez du milieu de vous les dieux étrangers et les Astartés, attachez fermement votre cœur à Yahweh et servez-le lui seul, et il vous délivrera de la main des Philistins. »'),
('1s',7,4,'crampon1923','Alors les enfants d''Israël ôtèrent du milieu d''eux les Baals et les Astartés, et ils servirent Yahweh seul.'),
('1s',7,5,'crampon1923','Samuel dit: « Assemblez tout Israël à Maspha, et je prierai Yahweh pour vous. »'),
('1s',7,6,'crampon1923','Et ils s''assemblèrent à Maspha. Ils puisèrent de l''eau et la répandirent devant Yahweh, et ils jeûnèrent ce jour-là, en disant: « Nous avons péché contre Yahweh. » Et Samuel jugea les enfants d''Israël à Maspha.'),
('1s',7,7,'crampon1923','Les Philistins apprirent que les enfants d''Israël s''étaient assemblés à Maspha, et les princes des Philistins montèrent contre Israël. Les enfants d''Israël l''apprirent et eurent peur des Philistins;'),
('1s',7,8,'crampon1923','et les enfants d''Israël dirent à Samuel: « Ne cesse point de crier pour nous vers Yahweh, notre Dieu, afin qu''il nous sauve de la main des Philistins. »'),
('1s',7,9,'crampon1923','Samuel prit un agneau de lait, et l''offrit tout entier en holocauste à Yahweh; et Samuel cria vers Yahweh pour Israël, et Yahweh l''exauça.'),
('1s',7,10,'crampon1923','Pendant que Samuel offrait l''holocauste, les Philistins s''approchèrent pour attaquer Israël. Mais Yahweh fit retentir en ce jour le tonnerre, avec un grand bruit, sur les Philistins, et les mit en déroute, et ils furent battus devant Israël.'),
('1s',7,11,'crampon1923','Les hommes d''Israël, sortant de Maspha, poursuivirent les Philistins et les battirent jusqu''au-dessous de Beth-Char.'),
('1s',7,12,'crampon1923','Samuel prit une pierre, qu''il plaça entre Maspha et Sen, et il lui donna le nom d''Eben-Ezer, en disant: « Jusqu''ici Yahweh nous a secourus. »'),
('1s',7,13,'crampon1923','Ainsi humiliés, les Philistins ne revinrent plus sur le territoire d''Israël; la main de Yahweh fut sur les Philistins pendant toute la vie de Samuel.'),
('1s',7,14,'crampon1923','Les villes que les Philistins avaient prises sur Israël retournèrent à Israël, depuis Accaron jusqu''à Geth; Israël arracha leur territoire des mains des Philistins. Et il y eut paix entre Israël et les Amorrhéens.'),
('1s',7,15,'crampon1923','Samuel jugea Israël tout le temps de sa vie.'),
('1s',7,16,'crampon1923','Chaque année il s''en allait, faisant le tour par Béthel, Galgala et Maspha, et il jugeait Israël dans tous ces lieux.'),
('1s',7,17,'crampon1923','Il revenait ensuite à Rama, où était sa maison, et là il jugeait Israël; il y bâtit un autel à Yahweh.'),
('1s',8,1,'crampon1923','Lorsque Samuel fut devenu vieux, il établit ses fils juges sur Israël.'),
('1s',8,2,'crampon1923','Son fils premier-né se nommait Joël, et le second Abia; ils jugeaient à Bersabée.'),
('1s',8,3,'crampon1923','Les fils de Samuel ne marchèrent pas sur ses traces; ils s''en détournaient pour le gain, recevaient des présents et violaient la justice.'),
('1s',8,4,'crampon1923','Tous les anciens d''Israël s''assemblèrent et vinrent vers Samuel à Rama.'),
('1s',8,5,'crampon1923','Ils lui dirent: « Voilà que tu es vieux, et tes fils ne marchent pas sur tes traces; établis donc sur nous un roi pour nous juger, comme en ont toutes les nations. »'),
('1s',8,6,'crampon1923','Ce langage déplut à Samuel parce qu''ils disaient: « Donne-nous un roi pour nous juger; » et Samuel pria Yahweh.'),
('1s',8,7,'crampon1923','Yahweh dit à Samuel: « Ecoute la voix du peuple dans tout ce qu''il te dira; car ce n''est pas toi qu''ils rejettent, c''est moi qu''ils rejettent, pour que je ne règne plus sur eux.'),
('1s',8,8,'crampon1923','Comme ils ont toujours agi à mon égard depuis le jour où je les ai fait monter d''Egypte jusqu''à présent, me délaissant pour servir d''autres dieux, ainsi ils agissent envers toi.'),
('1s',8,9,'crampon1923','Et maintenant, écoute leur voix; mais dépose témoignage contre eux, et fais-leur connaître le droit du roi qui régnera sur eux. »'),
('1s',8,10,'crampon1923','Samuel rapporta toutes les paroles de Yahweh au peuple qui lui demandait un roi.'),
('1s',8,11,'crampon1923','Il dit: « Voici quel sera le droit du roi qui régnera sur vous: Il prendra vos fils, et il les mettra sur son char et parmi ses cavaliers, et ils courront devant son char.'),
('1s',8,12,'crampon1923','Il s''en fera des chefs de mille et des chefs de cinquante; il leur fera labourer ses champs, récolter ses moissons, fabriquer ses armes de guerre et l''attirail de ses chars.'),
('1s',8,13,'crampon1923','Il prendra vos filles pour parfumeuses, pour cuisinières et pour boulangères.'),
('1s',8,14,'crampon1923','Vos champs, vos vignes et vos oliviers les meilleurs, il les prendra et les donnera à ses serviteurs.'),
('1s',8,15,'crampon1923','Il prendra la dîme de vos moissons et de vos vignes, et la donnera à ses courtisans et à ses serviteurs.'),
('1s',8,16,'crampon1923','Il prendra vos serviteurs et vos servantes, vos meilleurs bœufs et vos ânes, et les emploiera à ses ouvrages.'),
('1s',8,17,'crampon1923','Il prendra la dîme de vos troupeaux, et vous-mêmes serez ses esclaves.'),
('1s',8,18,'crampon1923','Vous crierez en ce jour-là à cause de votre roi que vous vous serez choisi, mais Yahweh ne vous exaucera pas. »'),
('1s',8,19,'crampon1923','Le peuple refusa d''écouter la voix de Samuel; ils dirent: « Non, mais il y aura un roi sur nous,'),
('1s',8,20,'crampon1923','et nous serons, nous aussi, comme toutes les nations; notre roi nous jugera, il marchera à notre tête et conduira nos guerres. »'),
('1s',8,21,'crampon1923','Après avoir entendu toutes les paroles du peuple, Samuel les redit aux oreilles de Yahweh.'),
('1s',8,22,'crampon1923','Et Yahweh dit à Samuel: « Ecoute leur voix et établis un roi sur eux. » Alors Samuel dit aux hommes d''Israël: « Que chacun de vous s''en aille à sa ville. »'),
('1s',9,1,'crampon1923','Il y avait un homme de Benjamin, nommé Cis, fils d''Abiel, fils de Séror, fils de Bécorath, fils d''Aphia, fils d''un Benjamite; c''était un homme vaillant.'),
('1s',9,2,'crampon1923','Il avait un fils du nom de Saül, jeune et beau; aucun des enfants d''Israël n''était plus beau que lui, et il dépassait de la tête tout le peuple.'),
('1s',9,3,'crampon1923','Les ânesses de Cis, père de Saül, s''étaient égarées, et Cis dit à Saül, son fils: « Prends avec toi un des serviteurs, lève-toi et va à la recherche des ânesses. »'),
('1s',9,4,'crampon1923','Il traversa la montagne d''Ephraïm et traversa le pays de Salisa, et ils ne les trouvèrent pas; ils traversèrent le pays de Salim, et elles n''y étaient pas; il traversa le pays de Benjamin, et ils ne les trouvèrent pas.'),
('1s',9,5,'crampon1923','Lorsqu''ils furent arrivés au pays de Suph, Saül dit à son serviteur qui l''accompagnait: « Viens, retournons, de peur que mon père, oubliant les ânesses, ne soit en peine à notre sujet. »'),
('1s',9,6,'crampon1923','Le serviteur lui dit: « Voici qu''il y a dans cette ville un homme de Dieu; c''est un homme très considéré, tout ce qu''il dit arrive sûrement. Allons-y donc; peut-être nous fera-t-il connaître le chemin que nous devons prendre. »'),
('1s',9,7,'crampon1923','Saül dit à son serviteur: « Si nous y allons, qu''apporterons-nous à l''homme de Dieu? Car il n''y a plus de vivres dans nos sacs, et nous n''avons aucun présent à offrir à l''homme de Dieu. Qu''avons-nous? »'),
('1s',9,8,'crampon1923','Le serviteur répondit encore et dit à Saül: « Voici que je trouve sur moi le quart d''un sicle d''argent; je le donnerai à l''homme de Dieu, et il nous indiquera notre chemin. »'),
('1s',9,9,'crampon1923','— Autrefois, en Israël, on disait, en allant consulter Dieu: « Venez et allons au voyant. » Car celui qu''on appelle aujourd''hui prophète s''appelait autrefois voyant. —'),
('1s',9,10,'crampon1923','Saül dit à son serviteur: « Ton avis est bon; viens, allons. » Et ils se rendirent à la ville où était l''homme de Dieu.'),
('1s',9,11,'crampon1923','Comme ils gravissaient la montée qui mène à la ville, ils rencontrèrent des jeunes filles sorties pour puiser de l''eau, et ils leur dirent: « Le voyant est-il ici? »'),
('1s',9,12,'crampon1923','Elles leur répondirent en disant: « Oui, il y est, le voilà devant toi; mais va promptement, car il est venu aujourd''hui à la ville, parce que le peuple a aujourd''hui un sacrifice sur le haut lieu.'),
('1s',9,13,'crampon1923','Dès votre entrée dans la ville, vous le trouverez, avant qu''il monte au haut lieu pour le repas; car le peuple ne mangera point qu''il ne soit arrivé, parce qu''il doit bénir le sacrifice; après quoi, les conviés mangeront. Montez donc maintenant, vous le trouverez aujourd''hui. »'),
('1s',9,14,'crampon1923','Et ils montèrent à la ville. Ils étaient entrés au milieu de la ville, et voici que Samuel sortait à leur rencontre, pour monter en haut lieu.'),
('1s',9,15,'crampon1923','Or, un jour avant l''arrivée de Saül, Yahweh avait fait une révélation à Samuel, en disant:'),
('1s',9,16,'crampon1923','« Demain, à cette heure, je t''enverrai un homme du pays de Benjamin, et tu l''oindras pour être le chef de mon peuple d''Israël, et il délivrera mon peuple de la main des Philistins; car j''ai regardé mon peuple, parce que son cri est venu jusqu''à moi. »'),
('1s',9,17,'crampon1923','Dès que Samuel eut vu Saül, Yahweh lui dit: « Voici l''homme dont je t''ai parlé; c''est lui qui régnera sur mon peuple. »'),
('1s',9,18,'crampon1923','Saül s''approcha de Samuel au milieu de la porte, et dit: « Indique-moi, je te prie, où est la maison du voyant. »'),
('1s',9,19,'crampon1923','Samuel répondit à Saül: « C''est moi qui suis le voyant. Monte devant moi au haut lieu, et vous mangerez aujourd''hui avec moi; je te laisserai partir demain, et je te dirai tout ce qu''il y a dans ton cœur.'),
('1s',9,20,'crampon1923','Quant aux ânesses que tu as perdues il y a trois jours, ne t''en inquiète pas, car elles sont retrouvées. Et à qui sera tout ce qu''il y a de précieux en Israël? N''est-ce pas à toi et à toute la maison de ton père? »'),
('1s',9,21,'crampon1923','Saül répondit: « Ne suis-je pas Benjamite, de la plus petite des tribus d''Israël? et ma famille n''est-elle pas la moindre de toutes les familles de la tribu de Benjamin? Pourquoi m''as-tu dit une telle parole? »'),
('1s',9,22,'crampon1923','Samuel, ayant pris Saül et son serviteur, les fit entrer dans la salle et leur donna la première place parmi les conviés, qui étaient environ trente hommes.'),
('1s',9,23,'crampon1923','Samuel dit au cuisinier: « Sers la portion que je t''ai remise et dont je t''ai dit: mets-la à part. »'),
('1s',9,24,'crampon1923','Le cuisinier leva l''épaule avec ce qui l''entoure, et il la servit à Saül. Et Samuel dit: « Voici la portion réservée; prends-la devant toi et mange, car elle a été gardée pour ce moment lorsque j''ai convoqué le peuple. » Et Saül mangea avec Samuel ce jour-là.'),
('1s',9,25,'crampon1923','Ils descendirent ensuite du haut lieu dans la ville, et Samuel s''entretint avec Saül sur le toit.'),
('1s',9,26,'crampon1923','Le lendemain, ils se levèrent de bon matin et, comme l''aurore montait, Samuel appela Saül sur le toit, et dit: « Lève-toi, et je te laisserai aller. » Saül se leva, et ils sortirent tous deux, lui et Samuel.'),
('1s',9,27,'crampon1923','Quand ils furent descendus à l''extrémité de la ville, Samuel dit à Saül: « Dis à ton serviteur de passer devant nous; » et le serviteur prit les devants. « Arrête-toi maintenant, ajouta Samuel, et je te ferai entendre ce que Dieu a dit. »'),
('1s',10,1,'crampon1923','Samuel prit une fiole d''huile, et la versa sur la tête de Saül; puis il le baisa et dit: « Yahweh ne t''a-t-il pas oint pour chef sur son héritage?'),
('1s',10,2,'crampon1923','Quand tu m''auras quitté aujourd''hui, tu trouveras deux hommes près du sépulcre de Rachel, dans le territoire de Benjamin, à Selsach; ils te diront: « Les ânesses que tu es allé chercher sont retrouvées; et voici, ton père a perdu de vue l''affaire des ânesses, mais il est en peine de vous et dit: Que dois-je faire au sujet de mon fils? »'),
('1s',10,3,'crampon1923','De là, poursuivant ta route, tu arriveras au chêne de Thabor, et là tu seras rencontré par trois hommes montant vers Dieu à Béthel, et portant l''un trois chevreaux, l''autre trois miches de pain, et l''autre une outre de vin.'),
('1s',10,4,'crampon1923','Après qu''ils t''auront salué, ils te donneront deux pains, et tu les recevras de leurs mains.'),
('1s',10,5,'crampon1923','Après cela, tu viendras à Gabaa de Dieu, où se trouve un poste de Philistins. En entrant dans la ville, tu rencontreras une troupe de prophètes descendant du haut lieu, précédés de luths, tambourins, flûtes et harpes, et prophétisant.'),
('1s',10,6,'crampon1923','L''Esprit de Yahweh te saisira, et tu prophétiseras avec eux, et tu seras changé en un autre homme.'),
('1s',10,7,'crampon1923','Lorsque ces signes se seront accomplis pour toi, fais ce qui se présentera, car Dieu est avec toi.'),
('1s',10,8,'crampon1923','Et tu descendras avant moi à Galgala; et voici, je descendrai vers toi, pour offrir des holocaustes et des sacrifices pacifiques. Tu attendras sept jours jusqu''à ce que je sois venu vers toi et je te ferai connaître ce que tu dois faire. »'),
('1s',10,9,'crampon1923','Dès que Saül eut tourné le dos pour se séparer de Samuel, Dieu lui donna un autre cœur, et tous ces signes s''accomplirent le même jour.'),
('1s',10,10,'crampon1923','Quand ils arrivèrent à Gabaa, voici qu''une troupe de prophètes vint à sa rencontre; et l''Esprit de Dieu le saisit, et il prophétisa au milieu d''eux.'),
('1s',10,11,'crampon1923','Quand tous ceux qui le connaissaient auparavant virent qu''il prophétisait avec les prophètes, tous ces gens se dirent l''un à l''autre: « Qu''est-il arrivé au fils de Cis? Saül est-il donc aussi parmi les prophètes? »'),
('1s',10,12,'crampon1923','Quelqu''un de la foule prit la parole et dit: « Et qui est leur père? » — C''est pourquoi cela est passé en proverbe: « Saül est-il aussi parmi les prophètes? » —'),
('1s',10,13,'crampon1923','Lorsqu''il eut cessé de prophétiser, il se rendit en haut lieu.'),
('1s',10,14,'crampon1923','L''oncle de Saül dit à Saül et à son serviteur: « Où êtes-vous allés? » Saül répondit: « Chercher les ânesses; mais ne les ayant vues nulle part, nous sommes allés vers Samuel. »'),
('1s',10,15,'crampon1923','L''oncle de Saül dit: « Raconte-moi ce que vous a dit Samuel. »'),
('1s',10,16,'crampon1923','Et Saül répondit à son oncle: « Il nous a appris que les ânesses étaient retrouvées. » Mais quant à l''affaire de la royauté, il ne lui rapporta pas ce qu''avait dit Samuel.'),
('1s',10,17,'crampon1923','Samuel convoqua le peuple devant Yahweh à Maspha,'),
('1s',10,18,'crampon1923','et il dit aux enfants d''Israël: « Ainsi parle Yahweh, le Dieu d''Israël: J''ai fait monter Israël d''Egypte, et je vous ai délivrés de la main des Egyptiens et de la main de tous les royaumes qui vous opprimaient.'),
('1s',10,19,'crampon1923','Et vous, aujourd''hui, vous rejetez votre Dieu, qui vous a délivrés de tous vos maux et de toutes vos souffrances, et vous lui dites: Etablis un roi sur nous! Présentez-vous maintenant devant Yahweh, selon vos tribus et selon vos familles. »'),
('1s',10,20,'crampon1923','Samuel fit approcher toutes les tribus d''Israël, et la tribu de Benjamin fut désignée par le sort.'),
('1s',10,21,'crampon1923','Il fit approcher la tribu de Benjamin par familles, et la famille de Métri fut désignée; puis Saül, fis de Cis fut désigné. On le chercha, mais on ne le trouva point.'),
('1s',10,22,'crampon1923','Alors ils interrogèrent de nouveau Yahweh: « Est-il venu ici encore quelqu''un? » Yahweh répondit: « Voici, il est caché parmi les bagages. »'),
('1s',10,23,'crampon1923','On courut le tirer de là, et il se tint au milieu du peuple, dépassant tout le peuple de l''épaule et au delà.'),
('1s',10,24,'crampon1923','Et Samuel dit à tout le peuple: « Voyez-vous celui que Yahweh a choisi? Il n''y a personne dans tout le peuple qui soit semblable à lui. » Et tout le peuple poussa des cris en disant: « Vive le roi! »'),
('1s',10,25,'crampon1923','Alors Samuel exposa au peuple le droit de la royauté, et il l''écrivit dans le livre, qu''il déposa devant Yahweh; puis il renvoya tout le peuple, chacun dans sa maison.'),
('1s',10,26,'crampon1923','Saül aussi s''en alla dans sa maison à Gabaa, accompagné d''hommes de valeur, dont Dieu avait touché le cœur.'),
('1s',10,27,'crampon1923','Toutefois les hommes de Bélial disaient: « Est-ce celui-là qui nous sauvera? » Et ils le méprisèrent et ne lui apportèrent pas de présents. Mais Saül n''y prit point garde.'),
('1s',11,1,'crampon1923','Naas l''Ammonite monta et campa devant Jabès en Galaad. Tous les habitants de Jabès dirent à Naas: « Conclus une alliance avec nous, et nous te servirons. »'),
('1s',11,2,'crampon1923','Mais Naas l''Ammonite leur répondit: « Je traiterai avec vous à la condition que je vous crève à tous l''œil droit, et que je mette ainsi un opprobre sur tout Israël. »'),
('1s',11,3,'crampon1923','Les anciens de Jabès lui dirent: « Accorde-nous un délai de sept jours, et nous enverrons des messagers dans tout le territoire d''Israël; et s''il n''y a personne qui nous secoure, nous nous rendrons à toi. »'),
('1s',11,4,'crampon1923','Les messagers vinrent à Gabaa de Saül, et dirent ces choses aux oreilles du peuple; et tout le peuple éleva la voix et pleura.'),
('1s',11,5,'crampon1923','Et voici que Saül revenait des champs, derrière ses bœufs; et Saül dit: « Qu''a donc le peuple, pour pleurer? » On lui rapporta ce qu''avaient dit les hommes de Jabès.'),
('1s',11,6,'crampon1923','Dès qu''il eut entendu ces paroles, l''Esprit de Yahweh saisit Saül, et sa colère s''enflamma.'),
('1s',11,7,'crampon1923','Ayant pris une paire de bœufs, il les coupa en morceau, et il en envoya par les messagers dans tout le territoire d''Israël, en disant: « Quiconque ne marchera pas à la suite de Saül et de Samuel, aura ses bœufs traités de la même manière. » La terreur de Yahweh tomba sur le peuple, et il se mit en marche comme un seul homme.'),
('1s',11,8,'crampon1923','Saül en fit la revue à Bezech: les enfants d''Israël étaient trois cent mille, et les hommes de Juda trente mille.'),
('1s',11,9,'crampon1923','Ils dirent aux messagers qui étaient venus: « Vous parlerez aussi aux hommes de Jabès en Galaad: Demain vous aurez du secours, quand le soleil sera dans sa force. » Les messagers reportèrent cette nouvelle aux hommes de Jabès, qui furent remplis de joie.'),
('1s',11,10,'crampon1923','Et les hommes de Jabès dirent aux Ammonites: « Demain, nous nous rendrons à vous, et vous agirez envers nous comme bon vous semblera. »'),
('1s',11,11,'crampon1923','Le lendemain, Saül disposa le peuple en trois corps; ils pénétrèrent dans le camp des Ammonites à la veille du matin, et ils les battirent jusqu''à la chaleur du jour. Ceux qui échappèrent furent dispersés, de telle sorte qu''il n''en resta pas deux ensemble.'),
('1s',11,12,'crampon1923','Le peuple dit à Samuel: « Qui est-ce qui disait: Saül régnera-t-il sur nous? Livrez-nous ces gens, et nous les mettrons à mort. »'),
('1s',11,13,'crampon1923','Mais Saül dit: « Personne ne sera mis à mort en ce jour, car aujourd''hui Yahweh a opéré le salut d''Israël. »'),
('1s',11,14,'crampon1923','Et Samuel dit au peuple: « Venez et allons à Galgala, pour y renouveler la royauté. »'),
('1s',11,15,'crampon1923','Tout le peuple se rendit à Galgala, et ils établirent Saül pour roi devant Yahweh, à Galgala, et ils offrirent en ce lieu des sacrifices pacifiques devant Yahweh; et Saül et tous les hommes d''Israël s''y livrèrent à de grandes réjouissances'),
('1s',12,1,'crampon1923','Samuel dit à tout Israël: « Voici, j''ai écouté votre voix dans tout ce que vous m''avez dit, et j''ai établi un roi sur vous.'),
('1s',12,2,'crampon1923','Et maintenant, voici le roi qui marchera devant vous. Pour moi, je suis vieux, j''ai blanchi, et mes fils sont au milieu de vous; j''ai marché devant vous, depuis ma jeunesse jusqu''à ce jour.'),
('1s',12,3,'crampon1923','Me voici; rendez témoignage de moi, en présence de Yahweh et en présence de son oint: De qui ai-je pris le bœuf et de qui ai-je pris l''âne? A qui ai-je fait tort et qui ai-je opprimé? De qui ai-je reçu un présent pour fermer les yeux sur lui? Je vous le rendrai. »'),
('1s',12,4,'crampon1923','Ils répondirent: « Tu ne nous as point fait tort, tu ne nous as point opprimés, et tu n''as rien reçu de la main de personne. »'),
('1s',12,5,'crampon1923','Il leur dit: « Yahweh est témoin contre vous, et son oint aussi est témoin, en ce jour, que vous n''avez rien trouvé dans mes mains! » Le peuple répondit: « Il en est témoin. »'),
('1s',12,6,'crampon1923','Et Samuel dit au peuple: « Oui, Yahweh est témoin, lui qui a établi Moïse et Aaron, et qui a fait monter vos pères du pays d''Egypte.'),
('1s',12,7,'crampon1923','Maintenant, présentez-vous, je veux vous appeler en jugement devant Yahweh au sujet de tous les bienfaits qu''il vous a accordés, à vous et à vos pères.'),
('1s',12,8,'crampon1923','Après que Jacob fut venu en Egypte, vos pères crièrent vers Yahweh, et Yahweh envoya Moïse et Aaron, qui firent sortir vos pères d''Egypte et les établirent dans ce lieu.'),
('1s',12,9,'crampon1923','Mais ils oublièrent Yahweh, leur Dieu, et il les livra entre les mains de Sisara chef de l''armée d''Hasor, entre les mains des Philistins et entre les mains du roi de Moab, qui leur firent la guerre.'),
('1s',12,10,'crampon1923','Ils crièrent vers Yahweh, en disant: « Nous avons péché, car nous avons abandonné Yahweh et nous avons servi les Baals et les Astartés; délivrez-nous maintenant de la main de nos ennemis, et nous vous servirons. »'),
('1s',12,11,'crampon1923','Et Yahweh envoya Jérobaal et Badan, et Jephté et Samuel, et il vous délivra de la main de vos ennemis tout autour de vous, et vous avez habité vos demeures en sécurité.'),
('1s',12,12,'crampon1923','Et quand vous avez vu Naas, roi des fils d''Ammon marcher contre vous, vous m''avez dit: Non! mais un roi régnera sur nous! alors que Yahweh, votre Dieu, était votre roi.'),
('1s',12,13,'crampon1923','Voici donc le roi que vous avez choisi, que vous avez demandé; voici que Yahweh a établi un roi sur vous.'),
('1s',12,14,'crampon1923','Si vous craignez Yahweh, si vous le servez et obéissez à sa voix, si vous n''êtes point rebelles au commandement de Yahweh et si vous suivez vous et le roi qui règne sur vous, Yahweh votre Dieu,...'),
('1s',12,15,'crampon1923','Mais si vous n''obéissez pas à la voix de Yahweh et si vous êtes rebelles au commandement de Yahweh la main de Yahweh sera contre vous, comme elle a été contre vos pères.'),
('1s',12,16,'crampon1923','Maintenant, restez encore, et voyez cette grande chose que Yahweh va opérer sous vos yeux.'),
('1s',12,17,'crampon1923','N''est-ce pas maintenant la moisson des blés? Eh bien, je vais invoquer Yahweh, et il enverra des tonnerres et de la pluie; vous saurez alors et vous verrez combien grand est aux yeux de Yahweh le mal que vous avez fait en demandant pour vous un roi. »'),
('1s',12,18,'crampon1923','Samuel invoqua Yahweh et Yahweh envoya ce même jour des tonnerres et de la pluie; et tout le peuple eut une grande crainte de Yahweh et de Samuel.'),
('1s',12,19,'crampon1923','Tout le peuple dit à Samuel: « Prie pour tes serviteurs Yahweh, ton Dieu, afin que nous ne mourions pas, car nous avons ajouté à tous nos péchés le tort de demander pour nous un roi. »'),
('1s',12,20,'crampon1923','Samuel dit au peuple: « Ne craignez point. Vous avez fait tout ce mal, mais ne cessez pas de suivre Yahweh, et servez Yahweh de tout votre cœur.'),
('1s',12,21,'crampon1923','Ne vous en détournez point, car ce serait pour aller à des choses de néant, qui ne vous donneraient ni profit ni délivrance, parce que ce sont des choses de néant.'),
('1s',12,22,'crampon1923','Car Yahweh n''abandonnera pas son peuple, à cause de son grand nom; car il a plu à Yahweh de faire de vous son peuple.'),
('1s',12,23,'crampon1923','Loin de moi aussi de pécher contre Yahweh, en cessant de prier pour vous! Je vous enseignerai le bon et droit chemin.'),
('1s',12,24,'crampon1923','Craignez seulement Yahweh, et servez-le en vérité de tout votre cœur; car voyez quelles grandes choses il a faites au milieu de vous!'),
('1s',12,25,'crampon1923','Mais si vous persévérez à faire le mal, vous périrez, vous et votre roi. »'),
('1s',13,1,'crampon1923','Saül était âgé de... ans lorsqu''il devint roi et il régna deux ans sur Israël.'),
('1s',13,2,'crampon1923','Saül se choisit trente mille hommes d''Israël: deux mille étaient avec lui à Machmas et sur la montagne de Béthel, et mille étaient avec Jonathas à Gabaa de Benjamin. Et il renvoya le reste du peuple, chacun dans sa tente.'),
('1s',13,3,'crampon1923','Jonathas battit le poste des Philistins qui était à Gabée et les Philistins l''apprirent. Et Saül fit sonner de la trompette dans tout le pays, en disant: « Que les Hébreux entendent! »'),
('1s',13,4,'crampon1923','Tout Israël entendit la nouvelle: « Saül a battu le poste des Philistins, et même Israël s''est rendu odieux auprès des Philistins. » Et le peuple fut convoqué auprès de Saül, à Galgala.'),
('1s',13,5,'crampon1923','Les Philistins s''assemblèrent pour combattre Israël; ils avaient trente mille chars, six mille cavaliers, et un peuple innombrable comme le sable qui est sur le bord de la mer. Ils montèrent et campèrent à Machmas, à l''orient de Beth-Aven.'),
('1s',13,6,'crampon1923','Les hommes d''Israël, se voyant dans une grande extrémité, car ils étaient serrés de près, se cachèrent dans les cavernes, dans les broussailles, dans les rochers, dans les trous et dans les citernes.'),
('1s',13,7,'crampon1923','Des Hébreux passèrent aussi le Jourdain, pour aller au pays de Gad et de Galaad. Saül était encore à Galgala, et tout le peuple derrière lui tremblait.'),
('1s',13,8,'crampon1923','Il attendit sept jours, selon le terme fixé par Samuel. Mais Samuel n''arrivait pas à Galgala, et le peuple se dispersait loin de Saül.'),
('1s',13,9,'crampon1923','Alors Saül dit: « Amenez-moi l''holocauste et les sacrifices pacifiques. » Et il offrit l''holocauste.'),
('1s',13,10,'crampon1923','Comme il achevait d''offrir l''holocauste, voici que Samuel arriva, et Saül sortit au-devant de lui pour le saluer.'),
('1s',13,11,'crampon1923','Samuel lui dit: « Qu''as-tu fait? » Saül répondit: « Lorsque j''ai vu que le peuple se dispersait loin de moi, que tu n''arrivais pas au terme fixé et que les Philistins étaient assemblés à Machmas,')
insert into bible_versets (livre_code, chapitre, verset, traduction, texte) values
('1s',13,12,'crampon1923','je me suis dit: Maintenant, les Philistins vont descendre contre moi à Galgala, et je n''ai pas imploré Yahweh. Alors, me faisant violence, j''ai offert l''holocauste. »'),
('1s',13,13,'crampon1923','Samuel dit à Saül: « Tu as agi en insensé, tu n''as pas observé le commandement que Yahweh ton Dieu t''avait donné; car Yahweh aurait affermi pour toujours ton règne sur Israël.'),
('1s',13,14,'crampon1923','Mais maintenant, ton règne ne subsistera point. Yahweh s''est cherché un homme selon son cœur et Yahweh l''a destiné à être le chef de son peuple, parce que tu n''as pas observé ce que Yahweh t''avait ordonné. »'),
('1s',13,15,'crampon1923','Et Samuel se leva, et monta de Galgala à Gabaa de Benjamin. Saül passa en revue le peuple qui se trouvait avec lui: il y en avait environ six cents hommes.'),
('1s',13,16,'crampon1923','Saül, Jonathas, son fils, et le peuple qui se trouvait avec eux s''étaient postés à Gabée de Benjamin, et les Philistins campaient à Machmas.'),
('1s',13,17,'crampon1923','L''armée de destruction sortit du camp des Philistins en trois corps: un corps prit le chemin d''Ephra, vers le pays de Sual;'),
('1s',13,18,'crampon1923','un autre corps prit le chemin de Beth-Horon; et le troisième corps, celui de la frontière qui domine la vallée de Seboïm, du côté du désert.'),
('1s',13,19,'crampon1923','On ne trouvait point de forgeron dans tout le pays d''Israël; car les Philistins avaient dit: « Que les Hébreux ne puissent plus fabriquer d''épées ou de lances! »'),
('1s',13,20,'crampon1923','Et tout Israël descendait chez les Philistins pour aiguiser chacun son soc, son hoyau, sa hache ou sa charrue,'),
('1s',13,21,'crampon1923','en sorte que le tranchant des socs, des hoyaux, des tridents et des haches était souvent émoussé et les aiguillons non redressés.'),
('1s',13,22,'crampon1923','Il arriva qu''au jour du combat, il ne se trouvait ni lance ni épée dans la main de tout le peuple qui était avec Saül et Jonathas; mais il s''en trouvait auprès de Saül et de Jonathas, son fils.'),
('1s',13,23,'crampon1923','Un poste des Philistins se rendit au passage de Machmas.'),
('1s',14,1,'crampon1923','Un jour, Jonathas, fils de Saül, dit au jeune homme qui portait ses armes: « Viens, et passons jusqu''au poste des Philistins, qui est là, de l''autre côté. » Et il n''en dit rien à son père.'),
('1s',14,2,'crampon1923','— Saül se tenait à l''extrémité de Gabaa, sous le grenadier de Magron, et le peuple qui était avec lui était d''environ six cents hommes.'),
('1s',14,3,'crampon1923','Achias, fils d''Achitob, frère d''Ichabod, fils de Phinées, fils d''Héli, prêtre de Yahweh à Silo, portait l''éphod. Le peuple ne savait pas non plus que Jonathas s''en fût allé.'),
('1s',14,4,'crampon1923','Entre les passages par lesquels Jonathas cherchait à arriver au poste des Philistins, il y avait une dent de rocher d''un côté et une dent de rocher de l''autre côté, l''une nommée Bosès, et l''autre nommée Séné.'),
('1s',14,5,'crampon1923','L''une de ces dents se dresse au nord, vis-à-vis de Machmas, et l''autre au midi, vis-à-vis de Gabée. —'),
('1s',14,6,'crampon1923','Jonathas dit donc au jeune homme qui portait ses armes: « Viens, et passons jusqu''au poste de ces incirconcis. Peut-être Yahweh agira-t-il pour nous; car rien n''empêche Yahweh de sauver, soit par un nombre grand, soit par un petit nombre. »'),
('1s',14,7,'crampon1923','Son écuyer lui répondit: « Fais tout ce que tu as dans le cœur; va où tu voudras, me voici avec toi prêt à te suivre. »'),
('1s',14,8,'crampon1923','Jonathas dit: « Voici, nous passerons vers ces hommes et nous nous montrerons vers eux.'),
('1s',14,9,'crampon1923','S''ils nous disent: Arrêtez, jusqu''à ce que nous venions à vous! nous resterons en place et nous ne monterons pas vers eux.'),
('1s',14,10,'crampon1923','Mais s''ils disent: Montez vers nous! nous monterons, car Yahweh les a livrés entre nos mains. Cela sera pour nous le signe. »'),
('1s',14,11,'crampon1923','Ils se montrèrent tous deux au poste des Philistins, et les Philistins dirent: « Voici les Hébreux qui sortent des trous où ils s''étaient cachés. »'),
('1s',14,12,'crampon1923','Et les hommes du poste, s''adressant à Jonathas et à son écuyer, dirent: « Montez vers nous, et nous vous ferons savoir quelque chose. » Et Jonathas dit à son écuyer: « Monte après moi, car Yahweh les a livrés entre nos mains. »'),
('1s',14,13,'crampon1923','Et Jonathas monta, sur les mains et sur les pieds, suivi de son écuyer. Les Philistins tombaient devant Jonathas, et son écuyer tuait derrière lui.'),
('1s',14,14,'crampon1923','Ce premier massacre que firent Jonathas et son écuyer fut d''environ vingt hommes, sur la longueur d''un demi-sillon d''un arpent de terre.'),
('1s',14,15,'crampon1923','L''épouvante se répandit dans le camp des Philistins, dans la campagne et dans tout le peuple; le poste aussi et l''armée de destruction furent saisis de peur; la terre trembla: c''était une terreur de Dieu.'),
('1s',14,16,'crampon1923','Les sentinelles de Saül qui étaient à Gabaa de Benjamin virent comment la multitude des Philistins se dispersait et allait de côté et d''autre.'),
('1s',14,17,'crampon1923','Saül dit au peuple qui était avec lui: « Faites la revue et voyez qui s''en est allé d''avec nous. » Ils firent la revue, et voici qu''il n''y avait ni Jonathas ni son écuyer.'),
('1s',14,18,'crampon1923','Et Saül dit à Achias: « Fais approcher l''arche de Dieu. » — Car l''arche de Dieu était en ce jour-là avec les enfants d''Israël. —'),
('1s',14,19,'crampon1923','Pendant que Saül parlait au prêtre, le tumulte qui se faisait dans le camp des Philistins allait croissant; et Saül dit au prêtre: « Retire ta main. »'),
('1s',14,20,'crampon1923','Puis Saül et tout le peuple qui était avec lui, s''étant rassemblés, s''avancèrent jusqu''au lieu du combat, et voici que l''épée de l''un était tournée contre l''autre, et la confusion était extrême.'),
('1s',14,21,'crampon1923','Les Hébreux qui étaient auparavant avec les Philistins, étant montés avec eux au camp tout autour, se mirent eux aussi du côté de ceux d''Israël qui étaient avec Saül et Jonathas.'),
('1s',14,22,'crampon1923','Tous les hommes d''Israël qui s''étaient cachés dans la montagne d''Ephraïm, apprenant la fuite des Philistins, s''attachèrent également à les poursuivre en combattant.'),
('1s',14,23,'crampon1923','C''est ainsi que Yahweh délivra Israël ce jour-là. Le combat se poursuivit jusqu''à Beth-Aven.'),
('1s',14,24,'crampon1923','Les hommes d''Israël étaient à bout de forces en ce jour-là. Saül fit jurer le peuple, en disant: « Maudit soit l''homme qui prendra de la nourriture jusqu''au soir, jusqu''à ce que je me sois vengé de mes ennemis! » Et personne ne goûta de nourriture.'),
('1s',14,25,'crampon1923','Tout le peuple vint dans la forêt, et il y avait du miel à la surface du sol.'),
('1s',14,26,'crampon1923','Et le peuple entra dans la forêt, il vit du miel qui coulait; mais nul ne porta la main à la bouche, car le peuple avait crainte du serment.'),
('1s',14,27,'crampon1923','Mais Jonathas n''avait pas entendu lorsque son père avait fait faire le serment au peuple; il avança l''extrémité du bâton qu''il avait à la main et, l''ayant plongé dans un rayon de miel, il ramena sa main à sa bouche, et ses yeux furent éclaircis.'),
('1s',14,28,'crampon1923','Alors quelqu''un du peuple, prenant la parole, lui dit: « Ton père a fait jurer le peuple, en disant: Maudit soit l''homme qui prendra de la nourriture aujourd''hui! Et le peuple était épuisé. »'),
('1s',14,29,'crampon1923','Jonathas dit: « Mon père a causé le malheur du peuple. Voyez donc comme mes yeux sont clairs, parce que j''ai goûté un peu de ce miel!'),
('1s',14,30,'crampon1923','Ah! Si le peuple avait mangé aujourd''hui du butin trouvé chez ses ennemis, combien la défaite des Philistins n''aurait-elle pas été plus grande! »'),
('1s',14,31,'crampon1923','Ils battirent ce jour-là les Philistins depuis Machmas jusqu''à Ajalon, et le peuple était tout défaillant.'),
('1s',14,32,'crampon1923','Le peuple se jeta sur le butin et, ayant pris des brebis, des bœufs et des veaux, il les égorgèrent sur la terre, et le peuple en mangea avec le sang.'),
('1s',14,33,'crampon1923','On le rapporta à Saül, en disant: « Voici que le peuple pèche contre Yahweh, en mangeant la chair avec le sang. » Saül dit: « Vous avez commis une infidélité, roulez à l''instant vers moi une grande pierre. »'),
('1s',14,34,'crampon1923','Et Saül dit: « Dispersez-vous parmi le peuple, et dites-leur: Amenez-moi chacun votre bœuf et chacun votre brebis; égorgez-les ici; vous en mangerez alors et vous ne pécherez pas contre Yahweh en mangeant avec le sang. » Et chacun parmi tout le peuple amena pendant la nuit son bœuf par la main, et l''égorgea là.'),
('1s',14,35,'crampon1923','Saül bâtit un autel à Yahweh; ce fut le premier autel qu''il éleva pour Yahweh.'),
('1s',14,36,'crampon1923','Saül dit: « Descendons, pendant qu''il fait nuit, à la poursuite des Philistins, pillons les jusqu''à ce que luise le matin, et n''en laissons pas survivre un seul. » Ils dirent: « Fais tout ce qui te semblera bon. » Mais le grand prêtre dit: « Approchons-nous ici de Dieu. »'),
('1s',14,37,'crampon1923','Et Saül consulta Dieu: « Descendrai-je à la poursuite des Philistins? Les livrerez-vous entre les mains d''Israël? » Et Yahweh ne lui donna pas de réponse ce jour-là.'),
('1s',14,38,'crampon1923','Saül dit: « Approchez ici, vous tous, chefs du peuple; recherchez et voyez quel est le péché qui a été commis aujourd''hui.'),
('1s',14,39,'crampon1923','Car, aussi vrai que Yahweh, le libérateur d''Israël, est vivant, le péché fût-il sur mon fils Jonathas, il mourra. » Et dans tout le peuple personne ne lui répondit.'),
('1s',14,40,'crampon1923','Il dit à tout Israël: « Vous, mettez-vous d''un côté, et moi et mon fils Jonathas nous serons de l''autre côté. » Et le peuple dit à Saül: « Fais ce qui te semblera bon. »'),
('1s',14,41,'crampon1923','Saül dit à Yahweh: « Dieu d''Israël, fais connaître la vérité! » Jonathas et Saül furent désignés, et le peuple fut libéré.'),
('1s',14,42,'crampon1923','Alors Saül dit: « Jetez le sort entre moi et Jonathas, mon fils. » Et Jonathas fut désigné.'),
('1s',14,43,'crampon1923','Saül dit à Jonathas: « Déclare-moi ce que tu as fait. » Jonathas le lui déclara, en disant: « J''ai goûté un peu de miel, avec l''extrémité du bâton que j''avais à la main; me voici, je mourrai! »'),
('1s',14,44,'crampon1923','Et Saül dit: « Que Dieu me traite dans toute sa rigueur, si tu ne meurs pas, Jonathas! »'),
('1s',14,45,'crampon1923','Le peuple dit à Saül: « Jonathas mourrait donc, lui qui a opéré cette grande délivrance en Israël? Loin de nous! Yahweh est vivant! il ne tombera pas à terre un cheveu de sa tête car c''est avec Dieu qu''il a agi en ce jour. » C''est ainsi que le peuple sauva Jonathas, et il ne mourut point.'),
('1s',14,46,'crampon1923','Saül monta à Gabaa, sans poursuivre les Philistins et les Philistins regagnèrent leur pays.'),
('1s',14,47,'crampon1923','Lorsque Saül eut pris possession de la royauté sur Israël, il fit la guerre aux alentours à tous ses ennemis, à Moab, aux enfants, d''Ammon, à Edom, aux rois de Soba et aux Philistins, et, partout où il se tournait, il l''emportait.'),
('1s',14,48,'crampon1923','Il fit des exploits, battit Amalec et délivra Israël de la main de ceux qui le pillaient.'),
('1s',14,49,'crampon1923','Les fils de Saül étaient Jonathas, Jessui et Melchisua; ses deux filles s''appelaient, l''aînée Mérob, et la plus jeune Michol.'),
('1s',14,50,'crampon1923','Le nom de la femme de Saül était Achinoam, fille d''Achimaas. Le nom du chef de son armée était Abner, fils de Ner, oncle de Saül.'),
('1s',14,51,'crampon1923','Cis, père de Saül, et Ner, père d''Abner, étaient fils d''Abiel.'),
('1s',14,52,'crampon1923','La guerre fut acharnée contre les Philistins pendant tous les jours de Saül, et quand Saül apercevait un homme fort et vaillant, il l''attachait à son service.'),
('1s',15,1,'crampon1923','Samuel dit à Saül: « C''est moi que Yahweh a envoyé pour t''oindre comme roi sur son peuple, sur Israël; écoute donc ce que dit Yahweh.'),
('1s',15,2,'crampon1923','Ainsi parle Yahweh des armées: J''ai considéré ce qu''Amalec a fait à Israël, lorsqu''il s''est élevé contre lui sur le chemin, quand Israël montait d''Egypte.'),
('1s',15,3,'crampon1923','Va maintenant, frappe Amalec, et dévoue par anathème tout ce qui lui appartient; tu n''auras pas pitié de lui, et tu feras mourir hommes et femmes, enfants et nourrissons, bœufs et brebis, chameaux et ânes. »'),
('1s',15,4,'crampon1923','Saül le fit savoir au peuple, qu''il passa en revue à Télaïm: il compta deux cent mille hommes de pied et dix mille hommes de Juda.'),
('1s',15,5,'crampon1923','Saül s''avança jusqu''à la ville d''Amalec, et il mit une embuscade dans la vallée.'),
('1s',15,6,'crampon1923','Saül dit aux Cinéens: « Allez, retirez-vous, descendez du milieu d''Amalec, de peur que je ne vous enveloppe avec lui; car vous avez usé de bonté envers tous les enfants d''Israël, lorsqu''ils montèrent d''Egypte. » Et les Cinéens se retirèrent du milieu d''Amalec.'),
('1s',15,7,'crampon1923','Saül battit Amalec depuis Hévila jusqu''à Sur, qui est à l''est de l''Egypte.'),
('1s',15,8,'crampon1923','Il prit vivant Agag, roi d''Amalec, et il dévoua tout le peuple par anathème, en le passant au fil de l''épée.'),
('1s',15,9,'crampon1923','Mais Saül et le peuple épargnèrent Agag, ainsi que le meilleur des brebis, des bœufs, des bêtes de la seconde portée, les agneaux et tout ce qu''il y avait de bon; ils ne voulurent pas le dévouer à l''anathème; et tout ce qui était chétif et sans valeur, ils le vouèrent à l''anathème.'),
('1s',15,10,'crampon1923','La parole de Yahweh fut adressée à Samuel, en ces termes:'),
('1s',15,11,'crampon1923','« Je me repens d''avoir établi Saül pour roi, car il s''est détourné de moi, et il n''a pas exécuté mes paroles. » Samuel s''attrista, et il cria vers Yahweh toute la nuit.'),
('1s',15,12,'crampon1923','Samuel se leva de bon matin pour aller à la rencontre de Saül; et on avertit Samuel en disant: « Saül est allé à Carmel, et voici qu''il s''est élevé un monument; puis il s''en est retourné et, passant plus loin, il est descendu à Galgala. »'),
('1s',15,13,'crampon1923','Samuel vint vers Saül, et Saül lui dit: « Sois béni de Yahweh! J''ai exécuté la parole de Yahweh. »'),
('1s',15,14,'crampon1923','Samuel dit: « Qu''est-ce donc que ce bêlement de brebis à mes oreilles, et ce mugissement de bœufs que j''entends? »'),
('1s',15,15,'crampon1923','Saül répondit: « Ils les ont amenés de chez les Amalécites, car le peuple a épargné le meilleur des brebis et des bœufs pour les sacrifier à Yahweh, ton Dieu; le reste, nous l''avons voué à l''anathème. »'),
('1s',15,16,'crampon1923','Samuel dit à Saül: « Assez! Je vais te faire connaître ce que Yahweh m''a dit cette nuit. » Et Saül lui dit: « Parle! »'),
('1s',15,17,'crampon1923','Samuel dit: « Est-ce que, lorsque tu étais petit à tes propres yeux, tu n''es pas devenu le chef des tribus d''Israël, et Yahweh ne t''a-t-il pas oint pour roi sur Israël?'),
('1s',15,18,'crampon1923','Yahweh t''avait envoyé dans le chemin en disant: Va, et dévoue à l''anathème ces pécheurs, les Amalécites, et combats-les jusqu''à ce qu''ils soient exterminés.'),
('1s',15,19,'crampon1923','Pourquoi n''as-tu pas écouté la voix de Yahweh, et t''es-tu jeté sur le butin, et as-tu fait ce qui est mal aux yeux de Yahweh? »'),
('1s',15,20,'crampon1923','Saül dit à Samuel: « Mais oui, j''ai écouté la voix de Yahweh, et j''ai marché dans le chemin où Yahweh m''envoyait. J''ai amené Agag, roi d''Amalec, et j''ai voué Amalec à l''anathème.'),
('1s',15,21,'crampon1923','Et le peuple a pris, sur le butin des brebis et des bœufs, les prémices de l''anathème, pour les sacrifier à Yahweh, ton Dieu, à Galgala. »'),
('1s',15,22,'crampon1923','Samuel dit: « Yahweh trouve-t-il du plaisir aux holocaustes et aux sacrifices, comme à l''obéissance à la voix de Yahweh? L''obéissance vaut mieux que le sacrifice et la docilité que la graisse des béliers.'),
('1s',15,23,'crampon1923','Car la rébellion est aussi coupable que la divination, et la résistance que l''idolâtrie et les théraphim. Puisque tu as rejeté la parole de Yahweh, il te rejette aussi pour que tu ne sois plus roi. »'),
('1s',15,24,'crampon1923','Alors Saül dit à Samuel: « J''ai péché, car j''ai transgressé l''ordre de Yahweh et tes paroles; je craignais le peuple et j''ai écouté sa voix.'),
('1s',15,25,'crampon1923','Maintenant, je te prie, pardonne mon péché, reviens avec moi, et j''adorerai Yahweh. »'),
('1s',15,26,'crampon1923','Samuel dit à Saül: « Je ne reviendrai point avec toi, car tu as rejeté la parole de Yahweh, et Yahweh te rejette afin que tu ne sois plus roi sur Israël. »'),
('1s',15,27,'crampon1923','Et, comme Samuel se tournait pour s''en aller, Saül saisit l''extrémité de son manteau, qui se déchira.'),
('1s',15,28,'crampon1923','Et Samuel lui dit: « Yahweh a déchiré aujourd''hui de dessus toi la royauté d''Israël, et il l''a donnée à ton voisin qui est meilleur que toi.'),
('1s',15,29,'crampon1923','Celui qui est la splendeur d''Israël ne ment point et ne se repent point, car il n''est pas un homme pour se repentir. »'),
('1s',15,30,'crampon1923','Saül dit: « J''ai péché! Maintenant, honore-moi, je te prie, en présence des anciens de mon peuple et en présence d''Israël; reviens avec moi, et j''adorerai Yahweh, ton Dieu. »'),
('1s',15,31,'crampon1923','Samuel revint et suivit Saül, et Saül adora Yahweh.'),
('1s',15,32,'crampon1923','Et Samuel dit: « Amenez-moi Agag, roi d''Amalec. » Et Agag s''avança vers lui d''un air joyeux; Agag disait: Certainement l''amertume de la mort est passée!'),
('1s',15,33,'crampon1923','Samuel dit: « De même que ton épée a privé des femmes de leurs enfants, ainsi ta mère sera privée d''enfants, entre les femmes! » Et Samuel coupa Agag en morceaux devant Yahweh, à Galgala.'),
('1s',15,34,'crampon1923','Samuel partit pour Rama, et Saül monta dans sa maison, à Gabaa de Saül.'),
('1s',15,35,'crampon1923','Et Samuel ne revit plus Saül jusqu''au jour de sa mort. Comme Samuel pleurait sur Saül, — car Yahweh s''était repenti d''avoir fait Saül roi sur Israël, —'),
('1s',16,1,'crampon1923','Yahweh dit à Samuel: « Jusques à quand pleureras-tu sur Saül, alors que je l''ai rejeté, afin qu''il ne règne plus sur Israël? Remplis ta corne d''huile et va; je t''envoie chez Isaï de Béthléem, car j''ai vu parmi ses fils le roi que je veux. »'),
('1s',16,2,'crampon1923','Samuel dit: « Comment irais-je? Saül l''apprendra, et il me tuera. » Et Yahweh dit: « Tu prendras avec toi une génisse, et tu diras: C''est pour offrir un sacrifice à Yahweh que je suis venu.'),
('1s',16,3,'crampon1923','Tu inviteras Isaï au sacrifice, et je te ferai connaître ce que tu auras à faire, et tu oindras pour moi celui que je te désignerai. »'),
('1s',16,4,'crampon1923','Samuel fit ce que Yahweh avait dit, et il se rendit à Bethléem. Les anciens de la ville vinrent inquiets au-devant de lui et dirent: « Ton arrivée est-elle pour la paix? »'),
('1s',16,5,'crampon1923','Il répondit: « Pour la paix! Je viens pour offrir un sacrifice à Yahweh. Sanctifiez-vous et venez avec moi au sacrifice. » Et il sanctifia Isaï et ses fils et les invita au sacrifice.'),
('1s',16,6,'crampon1923','Lorsqu''ils furent entrés, Samuel aperçut Eliab et dit: « Certainement l''oint de Yahweh est devant lui. »'),
('1s',16,7,'crampon1923','Et Yahweh dit à Samuel: « Ne prends pas garde à sa figure et à la hauteur de sa taille, car je l''ai écarté. Il ne s''agit pas de ce que l''homme voit; l''homme regarde le visage, mais Yahweh regarde le cœur. »'),
('1s',16,8,'crampon1923','Isaï appela Abinadab et le fit passer devant Samuel; et Samuel dit: « Ce n''est pas encore celui-ci que Yahweh a choisi. »'),
('1s',16,9,'crampon1923','Isaï fit passer Samma; et Samuel dit: « Ce n''est pas encore celui-ci que Yahweh a choisi. »'),
('1s',16,10,'crampon1923','Isaï fit passer ses sept fils devant Samuel; et Samuel dit à Isaï: « Yahweh n''a choisi aucun de ceux-ci. »'),
('1s',16,11,'crampon1923','Alors Samuel dit à Isaï: « Sont-ce là tous les jeunes gens? » Il répondit: « Il y a encore le plus jeune, et voilà qu''il fait paître les brebis. » Samuel dit à Isaï: « Envoie-le chercher, car nous ne nous mettrons point à table qu''il ne soit venu ici. »'),
('1s',16,12,'crampon1923','Isaï l''envoya chercher. Or il était blond, avec de beaux yeux et une belle figure. Yahweh dit: « Lève-toi, oins-le, car c''est lui! »'),
('1s',16,13,'crampon1923','Samuel, ayant pris la corne d''huile, l''oignit au milieu de ses frères, et l''Esprit de Yahweh fondit sur David à partir de ce jour et dans la suite. Samuel se leva et s''en alla à Ramatha.'),
('1s',16,14,'crampon1923','L''Esprit de Yahweh se retira de Saül, et un mauvais esprit venu de Yahweh fondit sur lui.'),
('1s',16,15,'crampon1923','Les serviteurs de Saül lui dirent: « Voici qu''un mauvais esprit de Dieu fond sur toi.'),
('1s',16,16,'crampon1923','Que notre seigneur parle; tes serviteurs sont devant toi, ils chercheront un homme sachant jouer de la harpe, et, quand le mauvais esprit venu de Dieu sera sur toi, il jouera de sa main, et tu seras soulagé. »'),
('1s',16,17,'crampon1923','Saül répondit à ses serviteurs: « Trouvez-moi donc un homme habile à jouer, et amenez-le-moi. »'),
('1s',16,18,'crampon1923','L''un des serviteurs, prenant la parole, dit: « J''ai vu un fils d''Isaï de Bethléem, qui sait jouer; il est fort et vaillant guerrier, parlant bien; c''est un homme de belle figure, et Yahweh est sur lui. »'),
('1s',16,19,'crampon1923','Saül envoya des messagers à Isaï, pour lui dire: « Envoie-moi David, ton fils, qui est avec les brebis. »'),
('1s',16,20,'crampon1923','Isaï prit un âne, avec du pain, une outre de vin et un chevreau, et les envoya à Saül par David, son fils.'),
('1s',16,21,'crampon1923','Arrivé chez Saül, David se tint devant lui; et Saül le prit en affection, et il devint son écuyer.'),
('1s',16,22,'crampon1923','Et Saül envoya dire à Isaï: « Que David, je te prie, reste devant moi, car il a trouvé grâce à mes yeux. »'),
('1s',16,23,'crampon1923','Lorsque l''esprit venu de Dieu était sur Saül, David prenait la harpe et jouait de sa main, et Saül se calmait et se trouvait bien, et le mauvais esprit se retirait de lui.'),
('1s',17,1,'crampon1923','Les Philistins, ayant rassemblé leurs armées pour faire la guerre, se réunirent à Socho, qui appartient à Juda; ils campèrent entre Socho et Azéca, à Ephès-Dommim.'),
('1s',17,2,'crampon1923','Saül et les hommes d''Israël se rassemblèrent aussi et campèrent dans la vallée de Térébinthe; ils se rangèrent en bataille en face des Philistins.'),
('1s',17,3,'crampon1923','Les Philistins étaient postés sur la montagne d''un côté, et Israël était posté sur la montagne de l''autre côté: la vallée était entre eux.'),
('1s',17,4,'crampon1923','Alors sortit des camps des Philistins un champion; il se nommait Goliath, il était de Geth, et sa taille était de six coudées et un palme.'),
('1s',17,5,'crampon1923','Un casque d''airain couvrait sa tête, et il portait une cuirasse à écailles; et le poids de la cuirasse était de cinq mille sicles d''airain.'),
('1s',17,6,'crampon1923','Il avait aux pieds une chaussure d''airain et un javelot d''airain entre ses épaules.'),
('1s',17,7,'crampon1923','Le bois de sa lance était comme une ensouple de tisserand, et la pointe de sa lance pesait six cents sicles de fer; celui qui portait son bouclier marchait devant lui.'),
('1s',17,8,'crampon1923','Goliath s''arrêta et, s''adressant aux bataillons d''Israël, il leur cria: « Pourquoi êtes-vous sortis pour vous ranger en bataille? Ne suis-je pas le Philistin, et n''êtes-vous pas les esclaves de Saül? Choisissez un homme qui descende contre moi.'),
('1s',17,9,'crampon1923','S''il l''emporte en se battant avec moi et qu''il me tue, nous vous serons assujettis; mais si je l''emporte sur lui et que je le tue, vous nous serez assujettis et vous nous servirez. »'),
('1s',17,10,'crampon1923','le Philistin ajouta: « Je jette aujourd''hui ce défi à l''armée d''Israël: Donnez-moi un homme, et nous nous battrons ensemble. »'),
('1s',17,11,'crampon1923','En entendant ces paroles du Philistin, Saül et tout Israël furent effrayés et saisis d''une grande crainte.'),
('1s',17,12,'crampon1923','Or David était fils de cet Ephratéen de Bethléem de Juda nommé Isaï, qui avait huit fils; cet homme, au temps de Saül, était vieux, avancé en âge.'),
('1s',17,13,'crampon1923','Les trois fils aînés d''Isaï étaient allés suivre Saül à la guerre; et les noms de ces trois fils qui étaient allés à la guerre étaient Eliab l''aîné, Abinadab le second, et Samma le troisième.'),
('1s',17,14,'crampon1923','David était le plus jeune. Les trois aînés suivaient Saül,'),
('1s',17,15,'crampon1923','et David allait et venait d''auprès de Saül, pour paître les brebis de son père à Bethléem.'),
('1s',17,16,'crampon1923','Le Philistin s''avançait matin et soir, et il se présenta pendant quarante jours.'),
('1s',17,17,'crampon1923','Isaï dit à David, son fils: « Prends pour tes frères cet épha de grain rôti et ces dix pains, et cours au camp vers tes frères.'),
('1s',17,18,'crampon1923','Et ces dix fromages, porte-les au chef de leur millier. Tu visiteras tes frères pour voir s''ils se portent bien, et tu prendras d''eux un gage.'),
('1s',17,19,'crampon1923','Saül et eux, et tous les hommes d''Israël, sont dans la vallée de Térébinthe, faisant la guerre aux Philistins. »'),
('1s',17,20,'crampon1923','David se leva de bon matin et, laissant les brebis à un gardien, il prit les provisions et partit, comme Isaï le lui avait commandé. Quand il arriva au campement, l''armée sortait du camp pour se ranger en bataille et on poussait des cris de guerre.'),
('1s',17,21,'crampon1923','Israélites et Philistins se rangèrent en ligne, troupe contre troupe.'),
('1s',17,22,'crampon1923','David déposa ses bagages entre les mains du gardien des bagages, et courut vers la troupe. Aussitôt arrivé, il demanda à ses frères comment ils se portaient.'),
('1s',17,23,'crampon1923','Pendant qu''il s''entretenait avec eux, voici que le champion, — il se nommait Goliath, le Philistin de Geth, — s''avança hors des rangs des Philistins, tenant les mêmes discours et David l''entendit.'),
('1s',17,24,'crampon1923','En voyant cet homme, tous ceux d''Israël se retirèrent devant lui, saisis d''une grande crainte.'),
('1s',17,25,'crampon1923','Un Israélite dit: « Voyez-vous cet homme qui s''avance? C''est pour défier Israël qu''il s''avance. Celui qui le tuera, le roi le comblera de grandes richesses, il lui donnera sa fille et il affranchira de toute charge la maison de son père en Israël. »'),
('1s',17,26,'crampon1923','David dit aux hommes qui se tenaient près de lui: « Que fera-t-on à celui qui tuera ce Philistin et qui ôtera l''opprobre de dessus Israël? Qui est donc ce Philistin, cet incirconcis, pour insulter les troupes du Dieu vivant? »'),
('1s',17,27,'crampon1923','Le peuple lui répéta les mêmes paroles, en disant: « Voilà ce qu''on fera à celui qui le tuera. »'),
('1s',17,28,'crampon1923','Eliab, son frère aîné, l''entendit parler aux hommes, et la colère d''Eliab s''enflamma contre David, et il dit: « Pourquoi es-tu descendu, et à qui as-tu laissé ce petit nombre de brebis dans le désert? Je connais ton orgueil et la malice de ton cœur; c''est pour voir la bataille que tu es descendu. »'),
('1s',17,29,'crampon1923','David répondit: « Qu''ai-je fait maintenant? N''est-ce pas une simple parole? »'),
('1s',17,30,'crampon1923','Et, se détournant de lui pour s''adresser à un autre, il tint le même langage; et le peuple lui répondit comme la première fois.'),
('1s',17,31,'crampon1923','Lorsqu''on eut entendu les paroles prononcées par David, on les rapporta à Saül, qui le fit venir.'),
('1s',17,32,'crampon1923','David dit à Saül: « Que le cœur ne défaille à personne! Ton serviteur ira combattre contre ce Philistin. »'),
('1s',17,33,'crampon1923','Saül dit à David: « Tu ne peux aller contre ce Philistin pour combattre avec lui, car tu es un enfant, et il est un homme de guerre depuis sa jeunesse. »'),
('1s',17,34,'crampon1923','David dit à Saül: « Lorsque ton serviteur faisait paître les brebis de son père, et qu''un lion ou un ours venait et enlevait une brebis du troupeau,'),
('1s',17,35,'crampon1923','je me mettais à sa poursuite, je le frappais et j''arrachais la brebis de sa gueule; s''il se dressait contre moi, je le saisissais à la mâchoire, je le frappais et je le tuais.'),
('1s',17,36,'crampon1923','Ton serviteur a tué le lion comme l''ours, et il en sera du Philistin, de cet incirconcis, comme de l''un d''eux, car il a insulté les troupes du Dieu vivant. »'),
('1s',17,37,'crampon1923','David ajouta: « Yahweh qui m''a délivré du lion et de l''ours, me délivrera aussi de la main de ce Philistin. » Et Saül dit à David: « Va, et que Yahweh soit avec toi! »'),
('1s',17,38,'crampon1923','Saül fit revêtir David de ses habits, mit sur sa tête un casque d''airain et l''endossa d''une cuirasse;'),
('1s',17,39,'crampon1923','puis David ceignit l''épée de Saül par-dessus son armure, et il essaya de marcher, car il n''avait jamais essayé d''armure. David dit à Saül: « Je ne puis marcher avec ces armes, je n''y suis point accoutumé. » Et, s''en étant débarrassé,'),
('1s',17,40,'crampon1923','David prit en main son bâton, choisit dans le torrent cinq cailloux polis et les mit dans son sac de berger, dans sa gibecière. Puis, sa fronde à la main, il s''avança vers le Philistin.'),
('1s',17,41,'crampon1923','Le Philistin s''approcha peu à peu de David, précédé de l''homme qui portait le bouclier.'),
('1s',17,42,'crampon1923','Le Philistin regarda, vit David et le méprisa, car il était très jeune, blond et beau de visage.'),
('1s',17,43,'crampon1923','Le Philistin dit à David: « Suis-je un chien, que tu viennes à moi avec un bâton? » Et le Philistin maudit David par ses dieux.'),
('1s',17,44,'crampon1923','Et le Philistin dit à David: « Viens à moi, que je donne ta chair aux oiseaux du ciel et aux bêtes des champs. »'),
('1s',17,45,'crampon1923','David répondit au Philistin: « Tu viens à moi avec l''épée, la lance et le javelot; et moi je viens à toi au nom de Yahweh des armées, du Dieu des bataillons d''Israël, que tu as insulté.'),
('1s',17,46,'crampon1923','Aujourd''hui Yahweh te livrera entre mes mains, je te frapperai et j''enlèverai ta tête de dessus toi; aujourd''hui je donnerai les cadavres de l''armée des Philistins aux oiseaux du ciel et aux animaux de la terre; et toute la terre saura qu''Israël a un Dieu;'),
('1s',17,47,'crampon1923','et toute cette multitude saura que ce n''est ni par l''épée ou par la lance que Yahweh sauve, car à Yahweh appartient la guerre, et il vous a livrés entre nos mains. »'),
('1s',17,48,'crampon1923','Le Philistin, s''étant levé, se mit en marche et s''avança au-devant de David, et David se hâta de courir, vers le front de la troupe, à la rencontre du Philistin.'),
('1s',17,49,'crampon1923','David mit la main dans sa gibecière, en retira une pierre et la lança avec sa fronde; il frappa le Philistin au front, et la pierre s''enfonça dans son front, et il tomba le visage contre terre.'),
('1s',17,50,'crampon1923','Ainsi David, avec une fronde et une pierre, fut plus fort que le Philistin, il frappa à mort le Philistin. Et il n''y avait pas d''épée dans la main de David.'),
('1s',17,51,'crampon1923','David courut, s''arrêta près du Philistin et, s''étant saisi de son épée qu''il tira du fourreau, il le tua et lui coupa la tête avec elle.'),
('1s',17,52,'crampon1923','Voyant leur héros mort, les Philistins prirent la fuite. Et les hommes d''Israël et de Juda se levèrent, en poussant des cris, et poursuivirent les Philistins jusqu''à l''entrée de Geth et jusqu''aux portes d''Accaron. Les cadavres des Philistins jonchèrent le chemin de Saraïm jusqu''à Geth et jusqu''à Accaron.'),
('1s',17,53,'crampon1923','A leur retour de la poursuite des Philistins, les enfants d''Israël pillèrent leur camp.'),
('1s',17,54,'crampon1923','David prit la tête du Philistin et la fit porter à Jérusalem, et il mit dans sa tente les armes du Philistin.'),
('1s',17,55,'crampon1923','Lorsque Saül eut vu David s''avancer à la rencontre du Philistin, il dit à Abner, chef de l''armée: « De qui ce jeune homme est-il fils, Abner? » Abner répondit: « Aussi vrai que ton âme est vivante, ô roi, je l''ignore. »'),
('1s',17,56,'crampon1923','Le roi lui dit: « Informe-toi donc de qui est fils ce jeune homme. »'),
('1s',17,57,'crampon1923','Quand David fut de retour après avoir tué le Philistin, Abner le prit et le mena devant Saül; David avait à la main la tête du Philistin.'),
('1s',17,58,'crampon1923','Saül lui dit: « De qui es-tu fils, jeune homme. » Et David répondit: « Je suis fils de ton serviteur, Isaï de Bethléem. »'),
('1s',18,1,'crampon1923','Lorsque David eut achevé de parler à Saül, l''âme de Jonathas s''attacha à l''âme de David, et Jonathas l''aima comme son âme.'),
('1s',18,2,'crampon1923','Ce même jour, Saül prit David, et ne le laissa pas retourner dans la maison de son père.'),
('1s',18,3,'crampon1923','Et Jonathas fit alliance avec David, parce qu''il l''aimait comme son âme.'),
('1s',18,4,'crampon1923','Jonathas se dépouilla du manteau qu''il portait et le donna à David, ainsi que son armure, jusqu''à son épée, jusqu''à son arc et jusqu''à sa ceinture.'),
('1s',18,5,'crampon1923','Quand David sortait, partout où l''envoyait Saül, il réussissait; Saül le mit à la tête des gens de guerre, et il plaisait à tout le peuple, même aux serviteurs du roi.'),
('1s',18,6,'crampon1923','Quand ils firent leur entrée, lorsque David revint après avoir tué le Philistin, les femmes sortirent de toutes les villes d''Israël, en chantant et en dansant, au-devant du roi Saül, avec joie, au son des tambourins et des harpes.'),
('1s',18,7,'crampon1923','Les femmes, les danseuses, se répondaient et disaient: Saül a tué ses mille, et David ses dix mille.'),
('1s',18,8,'crampon1923','Saül fut très irrité, et ces paroles lui déplurent: il dit: « On donne dix mille à David, et à moi on donne les mille! Il ne lui manque plus que la royauté. »'),
('1s',18,9,'crampon1923','Et Saül voyait David de mauvais œil, à partir de ce jour.'),
('1s',18,10,'crampon1923','Le lendemain, un mauvais esprit envoyé de Dieu fondit sur Saül, et il eut des transports au milieu de sa maison. David jouait de la harpe, comme les autres jours, et Saül avait sa lance à la main.'),
('1s',18,11,'crampon1923','Saül brandit sa lance, disant en lui-même: « Je frapperai David et la paroi »; mais David se détourna de devant lui par deux fois.'),
('1s',18,12,'crampon1923','Saül craignait David, car Yahweh était avec David et s''était retiré de Saül, —'),
('1s',18,13,'crampon1923','et Saül l''éloigna de sa personne, et il l''établit chef de mille hommes; et David sortait et rentrait devant le peuple.'),
('1s',18,14,'crampon1923','David se montrait habile dans toutes ses entreprises, et Yahweh était avec lui.'),
('1s',18,15,'crampon1923','Saül, voyant qu''il était très habile, avait peur de lui;'),
('1s',18,16,'crampon1923','mais tout Israël et Juda aimaient David, parce qu''il sortait et rentrait devant eux.'),
('1s',18,17,'crampon1923','Saül dit à David: « Voici que je te donnerai pour femme ma fille aînée Mérob; seulement montre-toi plein de vaillance et soutiens les guerres de Yahweh. » Or Saül se disait: « Que ma main ne soit pas sur lui, mais que sur lui soit la main des Philistins! »'),
('1s',18,18,'crampon1923','David répondit à Saül: « Qui suis-je et qu''est-ce que ma vie, qu''est-ce que la famille de mon père en Israël, pour que je devienne le gendre du roi? »'),
('1s',18,19,'crampon1923','Mais, au moment de donner Mérob, fille de Saül, à David, on la donna pour femme à Hadriel de Molathi.'),
('1s',18,20,'crampon1923','Michol, fille de Saül, aima David. On en informa Saül, et cela lui plut.'),
('1s',18,21,'crampon1923','Saül se disait: « Je la lui donnerai, afin qu''elle soit pour lui un piège, et que la main des Philistins soit sur lui. » Et Saül dit à David, pour la seconde fois: « Tu vas aujourd''hui devenir mon gendre. »'),
('1s',18,22,'crampon1923','Et Saül donna cet ordre à ses serviteurs: « Parlez confidentiellement à David, et dites-lui: Le roi t''a pris en affection, et tous ses serviteurs t''aiment; sois donc maintenant le gendre du roi. »'),
('1s',18,23,'crampon1923','Les serviteurs de Saül dirent ces paroles aux oreilles de David, et David répondit: « Est-ce peu de chose à vos yeux que de devenir le gendre du roi? Moi, je suis un homme pauvre et d''humble origine. »'),
('1s',18,24,'crampon1923','Les serviteurs de Saül lui firent rapport en ces termes: « David a tenu ce langage. »'),
('1s',18,25,'crampon1923','Saül dit: « Vous parlerez ainsi à David: Le roi ne demande aucune dot, mais cent prépuces de Philistins, pour être vengé des ennemis du roi. » Saül pensait faire ainsi tomber David dans la main des Philistins.'),
('1s',18,26,'crampon1923','Les serviteurs de Saül rapportèrent ces paroles à David, et cela plut à David, à savoir devenir le gendre du roi.'),
('1s',18,27,'crampon1923','Les jours n''étaient pas accomplis que David, s''étant levé, partit avec ses gens et tua aux Philistins deux cents hommes; et David apporta leurs prépuces et en remit au roi le nombre complet, afin de devenir son gendre. Alors Saül lui donna pour femme sa fille Michol.'),
('1s',18,28,'crampon1923','Saül vit et comprit que Yahweh était avec David; et Michol, fille de Saül, aimait David.'),
('1s',18,29,'crampon1923','Et Saül craignit David de plus en plus, et Saül fut hostile à David tous les jours.'),
('1s',18,30,'crampon1923','Les princes des Philistins faisaient des excursions et, chaque fois qu''ils sortaient, David par son habileté remportait plus de succès que tous les serviteurs de Saül; et son nom devint très célèbre.'),
('1s',19,1,'crampon1923','Saül parla à Jonathas, son fils, et à tous ses serviteurs de faire mourir David. Mais Jonathas, fils de Saül, avait une grande affection pour David.'),
('1s',19,2,'crampon1923','Et Jonathas informa David en disant: « Saül, mon père, cherche à te faire mourir. Sois donc sur tes gardes demain au matin, tiens-toi à l''écart et cache-toi.'),
('1s',19,3,'crampon1923','Moi, je sortirai et je me tiendrai à côté de mon père dans le champ où tu seras; je parlerai de toi à mon père, je verrai ce qu''il dira et je te le ferai savoir. »'),
('1s',19,4,'crampon1923','Jonathas parla favorablement de David à Saül, son père; il lui dit: « Que le roi ne pèche pas contre son serviteur David, car il n''a pas péché à ton égard. Ses actions, au contraire, sont toutes pour ton bien:'),
('1s',19,5,'crampon1923','il a exposé sa vie, il a frappé le Philistin, et Yahweh a opéré par lui une grande délivrance pour tout Israël. Tu l''as vu, et tu t''en es réjoui; pourquoi te rendrais-tu coupable du sang innocent, en faisant mourir David sans raison? »'),
('1s',19,6,'crampon1923','Saül écouta la voix de Jonathas, et Saül fit ce serment: « Yahweh est vivant! David ne sera pas mis à mort. »'),
('1s',19,7,'crampon1923','Jonathas appela David et Jonathas lui rapporta toutes ces paroles; puis Jonathas ramena David auprès de Saül, et David se tint en sa présence comme auparavant.'),
('1s',19,8,'crampon1923','La guerre ayant recommencé, David sortit contre les Philistins et leur livra bataille; il leur fit éprouver une grande défaite, et ils s''enfuirent devant lui.'),
('1s',19,9,'crampon1923','Alors le mauvais esprit de Yahweh fut sur Saül, pendant qu''il était assis dans sa maison, sa lance à la main; et David jouait de la harpe avec sa main.'),
('1s',19,10,'crampon1923','Saül chercha à frapper de sa lance David et le mur; mais David s''enfuit de devant Saül, qui frappa la lance contre le mur. David prit la fuite et s''échappa pendant la nuit.'),
('1s',19,11,'crampon1923','Saül envoya des messagers à la maison de David, pour s''assurer de lui et le faire mourir au matin; mais Michol, femme de David, l''en informa, en disant: « Si tu ne t''échappes pas cette nuit, demain tu es mis à mort. »'),
('1s',19,12,'crampon1923','Michol fit descendre David par la fenêtre, et David s''en alla et s''enfuit, et il fut sauvé.'),
('1s',19,13,'crampon1923','Michol prit ensuite le théraphim et, l''ayant placé dans le lit, elle mit une peau de chèvre à l''endroit de sa tête, et le couvrit d''un vêtement.'),
('1s',19,14,'crampon1923','Et lorsque Saül envoya des messagers pour prendre David, elle dit: « Il est malade. »'),
('1s',19,15,'crampon1923','Saül renvoya les messagers pour voir David, en disant: « Apportez-le-moi dans son lit, afin que je le fasse mourir. »'),
('1s',19,16,'crampon1923','Les messagers revinrent et voici que le théraphim était sur le lit avec une peau de chèvre à l''endroit de sa tête.'),
('1s',19,17,'crampon1923','Et Saül dit à Michol: « Pourquoi m''as-tu trompé ainsi, et as-tu laissé aller mon ennemi, pour qu''il fût sauvé? » Michol répondit à Saül: « Il m''a dit: Laisse-moi aller, ou je te tue. »'),
('1s',19,18,'crampon1923','C''est ainsi que David prit la fuite et fut sauvé. Il se rendit auprès de Samuel à Rama, et lui raconta tout ce que Saül lui avait fait. Puis il alla avec Samuel demeurer à Naioth.'),
('1s',19,19,'crampon1923','On le fit savoir à Saül, en disant: « Voici que David est à Naioth, en Rama. »'),
('1s',19,20,'crampon1923','Aussitôt Saül envoya des messagers pour prendre David; ils virent la troupe de prophètes qui prophétisaient, et Samuel était debout, les présidant; et l''Esprit de Dieu fut sur les envoyés de Saül, qui eux aussi prophétisèrent.'),
('1s',19,21,'crampon1923','On l''annonça à Saül, et il envoya d''autres messagers, et eux aussi prophétisèrent. Pour la troisième fois, Saül envoya des messagers, et eux aussi prophétisèrent.'),
('1s',19,22,'crampon1923','Alors Saül alla, lui aussi, à Rama. Arrivé à la grande citerne qui est à Socho, il demanda: « Où sont Samuel et David? » On lui répondit: « Voici, ils sont à Naioth en Rama. »'),
('1s',19,23,'crampon1923','Et il se dirigea là, vers Naioth en Rama. L''Esprit de Dieu fut aussi sur lui, et il allait et il prophétisait, jusqu''à son arrivée à Naioth en Rama.'),
('1s',19,24,'crampon1923','Là, ayant aussi ôté ses vêtements, il prophétisa, lui aussi, devant Samuel, et il resta nu par terre tout ce jour-là et toute la nuit. C''est pourquoi on dit: « Saül est-il aussi parmi les prophètes? »'),
('1s',20,1,'crampon1923','David s''enfuit de Naioth en Rama et, étant venu, il dit devant Jonathas: « Qu''ai-je fait? quel est mon crime, quel est mon péché devant ton père, pour qu''il en veuille à ma vie? »'),
('1s',20,2,'crampon1923','Jonathas lui dit: « Loin de là! Tu ne mourras point. Mon père ne fait aucune chose, grande ou petite, sans m''en faire part; pourquoi donc me cacherait-il celle-là? Il n''en est rien. »'),
('1s',20,3,'crampon1923','David répondit avec un serment: « Ton père sait bien que j''ai trouvé grâce à tes yeux, et il aura dit: Que Jonathas ne le sache pas, de peur qu''il en ait de la peine. Mais, aussi vrai que Yahweh est vivant et que ton âme est vivante! il n''y a qu''un pas entre la mort et moi. »'),
('1s',20,4,'crampon1923','Jonathas dit à David: « Tout ce que ton âme dira, je le ferai pour toi. »'),
('1s',20,5,'crampon1923','Et David dit à Jonathas: « Voici, c''est demain la nouvelle lune, et je devrais m''asseoir auprès du roi pour le repas; laisse-moi partir, et je me cacherai dans les champs jusqu''au soir du troisième jour.'),
('1s',20,6,'crampon1923','Si ton père s''aperçoit de mon absence, tu lui diras: David m''a prié de lui laisser faire une course à Bethléem, sa ville, parce qu''il y a là le sacrifice annuel pour toute sa famille.'),
('1s',20,7,'crampon1923','S''il dit: C''est bien! ton serviteur peut être en paix; mais s''il se met en colère, sache que le mal est bien résolu de sa part.'),
('1s',20,8,'crampon1923','Use donc de bonté envers ton serviteur, puisque c''est par une alliance au nom de Yahweh que tu as attiré vers toi ton serviteur. S''il y a quelque faute en moi, mets-moi à mort toi-même, car pourquoi me mènerais-tu à ton père? »'),
('1s',20,9,'crampon1923','Jonathas lui dit: « Loin de toi cette pensée! Car si j''apprends vraiment que le mal est résolu de la part de mon père pour venir sur toi, je jure de t''en informer. »'),
('1s',20,10,'crampon1923','David dit à Jonathas: « Qui m''informera de cela ou de ce que ton père répondrait de fâcheux? »'),
('1s',20,11,'crampon1923','Jonathas dit à David: « Viens, sortons dans les champs; » et ils sortirent tous deux dans les champs.'),
('1s',20,12,'crampon1923','Jonathas dit à David: « Yahweh, Dieu d''Israël! Je sonderai mon père demain ou après-demain, et si cela va bien pour David, et que je n''envoie pas vers toi pour t''en informer,'),
('1s',20,13,'crampon1923','que Yahweh traite Jonathas dans toute sa rigueur! S''il plaît à mon père de te faire du mal, je t''en informerai aussi et je te ferai partir, afin que tu t''en ailles en paix, et que Yahweh soit avec toi, comme il a été avec mon père!'),
('1s',20,14,'crampon1923','Et si je suis encore vivant, veuille user envers moi de la bonté de Yahweh, et, si je meurs,'),
('1s',20,15,'crampon1923','ne pas retirer à jamais ta bonté de ma maison, pas même lorsque Yahweh retranchera de dessus la face de la terre chacun des ennemis de David! »'),
('1s',20,16,'crampon1923','C''est ainsi que Jonathas fit alliance avec la maison de David, et que Yahweh tira vengeance des ennemis de David.'),
('1s',20,17,'crampon1923','Jonathas adjura encore une fois David par l''amour qu''il avait pour lui, car il l''aimait comme son âme.'),
('1s',20,18,'crampon1923','Jonathas lui dit: « C''est demain la nouvelle lune; on remarquera que ta place est vide.'),
('1s',20,19,'crampon1923','Le troisième jour, tu descendras promptement et tu viendras au lieu où tu étais caché, au jour de l''affaire, et tu resteras près de la pierre d''Ezel.'),
('1s',20,20,'crampon1923','Je tirerai trois flèches du côté de la pierre, comme si je visais à un but.'),
('1s',20,21,'crampon1923','Et voici, j''enverrai le garçon en lui disant: Va, retrouve les flèches. Si je dis au garçon: Voici, les flèches sont en deçà toi, prends-les! alors, viens, car tout va bien pour toi, et il n''y a nul danger, Yahweh est vivant!'),
('1s',20,22,'crampon1923','Mais si je parle ainsi au garçon: Voici, les flèches sont au delà de toi, alors va-t-en, car Yahweh te fait partir.'),
('1s',20,23,'crampon1923','Et quant à la parole que nous avons dite, moi et toi, voici que Yahweh est à jamais entre toi et moi. »'),
('1s',20,24,'crampon1923','David se cacha dans les champs. La nouvelle lune venue, le roi prit place au festin pour manger;'),
('1s',20,25,'crampon1923','comme à l''ordinaire, le roi s''assit sur son siège, sur le siège qui était près du mur; Jonathas se leva, et Abner s''assit à côté de Saül et la place de David resta vide.'),
('1s',20,26,'crampon1923','Saül ne dit rien ce jour-là, car, disait-il, « quelque chose lui est arrivé; il n''est pas pur, certainement il n''est pas pur. »'),
('1s',20,27,'crampon1923','Le lendemain, second jour de la nouvelle lune, la place de David était encore vide; et Saül dit à Jonathas, son fils: « Pourquoi le fils d''Isaï n''est-il pas venu au repas, ni hier ni aujourd''hui? »'),
('1s',20,28,'crampon1923','Jonathas répondit à Saül: « David m''a demandé avec instances la permission d''aller jusqu''à Bethléem.'),
('1s',20,29,'crampon1923','Il a dit: Laisse-moi aller, je te prie, car nous avons dans la ville un sacrifice de famille, et mon frère m''a commandé d''y assister; si donc j''ai trouvé grâce à tes yeux, permets que je m''y rende et que je voie mes frères! C''est pourquoi il n''est pas venu à la table du roi. »'),
('1s',20,30,'crampon1923','Alors la colère de Saül s''enflamma contre Jonathas, et il lui dit: « Fils d''une femme perverse et rebelle, ne sais-je pas que tu as pour ami le fils d''Isaï, à ta honte et à la honte de la nudité de ta mère?'),
('1s',20,31,'crampon1923','Car aussi longtemps que le fils d''Isaï sera vivant sur la terre, il n''y aura de sécurité ni pour toi, ni pour ta royauté. Et maintenant, envoie-le prendre et amène-le-moi, car c''est un fils de la mort. »'),
('1s',20,32,'crampon1923','Jonathas répondit à Saül, son père, et lui dit: « Pourquoi serait-il mis à mort? Qu''a-t-il fait? »'),
('1s',20,33,'crampon1923','Et Saül brandit sa lance contre lui pour le frapper. Jonathas comprit que c''était chose arrêtée chez son père de faire périr David.'),
('1s',20,34,'crampon1923','Jonathas se leva donc de table dans une violente colère, et ne prit point de nourriture, le second jour de la nouvelle lune; car il était affligé à cause de David, parce que son père l''avait outragé.'),
('1s',20,35,'crampon1923','Le lendemain matin, Jonathas alla aux champs, selon qu''il était convenu avec David; un petit garçon l''accompagnait.'),
('1s',20,36,'crampon1923','Il dit à son garçon: « Cours, retrouve les flèches que je vais tirer. » Le garçon courut, et Jonathas tira une flèche de manière à le dépasser.'),
('1s',20,37,'crampon1923','Lorsque le garçon arriva à l''endroit de la flèche que Jonathas avait tirée, Jonathas cria après le garçon et dit: « La flèche n''est-elle pas plus loin que toi? »'),
('1s',20,38,'crampon1923','Jonathas cria encore après le garçon: « Vite, hâte-toi, ne t''arrête pas! » Et le garçon de Jonathas ramassa la flèche et revint vers son maître.'),
('1s',20,39,'crampon1923','Le garçon ne savait rien; Jonathas et David seuls comprenaient la chose.'),
('1s',20,40,'crampon1923','Jonathas donna ses armes au garçon qui était avec lui, et lui dit: « Va, et portes-les à la ville. »'),
('1s',20,41,'crampon1923','Dès que le garçon fut parti, David se leva du côté du midi et, se jetant la face contre terre, il se prosterna trois fois devant Jonathas; puis ils s''embrassèrent l''un l''autre et pleurèrent au sujet l''un de l''autre, au point que David fondit en larmes.'),
('1s',20,42,'crampon1923','Et Jonathas dit à David: « Va en paix, après que nous avons juré l''un et l''autre, au nom de Yahweh, en disant: Que Yahweh soit entre moi et toi, entre ma postérité et ta postérité à jamais! »'),
('1s',21,1,'crampon1923','David se leva et s''en alla, et Jonathas rentra dans la ville.'),
('1s',21,2,'crampon1923','David se rendit à Nobé, auprès du grand prêtre Achimélech; et Achimélech accourut effrayé au-devant de David, et lui dit: « Pourquoi es-tu seul et n''y a-t-il personne avec toi? »'),
('1s',21,3,'crampon1923','David répondit au prêtre Achimélech: « Le roi m''a donné un ordre et m''a dit: Que personne ne sache rien de l''affaire pour laquelle je t''envoie et je t''ai donné un ordre. J''ai assigné à mes gens tel lieu de rendez-vous.'),
('1s',21,4,'crampon1923','Et maintenant qu''as-tu sous la main? Donne-moi cinq pains dans la main, ou ce qui se trouvera. »'),
('1s',21,5,'crampon1923','Le prêtre répondit à David et dit: « Je n''ai pas sous la main de pain ordinaire, mais il y a du pain consacré; pourvu que tes gens se soient abstenus de femmes. »'),
('1s',21,6,'crampon1923','David répondit au prêtre et lui dit: « Nous nous sommes abstenus de femmes depuis trois jours que je suis parti, et les vases de mes gens sont chose sainte; et si le voyage est profane, pourtant il est sanctifié quant au vase? »'),
('1s',21,7,'crampon1923','Alors le prêtre lui donna du pain consacré, car il n''y avait pas là d''autre pain que le pain de proposition, qu''on avait ôté de devant Yahweh, pour le remplacer par du pain chaud au moment où on l''enlevait.'),
('1s',21,8,'crampon1923','— Ce même jour, de trouvait là un homme d''entre les serviteurs de Saül, retenu devant Yahweh; il s''appelait Doëg, un Edomite, chef des bergers de Saül.'),
('1s',21,9,'crampon1923','David dit à Achimélech: « N''as-tu pas sous la main une lance ou une épée? car je n''ai pas même pris avec moi mon épée ni mes armes, parce que l''ordre du roi était pressant. »'),
('1s',21,10,'crampon1923','Le prêtre répondit: « Il y a l''épée de Goliath, le Philistin que tu as tué dans la vallée du Térébinthe; la voilà, enveloppée dans le manteau, derrière l''éphod. Si tu veux la prendre, prends-la, car il n''y en a pas d''autre ici. » Et David dit: « Elle n''a pas sa pareille, donne-la-moi. »'),
('1s',21,11,'crampon1923','David se leva et s''enfuit ce même jour loin de Saül; il se rendit chez Achis, roi de Geth.'),
('1s',21,12,'crampon1923','Les serviteurs d''Achis lui dirent: « N''est-ce pas là David, roi du pays? N''est-ce pas celui pour qui l''on chantait en dansant: Saül a tué ses mille, et David ses dix mille. »'),
('1s',21,13,'crampon1923','David prit ces paroles à cœur, et il eut une grande peur d''Achis, roi de Geth.'),
('1s',21,14,'crampon1923','Il dissimula sa raison à leurs yeux et fit l''insensé entre leurs mains; il battait du tambour sur les battants des portes, et il laissait couler sa salive sur sa barbe.'),
('1s',21,15,'crampon1923','Achis dit à ses serviteurs: « Vous voyez bien que cet homme est un fou; pourquoi me l''avez-vous amené?'),
('1s',21,16,'crampon1923','Est-ce que je manque de fous, que vous m''ameniez celui-ci, pour qu''il fasse des folies devant moi? Doit-il entrer dans ma maison? »'),
('1s',22,1,'crampon1923','David partit de là et s''enfuit dans la caverne d''Odollam. Ses frères et toute la maison de son père l''ayant appris, ils descendirent là, vers lui.'),
('1s',22,2,'crampon1923','Tous les opprimés, tous ceux qui avaient des créanciers et tous ceux qui étaient dans l''amertume, se rassemblèrent auprès de lui, et il devint leur chef; il y eut ainsi avec lui environ quatre cents hommes.'),
('1s',22,3,'crampon1923','De là, David s''en alla à Maspha de Moab. Il dit au roi de Moab: « Que mon père et ma mère puissent, je te prie, se retirer chez vous, jusqu''à ce que je sache ce que Dieu fera de moi. »'),
('1s',22,4,'crampon1923','Et il les amena devant le roi de Moab, et ils demeurèrent chez lui tout le temps que David fut dans le lieu fort.'),
('1s',22,5,'crampon1923','Le prophète Gad dit à David: « Ne reste pas dans le lieu fort; va-t''en et reviens dans le pays de Juda. » Et David s''en alla et se rendit à la forêt de Haret.'),
('1s',22,6,'crampon1923','Saül apprit que David et les gens qui étaient avec lui avaient été reconnus. Or Saül était assis, à Gabaa, sous le tamarisque, sur la hauteur, sa lance à la main, et tous ses serviteurs étaient rangés devant lui.'),
('1s',22,7,'crampon1923','Saül dit à ses serviteurs qui étaient rangés devant lui: « Ecoutez, Benjamites: le fils d''Isaï vous donnera-t-il aussi à tous des champs et des vignes, fera-t-il de vous tous des chefs de milliers et des chefs de centaines,'),
('1s',22,8,'crampon1923','que vous vous soyez tous ligués contre moi, qu''il n''y ait personne qui m''ait informé que mon fils a fait alliance avec le fils d''Isaï, et que nul de vous n''en souffre pour moi et ne m''avertisse que mon fils a soulevé mon serviteur contre moi, pour me dresser des embûches, comme il le fait aujourd''hui? »'),
('1s',22,9,'crampon1923','Doëg, l''Edomite, qui était le chef des serviteurs de Saül, répondit et dit: « J''ai vu le fils d''Isaï venir à Nobé, auprès d''Achimélech, fils d''Achitob.'),
('1s',22,10,'crampon1923','Achimélech a consulté pour lui Yahweh, et il lui a donné des vivres; il lui a aussi donné l''épée de Goliath, le Philistin. »'),
('1s',22,11,'crampon1923','Le roi envoya appeler le prêtre Achimélech, fils d''Achitob, et toute la maison de son père, les prêtres qui étaient à Nobé.'),
('1s',22,12,'crampon1923','Ils vinrent tous vers le roi; et Saül dit: « Ecoute, fils d''Achitob! » Il répondit: « Me voici, mon seigneur. »'),
('1s',22,13,'crampon1923','Saül lui dit: « Pourquoi vous êtes-vous ligués contre moi, toi et le fils d''Isaï? Tu lui as donné du pain et une épée, et tu as consulté Dieu pour lui, pour qu''il s''élève contre moi et me dresse des embûches, comme il le fait aujourd''hui? »'),
('1s',22,14,'crampon1923','Achimélech répondit au roi et dit: « Lequel d''entre tous tes serviteurs est, comme David, d''une fidélité éprouvée, gendre du roi, admis à tes conseils et honoré dans ta maison?'),
('1s',22,15,'crampon1923','Est-ce aujourd''hui que j''aurais commencé à consulter Dieu pour lui? Loin de moi! Que le roi ne mette pas à la charge de son serviteur une chose qui pèserait sur toute la maison de mon père, car ton serviteur n''a rien su de tout cela, ni peu ni beaucoup. »'),
('1s',22,16,'crampon1923','Le roi dit: « Tu mourras, Achimélech, toi et toute la maison de ton père. »'),
('1s',22,17,'crampon1923','Et le roi dit aux gardes qui se tenaient près de lui: « Tournez-vous et mettez à mort les prêtres de Yahweh; car leur main est avec David et, sachant bien qu''il était en fuite, ils ne m''en ont pas informé. » Mais les serviteurs du roi ne voulurent pas étendre la main pour frapper les prêtres de Yahweh.'),
('1s',22,18,'crampon1923','Alors le roi dit à Doëg: « Tourne-toi et frappe les prêtres. » Et Doëg l''Edomite se tourna, et ce fut lui qui frappa les prêtres; il mit à mort en ce jour quatre-vingt-cinq hommes portant l''éphod de lin.'),
('1s',22,19,'crampon1923','Saül frappa encore du tranchant de l''épée Nobé, ville sacerdotale: hommes et femmes, enfants et nourrissons, bœufs, ânes et brebis, furent passés au fil de l''épée.'),
('1s',22,20,'crampon1923','Un seul fils d''Achimélech, fils d''Achitob, s''échappa; son nom était Abiathar, et il se réfugia auprès de David.'),
('1s',22,21,'crampon1923','Abiathar annonça à David que Saül avait tué les prêtres de Yahweh.'),
('1s',22,22,'crampon1923','Et David dit à Abiathar: « Je savais bien, en ce jour-là, que Doëg l''Edomite, qui était là, ne manquerai pas d''informer Saül. C''est moi qui suis cause de la mort de toute la maison de ton père.'),
('1s',22,23,'crampon1923','Reste avec moi, ne crains rien; car celui qui en veut à ma vie en veut à ta vie, et près de moi tu auras bonne garde. »'),
('1s',23,1,'crampon1923','On vint dire à David: « Voici que les Philistins attaquent Céïla et pillent les aires. »'),
('1s',23,2,'crampon1923','David consulta Yahweh, en disant: « Irai-je et battrai-je ces Philistins? » Et Yahweh répondit à David: « Va, tu battras les Philistins et tu délivreras Céïla. »'),
('1s',23,3,'crampon1923','Mais les hommes de David lui dirent: « Voici que, en Juda, nous sommes dans la crainte; combien plus si nous allons à Céïla contre les troupes des Philistins? »'),
('1s',23,4,'crampon1923','David consulta de nouveau Yahweh, et Yahweh lui répondit en ces termes: « Lève-toi, descends à Céïla, car je livre les Philistins entre tes mains. »'),
('1s',23,5,'crampon1923','David alla donc avec ses hommes à Céïla, et attaqua les Philistins; il emmena leur bétail et leur fit éprouver une grande défaite. C''est ainsi que David délivra les habitants de Céïla.'),
('1s',23,6,'crampon1923','Or quand Abiathar, fils d''Achimélech, s''enfuit vers David à Céïla, il descendit ayant en main l''éphod.'),
('1s',23,7,'crampon1923','On annonça à Saül que David était allé à Céïla, et Saül dit: « Dieu le livre entre mes mains, car il s''est enfermé en venant dans une ville qui a des portes et des barres. »'),
('1s',23,8,'crampon1923','Et Saül convoqua tout le peuple à la guerre, afin de descendre à Céïla et d''assiéger David et ses hommes.'),
('1s',23,9,'crampon1923','Mais David, ayant su que Saül préparait le mal contre lui, dit au prêtre Abiathar: « Apporte l''éphod. »'),
('1s',23,10,'crampon1923','Et David dit: « Yahweh, Dieu d''Israël, votre serviteur a appris que Saül cherche à venir à Céïla, pour détruire la ville à cause de moi.'),
('1s',23,11,'crampon1923','Les habitants de Céïla me livreront-ils entre ses mains? Saül descendra-t-il, comme votre serviteur l''a entendu dire? Yahweh, Dieu d''Israël, daignez le révéler à votre serviteur. » Yahweh répondit: « Il descendra. »'),
('1s',23,12,'crampon1923','Et David dit: « Les habitants de Céïla me livreront-ils, moi et mes hommes, entre les mains de Saül? » Yahweh répondit: « Ils te livreront. »'),
('1s',23,13,'crampon1923','Alors David se leva avec ses gens au nombre d''environ six cents hommes; ils sortirent de Céïla, et ils allaient et venaient à l''aventure. Informé que David s''était enfui de Céïla, Saül suspendit sa marche.'),
('1s',23,14,'crampon1923','David demeura au désert, dans les lieux forts, et il resta dans la montagne au désert de Ziph. Saül le cherchait tous les jours, mais Dieu ne le livra pas entre ses mains.'),
('1s',23,15,'crampon1923','David sut que Saül s''était mis en campagne pour lui ôter la vie: David se tenait au désert de Ziph, dans la forêt;'),
('1s',23,16,'crampon1923','et Jonathas, fils de Saül, se leva et alla vers David dans la forêt. Il fortifia sa main en Dieu et lui dit:'),
('1s',23,17,'crampon1923','« Ne crains rien, car la main de Saül, mon père, ne t''atteindra pas. Toi, tu régneras sur Israël, et moi, je serai le second après toi; Saül, mon père, le sait bien aussi. »'),
('1s',23,18,'crampon1923','Ils firent tous deux alliance devant Yahweh; et David resta dans la forêt, et Jonathas retourna chez lui.'),
('1s',23,19,'crampon1923','Les Ziphiens montèrent vers Saül à Gabaa, et dirent: « David est caché parmi nous dans des lieux forts, dans la forêt, sur la colline de Hachila, qui est au midi de la lande.'),
('1s',23,20,'crampon1923','Descends donc, ô roi, comme toute ton âme le désire; c''est à nous de le livrer entre les mains du roi. »'),
('1s',23,21,'crampon1923','Saül dit: « Soyez bénis de Yahweh, de ce que vous avez eu pitié de moi!'),
('1s',23,22,'crampon1923','Allez, je vous prie, assurez-vous encore, sachez et voyez en quel lieu il porte ses pas et qui l''a vu là; car il est, m''a-t-on dit, fort rusé.'),
('1s',23,23,'crampon1923','Voyez et sachez toutes les retraites où il se cache; puis revenez vers moi avec des renseignements certains, et j''irai avec vous. S''il est dans le pays, je le chercherai parmi tous les milliers de Juda. »'),
('1s',23,24,'crampon1923','Ils se levèrent donc et allèrent à Ziph, avant Saül. Mais David et ses hommes s''étaient retirés au désert de Maon, dans la plaine, au midi de la lande.'),
('1s',23,25,'crampon1923','Saül partit avec ses hommes à la recherche de David. David, l''ayant appris, descendit au rocher et resta dans le désert de Maon. Saül en fut informé et poursuivit David dans le désert de Maon;'),
('1s',23,26,'crampon1923','Saül marchait d''un côté de la montagne, et David avec ses hommes de l''autre côté de la montagne; David se hâtait pour échapper à Saül, tandis que Saül et ses hommes cernaient David et ses hommes pour s''emparer d''eux.'),
('1s',23,27,'crampon1923','Un messager vint vers Saül en disant: « Hâte-toi de venir, car les Philistins ont fait invasion dans le pays. »'),
('1s',23,28,'crampon1923','Saül cessa de poursuivre David, et s''en alla à la rencontre des Philistins. C''est pourquoi on appela ce lieu Séla-Hammachleqoth.'),
('1s',24,1,'crampon1923','David monta de là et s''établit dans les lieux forts d''Engaddi.'),
('1s',24,2,'crampon1923','Lorsque Saül fut revenu de la poursuite des Philistins, on vint lui dire: « Voici que David est au désert d''Engaddi. »'),
('1s',24,3,'crampon1923','Saül prit trois mille hommes d''élite d''entre tout Israël, et il alla à la recherche de David et de ses gens jusque sur les rochers des boucs sauvages.'),
('1s',24,4,'crampon1923','Il arriva aux parcs des brebis qui étaient près du chemin; il y avait là une caverne, où Saül entra pour se couvrir les pieds; et David et ses gens étaient assis au fond de la caverne.'),
('1s',24,5,'crampon1923','Les hommes de David lui dirent: « Voici le jour dont Yahweh t''a dit: Voici que je livre ton ennemi entre tes mains; traite-le comme il te plaira. » David se leva et coupa à la dérobée le pan du manteau de Saül.'),
('1s',24,6,'crampon1923','Après cela, le cœur de David lui battit, de ce qu''il avait coupé le pan du manteau de Saül.'),
('1s',24,7,'crampon1923','Et il dit à ses hommes: « Que Yahweh me préserve de faire contre mon seigneur, l''oint de Yahweh, une chose telle que de porter ma main sur lui, car il est l''oint de Yahweh! »'),
('1s',24,8,'crampon1923','Par ses paroles, David réprima ses hommes et ne leur permit pas de se jeter sur Saül. Saül s''étant levé pour sortir de la caverne continua sa route.'),
('1s',24,9,'crampon1923','Après cela David se leva et, sortant de la caverne, il se mit à crier après Saül en disant: « O roi, mon seigneur! » Saül regarda derrière lui, et David s''inclina le visage contre terre et se prosterna.'),
('1s',24,10,'crampon1923','Et David dit à Saül: « Pourquoi écoutes-tu les propos de gens qui disent: Voici que David cherche à te faire du mal?'),
('1s',24,11,'crampon1923','Voici qu''aujourd''hui tes yeux ont vu comment Yahweh t''a livré, aujourd''hui même, entre mes mains dans la caverne. On me disait de te tuer; mais mon œil a eu pitié de toi, et j''ai dit: Je ne porterai point ma main sur mon seigneur, car il est l''oint de Yahweh.'),
('1s',24,12,'crampon1923','Vois donc, mon père, vois dans ma main le pan de ton manteau. Puisque j''ai coupé le pan de ton manteau et que je ne t''ai pas tué, reconnais et vois qu''il n''y a dans ma conduite ni méchanceté ni révolte, et que je n''ai point péché contre toi. Et toi, tu fais la chasse à ma vie pour me l''ôter.'),
('1s',24,13,'crampon1923','Que Yahweh soit juge entre moi et toi, et que Yahweh me venge de toi! Mais ma main ne sera pas sur toi.'),
('1s',24,14,'crampon1923','Des méchants vient la méchanceté, dit le vieux proverbe; aussi ma main ne sera pas sur toi.'),
('1s',24,15,'crampon1923','Après qui le roi d''Israël s''est-il mis en marche? Qui poursuis-tu? Un chien mort? Une puce?'),
('1s',24,16,'crampon1923','Que Yahweh juge et prononce entre toi et moi. Qu''il regarde et qu''il défende ma cause, et que sa sentence me délivre de ta main! »'),
('1s',24,17,'crampon1923','Lorsque David eut achevé d''adresser ces paroles à Saül, Saül dit: « Est-ce bien ta voix, mon fils David? » Et Saül éleva la voix et pleura.'),
('1s',24,18,'crampon1923','Il dit à David: « Tu es plus juste que moi; car toi tu m''as fait du bien, et moi je t''ai rendu du mal.'),
('1s',24,19,'crampon1923','Tu as montré aujourd''hui que tu agis avec bonté envers moi, puisque Yahweh m''a livré entre tes mains et que tu ne m''as pas tué.'),
('1s',24,20,'crampon1923','Si quelqu''un rencontre son ennemi, le laisse-t-il poursuivre en paix son chemin? Que Yahweh te fasse du bien en retour de ce que tu m''as fait en ce jour!'),
('1s',24,21,'crampon1923','Maintenant, voici que je sais que tu seras roi et que la royauté d''Israël sera stable entre tes mains.'),
('1s',24,22,'crampon1923','Jure-moi donc par Yahweh que tu ne détruiras pas ma postérité après moi, et que tu ne retrancheras pas mon nom de la maison de mon père. »'),
('1s',24,23,'crampon1923','David le jura à Saül. Et Saül s''en alla dans sa maison, et David et ses hommes montèrent à l''endroit fort.'),
('1s',25,1,'crampon1923','Cependant Samuel mourut et tout Israël s''assembla; on le pleura, et on l''enterra dans sa demeure, à Rama. Alors David se leva et descendit au désert de Pharan.'),
('1s',25,2,'crampon1923','Il y avait à Maon un homme ayant ses biens à Carmel; c''était un homme très riche, il avait trois mille brebis et mille chèvres, et il se trouvait à Carmel pour la tonte de ses brebis.'),
('1s',25,3,'crampon1923','Le nom de cet homme était Nabal, et le nom de sa femme Abigaïl. La femme était pleine de sens, et de belle figure; mais l''homme était dur et méchant en actes; il était de la race de Caleb.'),
('1s',25,4,'crampon1923','David apprit au désert que Nabal tondait ses brebis.'),
('1s',25,5,'crampon1923','David envoya dix jeunes gens, et David dit aux jeunes gens: « Montez à Carmel et allez trouver Nabal; vous le saluerez en mon nom,'),
('1s',25,6,'crampon1923','et vous lui parlerez ainsi: Pour la vie! Que la paix soit avec toi, que la paix soit avec ta maison et que la paix soit avec tout ce qui t''appartient.'),
('1s',25,7,'crampon1923','Et maintenant, j''ai appris que tu as les tondeurs. Or, tes bergers ont été avec nous; nous ne leur avons causé aucune peine, et rien du troupeau ne leur a été enlevé pendant tout le temps qu''ils ont été à Carmel.'),
('1s',25,8,'crampon1923','Interroge tes serviteurs, et ils te le diront. Que les jeunes gens trouvent donc grâce à tes yeux, puisque nous venons dans un jour de joie. Donne, je te prie, à tes serviteurs et à ton fils David ce que ta main pourra trouver. »'),
('1s',25,9,'crampon1923','Lorsque les jeunes gens de David furent arrivés, ils répétèrent toutes ces paroles à Nabal au nom de David, et ils se reposèrent.'),
('1s',25,10,'crampon1923','Nabal répondit aux serviteurs de David et dit: « Qui est David, et qui est le fils d''Isaï? Ils sont nombreux aujourd''hui les serviteurs qui s''échappent de chez leurs maîtres.'),
('1s',25,11,'crampon1923','Et je prendrais mon pain et mon eau, et mon bétail que j''ai tué pour mes tondeurs, et je les donnerais à des gens qui viennent je ne sais d''où? »'),
('1s',25,12,'crampon1923','Les jeunes gens de David, rebroussant chemin, s''en retournèrent et, lorsqu''ils furent arrivés, ils lui redirent toutes ces paroles.'),
('1s',25,13,'crampon1923','Alors David dit à ses hommes: « Que chacun de vous ceigne son épée! » Et ils ceignirent chacun leur épée, et David, lui aussi, ceignit son épée; environ quatre cents hommes montèrent à la suite de David; il en resta deux cents près des bagages.'),
('1s',25,14,'crampon1923','Un des serviteurs de Nabal vint apporter la nouvelle à Abigaïl en disant: « Voici que David a envoyé du désert des messagers pour saluer notre maître, qui s''est jeté sur eux.'),
('1s',25,15,'crampon1923','Et pourtant ces gens ont été bons pour nous; ils ne nous ont causé aucune peine, et rien ne nous a été enlevé tout le temps que nous avons cheminé avec eux, lorsque nous étions dans la campagne.'),
('1s',25,16,'crampon1923','Ils nous ont servi de rempart, aussi bien la nuit que le jour, tout le temps que nous avons été avec eux, paissant les troupeaux.'),
('1s',25,17,'crampon1923','Reconnais maintenant et vois ce que tu as à faire; car le mal est résolu contre notre maître et contre toute sa maison; pour lui, c''est un fils de Bélial, et on ne peut lui parler. »'),
('1s',25,18,'crampon1923','Aussitôt Abigaïl prit deux cents pains, deux outres de vin, cinq moutons apprêtés, cinq mesures de grain rôti, cent masses de raisin sec et deux cents de figues sèches et, les ayant mis sur des ânes,'),
('1s',25,19,'crampon1923','elle dit à ses jeunes gens: « Passez devant moi, je vous suis. » Mais elle ne dit rien à Nabal, son mari.'),
('1s',25,20,'crampon1923','Comme elle descendait, montée sur un âne, en un endroit couvert de la montagne, voici que David et ses hommes descendaient en face d''elle, et elle les rencontra. —'),
('1s',25,21,'crampon1923','David disait: « C''est bien en vain que j''ai surveillé tout ce que cet homme a dans le désert, et que rien n''a été enlevé de tout ce qu''il possède; il me rend le mal pour le bien!'),
('1s',25,22,'crampon1923','Que Dieu traite dans toute sa rigueur les ennemis de David! De tout ce qui appartient à Nabal, je ne laisserai rien subsister jusqu''au lever du jour, pas même celui qui urine contre le mur. »'),
('1s',25,23,'crampon1923','Dès qu''Abigaïl aperçut David, elle s''empressa de descendre de l''âne et, tombant sur sa face devant David, elle se prosterna contre terre.'),
('1s',25,24,'crampon1923','Puis elle se jeta à ses pieds, en disant: « Que sur moi, mon seigneur, sur moi soit la faute! Permets à ta servante de parler à tes oreilles, et écoute les paroles de ta servante!'),
('1s',25,25,'crampon1923','Que mon seigneur ne prenne pas garde à cet homme de Bélial, à Nabal, car il est ce que son nom indique; son nom est Le Fou, et il y a chez lui de la folie. Mais moi, ta servante, je n''ai pas vu les gens de mon seigneur, que tu as envoyés.'),
('1s',25,26,'crampon1923','Maintenant, mon seigneur, aussi vrai que Yahweh est vivant et que ton âme est vivante, Yahweh t''a préservé de répandre le sang et de te venger de ta main. Et maintenant, que tes ennemis et ceux qui veulent du mal à mon seigneur soient comme Nabal!'),
('1s',25,27,'crampon1923','Accepte donc ce présent que ta servante apporte à mon seigneur, et qu''il soit distribué aux jeunes gens qui marchent à la suite de mon seigneur.'),
('1s',25,28,'crampon1923','Pardonne, je te prie, la faute de ta servante, car Yahweh fera certainement à mon seigneur une maison stable; car mon seigneur soutient les guerres de Yahweh, et on ne trouvera pas de mal en toi tout le temps de ta vie.'),
('1s',25,29,'crampon1923','S''il s''élève quelqu''un pour te poursuivre et en vouloir à ta vie, la vie de mon seigneur sera liée dans le faisceau des vivants auprès de Yahweh, ton Dieu, et la vie de tes ennemis, il la lancera au loin du creux de la fronde.'),
('1s',25,30,'crampon1923','Lorsque Yahweh aura fait à mon seigneur selon tout le bien qu''il a dit à ton sujet et qu''il t''aura établi chef sur Israël,'),
('1s',25,31,'crampon1923','ce ne sera pas pour toi un sujet de remords ni pour mon seigneur une souffrance de cœur d''avoir répandu le sang sans motif et s''être vengé lui-même. Et lorsque Yahweh aura fait du bien à mon seigneur, souviens-toi de ta servante. »'),
('1s',25,32,'crampon1923','David dit à Abigaïl: « Béni soit Yahweh, le Dieu d''Israël, qui t''a envoyée, aujourd''hui à ma rencontre! Béni soit ton grand sens,'),
('1s',25,33,'crampon1923','et bénie sois-tu, toi qui m''as empêché en ce jour de répandre le sang et de me venger de ma main!'),
('1s',25,34,'crampon1923','Autrement, aussi vrai que Yahweh, le Dieu d''Israël, qui m''a empêché de te faire du mal, est vivant, si tu ne t''étais pas hâtée de venir au-devant de moi, il ne fût rien resté à Nabal d''ici au lever du jour, pas même celui qui urine contre le mur. »'),
('1s',25,35,'crampon1923','David prit de la main d''Abigaïl ce qu''elle lui avait apporté, et lui dit: « Monte en paix dans ta maison; vois, j''ai écouté ta voix et relevé ton visage! »'),
('1s',25,36,'crampon1923','Abigaïl retourna vers Nabal, et voici qu''il faisait dans sa maison un festin comme un festin de roi; et le cœur de Nabal était joyeux, et il était complètement ivre. Elle ne lui apprit ni peu, ni beaucoup, jusqu''au lever du jour.'),
('1s',25,37,'crampon1923','Mais le matin, quand Nabal fut revenu de son ivresse, sa femme lui raconta ces choses, et son cœur en reçut un coup mortel, et il devint comme une pierre.'),
('1s',25,38,'crampon1923','Environ dix jours après, Yahweh frappa Nabal, et il mourut.'),
('1s',25,39,'crampon1923','Lorsque David apprit la mort de Nabal, il dit: « Béni soit Yahweh qui a défendu ma cause et m''a vengé de l''outrage que j''ai reçu de la main de Nabal, et qui a empêché son serviteur de faire le mal! Yahweh a fait retomber la méchanceté de Nabal sur sa tête. » Ensuite David envoya dire à Abigaïl qu''il voulait la prendre pour femme.'),
('1s',25,40,'crampon1923','Arrivés chez Abigaïl à Carmel, les serviteurs de David lui parlèrent ainsi: « David nous a envoyés vers toi, afin de te prendre pour sa femme. »'),
('1s',25,41,'crampon1923','Elle se leva et, s''étant prosternée le visage contre terre, elle dit: « Voici que ta servante est comme une esclave pour laver les pieds des serviteurs de mon seigneur! »'),
('1s',25,42,'crampon1923','Aussitôt Abigaïl se leva et monta sur un âne, et cinq de ses jeunes filles allaient sur ses pas; elle suivit les messagers de David, et elle devint sa femme.'),
('1s',25,43,'crampon1923','David prit aussi Achinoam de Jezraël, et toutes les deux furent ses femmes.'),
('1s',25,44,'crampon1923','Mais Saül avait donné sa fille Michol, femme de David, à Phalti de Gallim, fils de Laïs.'),
('1s',26,1,'crampon1923','Les Ziphéens vinrent auprès de Saül à Gabaa, et dirent: « David est caché sur la colline de Hachila, à l''est de la lande. »'),
('1s',26,2,'crampon1923','Saül se leva et descendit au désert de Ziph avec trois mille hommes d''élite d''Israël, pour chercher David au désert de Ziph.'),
('1s',26,3,'crampon1923','Saül campa sur la colline de Hachila, à l''est de la lande, près du chemin, et David demeurait dans le désert. S''étant aperçut que Saül marchait à sa recherche au désert,'),
('1s',26,4,'crampon1923','David envoya des espions et apprit que Saül était réellement arrivé.'),
('1s',26,5,'crampon1923','David se leva et vint au lieu où Saül était campé. David vit l''endroit où était couché Saül, avec Abner, fils de Ner, chef de son armée: — or Saül couchait au milieu du camp, et le peuple était campé autour de lui. —'),
('1s',26,6,'crampon1923','S''adressant donc à Achimélech, le Héthéen, et à Abisaï, fils de Sarvia et frère de Joab, David dit: « Qui veut descendre avec moi au camp vers Saül. » Et Abisaï répondit: « Moi, je descendrai avec toi. »'),
('1s',26,7,'crampon1923','David et Abisaï arrivèrent de nuit vers le peuple, et voici que Saül était couché au milieu du camp et dormait, sa lance fichée en terre à son chevet; Abner et le peuple étaient couchés autour de lui.'),
('1s',26,8,'crampon1923','Abisaï dit à David: « Dieu a enfermé aujourd''hui ton ennemi entre tes mains; maintenant, je te prie, laisse-moi le frapper de la lance et le clouer en terre d''un seul coup, sans que j''aie à y revenir. »'),
('1s',26,9,'crampon1923','Mais David dit à Abisaï: « Ne le tue pas! Car qui porterait la main sur l''oint de Yahweh et resterait impuni? »'),
('1s',26,10,'crampon1923','Et David dit: « Aussi vrai que Yahweh est vivant! Ce sera seulement Yahweh qui le frappera; ou bien son jour arrivera et il mourra, ou bien il descendra à la guerre et il périra;'),
('1s',26,11,'crampon1923','mais que Yahweh me préserve de porter la main sur l''oint de Yahweh! Maintenant, prends la lance qui est à son chevet, avec la cruche d''eau, et allons-nous-en. »'),
('1s',26,12,'crampon1923','Et David prit la lance et la cruche d''eau qui étaient au chevet de Saül, et ils s''en allèrent. Personne ne vit, personne ne sut, personne ne se réveilla, car ils dormaient tous, Yahweh ayant fait tomber sur eux un profond assoupissement.'),
('1s',26,13,'crampon1923','David passa de l''autre côté, et se tint au loin sur le sommet de la montagne; un grand espace les séparait.'),
('1s',26,14,'crampon1923','Et David cria au peuple et à Abner, fils de Ner, en disant: « Ne répondras-tu pas, Abner! » Abner répondit en disant: « Qui es-tu, toi qui cries vers le roi? »'),
('1s',26,15,'crampon1923','David dit à Abner: « N''es-tu pas un homme? Et qui est ton pareil en Israël? Pourquoi donc n''as-tu pas gardé le roi, ton seigneur? Car quelqu''un du peuple est venu pour tuer le roi, ton seigneur.'),
('1s',26,16,'crampon1923','Ce que tu as fait là n''est pas bien. Aussi vrai que Yahweh est vivant! Vous avez mérité la mort, pour n''avoir pas gardé votre maître, l''oint de Yahweh. Regarde maintenant où sont la lance du roi et la cruche d''eau qui était à son chevet. »'),
('1s',26,17,'crampon1923','Saül reconnut la voix de David et dit: « Est-ce bien ta voix, mon fils David? » Et David répondit: « C''est ma voix, ô roi, mon seigneur. »'),
('1s',26,18,'crampon1923','Il ajouta: « Pourquoi mon seigneur poursuit-il son serviteur? Qu''ai-je fait, et quel crime ma main a-t-elle commis?'),
('1s',26,19,'crampon1923','Que le roi, mon seigneur, daigne maintenant écouter les paroles de ton serviteur: si c''est Yahweh qui t''excite contre moi, qu''il agrée le parfum d''une offrande; mais si ce sont des hommes, qu''ils soient maudits devant Yahweh, puisqu''ils m''ont chassé maintenant, pour m''ôter ma place de l''héritage de Yahweh, en disant: Va servir des dieux étrangers!'),
('1s',26,20,'crampon1923','Et maintenant que mon sang ne tombe pas sur la terre, loin de la face de Yahweh! Car le roi d''Israël s''est mis en marche pour chercher une puce, comme on poursuivrait une perdrix dans les montagnes. »'),
('1s',26,21,'crampon1923','Saül dit: « J''ai péché; reviens, mon fils David, car je ne te ferai plus de mal, puisqu''en ce jour ma vie a été précieuse à tes yeux. Voilà que j''ai agi en insensé et j''ai fait une grande faute. »'),
('1s',26,22,'crampon1923','David répondit: « Voici la lance, ô roi; que l''un de tes jeunes gens vienne la prendre.'),
('1s',26,23,'crampon1923','Yahweh rendra à chacun selon sa justice et sa fidélité; car Yahweh t''avait livré aujourd''hui entre mes mains, et je n''ai pas voulu porter la main sur l''oint de Yahweh.'),
('1s',26,24,'crampon1923','Voici que, comme ta vie a été aujourd''hui d''un grand prix à mes yeux, ainsi ma vie sera d''un grand prix aux yeux de Yahweh, et il me délivrera de toute angoisse! »'),
('1s',26,25,'crampon1923','Saül dit à David: « Sois béni mon fils, David! Tu réussiras certainement dans tes entreprises. » David continua son chemin, et Saül s''en retourna chez lui.'),
('1s',27,1,'crampon1923','David se dit à lui-même: « Je périrai un jour par la main de Saül; il n''y a rien de mieux pour moi que de me réfugier promptement au pays des Philistins, afin que Saül renonce à me chercher encore dans tout le territoire d''Israël; j''échapperai ainsi à sa main. »'),
('1s',27,2,'crampon1923','Et David s''étant levé, lui et les six cents hommes qui étaient avec lui, ils passèrent chez Achis, fils de Maoch, roi de Geth.'),
('1s',27,3,'crampon1923','David demeura auprès d''Achis, à Geth, lui et ses gens, chacun avec sa famille, et David avec ses deux femmes, Achinoam de Jezraël, et Abigaïl de Carmel, femme de Nabal.'),
('1s',27,4,'crampon1923','On annonça à Saül que David s''était enfui à Geth, et il ne recommença pas à le poursuivre.'),
('1s',27,5,'crampon1923','David dit à Achis: « Si j''ai trouvé grâce à tes yeux, qu''on me donne dans l''une des villes de la campagne un lieu où je puisse demeurer; car pourquoi ton serviteur habiterait-il avec toi dans la ville royale? »'),
('1s',27,6,'crampon1923','Et, ce jour-là, Achis lui donna Siceleg; c''est pourquoi Siceleg a appartenu aux rois de Juda jusqu''à ce jour.'),
('1s',27,7,'crampon1923','Le nombre des jours que David passa dans le pays des Philistins fut d''un an et quatre mois.'),
('1s',27,8,'crampon1923','David et ses hommes montaient et faisaient des incursions chez les Gessuriens, les Gerziens et les Amalécites; car ces peuplades habitaient dès les temps anciens du côté de Sur et jusqu''au pays d''Egypte.'),
('1s',27,9,'crampon1923','David ravageait la contrée, ne laissant en vie ni homme ni femme, enlevant les brebis, les bœufs, les ânes, les chameaux, les vêtements; puis il s''en revenait chez Achis.'),
('1s',27,10,'crampon1923','Achis disait: « Où avez-vous fait incursion, aujourd''hui? » Et David répondait: « Dans le Négéb de Juda, dans le Négéb des Jéraméélites et dans le Négéb des Cinéens. »'),
('1s',27,11,'crampon1923','David ne laissait en vie ni homme ni femme pour les amener à Geth, de peur, se disait-il, « qu''ils ne fassent des rapports contre nous, en disant: Ainsi a fait David. » Et telle fut sa manière d''agir tout le temps qu''il demeura dans le pays des Philistins.'),
('1s',27,12,'crampon1923','Achis se fiait à David, et il disait: « Il s''est rendu odieux à son peuple, à Israël, donc il sera mon serviteur à jamais. »'),
('1s',28,1,'crampon1923','En ce temps-là, les Philistins rassemblèrent leurs troupes en une seule armée pour aller combattre contre Israël. Et Achis dit à David: « Sache que tu viendras avec moi au camp, toi et tes hommes. »'),
('1s',28,2,'crampon1923','David répondit à Achis: « Aussi tu verras ce que fera ton serviteur. » Et Achis dit à David: « Et moi je t''établirai pour toujours gardien de ma personne. »'),
('1s',28,3,'crampon1923','Samuel était mort; tout Israël l''avait pleuré, et on l''avait enterré à Rama, dans sa ville. Et Saül avait fait disparaître du pays ceux qui évoquaient les morts et les devins.'),
('1s',28,4,'crampon1923','Les Philistins s''étant rassemblés, vinrent camper à Sunam; Saül rassembla tout Israël, et ils campèrent à Gelboé.'),
('1s',28,5,'crampon1923','A la vue du camp des Philistins, Saül eut peur, et son cœur fut fort agité.'),
('1s',28,6,'crampon1923','Saül consulta Yahweh, et Yahweh ne lui répondit point, ni par les songes, ni par l''Urim, ni par les prophètes.'),
('1s',28,7,'crampon1923','Alors Saül dit à ses serviteurs: « Cherchez-moi une femme qui évoque les morts, et j''irai vers elle et je la consulterai. » Ses serviteurs lui dirent: « Il y a à Endor une femme qui évoque les morts. »'),
('1s',28,8,'crampon1923','Saül se déguisa et mit d''autres vêtements, et il partit, accompagné de deux hommes. Ils arrivèrent de nuit chez la femme, et Saül lui dit: « Prédis-moi l''avenir en évoquant un mort, et fais-moi monter celui que je te dirai. »'),
('1s',28,9,'crampon1923','La femme lui répondit: « Voici que tu sais ce qu''a fait Saül, comment il a retranché du pays ceux qui évoquent les morts et les devins; pourquoi me tends-tu un piège, pour me faire mourir? »'),
('1s',28,10,'crampon1923','Saül lui jura par Yahweh en disant: « Aussi vrai que Yahweh est vivant! il ne t''arrivera aucun mal à cause de cela. »'),
('1s',28,11,'crampon1923','Et la femme dit: « Qui te ferai-je monter? » Il répondit: « Fais-moi monter Samuel. »'),
('1s',28,12,'crampon1923','A la vue de Samuel, la femme poussa un grand cri; et la femme dit à Saül: « Pourquoi m''as-tu trompée? Tu es Saül! »'),
('1s',28,13,'crampon1923','Le roi lui dit: « Ne crains pas; mais qu''as-tu vu? » La femme dit à Saül: « Je vois un dieu qui monte de la terre. »'),
('1s',28,14,'crampon1923','Il lui dit: « Quelle figure a-t-il? » Et elle répondit: « C''est un vieillard qui monte, et il est enveloppé d''un manteau. » Saül comprit que c''était Samuel, et il se jeta le visage contre terre et se prosterna.'),
('1s',28,15,'crampon1923','Samuel dit à Saül: « Pourquoi m''as-tu troublé, en me faisant monter? » Saül répondit: « Je suis dans une grande détresse: les Philistins me font la guerre, et Dieu s''est retiré de moi; il ne m''a répondu ni par les prophètes ni par les songes. Je t''ai évoqué pour que tu me fasses connaître ce que j''ai à faire. »'),
('1s',28,16,'crampon1923','Samuel dit: « Pourquoi me consultes-tu, puisque Yahweh s''est retiré de toi et qu''il est devenu ton adversaire?'),
('1s',28,17,'crampon1923','Yahweh a agi comme il l''avait annoncé par mon intermédiaire: Yahweh a arraché la royauté de ta main, et l''a donnée à ton compagnon, à David.'),
('1s',28,18,'crampon1923','Parce que tu n''as pas obéi à la voix de Yahweh, et que tu n''as pas traité Amalec selon l''ardeur de sa colère, c''est pour cela que Yahweh a ainsi agi envers toi en ce jour.'),
('1s',28,19,'crampon1923','Et même Yahweh livrera Israël avec toi aux mains des Philistins. Demain, toi et tes fils, vous serez avec moi, et Yahweh livrera le camp d''Israël entre les mains des Philistins. »'),
('1s',28,20,'crampon1923','Aussitôt Saül tomba par terre de toute sa hauteur, car les paroles de Samuel l''avaient rempli d''effroi; de plus, les forces lui manquaient, car il n''avait pris aucune nourriture de tout le jour et de toute la nuit.'),
('1s',28,21,'crampon1923','La femme vint vers Saül et, voyant son grand trouble, elle lui dit: « Ta servante a obéi à ta voix; j''ai exposé ma vie, en obéissant aux paroles que tu m''as dites.'),
('1s',28,22,'crampon1923','Ecoute maintenant, toi aussi, la voix de ta servante, et que je t''offre un morceau de pain; manges-en, pour avoir de la force lorsque tu poursuivras ta route. »'),
('1s',28,23,'crampon1923','Mais il refusa et dit: « Je ne mangerai point. » Ses serviteurs, ainsi que la femme, le pressèrent, et il se rendit à leurs instances. Il se leva de terre et s''assit sur le divan.'),
('1s',28,24,'crampon1923','La femme avait chez elle un veau gras, elle se hâta de le tuer et, prenant de la farine, elle la pétrit et en cuisit des pains sans levain.'),
('1s',28,25,'crampon1923','Elle les mit devant Saül et devant ses serviteurs, et ils mangèrent. Puis s''étant levés, ils partirent la nuit même.'),
('1s',29,1,'crampon1923','Les Philistins rassemblèrent toutes leurs troupes à Aphec, et Israël était campé près de la source, en Jezraël.'),
('1s',29,2,'crampon1923','Pendant que les princes des Philistins s''avançaient en tête des centaines et des milliers, et que David et ses gens marchaient à l''arrière-garde avec Achis,'),
('1s',29,3,'crampon1923','les chefs des Philistins dirent: « Qu''est-ce que ces Hébreux? » Achis répondit aux chefs des Philistins: « N''est-ce pas ce David, serviteur de Saül, roi d''Israël, qui est avec moi depuis des jours et depuis des années, sans que j''aie trouvé en lui la moindre chose à reprocher, depuis qu''il a passé vers nous jusqu''à ce jour. »'),
('1s',29,4,'crampon1923','Mais les chefs des Philistins s''irritèrent contre Achis, et les chefs des Philistins lui dirent: « Renvoie cet homme, et qu''il retourne dans le lieu où tu l''as établi; qu''il ne descende pas avec nous à la bataille, de peur qu''il ne soit pour nous un adversaire pendant le combat. Et comment pourrait-il rentrer en grâce auprès de son maître, si ce n''est en lui offrant les têtes de ces hommes?'),
('1s',29,5,'crampon1923','N''est-ce pas ce David pour qui l''on chantait en dansant: Saül a tué ses mille, et David ses dix mille. »'),
('1s',29,6,'crampon1923','Achis appela David et lui dit: « Aussi vrai que Yahweh est vivant! tu es un homme droit, et je vois de bon œil toute ta conduite avec moi dans le camp, car je n''ai rien trouvé de mauvais en toi, depuis le jour où tu es venu vers moi jusqu''à ce jour; mais tu déplais aux yeux des princes.'),
('1s',29,7,'crampon1923','Retourne donc et va-t-en en paix, pour ne rien faire de désagréable aux yeux des princes des Philistins. »'),
('1s',29,8,'crampon1923','David dit à Achis: « Mais qu''ai-je fait, et qu''as-tu trouvé en ton serviteur, depuis le jour où je suis venu auprès de toi jusqu''à ce jour, pour que je n''aille pas combattre les ennemis de mon seigneur le roi? »'),
('1s',29,9,'crampon1923','Achis répondit et dit à David: « Je sais que tu as été bon à mon égard comme un ange de Dieu; mais les chefs des Philistins disent: il ne montera point avec nous à la bataille.'),
('1s',29,10,'crampon1923','Ainsi lève-toi de bon matin, toi et les serviteurs de ton seigneur qui sont venus avec toi; levez-vous de bon matin, et dès qu''il fera jour, partez. »'),
('1s',29,11,'crampon1923','David et ses gens se levèrent de bonne heure, pour partir dès le matin et retourner au pays des Philistins; et les Philistins montèrent à Jezraël.'),
('1s',30,1,'crampon1923','Lorsque David arriva avec ses hommes le troisième jour à Siceleg, les Amalécites avaient fait une invasion dans le Négéb et à Siceleg; ils avaient frappé Siceleg et l''avaient brûlée;'),
('1s',30,2,'crampon1923','et ils avaient fait prisonniers les femmes et tous ceux qui s''y trouvaient, petits et grands, sans tuer personne, et ils les avaient emmenés, et s''étaient remis en route.'),
('1s',30,3,'crampon1923','Lors donc que David et ses gens arrivèrent à la ville, ils virent qu''elle était brûlée, et que leurs femmes, leurs fils et leurs filles avaient été emmenés captifs.'),
('1s',30,4,'crampon1923','Et David et le peuple qui était avec lui élevèrent la voix et pleurèrent jusqu''à ce qu''ils n''eussent plus la force de pleurer.'),
('1s',30,5,'crampon1923','Les deux femmes de David avaient été aussi emmenées captives, Achinoam de Jezraël, et Abigaïl de Carmel, femme de Nabal.'),
('1s',30,6,'crampon1923','David fut dans une grande angoisse, car la troupe parlait de le lapider, parce que tout le peuple avait de l''amertume dans l''âme, chacun au sujet de ses fils et de ses filles. Mais David reprit courage en Yahweh, son Dieu.'),
('1s',30,7,'crampon1923','David dit au prêtre Abiathar, fils d''Achimélech: « Apporte-moi l''éphod. » Abiathar apporta l''éphod à David.'),
('1s',30,8,'crampon1923','Et David consulta Yahweh en disant: « Poursuivrai-je cette bande? L''atteindrai-je? » Yahweh lui répondit: « Poursuis, car certainement tu atteindras et tu délivreras. »'),
('1s',30,9,'crampon1923','Et David se mit en marche, lui et les six cents hommes qui étaient avec lui. Lorsqu''ils furent arrivés au torrent de Bésor, les traînards s''arrêtèrent.'),
('1s',30,10,'crampon1923','Et David continua la poursuite avec quatre cents hommes; deux cents hommes s''étaient arrêtés, trop fatigués pour passer le torrent de Bésor.'),
('1s',30,11,'crampon1923','Ils trouvèrent dans les champs un Egyptien, qu''ils amenèrent à David. Ils lui donnèrent du pain qu''il mangea, et ils lui firent boire de l''eau;'),
('1s',30,12,'crampon1923','ils lui donnèrent une tranche d''un gâteau de figues sèches et deux gâteaux de raisins secs. Dès qu''il eut pris de la nourriture, ses esprits lui revinrent, car il n''avait mangé de nourriture ni bu d''eau depuis trois jours et trois nuits.'),
('1s',30,13,'crampon1923','David lui dit: « A qui es-tu et d''où es-tu? » Il répondit: « Je suis un esclave égyptien, au service d''un Amalécite, et voilà trois jours que mon maître m''a abandonné, parce que j''étais malade.'),
('1s',30,14,'crampon1923','Nous avons fait une incursion dans le Négéb des Céréthiens, et sur le territoire de Juda, et dans le Négéb de Caleb, et nous avons brûlé Siceleg. »'),
('1s',30,15,'crampon1923','David lui dit: « Veux-tu me conduire vers cette bande? » Il répondit: « Jure-moi par le nom de Dieu que tu ne me tueras pas et que tu ne me livreras pas aux mains de mon maître, et je te conduirai vers cette bande. »'),
('1s',30,16,'crampon1923','Lorsqu''il l''eut conduit, voici que les Amalécites étaient répandus sur toute la contrée, mangeant, buvant et dansant, à cause de tout le grand butin qu''ils avaient enlevé du pays des Philistins et du pays de Juda.'),
('1s',30,17,'crampon1923','David les battit depuis le crépuscule du soir jusqu''au soir du lendemain, et aucun d''eux n''échappa, excepté quatre cents jeunes hommes, qui s''enfuirent, montés sur des chameaux.')
